nz <- function(x) !is.null(x) && length(x) > 0 && all(nzchar(as.character(x)))

fmt <- function(x, d = 3) {
  ifelse(is.na(x), "-", formatC(as.numeric(x), digits = d, format = "f"))
}

## An effect's SE(m), SE(d) or C.D. for display (`what` is "sem", "sed" or "cd"):
## the single value when one applies to every mean and pair, otherwise its
## range, so a figure that fits only some of the means is never printed as if
## it fitted them all.
err_text <- function(e, what, digits = 2, html = TRUE) {
  v <- e[[what]]
  if (length(v) == 1L && !is.na(v)) return(fmt(v, digits))
  rg <- e[[c(sem = "se_range", sed = "sed_range", cd = "cd_range")[[what]]]]
  if (length(rg) != 2L || anyNA(rg)) return("-")
  ## a range whose ends round to the same figure reads as nonsense, so show
  ## enough decimals to tell them apart
  dg <- digits
  while (dg < digits + 3 && fmt(rg[1], dg) == fmt(rg[2], dg)) dg <- dg + 1
  paste0(fmt(rg[1], dg), if (html) "&ndash;" else " to ", fmt(rg[2], dg))
}

## a p-value for reading: never in scientific notation, never "= <0.0001"
p_text <- function(p) ifelse(is.na(p), "-", ifelse(p < 1e-4, "< 0.0001",
                             trimws(formatC(signif(p, 3), format = "fg", digits = 3))))
pval <- function(p) gsub("<", "&lt;", p_text(p), fixed = TRUE)

## "p = 0.0373" or "p &lt; 0.0001", for running text
p_eq <- function(p) ifelse(!is.na(p) & p < 1e-4, "p &lt; 0.0001", paste("p =", p_text(p)))

## Significance marks at the level the user chose: one star at alpha, two at
## alpha / 5. At alpha = 0.05 that is the familiar 5% and 1% pair; at any other
## level the marks follow the choice instead of staying at 5% and 1%.
star <- function(p, alpha) {
  ifelse(is.na(p), "", ifelse(p < alpha / 5, "**", ifelse(p < alpha, "*", "NS")))
}

## a probability as it is written in labels: 0.05, 0.01, 0.002
p_lab <- function(a) format(a, digits = 6, drop0trailing = TRUE, trim = TRUE, scientific = FALSE)

## a probability as a percentage, for "the 5% level"
pct <- function(a) format(100 * a, digits = 6, drop0trailing = TRUE, trim = TRUE, scientific = FALSE)

## the key printed under an ANOVA table, so the stars mean what they say
star_key <- function(alpha)
  sprintf("** significant at p &lt; %s; * significant at p &lt; %s; NS not significant at the %s%% level.",
          p_lab(alpha / 5), p_lab(alpha), pct(alpha))

## Letters from critical differences. `cd` is one number that applies to every
## pair, or a square matrix holding one critical difference per pair (unequal
## replication). Any missing value means no letters can be given.
cld_lsd <- function(mu, cd) {
  n <- length(mu)
  if (n < 2) return(rep("a", n))
  if (!length(cd) || anyNA(cd) || any(!is.finite(cd))) return(rep("", n))
  crit <- if (is.matrix(cd)) cd else matrix(cd, n, n)
  sig <- abs(outer(mu, mu, "-")) > crit
  diag(sig) <- FALSE
  off <- crit[row(crit) != col(crit)]
  if (diff(range(off)) <= 1e-12 * max(abs(off))) cld_sweep(mu, sig) else cld_from_sig(mu, sig)
}

## Letters when one critical difference applies to every pair: a single sweep
## down the sorted means. Exact in that case and instant for hundreds of means,
## where the general algorithm below is slow; both give identical letters.
cld_sweep <- function(mu, sig) {
  n <- length(mu)
  ord <- order(mu, decreasing = TRUE)
  groups <- list(); done <- integer(0)
  for (i in ord) {
    joined <- FALSE
    for (k in seq_along(groups)) {
      if (all(!sig[i, groups[[k]]])) {
        groups[[k]] <- c(groups[[k]], i); joined <- TRUE
      }
    }
    if (!joined) groups[[length(groups) + 1L]] <- c(done[!sig[i, done]], i)
    done <- c(done, i)
  }
  keep <- rep(TRUE, length(groups))
  for (i in seq_along(groups)) for (j in seq_along(groups)) {
    if (i != j && keep[i] && keep[j] && all(groups[[i]] %in% groups[[j]]) &&
        length(groups[[i]]) < length(groups[[j]])) keep[i] <- FALSE
  }
  groups <- groups[keep]
  groups <- groups[!duplicated(vapply(groups, function(g)
    paste(sort(g), collapse = "-"), character(1)))]
  lets <- letter_seq(length(groups))
  out <- character(n)
  for (k in seq_along(groups)) out[groups[[k]]] <- paste0(out[groups[[k]]], lets[k])
  out
}

## Compact letter display from a symmetric logical matrix `sig` (TRUE where two
## means differ significantly), by the insert and absorb steps of Piepho's
## (2004, Journal of Computational and Graphical Statistics 13, 456-466)
## algorithm. Two means share a letter exactly when they do not differ
## significantly, whatever produced `sig`. The sweep above only guarantees that
## when one critical difference applies to every pair, which unequal
## replication and the step-down range tests both break.
cld_from_sig <- function(mu, sig) {
  n <- length(mu)
  if (n < 2) return(rep("a", n))
  G <- matrix(TRUE, n, 1L)                      # one column per letter
  pairs <- which(upper.tri(sig) & sig, arr.ind = TRUE)
  for (r in seq_len(nrow(pairs))) {
    i <- pairs[r, 1]; j <- pairs[r, 2]
    both <- which(G[i, ] & G[j, ])
    if (!length(both)) next
    ## insert: split every letter holding both members of a significant pair
    ## into one copy without i and one without j
    add <- G[, both, drop = FALSE]
    add[j, ] <- FALSE
    G[i, both] <- FALSE
    G <- absorb_letters(cbind(G, add))
  }
  ## letter "a" goes to the group holding the highest mean, and so on down
  rk <- integer(n); rk[order(mu, decreasing = TRUE)] <- seq_len(n)
  key <- apply(G, 2, function(g) paste(sprintf("%06d", sort(rk[g])), collapse = "-"))
  G <- G[, order(key), drop = FALSE]
  lets <- letter_seq(ncol(G))
  vapply(seq_len(n), function(i) paste(lets[G[i, ]], collapse = ""), character(1))
}

## absorb: drop any letter whose members all carry another letter too, and any
## repeat of an identical letter. sub[a, b] is TRUE when letter a lies inside
## letter b; done as one matrix product because this runs after every insert.
absorb_letters <- function(G) {
  if (ncol(G) < 2L) return(G)
  sub <- crossprod(G, !G) == 0
  diag(sub) <- FALSE
  same <- sub & t(sub)
  drop <- rowSums(sub & !t(sub)) > 0 | rowSums(same & row(same) > col(same)) > 0
  G[, !drop, drop = FALSE]
}

## a, b, ..., z, then aa, bb, ..., then aaa, ...
letter_seq <- function(k)
  unlist(lapply(seq_len(ceiling(k / 26)), function(r) strrep(letters, r)))[seq_len(k)]

## read data pasted straight out of Excel
read_pasted <- function(txt, sep = "\t", header = TRUE) {
  txt <- gsub("\r\n", "\n", txt, fixed = TRUE)
  if (!nzchar(trimws(txt))) return(NULL)
  s <- switch(sep, "tab" = "\t", "comma" = ",", "semicolon" = ";",
              "space" = "", sep)
  ## only empty cells and NA count as missing here: markers such as "-" or
  ## "n/a" are left as typed so the data check can show them and say what it
  ## will do with them, rather than R changing them silently
  ## Everything is read as text first and converted only where no information
  ## is lost (convert_lossless), so codes such as 1.1 and 1.10 stay distinct.
  rd <- function(q) utils::read.table(text = txt, header = header, sep = s,
                         stringsAsFactors = FALSE, check.names = FALSE,
                         na.strings = c("NA", ""), fill = TRUE, colClasses = "character",
                         strip.white = TRUE, quote = q, comment.char = "")
  ## quotes are honoured only when they are real quoting, not inch marks
  ## (12" pot), which would swallow lines (see quote_char)
  d <- rd(quote_char(strsplit(txt, "\n", fixed = TRUE)[[1]]))
  ## a header one name short makes read.table use the first column as row
  ## names; keep it as a column, so row numbers in messages stay the visible ones
  if (!identical(rownames(d), as.character(seq_len(nrow(d))))) {
    d <- cbind(Label = rownames(d), d, stringsAsFactors = FALSE)
    rownames(d) <- NULL
  }
  d[] <- lapply(d, convert_lossless)
  names(d) <- make.names(names(d), unique = TRUE)
  d
}

## data.frame -> plain HTML table (used by the integrated-means view & report)
df_html <- function(df, caption = NULL, foot = NULL, digits = 3) {
  num <- vapply(df, is.numeric, logical(1))
  int <- names(df) %in% c("n", "N", "Df") | vapply(df, is.integer, logical(1))
  df[num & !int] <- lapply(df[num & !int], function(z) fmt(z, digits))
  df[num & int]  <- lapply(df[num & int],
    function(z) ifelse(is.na(z), "-", as.character(as.integer(round(z)))))
  df[] <- lapply(df, function(z) gsub("<", "&lt;", as.character(z), fixed = TRUE))
  hdr <- paste0("<th>", names(df), "</th>", collapse = "")
  body <- paste0(apply(df, 1, function(r)
    paste0("<tr><td>", paste(r, collapse = "</td><td>"), "</td></tr>")),
    collapse = "")
  paste0(
    "<table class='doe'>",
    if (!is.null(caption)) paste0("<caption>", caption, "</caption>") else "",
    "<thead><tr>", hdr, "</tr></thead><tbody>", body, "</tbody>",
    if (!is.null(foot)) paste0("<tfoot>", foot, "</tfoot>") else "",
    "</table>")
}

anova_display <- function(an, alpha) {
  data.frame(Source = an$Source, Df = an$Df,
             `Sum of squares` = an$SS, `Mean square` = an$MS,
             `F value` = an$F,
             `p value` = p_text(an$p),
             Signif = star(an$p, alpha), check.names = FALSE)
}

## ------------------------------------------------------------- demo datasets
## Deterministic stand-in for stats::demo_noise(), used only to build the example
## datasets returned by demo_data(). A stored vector of standardised deviates is
## recycled instead of drawing random numbers, so the examples are identical on
## every machine and the user's random number stream is left untouched. The
## vector has prime length, so recycling cannot line up with the block, plot or
## treatment structure of any of the example designs.
demo_noise <- function(n, mean = 0, sd = 1) {
  z <- c(
    1.148, 0.655, 0.101, 0.001, 1.317, 1.446, 0.718,
    0.083, -0.971, -0.872, -1.400, 0.655, 1.004, 0.486,
    -2.939, 0.063, -0.688, 0.641, -1.337, -1.727, 1.300,
    0.508, 1.206, 0.001, 0.586, -1.277, 0.092, 0.863,
    -1.769, 0.100, -1.178, -0.107, -0.280, 1.361, -0.274,
    0.579, 0.529, -0.265, -0.343, 0.616, -0.633)
  mean + sd * rep_len(z, n)
}

#' Example datasets for each design
#'
#' Generates a small, balanced example dataset for a design, so you can try
#' DOEpro without your own data. These are the datasets behind the
#' \strong{Load example} button in the application.
#'
#' @param which The example to build: \code{"CRD"}, \code{"RCBD"}, \code{"LSD"},
#'   \code{"FRCBD"} (factorial), \code{"SPLIT"}, \code{"STRIP"},
#'   \code{"POOLRCBD"} or \code{"POOLCRD"} (a single treatment factor over
#'   environments), \code{"POOLFACT"} or \code{"POOLFACTC"} (factorial
#'   treatments over environments, RCBD and CRD base respectively).
#'
#' @return A data frame in long format, ready to pass to \code{\link{analyze}}.
#'
#' @examples
#' head(demo_data("RCBD"))
#' str(demo_data("SPLIT"))
#'
#' @export
demo_data <- function(which) {
  switch(which,
    "CRD" = {
      d <- expand.grid(Rep = 1:4, Treatment = paste0("T", 1:5))
      d$Yield <- round(demo_noise(nrow(d), rep(c(28, 31, 35, 30, 40), each = 4), 2.2), 2)
      d[, c("Treatment", "Rep", "Yield")]
    },
    "RCBD" = {
      d <- expand.grid(Block = paste0("B", 1:4), Variety = paste0("V", 1:6))
      d$Yield <- round(demo_noise(nrow(d), rep(c(42, 47, 39, 55, 50, 44), each = 4) +
                               rep(c(-1.5, 0, 1, 0.5), 6), 2.0), 2)
      d[, c("Block", "Variety", "Yield")]
    },
    "LSD" = {
      d <- expand.grid(Row = paste0("R", 1:4), Column = paste0("C", 1:4))
      d$Treatment <- c("A","B","C","D","B","C","D","A",
                       "C","D","A","B","D","A","B","C")
      d$Yield <- round(demo_noise(16, c(20, 24, 27, 22)[
        match(d$Treatment, c("A","B","C","D"))], 1.4), 2)
      d[, c("Row", "Column", "Treatment", "Yield")]
    },
    "FRCBD" = {
      d <- expand.grid(Block = paste0("B", 1:3),
                       Nitrogen = c("N0", "N60", "N120"),
                       Variety  = c("V1", "V2"))
      mu <- 30 + c(0, 6, 9)[as.integer(d$Nitrogen)] +
            c(0, 4)[as.integer(d$Variety)] +
            ifelse(d$Variety == "V2" & d$Nitrogen == "N120", 5, 0)
      d$Yield <- round(demo_noise(nrow(d), mu, 1.8), 2)
      d[, c("Block", "Nitrogen", "Variety", "Yield")]
    },
    "SPLIT" = {
      d <- expand.grid(Rep = paste0("R", 1:4),
                       Irrigation = c("I1", "I2", "I3"),
                       Variety    = c("V1", "V2", "V3", "V4"))
      mu <- 40 + c(0, 5, 8)[as.integer(d$Irrigation)] +
            c(0, 3, 6, 2)[as.integer(d$Variety)] +
            ifelse(d$Irrigation == "I3" & d$Variety == "V3", 4, 0)
      wp <- demo_noise(12, 0, 2.0)[as.integer(interaction(d$Rep, d$Irrigation))]
      d$Yield <- round(mu + wp + demo_noise(nrow(d), 0, 1.3), 2)
      d[, c("Rep", "Irrigation", "Variety", "Yield")]
    },
    "STRIP" = {
      d <- expand.grid(Rep = paste0("R", 1:4),
                       Tillage = c("Conventional", "Minimum", "Zero"),
                       Mulch   = c("M0", "M1", "M2", "M3"))
      mu <- 25 + c(0, 2, -3)[as.integer(d$Tillage)] +
            c(0, 3, 5, 6)[as.integer(d$Mulch)] +
            ifelse(d$Tillage == "Zero" & d$Mulch %in% c("M2", "M3"), 2.5, 0)
      ea <- demo_noise(12, 0, 1.0)[as.integer(interaction(d$Rep, d$Tillage))]
      eb <- demo_noise(16, 0, 0.8)[as.integer(interaction(d$Rep, d$Mulch))]
      d$Yield <- round(mu + ea + eb + demo_noise(nrow(d), 0, 0.9), 2)
      d[, c("Rep", "Tillage", "Mulch", "Yield")]
    },
    "POOLRCBD" = {
      d <- expand.grid(Rep = paste0("R", 1:3),
                       Variety = c("V1", "V2", "V3", "V4"),
                       Location = c("Shalimar", "Wadura", "Zampathan"))
      loc  <- c(0, 4, -3)[as.integer(d$Location)]        # site effect
      var  <- c(0, 3, 6, 4)[as.integer(d$Variety)]       # variety effect
      vxl  <- ifelse(d$Location == "Zampathan" & d$Variety %in% c("V3", "V4"), 3.5, 0) +
              ifelse(d$Location == "Wadura" & d$Variety == "V2", 2.0, 0)  # V x L
      repe <- demo_noise(9, 0, 1.1)[as.integer(interaction(d$Rep, d$Location))]
      d$Yield <- round(28 + loc + var + vxl + repe + demo_noise(nrow(d), 0, 1.0), 2)
      d[, c("Location", "Rep", "Variety", "Yield")]
    },
    "POOLCRD" = {
      d <- expand.grid(Rep = 1:4,
                       Treatment = c("T1", "T2", "T3", "T4"),
                       Season = c("Kharif", "Rabi", "Zaid"))
      sea <- c(0, 5, -4)[as.integer(d$Season)]
      trt <- c(0, 4, 7, 5)[as.integer(d$Treatment)]
      txs <- ifelse(d$Season == "Zaid" & d$Treatment %in% c("T3", "T4"), 3.0, 0)
      d$Yield <- round(22 + sea + trt + txs + demo_noise(nrow(d), 0, 1.3), 2)
      d[, c("Season", "Treatment", "Yield")]
    },
    "POOLFACT" = {                                   # 2-factor factorial over locations (RCBD)
      d <- expand.grid(Rep = paste0("R", 1:3),
                       Nitrogen = c("N0", "N1"),
                       Variety  = c("V1", "V2", "V3"),
                       Location = c("Shalimar", "Wadura", "Zampathan"))
      loc <- c(0, 4, -3)[as.integer(d$Location)]
      nit <- c(0, 5)[as.integer(d$Nitrogen)]
      var <- c(0, 3, 6)[as.integer(d$Variety)]
      nxv <- ifelse(d$Nitrogen == "N1" & d$Variety == "V3", 2.5, 0)           # N x V
      nxl <- ifelse(d$Nitrogen == "N1" & d$Location == "Zampathan", -2.0, 0)  # N x Location
      rep_e <- demo_noise(9, 0, 1.0)[as.integer(interaction(d$Rep, d$Location))]
      d$Yield <- round(26 + loc + nit + var + nxv + nxl + rep_e +
                       demo_noise(nrow(d), 0, 1.0), 2)
      d[, c("Location", "Rep", "Nitrogen", "Variety", "Yield")]
    },
    "POOLFACTC" = {                                  # 2-factor factorial over seasons (CRD)
      d <- expand.grid(Rep = 1:4,
                       Spacing = c("S1", "S2"),
                       Variety = c("V1", "V2", "V3"),
                       Season  = c("Kharif", "Rabi", "Zaid"))
      sea <- c(0, 5, -4)[as.integer(d$Season)]
      sp  <- c(0, 3)[as.integer(d$Spacing)]
      var <- c(0, 4, 7)[as.integer(d$Variety)]
      sxv <- ifelse(d$Spacing == "S2" & d$Variety == "V3", 3.0, 0)
      d$Yield <- round(24 + sea + sp + var + sxv + demo_noise(nrow(d), 0, 1.3), 2)
      d[, c("Season", "Spacing", "Variety", "Yield")]
    }
  )
}

## ------------------------------------------------------------ ANOVA helpers
tidy_aov <- function(fit) {
  a <- summary(fit)[[1]]
  ## with no error degrees of freedom summary() has no F column; say so later
  ## in words rather than fail here
  data.frame(Source = trimws(rownames(a)), Df = a[["Df"]], SS = a[["Sum Sq"]],
             MS = a[["Mean Sq"]],
             F = if (is.null(a[["F value"]])) NA_real_ else a[["F value"]],
             p = if (is.null(a[["Pr(>F)"]])) NA_real_ else a[["Pr(>F)"]],
             check.names = FALSE)
}

tidy_aovlist <- function(fit) {
  s <- summary(fit)
  out <- lapply(names(s), function(nm) {
    a <- s[[nm]][[1]]
    data.frame(Stratum = nm, Source = trimws(rownames(a)), Df = a[["Df"]],
               SS = a[["Sum Sq"]], MS = a[["Mean Sq"]],
               F = if (is.null(a[["F value"]])) NA_real_ else a[["F value"]],
               p = if (is.null(a[["Pr(>F)"]])) NA_real_ else a[["Pr(>F)"]],
               check.names = FALSE)
  })
  do.call(rbind, out)
}

## residual mean square + df of a given stratum
strat_res <- function(tab, stratum) {
  r <- tab[tab$Stratum == stratum & tab$Source == "Residuals", ]
  list(ms = r$MS[1], df = r$Df[1], ss = r$SS[1])
}

t_weighted <- function(w1, t1, w2, t2) (w1 * t1 + w2 * t2) / (w1 + w2)

## Bartlett's test of homogeneity of k error variances, each an s^2 with df
## degrees of freedom (as they arise from k separate error mean squares).
## Used in combined analysis to decide whether the errors may be pooled.
bartlett_ms <- function(df, s2) {
  ok <- is.finite(df) & is.finite(s2) & df > 0 & s2 > 0
  df <- df[ok]; s2 <- s2[ok]; k <- length(s2)
  if (k < 2) return(NULL)
  N <- sum(df); sp2 <- sum(df * s2) / N
  num <- N * log(sp2) - sum(df * log(s2))
  C <- 1 + (sum(1 / df) - 1 / N) / (3 * (k - 1))
  chisq <- num / C
  list(chisq = chisq, df = k - 1, p = stats::pchisq(chisq, k - 1, lower.tail = FALSE),
       pooled_var = sp2, k = k)
}

## Factor levels in natural order: numbers inside labels compare as numbers, so
## D0, D60, D120, D180 and T1, T2, ..., T10 come out in the order people mean
## rather than the alphabetical D0, D120, D180, D60. A column that is already a
## factor keeps the order it was given; a numeric column sorts numerically.
natural_levels <- function(x) {
  if (is.factor(x)) return(levels(droplevels(x)))
  if (is.numeric(x)) return(levels(factor(x)))
  u <- unique(as.character(x[!is.na(x)]))
  if (!length(u)) return(u)
  ## a thousands separator is part of the number (1,000 ppm); a decimal comma
  ## (5,6) is left for the data checks to flag
  s <- gsub("(?<=[0-9]),(?=[0-9]{3}([^0-9]|$))", "", u, perl = TRUE)
  ## a sign belongs to the number only when it stands apart from the letters
  ## and digits before it: "-20 C" is negative, "SR-1" and "0-15 cm" are not
  num <- "(?:(?<![[:alnum:].])[-+])?[0-9]+(?:[.][0-9]+)?"
  m <- gregexpr(num, s, perl = TRUE)
  hits <- regmatches(s, m)
  ## each number is replaced by its zero-padded rank among all the numbers, so
  ## numbers of any size or sign compare correctly as text
  vals <- sort(unique(as.numeric(unlist(hits))))
  w <- nchar(length(vals))
  regmatches(s, m) <- lapply(hits, function(h)
    formatC(match(as.numeric(h), vals), width = w, flag = "0"))
  ## a label without a number beside numbered ones is usually the control or
  ## the starting point (Control, Fresh, Local check), so it comes first
  plain <- lengths(hits) == 0
  first <- if (sum(!plain) >= 2 && any(plain)) ifelse(plain, "0", "1") else ""
  u[order(paste0(first, tolower(s)), u, method = "radix")]
}

## cell means for a set of factors
eff_means <- function(d, resp, vars) {
  agg <- stats::aggregate(d[[resp]], by = d[vars], FUN = mean)
  names(agg)[ncol(agg)] <- "Mean"
  agg$N <- stats::aggregate(d[[resp]], by = d[vars], FUN = length)$x
  agg$SD <- stats::aggregate(d[[resp]], by = d[vars], FUN = stats::sd)$x
  agg[do.call(order, agg[vars]), , drop = FALSE]
}

## one label per row of a table of means, naming its level(s), as shown to the
## user and used for the dimnames of an effect's SE(d) and C.D. matrices
level_key <- function(df, vars)
  do.call(paste, c(lapply(df[vars], as.character), sep = " : "))

## the same, joined by a character that cannot appear in data, for matching
## cells internally: two cells whose level names contain " : " could otherwise
## share a label and be merged
cell_key <- function(df, vars)
  do.call(paste, c(lapply(df[vars], as.character), sep = "\u001f"))

## Least-squares (adjusted) means of `vars` from a fitted linear model, with
## their covariance matrix, in the order of `keys`. Each mean averages the
## model's predictions over every level of the other factors with equal weight,
## so a treatment that lost a plot is not pulled up or down by the block that
## plot was in, and a marginal mean is not weighted by unequal cell sizes. With
## complete, balanced data these are the plain averages with variance MSE / n.
## Base R only: the model matrix of a reference grid, coef() and vcov().
ls_means <- function(fit, vars, keys) {
  xl <- fit$xlevels
  grid <- expand.grid(xl, KEEP.OUT.ATTRS = FALSE, stringsAsFactors = FALSE)
  for (v in names(xl)) grid[[v]] <- factor(grid[[v]], levels = xl[[v]])
  X <- stats::model.matrix(stats::delete.response(stats::terms(fit)), grid,
                           contrasts.arg = fit$contrasts)
  g <- cell_key(grid, vars)
  L <- rowsum(X, g, reorder = FALSE) / as.vector(table(g)[unique(g)])
  L <- L[match(keys, rownames(L)), , drop = FALSE]
  ## a mean is estimable only if its row of L lies in the row space of the
  ## data's model matrix; otherwise the data cannot separate it from the blocks
  Xd <- stats::model.matrix(fit)
  off <- qr.resid(qr(t(Xd)), t(L))
  if (any(abs(off) > 1e-8 * max(1, abs(L))))
    stop("Some means cannot be estimated: the treatments that are present never ",
         "appear together in a block, so their differences cannot be separated ",
         "from the block differences.", call. = FALSE)
  b <- stats::coef(fit); ok <- !is.na(b)
  Lk <- L[, ok, drop = FALSE]
  V <- Lk %*% stats::vcov(fit)[ok, ok, drop = FALSE] %*% t(Lk)
  list(est = drop(Lk %*% b[ok]), V = V)
}

## One effect's table of means, with the standard errors and critical
## differences for every comparison. Every standard error comes from V, the
## covariance matrix of the means: SE(m)_i = sqrt(V_ii) and
## SE(d)_ij = sqrt(V_ii + V_jj - 2 V_ij). Without a fitted model the means are
## plain averages with V = diag(MSE / n_i), so with unequal replication each
## mean and each pair still gets its own value. Given `fit`, the means are
## least-squares means and V comes from the model, which is what blocked
## designs with a missing plot and factorials with unequal cells need.
new_effect <- function(d, resp, vars, mse, df, p, Fv, alpha, label = NULL, fit = NULL) {
  m <- eff_means(d, resp, vars)
  key <- level_key(m, vars)
  notes <- character(0)
  if (is.null(fit)) {
    V <- diag(mse / m$N, nrow(m))
  } else {
    ls <- ls_means(fit, vars, cell_key(m, vars))
    V <- ls$V
    if (any(abs(ls$est - m$Mean) > 1e-8 * max(1, abs(m$Mean)))) {
      m$Raw_mean <- m$Mean
      m$Mean <- unname(ls$est)
      notes <- paste0("The data are unbalanced, so these are adjusted (least-squares) ",
        "means: each is estimated as if every level had appeared in every block and ",
        "alongside every level of the other factors. The plain average of the data ",
        "is shown as the unadjusted mean.")
    }
  }
  dv <- diag(V)
  S <- sqrt(pmax(outer(dv, dv, "+") - 2 * V, 0))
  diag(S) <- 0
  dimnames(S) <- list(key, key)
  tq <- stats::qt(1 - alpha / 2, df)
  C <- tq * S
  m$SE <- sqrt(dv)
  m$Letter <- cld_lsd(m$Mean, C)
  e <- list(label = label %||% paste(vars, collapse = " x "), vars = vars,
            means = m, mse = mse, df = df, alpha = alpha, tcrit = tq,
            p = p, F = Fv, notes = notes)
  set_errors(e, m$SE, S, C)
}

## Attach the standard errors to an effect: the per-mean SE (already a column
## of the means), the SE(d) and C.D. matrices, and single values sem, sed and cd
## only when one number genuinely applies to every mean and every pair. When it
## does not they are NA, the range is kept for display, and equal_rep is FALSE,
## so no table can print one SE that fits some means and not others.
set_errors <- function(e, se, S, C) {
  off <- row(S) != col(S)
  sd_ <- S[off]; sd_ <- sd_[!is.na(sd_)]
  cd_ <- C[off]; cd_ <- cd_[!is.na(cd_)]
  same <- function(x) length(x) > 0 && diff(range(x)) <= 1e-9 * max(abs(x))
  one <- function(x) if (same(x)) x[1] else NA_real_
  n <- e$means$N
  e$sem <- one(se); e$sed <- one(sd_); e$cd <- one(cd_)
  e$se_range <- range(se)
  e$sed_range <- if (length(sd_)) range(sd_) else c(NA_real_, NA_real_)
  e$cd_range <- if (length(cd_)) range(cd_) else c(NA_real_, NA_real_)
  e$equal_rep <- same(se) && same(sd_)
  e$n_per_mean <- if (length(unique(n)) == 1L) n[1] else NA_real_
  e$sed_mat <- S; e$cd_mat <- C
  e
}

## An interaction effect from a design with several error strata (split plot,
## strip plot, pooled analysis). Only comparisons inside one level of `slice`
## share a single standard error, so the SE(d) and C.D. matrices are filled for
## those pairs and left NA across slices; letters and post-hoc tests then work
## one slice at a time. These designs are analysed only when complete, so every
## within-slice comparison has the same SE(d). The SE column here is the
## conventional SE(m) for those comparisons, SE(d) / sqrt(2), not the standard
## error of a cell mean on its own, which would also carry the main-plot (or
## environment) variation; plots and tables say so. `extra` holds the SE(d) and
## C.D. of the other comparisons, and `extra_p` the p-value that gates each
## C.D. (NA for an SE(d), which is always shown).
slice_effect <- function(m, vars, slice, label, se, sed, tcrit, mse, df, alpha,
                         p, Fv, extra, notes, ...) {
  key <- level_key(m, vars)
  k <- nrow(m)
  inside <- outer(as.character(m[[slice]]), as.character(m[[slice]]), "==")
  S <- matrix(NA_real_, k, k, dimnames = list(key, key))
  S[inside] <- sed
  diag(S) <- 0
  m$SE <- rep(se, k)
  e <- c(list(label = label, vars = vars, means = m, mse = mse, df = df,
              alpha = alpha, tcrit = tcrit, p = p, F = Fv, slice = slice,
              extra = extra, notes = notes), list(...))
  set_errors(e, m$SE, S, tcrit * S)
}

## An effect's further comparisons (e$extra) as label and display text, each
## C.D. replaced by "NS" when the F-test it belongs to is not significant.
extra_text <- function(e, digits = 3) {
  if (is.null(e$extra)) return(NULL)
  v <- unlist(e$extra)
  p <- if (is.null(e$extra_p)) rep(NA_real_, length(v)) else e$extra_p
  txt <- ifelse(!is.na(p) & !(p < e$alpha), "NS", fmt(v, digits))
  stats::setNames(txt, names(e$extra))
}

## Two-sided critical t for an effect at level alpha: plain t on the effect's
## error df, or, for a comparison whose standard error mixes two error terms,
## the weighted t of Gomez & Gomez (1984) stored in t_mix.
t_crit <- function(e, alpha) {
  if (is.null(e$t_mix)) return(stats::qt(1 - alpha / 2, e$df))
  w <- e$t_mix$w
  sum(w * stats::qt(1 - alpha / 2, e$t_mix$df)) / sum(w)
}
`%||%` <- function(a, b) if (is.null(a)) b else a

## ---------------------------------------------------------- data_quality.R ----
###############################################################################
##  DATA QUALITY
###############################################################################
## Checks run on the data as soon as it is loaded, before any analysis. Each
## problem is described in plain words with the rows it affects and, where a
## correction is safe, what that correction will be. Nothing is changed until
## the user asks, and then only entry by entry: a value is rewritten only when
## its meaning is certain (5,6 is 5.6; "n/a" means no value). An entry whose
## meaning is not certain (12a, nil, 1,250, a word among numbers, a % sign on
## some entries only) is never changed or emptied; it is listed for the user,
## and an analysis that cannot use it says so.

## what people type for "no value", including the error values Excel pastes
## along with the data. "nil" is not here: in field records it usually means
## zero, so it is shown to the user instead.
MISSING_MARKS <- c("na", "n/a", "n.a.", "n.a", "missing", "-", "--", "---",
                   ".", "?", "*", "nd", "n.d.", "#n/a", "#value!", "#div/0!",
                   "#num!", "#ref!", "#name?", "#null!")

## Units that may follow a number in a column of measurements. Only these are
## recognised, so that a variety such as "1121 Basmati", a stage such as
## "30 DAS" or DMRT letters such as "12ab" are never taken for units.
KNOWN_UNITS <- c("kg", "g", "mg", "t", "q", "qt", "ha", "cm", "mm", "m", "km",
                 "m2", "cm2", "mm2", "ml", "l", "kg/ha", "q/ha", "t/ha", "g/plant",
                 "g/m2", "kg/m2", "kg/plot", "g/plot", "ppm", "ppb", "ds/m",
                 "mg/kg", "mg/l", "mg/g", "g/kg")

## user text going into HTML: "<LOD" must show as text, not open a tag
esc <- function(x) {
  x <- gsub("&", "&amp;", x, fixed = TRUE)
  x <- gsub("<", "&lt;", x, fixed = TRUE)
  gsub(">", "&gt;", x, fixed = TRUE)
}

## one or many: pl(1, "row", "rows")
pl <- function(n, one, many) if (n == 1) one else many

## the row numbers shown in the data table, which are the data frame's row
## names, so that numbers in messages are ones the user can find
row_ids <- function(d) {
  id <- suppressWarnings(as.integer(rownames(d)))
  if (anyNA(id)) seq_len(nrow(d)) else id
}

## "row 3" or "rows 3, 7 and 12" (at most eight listed)
rows_text <- function(i) {
  if (!length(i)) return("")
  paste(pl(length(i), "row", "rows"), join_and(head_more(as.character(i), 8)))
}

## a few entries, quoted, saying "such as" when there are more
eg_text <- function(x) {
  u <- unique(x)
  paste0(if (length(u) > 3) "such as " else "", join_and(sprintf("'%s'", head(u, 3))))
}

## a number as it will be written back: as many digits as it needs, no more
## (never in scientific notation: 400000, not 4e+05, which would also be
## written into the data by a correction)
num_text <- function(v) vapply(v, function(z) format(z, digits = 15, trim = TRUE, scientific = FALSE), "")

## rows with no value in any cell: empty, or holding only entries such as "-"
## or "n/a", so that one pass of the corrections removes them
empty_rows <- function(d) {
  if (!nrow(d) || !ncol(d)) return(integer(0))
  which(Reduce(`&`, lapply(d, function(x) {
    s <- trimws(as.character(x))
    is.na(x) | s == "" | tolower(s) %in% MISSING_MARKS
  })))
}

## a label tidied of spacing only: no-break spaces made plain, runs of spaces
## made single, the ends trimmed. Nothing else in a label is touched; a dash
## or a capital letter may carry meaning.
label_tidy <- function(x) {
  s <- as.character(x)
  for (ch in ODD_SPACES) s <- gsub(ch, " ", s, fixed = TRUE)
  gsub("[[:space:]]+", " ", trimws(s))
}

## Characters that look like a minus sign or a space but are not the plain
## ones: the minus sign and en dash from Word, the no-break spaces Excel puts
## between thousands. Built here rather than written into the source, which
## must stay ASCII.
ODD_MINUS  <- intToUtf8(c(0x2212, 0x2013), multiple = TRUE)
ODD_SPACES <- intToUtf8(c(0x00A0, 0x202F, 0x2009), multiple = TRUE)

## How the number part of an entry reads (no % sign or unit attached).
read_core <- function(core) {
  n <- length(core)
  kind <- rep("text", n); value <- rep(NA_real_, n)
  num <- function(v) suppressWarnings(as.numeric(v))
  plain <- grepl("^[-+]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][-+]?[0-9]+)?$", core)
  ## 1,250 may be a thousands separator or a decimal comma; 0,125 cannot be
  ## thousands, so it is a decimal comma
  three <- grepl("^[-+]?[1-9][0-9]{0,2},[0-9]{3}$", core)
  comma <- grepl("^[-+]?[0-9]+,[0-9]+$", core) & !three
  thous <- grepl("^[-+]?[1-9][0-9]{0,2}(,[0-9]{3})+([.][0-9]+)?$", core) & !three
  space <- grepl("^[-+]?[1-9][0-9]{0,2}( [0-9]{3})+([.,][0-9]+)?$", core)
  euro  <- grepl("^[-+]?[1-9][0-9]{0,2}([.][0-9]{3})+,[0-9]+$", core)
  value[plain] <- num(core[plain])
  value[comma] <- num(sub(",", ".", core[comma], fixed = TRUE))
  value[thous] <- num(gsub(",", "", core[thous], fixed = TRUE))
  value[space] <- num(sub(",", ".", gsub(" ", "", core[space], fixed = TRUE), fixed = TRUE))
  value[euro]  <- num(sub(",", ".", gsub(".", "", core[euro], fixed = TRUE), fixed = TRUE))
  kind[plain] <- "number"; kind[comma] <- "comma"; kind[thous | space] <- "thousands"
  kind[euro] <- "european"; kind[three] <- "ambiguous"
  list(kind = kind, value = value)
}

## How each entry reads as a number. `kind` is one of
##   blank      empty
##   mark       a no-value marker such as n/a, - or #DIV/0!
##   number     a plain number with a decimal point (5.6, -2, 1e3)
##   comma      a decimal comma (5,6; 0,125; 1234,5)
##   ambiguous  1,250: a thousands separator or a decimal comma
##   thousands  1,250,000; 1,250.5; 1 250
##   european   1.250,5 (point between thousands, decimal comma)
##   percent    45% or 4,5 %
##   unit       a number followed by a known unit (45 cm, 2.5kg, 12 q/ha)
##   text       anything else
## `value` is the number it would be, `text` the entry tidied of odd spaces and
## minus signs, `unit` the unit text, and `core` the kind of the number part of
## an entry with a % sign or a unit.
read_entries <- function(x) {
  s <- as.character(x)
  s[is.na(s)] <- ""
  for (ch in ODD_SPACES) s <- gsub(ch, " ", s, fixed = TRUE)
  for (ch in ODD_MINUS) s <- gsub(ch, "-", s, fixed = TRUE)
  s <- trimws(s)
  n <- length(s)
  pct <- grepl("^[-+]?[0-9][0-9., ]*%$", s)
  sci <- grepl("^[-+]?([0-9]+([.][0-9]*)?|[.][0-9]+)[eE][-+]?[0-9]+$", s)
  ut  <- ifelse(!pct & !sci, sub("^[-+]?[0-9][0-9.,]* ?", "", s), "")
  ## a known unit, with a space before it or at least two letters (45 cm,
  ## 2.5kg): a single letter stuck to a number (5m, 12a) may well be a code
  unit <- !pct & !sci & grepl("^[-+]?[0-9][0-9.,]*( [A-Za-z]|[A-Za-z]{2})[A-Za-z/0-9]*$", s) &
          tolower(ut) %in% KNOWN_UNITS
  core <- s
  core[pct] <- trimws(sub("%$", "", s[pct]))
  core[unit] <- sub("^([-+]?[0-9][0-9.,]*) ?[A-Za-z].*$", "\\1", s[unit])
  r <- read_core(core)
  kind <- r$kind; value <- r$value; ckind <- r$kind
  ok <- !ckind %in% c("text", "ambiguous")
  kind[pct & ok] <- "percent"
  kind[unit & ok] <- "unit"
  kind[(pct | unit) & !ok] <- ifelse(ckind[(pct | unit) & !ok] == "ambiguous", "ambiguous", "text")
  un <- rep("", n)
  un[unit] <- ut[unit]
  un[pct] <- "%"
  kind[tolower(s) %in% MISSING_MARKS & s != ""] <- "mark"
  kind[s == ""] <- "blank"
  value[!kind %in% c("number", "comma", "thousands", "european", "percent", "unit")] <- NA_real_
  list(kind = kind, value = value, text = s, unit = un, core = ckind)
}

NUMBER_KINDS <- c("number", "comma", "ambiguous", "thousands", "european", "percent", "unit")

## A response as the analysis uses it: a column of numbers as it is; a column
## of text read entry by entry, keeping only entries that are plainly numbers.
## Anything the data check would flag (5,6; 45%; 0x10; 12a) is left out, with
## the reason recorded by excluded_rows().
response_values <- function(x) {
  if (is.numeric(x)) return(x)
  r <- read_entries(x)
  ifelse(r$kind == "number", r$value, NA_real_)
}

## Everything the check and the corrections need to know about one column.
## A column is read as numbers when at least three quarters of its filled-in,
## non-marker entries read as numbers in some notation, and as labels when
## fewer than a quarter do; in between it is a mixture the user should see.
## `new` holds each entry's corrected form, or NA where nothing is changed.
assess_column <- function(x) {
  raw <- as.character(x)
  r <- read_entries(x)
  k <- r$kind; txt <- r$text
  real <- !k %in% c("blank", "mark")
  share <- if (any(real)) mean(k[real] %in% NUMBER_KINDS) else 0
  role <- if (!any(real)) "empty" else if (share >= 0.75) "numbers" else
          if (share >= 0.25) "mixed" else "labels"
  ## which notation the column writes its decimals in; an entry like 1.250 is
  ## not evidence of decimal points, since it is the very thing in doubt
  dot3_pat <- "^[-+]?[0-9]{1,3}([.][0-9]{3})+$"
  dot_dec <- any((k == "number" & grepl(".", txt, fixed = TRUE) & !grepl(dot3_pat, txt)) |
                 (k == "thousands" & grepl("[.][0-9]+$", txt)) |
                 (k %in% c("percent", "unit") & r$core == "number" & grepl(".", txt, fixed = TRUE)))
  comma_dec <- any(k %in% c("comma", "european") |
                   (k == "thousands" & grepl(",[0-9]+$", txt) & grepl(" ", txt, fixed = TRUE)) |
                   (k %in% c("percent", "unit") & r$core == "comma"))
  sep <- any(k == "thousands" & grepl(",[0-9]{3}", txt))
  ## 1,250 is settled by the rest of the column: decimal commas and no
  ## decimal points means a decimal; decimal points or separators and no
  ## decimal commas means a thousands separator; both or neither, the user
  ## must say
  three <- if (comma_dec && !dot_dec && !sep) "comma" else
           if ((dot_dec || sep) && !comma_dec) "thousands" else NA_character_
  ## in a column written with decimal commas, 1.250 is the mirror image
  dot3_rows <- if (comma_dec && !dot_dec) which(k == "number" & grepl(dot3_pat, txt)) else integer(0)
  ## a % sign or a unit is dropped only when every number in the column
  ## carries it (and, for units, the same one): 62% beside 0.45 and 0.50, or
  ## 1.5 kg beside 1500, may be on another scale. Entries such as 1,250 kg
  ## count too.
  numlike <- k %in% NUMBER_KINDS
  has_pct <- r$unit == "%"
  has_unit <- r$unit != "" & !has_pct
  units <- unique(r$unit[has_unit & numlike])
  all_pct <- any(has_pct & numlike) && all(has_pct[numlike])
  all_unit <- length(units) == 1 && all(has_unit[numlike])
  val <- r$value
  amb <- k == "ambiguous"
  ## While a 1,250 or a 1.250 waits for the user, no other number in the
  ## column is rewritten: changing 5,6 to 5.6 would change the evidence, and a
  ## second press of the button would then settle the doubtful entry by itself.
  hold <- (any(amb) && is.na(three)) || length(dot3_rows) > 0
  if (any(amb) && !is.na(three)) {
    cr <- sub(" ?%$", "", sub(" ?[A-Za-z].*$", "", txt[amb]))
    val[amb] <- suppressWarnings(as.numeric(
      if (three == "comma") sub(",", ".", cr, fixed = TRUE) else gsub(",", "", cr, fixed = TRUE)))
  }
  sign_ok <- (!has_unit & !has_pct) | (has_unit & all_unit) | (has_pct & all_pct)
  new <- rep(NA_character_, length(k))
  if (role == "numbers" && !hold) {
    change <- (k %in% c("comma", "thousands", "european") & sign_ok) |
              (k %in% c("percent", "unit") & sign_ok) | (amb & !is.na(three) & sign_ok) |
              (k == "number" & !is.na(raw) & txt != trimws(raw))       # odd minus or spaces
    new[change] <- num_text(val[change])
  }
  list(r = r, kind = k, txt = txt, raw = raw, role = role, share = share, three = three,
       dot3_rows = dot3_rows, all_pct = all_pct, all_unit = all_unit, units = units,
       has_pct = has_pct, has_unit = has_unit, hold = hold, value = val, new = new)
}

## The checks on labels (used for columns of labels and for mixtures): extra
## spaces, which are certainly a slip and are tidied; and labels that differ
## only in capitals or punctuation, which can carry meaning (genotypes AA, Aa,
## aa; codes T1 and T-1) and are therefore shown, never merged.
label_issues <- function(v, a, keep, at, add) {
  real <- intersect(which(!a$kind %in% c("blank", "mark")), keep)
  if (!length(real)) return(invisible())
  tidy <- label_tidy(a$raw)
  sp <- real[!is.na(a$raw[real]) & a$raw[real] != tidy[real]]
  if (length(sp))
    add(v, "correct", sprintf(paste0("In '%s', %s %s extra spaces in the label (%s). ",
      "They will be removed so that %s the same label as the rest."), v, rows_text(at(sp)),
      pl(length(sp), "has", "have"), eg_text(a$raw[sp]),
      pl(length(sp), "it counts as", "they count as")), at(sp))
  if (length(real) < 2) return(invisible())
  lab <- tidy[real]
  g1 <- split(real, tolower(lab))
  g1 <- g1[vapply(g1, function(i) length(unique(tidy[i])) > 1, logical(1))]
  if (length(g1)) {
    ex <- head_more(vapply(g1, function(i) join_and(sprintf("'%s'", unique(tidy[i]))), ""), 4)
    add(v, "check", sprintf(paste0("In '%s', some labels differ only in capital letters (%s), so ",
      "the analysis treats them as different groups. If they are the same, retype them in the ",
      "table so they match exactly."), v, paste(ex, collapse = "; ")),
      at(sort(unlist(g1))), fixable = FALSE)
  }
  ## the same letters and the same numbers written with different spacing or
  ## punctuation (T1, T-1, T 1); labels whose numbers differ (1.5 kg and
  ## 15 kg, -10 and 10) are not grouped
  nums <- vapply(regmatches(lab, gregexpr("(?<![[:alnum:].])[-+]?[0-9]+([.][0-9]+)?|[0-9]+([.][0-9]+)?",
                                          lab, perl = TRUE)), paste, "", collapse = "|")
  key <- paste(gsub("[^[:alpha:]]", "", tolower(lab)), nums)
  g2 <- split(real, key)
  g2 <- g2[vapply(g2, function(i) length(unique(tolower(tidy[i]))) > 1, logical(1))]
  if (length(g2)) {
    ## one spelling for each way of writing it, ignoring capitals (those are
    ## reported above), with the rows that use exactly that spelling
    rep_rows <- lapply(g2, function(i) {
      cls <- split(i, tolower(tidy[i]))
      unlist(lapply(cls, function(j) { tb <- table(tidy[j]); j[tidy[j] == names(tb)[which.max(tb)]] }))
    })
    ex <- head_more(vapply(rep_rows, function(i) {
      u <- unique(tidy[i])
      join_and(sprintf("'%s' (%s)", u, vapply(u, function(z) rows_text(at(i[tidy[i] == z])), "")))
    }, ""), 4)
    add(v, "check", sprintf(paste0("In '%s', some labels differ only in spaces or punctuation: %s. ",
      "The analysis treats them as different groups. If they are the same, retype them in the ",
      "table so they match exactly."), v, paste(ex, collapse = "; ")),
      at(sort(unlist(rep_rows))), fixable = FALSE)
  }
}

#' Check data for common entry problems
#'
#' Looks through every column for the problems that most often spoil an
#' analysis of field data: numbers written with a decimal comma, decimal points
#' and commas mixed in one column, thousands separators, per cent signs and
#' units typed after numbers, numbers stored as text, entries that are not
#' numbers, empty cells and the markers people type for them (such as n/a or
#' Excel's #DIV/0!), labels that differ only in spacing, capitals or
#' punctuation, and empty or repeated rows. Each problem is described with the
#' rows it affects and, where a correction is safe, what the correction would
#' be. Nothing is changed; see \code{\link{fix_data}}.
#'
#' @param d A data frame, as loaded.
#'
#' @return A list with \code{issues}, a list with one element per problem
#'   (\code{column}; \code{level}: \code{"correct"} for a correction
#'   \code{\link{fix_data}} will make, \code{"check"} for something only the
#'   user can settle, \code{"note"} for information; \code{message};
#'   \code{rows}, as row numbers of the data; \code{fixable}), and
#'   \code{numeric} and \code{labels}, the columns read as numbers and as
#'   labels.
#'
#' @examples
#' d <- data.frame(Variety = c("V1", "V1", "V2", "V2"),
#'                 Yield = c("5,6", "6.1", "n/a", "12a"))
#' chk <- check_data(d)
#' vapply(chk$issues, `[[`, "", "message")
#'
#' @export
check_data <- function(d) {
  issues <- list()
  add <- function(column, level, message, rows = integer(0), fixable = level == "correct")
    issues[[length(issues) + 1L]] <<- list(column = column, level = level, message = message,
                                           rows = rows, fixable = fixable)
  ids <- row_ids(d)
  numeric_cols <- character(0); label_cols <- character(0)

  empty <- empty_rows(d)
  if (length(empty))
    add(NA, "correct", sprintf("%s %s no values and will be removed.",
      sub("^r", "R", rows_text(ids[empty])), pl(length(empty), "has", "have")), ids[empty])
  keep <- setdiff(seq_len(nrow(d)), empty)
  at <- function(i) ids[intersect(i, keep)]

  for (v in names(d)) {
    x <- d[[v]]
    if (is.numeric(x)) {
      numeric_cols <- c(numeric_cols, v)
      miss <- at(which(is.na(x)))
      if (length(miss))
        add(v, "note", sprintf("In '%s', %s %s empty, so %s left out of any analysis that uses '%s'.",
          v, rows_text(miss), pl(length(miss), "is", "are"), pl(length(miss), "it is", "they are"), v), miss)
      next
    }
    a <- assess_column(x)
    k <- a$kind; txt <- a$txt
    marks <- function() {
      w <- intersect(which(k == "mark"), keep)
      if (length(w))
        add(v, "correct", sprintf(paste0("In '%s', %s %s %s, meaning no value. %s will be emptied ",
          "and treated as missing. If a value meant zero, type 0 instead."), v, rows_text(at(w)),
          pl(length(w), "has", "have"), eg_text(txt[w]), pl(length(w), "It", "They")), at(w))
    }
    blanks <- function() {
      w <- at(which(k == "blank"))
      if (length(w))
        add(v, "note", sprintf("In '%s', %s %s empty, so %s left out of any analysis that uses '%s'.",
          v, rows_text(w), pl(length(w), "is", "are"), pl(length(w), "it is", "they are"), v), w)
    }
    if (a$role == "empty") {
      if (any(k == "mark")) { label_cols <- c(label_cols, v); marks() }
      else add(v, "note", sprintf("Column '%s' is empty.", v))
      next
    }

    if (a$role == "numbers") {
      numeric_cols <- c(numeric_cols, v)
      hp <- a$has_pct & k %in% NUMBER_KINDS; hu <- a$has_unit & k %in% NUMBER_KINDS
      ## while a doubtful entry waits for the user, the column's other number
      ## corrections wait too (see assess_column); say what is waiting
      pend <- if (a$hold) c(
        if (any(k[keep] == "comma")) "decimal commas",
        if (any(k[keep] %in% c("thousands", "european"))) "thousands separators",
        if (any(hp[keep])) "% signs", if (any(hu[keep])) "units") else character(0)
      waiting <- if (length(pend)) sprintf(" The other corrections to '%s' (%s) will be offered once this is settled.",
                                           v, join_and(pend)) else ""
      if (!a$hold) {
        w <- intersect(which(k == "comma"), keep)
        if (length(w))
          add(v, "correct", sprintf(paste0("In '%s', %s %s written with a decimal comma (%s)%s. ",
            "%s will be changed to %s, so %s becomes %s."), v, rows_text(at(w)),
            pl(length(w), "is", "are"), eg_text(txt[w]),
            if (any(k == "number" & grepl(".", txt, fixed = TRUE))) ", while other entries use a decimal point" else "",
            pl(length(w), "The comma", "The commas"), pl(length(w), "a point", "points"),
            txt[w[1]], a$new[w[1]]), at(w))
        w <- intersect(which(k == "thousands"), keep)
        if (length(w))
          add(v, "correct", sprintf(paste0("In '%s', %s %s a separator between the thousands (%s). ",
            "It will be removed, so %s becomes %s."), v, rows_text(at(w)),
            pl(length(w), "has", "have"), eg_text(txt[w]), txt[w[1]], a$new[w[1]]), at(w))
        w <- intersect(which(k == "european"), keep)
        if (length(w))
          add(v, "correct", sprintf(paste0("In '%s', %s %s written with a point between the thousands ",
            "and a decimal comma (%s). %s will be read the usual way, so %s becomes %s."),
            v, rows_text(at(w)), pl(length(w), "is", "are"), eg_text(txt[w]),
            pl(length(w), "It", "They"), txt[w[1]], a$new[w[1]]), at(w))
        w <- intersect(which(hp), keep)
        if (length(w) && a$all_pct)
          add(v, "correct", sprintf(paste0("In '%s', every value has a %% sign (%s). The signs will be ",
            "dropped, so %s becomes %s."), v, eg_text(txt[w]), txt[w[1]], a$new[w[1]]), at(w))
        w <- intersect(which(hu), keep)
        if (length(w) && a$all_unit)
          add(v, "correct", sprintf(paste0("In '%s', every value has the unit '%s' after it. It will be ",
            "dropped, so %s becomes %s; consider putting the unit in the column name."),
            v, a$units[1], txt[w[1]], a$new[w[1]]), at(w))
        w <- intersect(which(k == "number" & !is.na(a$new)), keep)
        if (length(w))
          add(v, "correct", sprintf(paste0("In '%s', %s %s a minus sign or space typed with an unusual ",
            "character (%s). %s will be written the usual way, as %s."), v, rows_text(at(w)),
            pl(length(w), "has", "have"), eg_text(a$raw[w]), pl(length(w), "It", "They"),
            join_and(head(a$new[w], 3))), at(w))
      }
      w <- intersect(which(hp), keep)
      if (length(w) && !a$all_pct)
        add(v, "check", sprintf(paste0("In '%s', %s %s a %% sign (%s) but other values do not, so they ",
          "may be on a different scale (62%% beside 0.45 could be 0.62). Make them consistent in the ",
          "table; until then %s left out of any analysis of '%s'."), v, rows_text(at(w)),
          pl(length(w), "has", "have"), eg_text(txt[w]), pl(length(w), "it is", "they are"), v),
          at(w), fixable = FALSE)
      w <- intersect(which(hu), keep)
      if (length(w) && !a$all_unit)
        add(v, "check", if (length(a$units) > 1)
          sprintf(paste0("In '%s', the values carry different units (%s). Convert them to one unit, ",
            "without the unit text, in the table; until then %s left out of any analysis of '%s'."),
            v, eg_text(txt[w]), pl(length(w), "that row is", "those rows are"), v)
          else sprintf(paste0("In '%s', %s %s the unit '%s' after the number but other values have none, ",
            "so they may be on a different scale. Make them consistent in the table; until then %s ",
            "left out of any analysis of '%s'."), v, rows_text(at(w)), pl(length(w), "has", "have"),
            a$units[1], pl(length(w), "it is", "they are"), v), at(w), fixable = FALSE)
      w <- intersect(which(k == "ambiguous"), keep)
      two <- function(z) { z <- sub(" ?%$", "", sub(" ?[A-Za-z].*$", "", z))
        c(gsub(",", "", z, fixed = TRUE), sub(",", ".", z, fixed = TRUE)) }
      w2 <- w[!is.na(a$new[w])]                 # settled, and their sign or unit can go
      if (length(w2) && !is.na(a$three))
        add(v, "correct", sprintf(paste0("In '%s', %s (%s) could mean %s or %s. %s will be read as %s, ",
          "because the rest of the column uses %s. If that is wrong, retype %s in the table."),
          v, rows_text(at(w2)), eg_text(txt[w2]), two(txt[w2[1]])[1], two(txt[w2[1]])[2],
          pl(length(w2), "It", "They"), a$new[w2[1]],
          if (a$three == "comma") "decimal commas" else "decimal points or thousands separators",
          pl(length(w2), "it", "them")), at(w2))
      else if (length(w) && is.na(a$three))
        add(v, "check", sprintf(paste0("In '%s', %s (%s) could mean %s or %s, and the rest of the ",
          "column does not show which. Retype %s as %s or as %s, whichever you meant; until then ",
          "%s left out of any analysis of '%s'.%s"), v, rows_text(at(w)), eg_text(txt[w]),
          two(txt[w[1]])[1], two(txt[w[1]])[2], pl(length(w), "it", "each"),
          two(txt[w[1]])[1], two(txt[w[1]])[2], pl(length(w), "it is", "they are"), v, waiting),
          at(w), fixable = FALSE)
      w <- intersect(a$dot3_rows, keep)
      if (length(w))
        add(v, "check", sprintf(paste0("In '%s', %s (%s) could mean %s or %s: the rest of the column ",
          "uses decimal commas, where a point usually separates thousands. Retype %s as %s or as %s, ",
          "whichever you meant.%s"), v, rows_text(at(w)), eg_text(txt[w]),
          gsub(".", "", txt[w[1]], fixed = TRUE), txt[w[1]], pl(length(w), "it", "each"),
          gsub(".", "", txt[w[1]], fixed = TRUE), txt[w[1]],
          if (any(k[keep] == "ambiguous") && is.na(a$three)) "" else waiting),
          at(w), fixable = FALSE)
      nil <-intersect(which(k == "text" & tolower(txt) %in% c("nil", "none", "zero")), keep)
      if (length(nil))
        add(v, "check", sprintf(paste0("In '%s', %s %s %s. If %s zero, type 0; if %s no value, clear ",
          "the cell. Until then %s left out of any analysis of '%s'."), v, rows_text(at(nil)),
          pl(length(nil), "has", "have"), eg_text(txt[nil]), pl(length(nil), "it means", "they mean"),
          pl(length(nil), "it means", "they mean"), pl(length(nil), "that row is", "those rows are"), v),
          at(nil), fixable = FALSE)
      w <- setdiff(intersect(which(k == "text"), keep), nil)
      if (length(w)) {
        recurs <- any(duplicated(tolower(txt[w])))
        add(v, "check", sprintf(paste0("'%s' is mostly numbers, but %s %s %s (%s).%s If '%s' holds ",
          "measurements, correct %s in the table; until then %s left out of any analysis of '%s'."),
          v, rows_text(at(w)), pl(length(w), "has", "have"),
          pl(length(w), "an entry that is not a number", "entries that are not numbers"), eg_text(txt[w]),
          if (recurs) sprintf(" That is fine if '%s' holds labels, such as treatment codes with a check.", v)
          else "", v, pl(length(w), "it", "them"), pl(length(w), "that row is", "those rows are"), v),
          at(w), fixable = FALSE)
      }
      if (!any(k[keep] %in% c("comma", "thousands", "european", "percent", "unit", "ambiguous",
                              "text", "mark")) && !length(a$dot3_rows))
        add(v, "correct", sprintf(paste0("'%s' contains only numbers but is being read as text. It ",
          "will be changed to a column of numbers."), v))
      marks(); blanks()
      next
    }

    label_cols <- c(label_cols, v)
    if (a$role == "mixed") {
      w <- intersect(which(!k %in% c(NUMBER_KINDS, "blank", "mark")), keep)
      add(v, "check", sprintf(paste0("'%s' is being read as labels, not numbers, because %d of its %d ",
        "filled-in entries %s (%s). If it should hold numbers, correct %s in the table."), v,
        length(w), sum(!k[keep] %in% c("blank", "mark")),
        pl(length(w), "is not a number", "are not numbers"), eg_text(txt[w]),
        pl(length(w), "that entry", "those entries")), at(w), fixable = FALSE)
    }
    marks(); blanks()
    label_issues(v, a, keep, at, add)
  }

  ## identical rows: often two plots that happen to have the same values, so
  ## this is information, not an error
  if (length(keep) > 1) {
    rk <- do.call(paste, c(lapply(d[keep, , drop = FALSE], as.character), sep = "|"))
    grp <- split(keep, rk)
    grp <- grp[lengths(grp) > 1]
    if (length(grp)) {
      sets <- vapply(grp, function(i) join_and(as.character(ids[i])), "")
      rest <- sets[-1]
      more <- if (!length(rest)) "" else paste0(", and so are rows ",
        paste(head(rest, 3), collapse = "; rows "),
        if (length(rest) > 3) sprintf("; and %d more groups", length(rest) - 3) else "")
      add(NA, "note", sprintf(paste0("Rows %s are identical in every column%s. If a row was entered ",
        "twice, delete the extra copy in your spreadsheet and load it again; if they are separate ",
        "plots that happen to have the same values, leave them."), sets[1], more),
        ids[sort(unlist(grp))])
    }
  }
  list(issues = issues, numeric = numeric_cols, labels = label_cols)
}

#' Apply the safe corrections found by check_data
#'
#' Makes only the corrections whose meaning is certain, entry by entry:
#' decimal commas become points, thousands separators are removed, a per cent
#' sign or a unit carried by every value in a column is dropped, entries such
#' as n/a or - are emptied, extra spaces in labels are removed, and empty rows
#' are deleted. A column becomes a column of numbers once every entry in it is
#' a number. Entries whose meaning is not certain, such as 12a, nil, or 1,250
#' where the column does not show which notation it uses, are left exactly as
#' they are, and labels that differ in capitals or punctuation are not merged.
#'
#' @param d A data frame, as loaded.
#'
#' @return A list with \code{data}, the corrected data frame (row names kept,
#'   so row numbers still match the data as loaded), and \code{log}, a
#'   character vector saying what was changed.
#'
#' @examples
#' d <- data.frame(Variety = c("V1", "V1", "V2", "V2"),
#'                 Yield = c("5,6", "6.1", "n/a", "7,2"))
#' fix_data(d)
#'
#' @export
fix_data <- function(d) {
  log <- character(0)
  ids <- row_ids(d)
  empty <- empty_rows(d)
  keep <- setdiff(seq_len(nrow(d)), empty)
  for (v in names(d)) {
    x <- d[[v]]
    if (is.numeric(x)) next
    a <- assess_column(x)
    k <- a$kind
    out <- a$raw
    say <- function(w, what) if (length(w))
      log <<- c(log, sprintf("'%s': %s (%s).", v, what, rows_text(ids[w])))
    if (a$role == "numbers") {
      ch <- intersect(which(!is.na(a$new)), keep)
      out[ch] <- a$new[ch]
      say(intersect(which(k == "comma"), ch), "decimal commas changed to points")
      say(intersect(which(k %in% c("thousands", "european")), ch), "thousands separators removed")
      say(intersect(which(k == "percent"), ch), "per cent signs dropped")
      say(intersect(which(k == "unit"), ch), sprintf("the unit '%s' dropped", a$units[1]))
      say(intersect(which(k == "ambiguous"), ch),
          if (identical(a$three, "comma")) "entries such as 1,250 read as decimals"
          else "entries such as 1,250 read as thousands")
      say(intersect(which(k == "number"), ch), "unusual minus signs or spaces tidied")
    }
    mk <- intersect(which(k == "mark"), keep)
    out[mk] <- NA
    say(mk, "entries meaning no value emptied")
    if (a$role %in% c("labels", "mixed")) {
      tidy <- label_tidy(a$raw)
      sp <- intersect(which(!is.na(out) & out != tidy & !k %in% c("blank", "mark")), keep)
      out[sp] <- tidy[sp]
      say(sp, "extra spaces removed from labels")
    }
    ## a column of numbers in which every entry is now certainly a number
    ## becomes one; the values come from the parsed entries, so nothing that
    ## reads as a number is lost in the conversion
    if (a$role == "numbers") {
      after <- read_entries(out[keep])
      if (all(after$kind %in% c("number", "blank")) && !length(a$dot3_rows)) {
        num <- rep(NA_real_, length(out)); num[keep] <- after$value
        out <- num
        log <- c(log, sprintf("'%s' is now a column of numbers.", v))
      } else if (length(intersect(which(!is.na(a$new) | k == "mark"), keep)))
        log <- c(log, sprintf(paste0("'%s' still has entries that are not certain numbers, so it ",
          "stays as text until they are corrected (see 'Needs you to decide')."), v))
    }
    if (is.numeric(out)) d[[v]] <- out
    else if (!identical(out, a$raw)) {
      d[[v]] <- if (is.factor(x)) {
        ## keep the order the factor's levels had, under their new spellings
        old <- vapply(levels(x), function(l) { i <- match(l, a$raw); if (is.na(i)) NA_character_ else out[i] }, "")
        factor(out, levels = unique(c(stats::na.omit(old), unique(stats::na.omit(out)))))
      } else out
    }
  }
  if (length(empty)) {
    log <- c(log, sprintf("%s had no values and %s removed; the other rows keep their numbers.",
      sub("^r", "R", rows_text(ids[empty])), pl(length(empty), "has been", "have been")))
    d <- d[-empty, , drop = FALSE]
    ## a level used only in a removed row would linger in a factor otherwise
    d[] <- lapply(d, function(z) if (is.factor(z)) droplevels(z) else z)
  }
  list(data = d, log = log)
}

## The data check as HTML for the Data tab: green when nothing needs the
## user, otherwise the problems grouped as what can be corrected, what needs
## the user and what is for information.
check_html <- function(chk, d) {
  is_ <- chk$issues
  lv <- vapply(is_, `[[`, character(1), "level")
  cols <- function(x) join_and(sprintf("<b>%s</b>", esc(x)))
  head_ <- paste0(sprintf("%d %s and %d %s.", nrow(d), pl(nrow(d), "row", "rows"),
                          ncol(d), pl(ncol(d), "column", "columns")),
                  if (length(chk$numeric)) paste0(" Read as numbers: ", cols(chk$numeric), ".") else "",
                  if (length(chk$labels)) paste0(" Read as labels: ", cols(chk$labels), ".") else "")
  if (!length(is_))
    return(paste0("<div class='sugbox'><b>Data check: no problems found.</b> ", head_, "</div>"))
  block <- function(level, title)
    if (any(lv == level)) paste0("<p><b>", title, "</b></p><ul>",
      paste0("<li>", esc(vapply(is_[lv == level], `[[`, character(1), "message")), "</li>",
             collapse = ""), "</ul>") else ""
  paste0("<div class='", if (any(lv %in% c("correct", "check"))) "warn" else "sugbox", "'>",
         "<b>Data check.</b> ", head_,
         block("correct", "Can be corrected for you"),
         block("check", "Needs you to decide"),
         block("note", "For information"),
         "</div>")
}

## Whether double quotes in some lines of data are real quoting or inch marks
## (12" pot). Real quoting always leaves an even number of quotes on a line;
## an inch mark leaves an odd number, and reading it as a quote would swallow
## the rest of the line and the next ones. So quotes are honoured only when
## every line has an even number of them.
quote_char <- function(lines) {
  n <- lengths(regmatches(lines, gregexpr("\"", lines, fixed = TRUE)))
  if (any(n %% 2 == 1)) "" else "\""
}

## Turn a column of text into numbers only when nothing is lost: labels such
## as 1.1 and 1.10, or 01 and 1, must not become the same number. Anything
## else stays as text for the data check to look at.
convert_lossless <- function(col) {
  if (!is.character(col)) return(col)
  conv <- utils::type.convert(col, as.is = TRUE, na.strings = c("NA", ""))
  if (!is.numeric(conv)) return(conv)
  s <- trimws(col); ok <- !is.na(col) & s != ""
  if (length(unique(s[ok])) > length(unique(conv[ok]))) col else conv
}

## Read an uploaded CSV. The separator is the one (comma, semicolon or tab)
## that splits every line into the same number of fields, at least two; a
## comma file with unquoted decimal commas, which would be cut apart wrongly,
## is refused with a reason. An inch mark (12" pot) that opens a quoted field
## and swallows lines is read again without quoting. Text that looks like
## numbers is converted only when nothing is lost, so the data check sees
## decimal commas and no-value markers as typed.
read_upload <- function(path) {
  counts <- function(s, q) tryCatch({
    n <- utils::count.fields(path, sep = s, quote = q, comment.char = "", blank.lines.skip = TRUE)
    n[!is.na(n)] }, error = function(e) integer(0))
  pick <- function(q) {
    fits <- vapply(c(",", ";", "\t"), function(s) {
      n <- counts(s, q); if (length(n) && all(n == n[1]) && n[1] > 1) n[1] else 0L }, integer(1))
    if (any(fits > 0)) c(",", ";", "\t")[which.max(fits)] else NA_character_
  }
  quote <- quote_char(readLines(path, warn = FALSE))
  sep <- pick(quote)
  if (is.na(sep)) {
    one <- vapply(c(",", ";", "\t"), function(s) { n <- counts(s, ""); length(n) > 0 && all(n == 1) }, logical(1))
    if (!all(one))
      stop(paste0("The lines of this file do not all have the same number of values. This usually ",
                  "means numbers with decimal commas in a comma-separated file. Save it from Excel as ",
                  "'CSV (semicolon delimited)', or copy the cells and use the paste box."), call. = FALSE)
    sep <- ";"
  }
  d <- utils::read.csv(path, sep = sep, stringsAsFactors = FALSE, check.names = FALSE,
                       na.strings = c("NA", ""), strip.white = TRUE, row.names = NULL,
                       quote = quote, comment.char = "", colClasses = "character")
  d[] <- lapply(d, convert_lossless)
  names(d) <- make.names(names(d), unique = TRUE)
  d
}

## Rows left out of an analysis and why: one record for each row and column
## that had no usable value. `raw` is the data as supplied, `d` the same rows
## after the response was read as numbers and no-value markers in the factors
## were emptied, `keep` the columns the analysis needs.
excluded_rows <- function(raw, d, keep) {
  miss <- is.na(as.matrix(d[, keep, drop = FALSE]))
  drop <- which(rowSums(miss) > 0)
  if (!length(drop)) return(NULL)
  idx <- which(miss[drop, , drop = FALSE], arr.ind = TRUE)
  r <- drop[idx[, 1]]; cols <- keep[idx[, 2]]
  vals <- vapply(seq_along(r), function(j) {
    z <- raw[[cols[j]]][r[j]]; if (is.na(z)) "" else trimws(as.character(z)) }, "")
  out <- data.frame(row = row_ids(raw)[r], column = cols, kind = read_entries(vals)$kind,
                    value = vals, stringsAsFactors = FALSE, row.names = NULL)
  out[order(out$row), , drop = FALSE]
}

## "3 rows were left out of this analysis: Yield is written with a decimal
## comma in rows 1 and 4 ('6,5' and '7,2'); Yield is empty in row 9." Grouped
## by column and reason so a long list reads as a few sentences. `html`
## escapes the user's entries; `hint` adds what to do in the app.
excluded_text <- function(ex, html = FALSE, hint = FALSE) {
  if (is.null(ex) || !nrow(ex)) return("")
  n <- length(unique(ex$row))
  grp <- split(ex, paste(ex$column, ex$kind))
  grp <- grp[order(vapply(grp, function(g) min(g$row), numeric(1)))]
  parts <- vapply(grp, function(g) {
    v <- g$column[1]; rr <- rows_text(unique(g$row)); eg <- eg_text(g$value)
    switch(g$kind[1],
      blank = sprintf("%s is empty in %s", v, rr),
      mark = sprintf("%s is marked as having no value in %s (%s)", v, rr, eg),
      comma = sprintf("%s is written with a decimal comma in %s (%s)", v, rr, eg),
      ambiguous = sprintf("%s could be read two ways in %s (%s)", v, rr, eg),
      percent = sprintf("%s has a %% sign in %s (%s)", v, rr, eg),
      unit = sprintf("%s has a unit after the number in %s (%s)", v, rr, eg),
      thousands = , european = sprintf("%s has a thousands separator in %s (%s)", v, rr, eg),
      sprintf("%s is not a number in %s (%s)", v, rr, eg))
  }, "")
  out <- sprintf("%d %s left out of this analysis: %s.", n, pl(n, "row was", "rows were"),
                 paste(parts, collapse = "; "))
  ## what to do in the app, only where something can be done: decimal commas
  ## and separators are corrected by the button; entries that are not numbers,
  ## doubtful ones and partial units or % signs need the user
  if (hint) {
    fixable <- any(ex$kind %in% c("comma", "thousands", "european"))
    manual <- any(ex$kind %in% c("text", "ambiguous", "percent", "unit"))
    if (fixable)
      out <- paste(out, "To include the rows with decimal commas or thousands separators, press 'Apply the corrections' on the Data tab.")
    if (manual)
      out <- paste(out, sprintf("To include %s, correct those entries in the table on the Data tab, where the data check lists them.",
                                if (fixable) "the others" else "these rows"))
    if (fixable || manual) out <- paste(out, "Then run the analysis again.")
  }
  if (html) esc(out) else out
}

## ---------------------------------------------------------- analyze.R ----
###############################################################################
##  MAIN ANALYSIS ENGINE
###############################################################################
#' Analyse one response from a designed experiment
#'
#' Fits the analysis of variance for a single response variable and returns the
#' means, standard errors and critical differences for every legitimate
#' comparison the design allows.
#'
#' The error term is chosen to match the design. A split plot is fitted with
#' \code{Error(rep/main)} and a strip plot with \code{Error(rep/(A+B))}, so the
#' main-plot and sub-plot comparisons are each tested against their own error;
#' the two mixed comparisons use a weighted \emph{t}. In a pooled (combined)
#' analysis over environments, each treatment effect is tested against its own
#' interaction with the environment, and each environment by treatment
#' interaction against the pooled error.
#'
#' Unequal replication is handled exactly in the designs with a single error
#' term (CRD, RCBD, Latin square and the factorials): each mean gets its own
#' standard error and each pair of means its own standard error of a difference
#' and critical difference. When blocks are incomplete or factorial cells are
#' unequal, the means are adjusted (least-squares) means and every term is
#' tested adjusted for all the others (Type III). Designs with several error
#' strata (split plot, strip plot and the pooled analyses) can only be analysed
#' exactly when they are complete; with a plot missing \code{analyze()} stops
#' and says which combinations are missing.
#'
#' @param d A data frame in long format: one row per plot, with columns for the
#'   design factors and the response. Text factor columns are put in natural
#'   order (D0, D60, D120; T1, T2, ..., T10), with a label carrying no number,
#'   such as Control, placed first; a column that is already a factor keeps its
#'   levels, so supply a factor to fix an order such as Vegetative, Flowering,
#'   Maturity.
#' @param design The design code. One of the values of \code{\link{DESIGNS}},
#'   for example \code{"RCBD"}, \code{"SPLIT"} or \code{"POOLFRCBD"}.
#' @param map A named list mapping roles to column names of \code{d}. Always
#'   needs \code{response}. Then, by design: \code{treat} (CRD, RCBD, LSD);
#'   \code{block} (RCBD, factorial RCBD); \code{row}, \code{col} (LSD);
#'   \code{factors}, a character vector of two to four column names (factorial);
#'   \code{rep}, \code{main}, \code{sub} (split and strip plots); \code{env}
#'   together with \code{treat} or \code{factors}, and \code{rep} for an RCBD
#'   base (pooled designs).
#' @param alpha The significance level. It sets the critical differences, the
#'   grouping letters and the significance of every F-test. Defaults to 0.05.
#'
#' @return A list with, among others:
#'   \describe{
#'     \item{\code{anova}}{The analysis of variance table.}
#'     \item{\code{effects}}{One entry per effect. Each holds \code{means}, the
#'       table of means with columns \code{Mean}, \code{N}, \code{SD}, \code{SE}
#'       (the standard error of that mean), the grouping letters and, when the
#'       means are adjusted, \code{Raw_mean}; \code{sed_mat} and \code{cd_mat},
#'       the standard error of the difference and the critical difference for
#'       every pair of means; \code{sem}, \code{sed} and \code{cd}, single
#'       values that are \code{NA} when replication is unequal and they differ
#'       from mean to mean (\code{equal_rep} is then \code{FALSE}, and
#'       \code{se_range}, \code{sed_range} and \code{cd_range} give the range);
#'       \code{mse} and \code{df}, the error mean square and degrees of freedom
#'       the effect is tested against; \code{p}, \code{F} and \code{alpha}. The
#'       interaction of a split plot, strip plot or pooled analysis also has
#'       \code{slice}, the factor within whose levels its means are compared:
#'       its \code{SE}, \code{sed} and \code{cd} apply to those comparisons,
#'       \code{sed_mat} and \code{cd_mat} are \code{NA} across levels of
#'       \code{slice}, and \code{extra} gives the standard errors and critical
#'       differences of the other comparisons.}
#'     \item{\code{mse}, \code{dfe}}{The error mean square and its degrees of
#'       freedom.}
#'     \item{\code{balanced}}{Whether every cell of the design holds the same
#'       number of observations.}
#'     \item{\code{cv}, \code{grand}, \code{resid}, \code{lm}}{The coefficient of
#'       variation, grand mean, residuals and the fitted linear model.}
#'   }
#'
#' @seealso \code{\link{run_all}} to analyse several responses at once, and
#'   \code{\link{build_report}} to render the result.
#'
#' @examples
#' d <- demo_data("RCBD")
#' res <- analyze(d, "RCBD", list(response = "Yield", treat = "Variety",
#'                                block = "Block"))
#' res$anova
#' res$effects[["Variety"]]$means
#'
#' @export
analyze <- function(d, design, map, alpha = 0.05) {
  if (!is.numeric(alpha) || length(alpha) != 1L || is.na(alpha) ||
      alpha <= 0 || alpha >= 0.5)
    stop("The significance level must be a single number between 0 and 0.5, such as 0.05.")
  resp <- map$response
  raw <- d                                  # as supplied, for saying why rows were left out
  ## the response is read the way the data check reads it, so an entry the
  ## check calls "not a number" (0x10, 5,6, 45%) is left out here too, and a
  ## number typed with an unusual minus sign is still read
  d[[resp]] <- response_values(d[[resp]])

  facs <- switch(design,
    CRD = map$treat, RCBD = map$treat, LSD = map$treat,
    FCRD = map$factors, FRCBD = map$factors,
    SPLIT = c(map$main, map$sub), STRIP = c(map$main, map$sub),
    POOLRCBD = c(map$env, map$treat), POOLCRD = c(map$env, map$treat),
    POOLFRCBD = c(map$env, map$factors), POOLFCRD = c(map$env, map$factors))
  blks <- switch(design,
    CRD = character(0), RCBD = map$block, LSD = c(map$row, map$col),
    FCRD = character(0), FRCBD = map$block, SPLIT = map$rep, STRIP = map$rep,
    POOLRCBD = map$rep, POOLCRD = character(0),
    POOLFRCBD = map$rep, POOLFCRD = character(0))

  ## the tables of means add columns with these names, so a design factor
  ## called N (for nitrogen, say) would be overwritten by the counts
  clash <- intersect(c(facs, blks), RESERVED_COLS)
  if (length(clash))
    stop(sprintf(paste0("A column used as a design factor is called %s, a name DOEpro ",
      "uses in its tables of means. Please rename it (for example 'Nitrogen' rather ",
      "than 'N') and run the analysis again."), join_and(sprintf("'%s'", clash))),
      call. = FALSE)
  keep <- unique(c(resp, facs, blks))
  ## an empty label, or one such as "-" or "n/a" typed for no value, is a
  ## missing factor, not a treatment or block of its own
  for (v in c(facs, blks)) {
    s <- trimws(as.character(d[[v]]))
    gone <- is.na(s) | s == "" | tolower(s) %in% MISSING_MARKS
    if (any(gone)) { x <- as.character(d[[v]]); x[gone] <- NA; d[[v]] <- x }
  }
  ## rows without a usable response or factor are left out, and recorded with
  ## the reason, so the user is told rather than finding fewer plots
  excluded <- excluded_rows(raw, d, keep)
  d <- d[stats::complete.cases(d[, keep, drop = FALSE]), keep, drop = FALSE]
  why <- function() if (is.null(excluded)) "" else paste0(" ", excluded_text(excluded))
  if (nrow(d) < 3)
    stop(paste0(if (nrow(d) == 0) "No rows can be analysed." else
                  sprintf("Only %d %s can be analysed; at least 3 are needed.", nrow(d),
                          pl(nrow(d), "row", "rows")), why()), call. = FALSE)
  ## levels in natural order, so tables and plots run D0, D60, D120 and
  ## T1, T2, ..., T10 instead of alphabetically
  for (v in c(facs, blks)) d[[v]] <- factor(d[[v]], levels = natural_levels(d[[v]]))

  ## a layout refused because rows were left out says so first: correcting
  ## those entries may be all that is needed, before anything is deleted
  lay <- tryCatch(check_layout(d, design, map, facs, blks), error = function(e) {
    if (is.null(excluded)) stop(conditionMessage(e), call. = FALSE)
    stop(paste0(excluded_text(excluded), " With those rows left out, the layout is ",
                "incomplete. Correct those entries first if you can. ", conditionMessage(e)),
         call. = FALSE)
  })
  grand <- mean(d[[resp]])
  res <- list(design = design, resp = resp, data = d, facs = facs, blks = blks,
              alpha = alpha, grand = grand, balanced = lay$balanced,
              reps = lay$reps, n_range = lay$n_range, excluded = excluded)

  ## ------------------------------------------------- classic / factorial ----
  if (design %in% c("CRD", "RCBD", "LSD", "FCRD", "FRCBD")) {
    rhs <- paste(c(blks, paste(facs, collapse = "*")), collapse = " + ")
    form <- stats::as.formula(paste(resp, "~", rhs))
    fit <- stats::aov(form, data = d)
    an  <- tidy_aov(fit)
    mse <- an$MS[an$Source == "Residuals"]
    dfe <- an$Df[an$Source == "Residuals"]
    if (!length(dfe) || dfe < 1)
      stop(paste0("There are too few rows to estimate the experimental error: each treatment ",
                  "needs to appear more than once.", why()), call. = FALSE)
    lmfit <- stats::lm(form, data = d)
    if (!lay$balanced) an <- type3_anova(an, form, d, c(blks, facs))

    effs <- list()
    for (k in seq_along(facs)) {
      for (v in utils::combn(facs, k, simplify = FALSE)) {
        lab <- paste(v, collapse = ":")
        row <- an[an$Source == lab, ]
        effs[[lab]] <- new_effect(d, resp, v, mse, dfe,
                                  if (nrow(row)) row$p[1] else NA,
                                  if (nrow(row)) row$F[1] else NA, alpha,
                                  label = paste(v, collapse = " x "),
                                  fit = if (lay$balanced) NULL else lmfit)
      }
    }
    res$anova <- add_total(an, d[[resp]])
    ## with one treatment factor and no blocks there is nothing to adjust for:
    ## the means are the plain averages and the sums of squares still add up
    res$adjusted_ss <- !lay$balanced && length(c(blks, facs)) > 1
    res$mse <- mse; res$dfe <- dfe
    res$cv <- c("CV (%)" = 100 * sqrt(mse) / grand)
    res$effects <- effs
    res$lm <- lmfit
  }

  ## ----------------------------------------------------------- split plot ---
  if (design == "SPLIT") {
    A <- map$main; B <- map$sub; R <- map$rep
    a <- nlevels(d[[A]]); b <- nlevels(d[[B]]); r <- nlevels(d[[R]])
    f <- stats::as.formula(sprintf("%s ~ %s*%s + Error(%s/%s)", resp, A, B, R, A))
    fit <- stats::aov(f, data = d)
    tab <- tidy_aovlist(fit)
    st  <- unique(tab$Stratum)
    s_a <- paste0("Error: ", R, ":", A)
    s_w <- st[grepl("Within", st)][1]
    if (!s_a %in% st) stop("Could not identify the main-plot error stratum.")
    Ea <- strat_res(tab, s_a); Eb <- strat_res(tab, s_w)
    if (is.na(Ea$ms) || is.na(Eb$ms) || Ea$df < 1 || Eb$df < 1)
      stop("Split-plot needs at least 2 replications and 2 levels of each factor.")

    get <- function(stratum, src) {
      x <- tab[tab$Stratum == stratum & tab$Source == src, ]
      if (!nrow(x)) return(data.frame(Df = NA, SS = NA, MS = NA, F = NA, p = NA))
      x[, c("Df", "SS", "MS", "F", "p")]
    }
    rep_row <- strat_res(tab, st[1])
    rA <- get(s_a, A); rB <- get(s_w, B); rAB <- get(s_w, paste0(A, ":", B))
    an <- rbind(
      data.frame(Source = "Replication", Df = rep_row$df, SS = rep_row$ss,
                 MS = rep_row$ms, F = NA, p = NA),
      data.frame(Source = A, rA),
      data.frame(Source = "Error (a)", Df = Ea$df, SS = Ea$ss, MS = Ea$ms, F = NA, p = NA),
      data.frame(Source = B, rB),
      data.frame(Source = paste(A, "x", B), rAB),
      data.frame(Source = "Error (b)", Df = Eb$df, SS = Eb$ss, MS = Eb$ms, F = NA, p = NA))
    names(an) <- c("Source", "Df", "SS", "MS", "F", "p")
    an <- add_total(an, d[[resp]])

    ta <- stats::qt(1 - alpha / 2, Ea$df); tb <- stats::qt(1 - alpha / 2, Eb$df)

    eA <- new_effect(d, resp, A, Ea$ms, Ea$df, rA$p, rA$F, alpha, label = A)
    eB <- new_effect(d, resp, B, Eb$ms, Eb$df, rB$p, rB$F, alpha, label = B)

    ## interaction: two different comparisons
    m <- eff_means(d, resp, c(A, B))
    sed_b <- sqrt(2 * Eb$ms / r)                                   # B within same A
    sed_a <- sqrt(2 * ((b - 1) * Eb$ms + Ea$ms) / (r * b))         # A at same B
    tw  <- t_weighted((b - 1) * Eb$ms, tb, Ea$ms, ta)
    cd_b <- tb * sed_b; cd_a <- tw * sed_a
    m$Letter_within_MP <- ave_letters(m, A, m$Mean, cd_b)
    m$Letter_within_SP <- ave_letters(m, B, m$Mean, cd_a)
    cdl <- cd_name(alpha)
    eAB <- slice_effect(m, c(A, B), slice = A, label = paste(A, "x", B),
      se = sqrt(Eb$ms / r), sed = sed_b, tcrit = tb, mse = Eb$ms, df = Eb$df,
      alpha = alpha, p = rAB$p, Fv = rAB$F,
      extra = stats::setNames(list(sed_b, cd_b, sed_a, cd_a), c(
        "SE(d): two sub-plot means at the same main plot",
        paste0(cdl, ": two sub-plot means at the same main plot"),
        "SE(d): two main-plot means at the same sub plot",
        paste0(cdl, ": two main-plot means at the same sub plot"))),
      extra_p = c(NA, rAB$p, NA, rAB$p),
      notes = paste0("Letters 'within MP' compare sub-plot means inside one main plot (",
        cdl, " = ", fmt(cd_b), "). Letters 'within SP' compare main-plot means at one ",
        "sub-plot level (", cdl, " = ", fmt(cd_a), ", weighted t = ", fmt(tw, 2), ")."))

    res$anova <- an
    res$mse <- Eb$ms; res$dfe <- Eb$df
    res$cv <- c("CV(a) (%)" = 100 * sqrt(Ea$ms) / grand,
                "CV(b) (%)" = 100 * sqrt(Eb$ms) / grand)
    res$effects <- stats::setNames(list(eA, eB, eAB), c(A, B, paste0(A, ":", B)))
    res$lm <- stats::lm(stats::as.formula(
      sprintf("%s ~ %s + %s*%s + %s:%s", resp, R, A, B, R, A)), data = d)
    res$errors <- list(`Error (a)` = Ea, `Error (b)` = Eb)
  }

  ## ----------------------------------------------------------- strip plot ---
  if (design == "STRIP") {
    A <- map$main; B <- map$sub; R <- map$rep
    a <- nlevels(d[[A]]); b <- nlevels(d[[B]]); r <- nlevels(d[[R]])
    f <- stats::as.formula(sprintf("%s ~ %s*%s + Error(%s/(%s+%s))", resp, A, B, R, A, B))
    fit <- stats::aov(f, data = d)
    tab <- tidy_aovlist(fit)
    st  <- unique(tab$Stratum)
    s_a <- paste0("Error: ", R, ":", A)
    s_b <- paste0("Error: ", R, ":", B)
    s_w <- st[grepl("Within", st)][1]
    if (!all(c(s_a, s_b) %in% st)) stop("Could not identify the strip-plot error strata.")
    Ea <- strat_res(tab, s_a); Eb <- strat_res(tab, s_b); Ec <- strat_res(tab, s_w)
    if (any(is.na(c(Ea$ms, Eb$ms, Ec$ms))))
      stop("Strip plot needs >= 2 replications and >= 2 levels of each factor.")

    get <- function(stratum, src) {
      x <- tab[tab$Stratum == stratum & tab$Source == src, ]
      if (!nrow(x)) return(data.frame(Df = NA, SS = NA, MS = NA, F = NA, p = NA))
      x[, c("Df", "SS", "MS", "F", "p")]
    }
    rep_row <- strat_res(tab, st[1])
    rA <- get(s_a, A); rB <- get(s_b, B); rAB <- get(s_w, paste0(A, ":", B))
    an <- rbind(
      data.frame(Source = "Replication", Df = rep_row$df, SS = rep_row$ss,
                 MS = rep_row$ms, F = NA, p = NA),
      data.frame(Source = A, rA),
      data.frame(Source = "Error (a)", Df = Ea$df, SS = Ea$ss, MS = Ea$ms, F = NA, p = NA),
      data.frame(Source = B, rB),
      data.frame(Source = "Error (b)", Df = Eb$df, SS = Eb$ss, MS = Eb$ms, F = NA, p = NA),
      data.frame(Source = paste(A, "x", B), rAB),
      data.frame(Source = "Error (c)", Df = Ec$df, SS = Ec$ss, MS = Ec$ms, F = NA, p = NA))
    names(an) <- c("Source", "Df", "SS", "MS", "F", "p")
    an <- add_total(an, d[[resp]])

    ta <- stats::qt(1 - alpha / 2, Ea$df); tb <- stats::qt(1 - alpha / 2, Eb$df)
    tc <- stats::qt(1 - alpha / 2, Ec$df)

    eA <- new_effect(d, resp, A, Ea$ms, Ea$df, rA$p, rA$F, alpha, label = A)
    eB <- new_effect(d, resp, B, Eb$ms, Eb$df, rB$p, rB$F, alpha, label = B)

    m <- eff_means(d, resp, c(A, B))
    sed_a_at_b <- sqrt(2 * ((b - 1) * Ec$ms + Ea$ms) / (r * b))
    sed_b_at_a <- sqrt(2 * ((a - 1) * Ec$ms + Eb$ms) / (r * a))
    tw_a <- t_weighted((b - 1) * Ec$ms, tc, Ea$ms, ta)
    tw_b <- t_weighted((a - 1) * Ec$ms, tc, Eb$ms, tb)
    cd_a_at_b <- tw_a * sed_a_at_b; cd_b_at_a <- tw_b * sed_b_at_a
    m$Letter_within_A <- ave_letters(m, A, m$Mean, cd_b_at_a)
    m$Letter_within_B <- ave_letters(m, B, m$Mean, cd_a_at_b)
    ## B means at one level of A: their SE(d) mixes Error (b) and Error (c), so
    ## tests that need degrees of freedom use Satterthwaite's approximation
    w <- c((a - 1) * Ec$ms, Eb$ms); wdf <- c(Ec$df, Eb$df)
    df_s <- sum(w)^2 / sum(w^2 / wdf)
    cdl <- cd_name(alpha)
    eAB <- slice_effect(m, c(A, B), slice = A, label = paste(A, "x", B),
      se = sed_b_at_a / sqrt(2), sed = sed_b_at_a, tcrit = tw_b,
      mse = sum(w) / a, df = df_s, alpha = alpha, p = rAB$p, Fv = rAB$F,
      extra = stats::setNames(list(sed_a_at_b, cd_a_at_b, sed_b_at_a, cd_b_at_a), c(
        sprintf("SE(d): two %s means at the same level of %s", A, B),
        sprintf("%s: two %s means at the same level of %s", cdl, A, B),
        sprintf("SE(d): two %s means at the same level of %s", B, A),
        sprintf("%s: two %s means at the same level of %s", cdl, B, A))),
      extra_p = c(NA, rAB$p, NA, rAB$p),
      notes = paste0("The strip-plot interaction uses a weighted t. Letters 'within ", A,
        "' compare ", B, " means at a fixed ", A, "; letters 'within ", B, "' compare ",
        A, " means at a fixed ", B, "."),
      t_mix = list(w = w, df = wdf),
      error_desc = sprintf(paste0("Comparisons of %s means at the same level of %s ",
        "combine Error (b) and Error (c). The critical difference uses the weighted t ",
        "of Gomez &amp; Gomez; tests that need degrees of freedom use Satterthwaite's ",
        "approximation (%s df)."), B, A, fmt(df_s, 1)))

    res$anova <- an
    res$mse <- Ec$ms; res$dfe <- Ec$df
    res$cv <- c("CV(a) (%)" = 100 * sqrt(Ea$ms) / grand,
                "CV(b) (%)" = 100 * sqrt(Eb$ms) / grand,
                "CV(c) (%)" = 100 * sqrt(Ec$ms) / grand)
    res$effects <- stats::setNames(list(eA, eB, eAB), c(A, B, paste0(A, ":", B)))
    res$lm <- stats::lm(stats::as.formula(
      sprintf("%s ~ %s + %s*%s + %s:%s + %s:%s", resp, R, A, B, R, A, R, B)), data = d)
    res$errors <- list(`Error (a)` = Ea, `Error (b)` = Eb, `Error (c)` = Ec)
  }

  ## ----------------------------------------- pooled / combined over envs ----
  if (design %in% c("POOLRCBD", "POOLCRD")) {
    E <- map$env; Tf <- map$treat; R <- if (design == "POOLRCBD") map$rep else NULL
    e <- nlevels(d[[E]]); t <- nlevels(d[[Tf]])
    if (e < 2) stop("Pooled analysis needs at least two environments.")
    if (t < 2) stop("Pooled analysis needs at least two treatments.")
    r <- lay$reps                             # replications in every environment

    ## homogeneity of error variances across environments (Bartlett) -----------
    per_env <- lapply(levels(d[[E]]), function(lv) {
      di <- d[d[[E]] == lv, , drop = FALSE]
      form <- if (design == "POOLRCBD") sprintf("%s ~ %s + %s", resp, R, Tf)
              else sprintf("%s ~ %s", resp, Tf)
      a <- tryCatch(tidy_aov(stats::aov(stats::as.formula(form), data = droplevels(di))),
                    error = function(err) NULL)
      if (is.null(a)) return(c(df = NA, ss = NA))
      c(df = a$Df[a$Source == "Residuals"], ss = a$SS[a$Source == "Residuals"])
    })
    edf <- vapply(per_env, `[`, numeric(1), "df")
    ess <- vapply(per_env, `[`, numeric(1), "ss")
    hom <- bartlett_ms(edf, ess / edf)

    ## combined ANOVA via nested Error strata ---------------------------------
    f <- if (design == "POOLRCBD")
      stats::as.formula(sprintf("%s ~ %s*%s + Error(%s/%s)", resp, E, Tf, E, R))
    else stats::as.formula(sprintf("%s ~ %s*%s + Error(%s)", resp, E, Tf, E))
    fit <- stats::aov(f, data = d)
    tab <- tidy_aovlist(fit)
    st  <- unique(tab$Stratum)
    s_top <- paste0("Error: ", E)
    s_w   <- st[grepl("Within", st)][1]

    get <- function(stratum, src) {
      x <- tab[tab$Stratum == stratum & tab$Source == src, ]
      if (!nrow(x)) return(data.frame(Df = NA, SS = NA, MS = NA, F = NA, p = NA))
      x[, c("Df", "SS", "MS", "F", "p")]
    }
    Erow <- get(s_top, E)                     # Environment (e-1)
    Trow <- get(s_w, Tf)                      # Treatment (t-1)
    ETrow <- get(s_w, paste0(E, ":", Tf))     # E x T
    Eerr <- strat_res(tab, s_w)               # pooled error

    if (design == "POOLRCBD") {
      s_re <- paste0("Error: ", E, ":", R)
      RE <- strat_res(tab, s_re)              # replications within environment
      err_for_env <- RE                       # E tested against R(E)
    } else {
      RE <- NULL
      err_for_env <- Eerr                     # CRD: E tested against pooled error
    }

    ## recompute the F-tests with the CORRECT error terms ---------------------
    fp <- function(ms, dfn, msE, dfd) {
      if (any(is.na(c(ms, msE))) || msE <= 0) return(c(F = NA, p = NA))
      Fv <- ms / msE
      c(F = Fv, p = stats::pf(Fv, dfn, dfd, lower.tail = FALSE))
    }
    Fe  <- fp(Erow$MS,  Erow$Df,  err_for_env$ms, err_for_env$df)
    Ft  <- fp(Trow$MS,  Trow$Df,  ETrow$MS,       ETrow$Df)
    Fet <- fp(ETrow$MS, ETrow$Df, Eerr$ms,        Eerr$df)
    Fre <- if (!is.null(RE)) fp(RE$ms, RE$df, Eerr$ms, Eerr$df) else c(F = NA, p = NA)

    ## ANOVA table ------------------------------------------------------------
    rows <- list(data.frame(Source = paste0("Environment (", E, ")"),
                            Df = Erow$Df, SS = Erow$SS, MS = Erow$MS,
                            F = Fe["F"], p = Fe["p"]))
    if (!is.null(RE))
      rows <- c(rows, list(data.frame(Source = "Replication within environment",
                            Df = RE$df, SS = RE$ss, MS = RE$ms, F = Fre["F"], p = Fre["p"])))
    rows <- c(rows,
      list(data.frame(Source = paste0("Treatment (", Tf, ")"),
                      Df = Trow$Df, SS = Trow$SS, MS = Trow$MS, F = Ft["F"], p = Ft["p"]),
           data.frame(Source = paste0(E, " x ", Tf),
                      Df = ETrow$Df, SS = ETrow$SS, MS = ETrow$MS, F = Fet["F"], p = Fet["p"]),
           data.frame(Source = "Pooled error", Df = Eerr$df, SS = Eerr$ss,
                      MS = Eerr$ms, F = NA, p = NA)))
    an <- do.call(rbind, lapply(rows, function(z) { names(z) <- c("Source","Df","SS","MS","F","p"); z }))
    an <- add_total(an, d[[resp]])
    rownames(an) <- NULL

    ## effects with the correct error term for each comparison ----------------
    eEnv <- new_effect(d, resp, E, err_for_env$ms, err_for_env$df, unname(Fe["p"]),
                       unname(Fe["F"]), alpha, label = paste0("Environment (", E, ")"))
    eT   <- new_effect(d, resp, Tf, ETrow$MS, ETrow$Df, unname(Ft["p"]), unname(Ft["F"]),
                       alpha, label = paste0("Treatment (", Tf, ") - over environments"))

    ## E x T cell means: compare treatments within an environment (pooled error)
    m <- eff_means(d, resp, c(E, Tf))
    t_we   <- stats::qt(1 - alpha / 2, Eerr$df)
    sed_we <- sqrt(2 * Eerr$ms / r)                    # two treatments, same environment
    sed_to <- sqrt(2 * ETrow$MS / (e * r))             # two treatment means over environments
    cd_we  <- t_we * sed_we
    m$Letter_within_env <- ave_letters(m, E, m$Mean, cd_we)
    cdl <- cd_name(alpha)
    eET <- slice_effect(m, c(E, Tf), slice = E, label = paste0(E, " x ", Tf),
      se = sqrt(Eerr$ms / r), sed = sed_we, tcrit = t_we, mse = Eerr$ms, df = Eerr$df,
      alpha = alpha, p = unname(Fet["p"]), Fv = unname(Fet["F"]),
      extra = stats::setNames(list(sed_we, cd_we, sed_to,
                                   stats::qt(1 - alpha / 2, ETrow$Df) * sed_to), c(
        "SE(d): two treatments in the same environment",
        paste0(cdl, ": two treatments in the same environment"),
        "SE(d): two treatment means over all environments",
        paste0(cdl, ": two treatment means over all environments"))),
      extra_p = c(NA, unname(Fet["p"]), NA, unname(Ft["p"])),
      notes = gxe_note(Fet["p"], alpha, E, Tf, cd_we, cdl),
      env = E, is_gxe = TRUE)

    an[["F"]] <- as.numeric(an[["F"]]); an[["p"]] <- as.numeric(an[["p"]])
    res$anova <- an
    res$mse <- Eerr$ms; res$dfe <- Eerr$df
    res$cv  <- c("CV (%)" = 100 * sqrt(Eerr$ms) / grand)
    res$effects <- stats::setNames(list(eEnv, eT, eET), c(E, Tf, paste0(E, ":", Tf)))
    lm_rhs <- if (design == "POOLRCBD") sprintf("%s + %s:%s + %s*%s", E, E, R, E, Tf)
              else sprintf("%s*%s", E, Tf)
    res$lm <- stats::lm(stats::as.formula(paste(resp, "~", lm_rhs)), data = d)
    res$errors <- list(`Pooled error` = Eerr,
                       `Rep within env` = if (!is.null(RE)) RE else NULL)
    res$homogeneity <- hom
    res$pooled <- TRUE
  }

  ## ------------------------------ factorial pooled / combined over envs ------
  if (design %in% c("POOLFRCBD", "POOLFCRD")) {
    E <- map$env; fs <- map$factors; R <- if (design == "POOLFRCBD") map$rep else NULL
    e <- nlevels(d[[E]]); k <- length(fs)
    if (e < 2) stop("Pooled analysis needs at least two environments.")
    if (k < 2) stop("Factorial pooled analysis needs at least two treatment factors.")
    r <- lay$reps                             # replications in every environment

    ## homogeneity of the per-environment error variances (Bartlett) ----------
    per_env <- lapply(levels(d[[E]]), function(lv) {
      di <- droplevels(d[d[[E]] == lv, , drop = FALSE])
      rhs <- paste(fs, collapse = "*")
      form <- if (design == "POOLFRCBD") sprintf("%s ~ %s + %s", resp, R, rhs)
              else sprintf("%s ~ %s", resp, rhs)
      a <- tryCatch(tidy_aov(stats::aov(stats::as.formula(form), data = di)),
                    error = function(err) NULL)
      if (is.null(a)) return(c(df = NA, ss = NA))
      c(df = a$Df[a$Source == "Residuals"], ss = a$SS[a$Source == "Residuals"])
    })
    edf <- vapply(per_env, `[`, numeric(1), "df")
    ess <- vapply(per_env, `[`, numeric(1), "ss")
    hom <- bartlett_ms(edf, ess / edf)

    ## combined ANOVA: E crossed with the full treatment factorial -------------
    trt_rhs <- paste(fs, collapse = "*")
    f <- if (design == "POOLFRCBD")
      stats::as.formula(sprintf("%s ~ %s*(%s) + Error(%s/%s)", resp, E, trt_rhs, E, R))
    else stats::as.formula(sprintf("%s ~ %s*(%s) + Error(%s)", resp, E, trt_rhs, E))
    fit <- stats::aov(f, data = d)
    tab <- tidy_aovlist(fit)
    st  <- unique(tab$Stratum)
    s_w   <- st[grepl("Within", st)][1]
    s_top <- paste0("Error: ", E)

    ## match a source row by the *set* of its factor components ----------------
    find_src <- function(comps) {
      rows <- tab[tab$Stratum == s_w & tab$Source != "Residuals", , drop = FALSE]
      cs <- sort(comps)
      for (i in seq_len(nrow(rows)))
        if (identical(sort(strsplit(rows$Source[i], ":")[[1]]), cs)) return(rows[i, ])
      NULL
    }
    err <- strat_res(tab, s_w)                       # pooled error

    Erow <- tab[tab$Stratum == s_top & tab$Source == E, , drop = FALSE]
    if (design == "POOLFRCBD") {
      RE <- strat_res(tab, paste0("Error: ", E, ":", R)); err_env <- RE
    } else { RE <- NULL; err_env <- err }

    fp <- function(ms, dfn, msE, dfd) {
      if (any(is.na(c(ms, msE))) || msE <= 0) return(c(F = NA, p = NA))
      Fv <- ms / msE; c(F = Fv, p = stats::pf(Fv, dfn, dfd, lower.tail = FALSE))
    }
    Fe  <- fp(Erow$MS[1], Erow$Df[1], err_env$ms, err_env$df)
    Fre <- if (!is.null(RE)) fp(RE$ms, RE$df, err$ms, err$df) else c(F = NA, p = NA)

    ## every treatment effect (main effects + all interactions) ---------------
    subsets <- unlist(lapply(1:k, function(mm) utils::combn(fs, mm, simplify = FALSE)),
                      recursive = FALSE)
    trt_block <- list(); ext_block <- list(); effects <- list()
    for (S in subsets) {
      Trow  <- find_src(S)
      ETrow <- find_src(c(E, S))
      if (is.null(Trow) || is.null(ETrow)) next
      Ft  <- fp(Trow$MS,  Trow$Df,  ETrow$MS, ETrow$Df)     # treatment vs E x treatment
      Fet <- fp(ETrow$MS, ETrow$Df, err$ms,   err$df)       # E x treatment vs pooled error
      lbl <- paste(S, collapse = " x ")
      trt_block[[length(trt_block) + 1]] <- data.frame(
        Source = lbl, Df = Trow$Df, SS = Trow$SS, MS = Trow$MS, F = Ft["F"], p = Ft["p"])
      ext_block[[length(ext_block) + 1]] <- data.frame(
        Source = paste0(E, " x ", lbl), Df = ETrow$Df, SS = ETrow$SS, MS = ETrow$MS,
        F = Fet["F"], p = Fet["p"])
      effects[[paste(S, collapse = ":")]] <- new_effect(
        d, resp, S, ETrow$MS, ETrow$Df, unname(Ft["p"]), unname(Ft["F"]), alpha,
        label = lbl)
    }

    ## assemble the ANOVA table -----------------------------------------------
    anrows <- list(data.frame(Source = paste0("Environment (", E, ")"),
                              Df = Erow$Df[1], SS = Erow$SS[1], MS = Erow$MS[1],
                              F = Fe["F"], p = Fe["p"]))
    if (!is.null(RE))
      anrows <- c(anrows, list(data.frame(Source = "Replication within environment",
                              Df = RE$df, SS = RE$ss, MS = RE$ms, F = Fre["F"], p = Fre["p"])))
    anrows <- c(anrows, trt_block, ext_block,
                list(data.frame(Source = "Pooled error", Df = err$df, SS = err$ss,
                                MS = err$ms, F = NA, p = NA)))
    an <- do.call(rbind, lapply(anrows, function(z) {
      names(z) <- c("Source","Df","SS","MS","F","p"); z }))
    an <- add_total(an, d[[resp]])
    an[["F"]] <- as.numeric(an[["F"]]); an[["p"]] <- as.numeric(an[["p"]])
    rownames(an) <- NULL

    ## Environment effect, and the E x (full treatment) stability table --------
    eEnv <- new_effect(d, resp, E, err_env$ms, err_env$df, unname(Fe["p"]),
                       unname(Fe["F"]), alpha, label = paste0("Environment (", E, ")"))
    ETfull <- find_src(c(E, fs))
    Ffull <- if (!is.null(ETfull)) fp(ETfull$MS, ETfull$Df, err$ms, err$df) else c(F = NA, p = NA)
    m <- eff_means(d, resp, c(E, fs))
    t_we   <- stats::qt(1 - alpha / 2, err$df)
    sed_we <- sqrt(2 * err$ms / r)
    cd_we  <- t_we * sed_we
    m$Letter_within_env <- ave_letters(m, E, m$Mean, cd_we)
    eETfull <- slice_effect(m, c(E, fs), slice = E,
      label = paste0(E, " x ", paste(fs, collapse = " x ")),
      se = sqrt(err$ms / r), sed = sed_we, tcrit = t_we, mse = err$ms, df = err$df,
      alpha = alpha, p = unname(Ffull["p"]), Fv = unname(Ffull["F"]), extra = NULL,
      notes = gxe_note(Ffull["p"], alpha, E, "treatment", cd_we, cd_name(alpha), factorial = TRUE),
      env = E, is_gxe = TRUE)

    res$effects <- c(effects, stats::setNames(list(eEnv), E),
                     stats::setNames(list(eETfull), paste0(E, ":", paste(fs, collapse = ":"))))
    res$anova <- an
    res$mse <- err$ms; res$dfe <- err$df
    res$cv  <- c("CV (%)" = 100 * sqrt(err$ms) / grand)
    res$facs <- fs                                   # means section loops treatment factors
    lm_rhs <- if (design == "POOLFRCBD")
      sprintf("%s + %s:%s + %s*(%s)", E, E, R, E, trt_rhs) else sprintf("%s*(%s)", E, trt_rhs)
    res$lm <- stats::lm(stats::as.formula(paste(resp, "~", lm_rhs)), data = d)
    res$errors <- list(`Pooled error` = err,
                       `Rep within env` = if (!is.null(RE)) RE else NULL)
    res$homogeneity <- hom
    res$pooled <- TRUE
  }
  res$resid  <- stats::residuals(res$lm)
  res$fitted <- stats::fitted(res$lm)
  res$X      <- stats::model.matrix(res$lm)   # for the Box-Cox profile
  res
}

## "C.D. (5%)", at whatever level was chosen
cd_name <- function(alpha) sprintf("C.D. (%s%%)", pct(alpha))

## The note under a pooled analysis's environment x treatment table. A
## non-significant interaction is reported as insufficient evidence, not as
## proof that the treatments behave alike everywhere. In a factorial this is
## the interaction with the full treatment combination only; the interactions
## of the environment with each factor are separate rows of the ANOVA.
gxe_note <- function(p, alpha, E, what, cd, cdl, factorial = FALSE) {
  if (!is.na(p) && p < alpha)
    paste0("The ", E, " x ", what, " interaction is significant at the ", pct(alpha),
      "% level: ", what, " performance is shown separately for each environment below. ",
      "Letters compare means within one environment only (pooled error, ", cdl, " = ",
      fmt(cd), ").")
  else
    paste0("The ", E, " x ", what, " interaction is <b>not significant</b> at the ",
      pct(alpha), "% level (NS). There is insufficient evidence that the differences ",
      "between ", if (factorial) "treatment combinations" else "treatments",
      " change from one environment to another, so the pooled tables above summarise ",
      "them and the individual environment cells are not compared.",
      if (factorial) paste0(" The interactions of ", E, " with each single factor are ",
                            "tested separately in the ANOVA table.") else "")
}

## columns the tables of means add, which a design factor must not be called
RESERVED_COLS <- c("Mean", "N", "SD", "SE", "Raw_mean", "Mean_bt", ".se",
                   "Letter", "Letter_within_MP", "Letter_within_SP",
                   "Letter_within_A", "Letter_within_B", "Letter_within_env")

## Is the layout one DOEpro can analyse exactly, and is it balanced? Designs
## with a single error term (CRD, RCBD, Latin square, the factorials) cope with
## unequal replication through adjusted means, as long as every treatment
## combination was observed. Designs with several error strata (split plot,
## strip plot, the pooled analyses) do not: with a plot missing the strata are
## no longer orthogonal, aov() moves treatment sums of squares into the
## replication strata where they silently vanish, and an exact analysis needs a
## mixed model fitted by REML, which base R does not provide. Those designs
## must be complete; the message says what is missing instead of printing a
## wrong ANOVA.
check_layout <- function(d, design, map, facs, blks) {
  pooled <- design %in% c("POOLRCBD", "POOLCRD", "POOLFRCBD", "POOLFCRD")
  trt <- if (pooled) setdiff(facs, map$env) else facs
  one <- c(facs, blks)[vapply(c(facs, blks), function(v) nlevels(d[[v]]) < 2, logical(1))]
  if (length(one))
    stop(sprintf(paste0("%s %s only one level in the complete rows of data, so there is ",
      "nothing to compare. Check that the right column is mapped, and that the response ",
      "is not missing for every other level."), join_and(sprintf("'%s'", one)),
      if (length(one) == 1) "has" else "have"), call. = FALSE)
  cells <- table(d[trt])
  if (length(trt) > 1 && any(cells == 0)) {
    empty <- as.data.frame(cells, stringsAsFactors = FALSE)
    empty <- empty[empty$Freq == 0, trt, drop = FALSE]
    stop(sprintf(paste0("Every combination of %s needs at least one observation, but ",
      "there are none for %s. Without them the main effects cannot be separated from ",
      "the interaction. Check the data, or leave out the factor with the gap."),
      join_and(trt), list_cells(empty)), call. = FALSE)
  }

  if (design %in% c("SPLIT", "STRIP")) {
    v <- c(map$rep, map$main, map$sub)
    tab <- as.data.frame(table(d[v]), stringsAsFactors = FALSE)
    miss <- tab[tab$Freq == 0, v, drop = FALSE]
    dup  <- tab[tab$Freq > 1, v, drop = FALSE]
    if (nrow(miss) || nrow(dup))
      stop(paste0(if (design == "SPLIT") "A split-plot" else "A strip-plot",
        " analysis needs exactly one observation for every combination of ",
        join_and(v), ". ",
        if (nrow(miss)) sprintf("Missing: %s. ", list_cells(miss)) else "",
        if (nrow(dup)) sprintf("More than one row: %s. ", list_cells(dup)) else "",
        "With a plot missing or repeated, the design's separate error terms can no ",
        "longer be estimated exactly, and DOEpro does not estimate missing plots. ",
        "Remove the incomplete replication and analyse the complete ones",
        if (nrow(dup)) ", and average repeated measurements of one plot into a single value" else "",
        "."), call. = FALSE)
    return(list(balanced = TRUE, reps = nlevels(d[[map$rep]]),
                n_range = rep(nlevels(d[[map$rep]]), 2)))
  }

  if (design %in% c("POOLRCBD", "POOLFRCBD")) {
    E <- map$env; R <- map$rep
    probs <- character(0); nrep <- integer(0)
    for (lv in levels(d[[E]])) {
      di <- d[d[[E]] == lv, , drop = FALSE]
      di[[R]] <- droplevels(di[[R]])
      tab <- as.data.frame(table(di[c(R, trt)]), stringsAsFactors = FALSE)
      miss <- tab[tab$Freq == 0, c(R, trt), drop = FALSE]
      dup  <- tab[tab$Freq > 1, c(R, trt), drop = FALSE]
      if (nrow(miss)) probs <- c(probs, sprintf("in %s, %s %s missing", lv, list_cells(miss),
                                                if (nrow(miss) == 1) "is" else "are"))
      if (nrow(dup)) probs <- c(probs, sprintf("in %s, %s %s more than one row", lv,
                                               list_cells(dup), if (nrow(dup) == 1) "has" else "have"))
      nrep[[lv]] <- nlevels(di[[R]])
    }
    if (length(unique(nrep)) > 1)
      probs <- c(probs, paste("the number of replications differs between environments (",
        paste(sprintf("%s %d", names(nrep), nrep), collapse = ", "), ")", sep = ""))
    if (length(probs))
      stop(paste0("A combined analysis over environments needs a complete RCBD in every ",
        "environment, with the same number of replications in each. Here ",
        paste(head_more(probs, 3), collapse = "; "), ". With incomplete or unequal replication the ",
        "treatments cannot be tested exactly against their interaction with the ",
        "environment, so DOEpro stops rather than print approximate results. Remove ",
        "the incomplete replication(s), or analyse each environment on its own as an ",
        "RCBD, which does handle a missing plot."), call. = FALSE)
    return(list(balanced = TRUE, reps = nrep[[1]], n_range = rep(nrep[[1]], 2)))
  }

  if (design %in% c("POOLCRD", "POOLFCRD")) {
    v <- c(map$env, trt)
    tab <- as.data.frame(table(d[v]), stringsAsFactors = FALSE)
    if (length(unique(tab$Freq)) > 1) {
      common <- as.integer(names(which.max(table(tab$Freq))))
      odd <- tab[tab$Freq != common, , drop = FALSE]
      lab <- sprintf("%s has %s", do.call(paste, c(lapply(odd[v], as.character), sep = " x ")),
                     ifelse(odd$Freq == 0, "none", as.character(odd$Freq)))
      stop(sprintf(paste0("A combined analysis over environments needs the same number of ",
        "observations in every environment x treatment cell. Most cells have %d, but %s. ",
        "With unequal numbers the treatments cannot be tested exactly against their ",
        "interaction with the environment, so DOEpro stops rather than print approximate ",
        "results. Analyse each environment on its own as a CRD, which does handle unequal ",
        "replication."), common, join_and(head_more(lab))), call. = FALSE)
    }
    return(list(balanced = TRUE, reps = tab$Freq[1], n_range = rep(tab$Freq[1], 2)))
  }

  ## single error term: balanced when every cell of the full layout, blocks
  ## included, holds the same number of plots. An RCBD whose treatments are each
  ## present three times but in different blocks is not balanced: its plain
  ## means are pulled by the block effects.
  full <- if (design == "LSD")
    list(table(d[c(map$row, map$col)]), table(d[c(map$row, trt)]), table(d[c(map$col, trt)]))
  else list(table(d[c(blks, trt)]))
  balanced <- all(vapply(full, function(x) all(x == x[1]) && x[1] > 0, logical(1)))
  if (design == "LSD") balanced <- balanced && all(full[[1]] == 1L)
  list(balanced = balanced, reps = if (balanced) as.vector(cells)[1] else NA,
       n_range = range(cells))
}

## "R2 x I2 x V3, R3 x I1 x V2 and 4 more", from rows of factor levels
list_cells <- function(cells)
  join_and(head_more(do.call(paste, c(lapply(cells, as.character), sep = " x "))))

## at most five items, then "and N more"
head_more <- function(x, k = 5)
  if (length(x) > k) c(x[seq_len(k)], sprintf("%d more", length(x) - k)) else x

## "a", "a and b", "a, b and c"
join_and <- function(x)
  if (length(x) < 2) x else paste(paste(x[-length(x)], collapse = ", "), "and", x[length(x)])

## A Total row that is the total sum of squares of the data, not the sum of the
## rows above it, so that nothing an error stratum dropped can go unnoticed.
add_total <- function(an, y) {
  rbind(an, data.frame(Source = "Total", Df = length(y) - 1, SS = sum((y - mean(y))^2),
                       MS = NA, F = NA, p = NA, check.names = FALSE))
}

## With unequal replication the sequential (Type I) sums of squares depend on
## the order of the terms and test hypotheses about weighted means. Replace each
## term's row with its Type III test: the term dropped from the full model fitted
## with sum-to-zero contrasts. That tests equality of the adjusted means the
## tables report, so the F-test that gates the letters and the means it gates
## are about the same thing. The rows then no longer add up to the total.
type3_anova <- function(an, form, d, fvars) {
  ctr <- stats::setNames(rep(list("contr.sum"), length(fvars)), fvars)
  fit <- stats::lm(form, data = d, contrasts = ctr)
  tl <- attr(stats::terms(fit), "term.labels")
  dr <- stats::drop1(fit, scope = tl, test = "F")
  for (x in tl) {
    i <- an$Source == x
    if (!any(i)) next
    an$SS[i] <- dr[x, "Sum of Sq"]
    an$MS[i] <- dr[x, "Sum of Sq"] / an$Df[i]
    an$F[i]  <- dr[x, "F value"]
    an$p[i]  <- dr[x, "Pr(>F)"]
  }
  an
}

## letters computed separately inside each level of `by`
ave_letters <- function(m, by, mu, cd) {
  out <- character(nrow(m))
  for (lv in unique(m[[by]])) {
    idx <- which(m[[by]] == lv)
    out[idx] <- cld_lsd(mu[idx], cd)
  }
  out
}

## every column that may carry compact-letter groupings
LETTER_COLS <- c("Letter", "Letter_within_MP", "Letter_within_SP",
                 "Letter_within_A", "Letter_within_B", "Letter_within_env")

## Protected mean separation. Returns the effect's table of means with the
## grouping letters blanked whenever the effect's F-test is not significant at
## the chosen level. This keeps the letters in step with the "C.D. = NS" in the
## footers: letters are shown only when the F-test justifies pairwise
## comparison, so an a-e sequence can never sit beneath a non-significant F.
gate_letters <- function(e) {
  m <- e$means
  if (!effect_sig(e))
    for (col in intersect(LETTER_COLS, names(m))) m[[col]] <- rep("", nrow(m))
  m
}

## is the effect significant at the chosen level (so its letters should be shown)?
effect_sig <- function(e) !is.na(e$p) && e$p < e$alpha

## does a table of means carry any non-empty grouping letter?
has_groups <- function(m) {
  cols <- intersect(LETTER_COLS, names(m))
  length(cols) > 0 && any(nzchar(unlist(m[cols])))
}

## ---------------------------------------------------------- assumptions.R ----
###############################################################################
##  ASSUMPTIONS  &  TRANSFORMATIONS
###############################################################################
## Levene's test, median-centred (Brown-Forsythe): a one-way ANOVA on the
## absolute deviations from the cell medians. In a cell with an odd number of
## values the median is one of them, so one deviation is always zero; when
## every cell has three values that caps F at 4, and the test could never find
## unequal variances among four or fewer treatments. When every cell used is
## of odd size, each therefore loses that one zero (Hines and O'Hara Hines,
## 2000, Biometrics 56: 451-454), which by simulation holds the 5% level for
## normal, skewed and count data with three or five values per cell. When
## sizes are mixed (a missing plot among cells of four) the zero stays:
## removing it from the odd cells alone makes them look more spread out than
## the even ones, and the test then calls equal variances unequal too often,
## while the plain test holds its level there. `zeros_removed` counts the
## cells that lost a zero.
## A cell needs three values to take part. With two, both values lie equally far from their median, so
## nothing varies within the cell: a design with two replications gave an
## enormous F and a false verdict of unequal variances, and keeping two-value
## cells beside larger ones (as car::leveneTest does) adds error degrees of
## freedom with no variation in them, which by simulation calls equal
## variances unequal 13-45% of the time at the 5% level. Such cells are left
## out and named in `left_out`; when fewer than two cells remain, or the
## deviations do not vary within any cell, the test is not run and `why`
## gives the reason as a plain clause.
levene_test <- function(y, g) {
  ok <- !is.na(y) & !is.na(g)
  y <- y[ok]; g <- droplevels(factor(g[ok]))
  n <- table(g)
  out <- list(F = NA_real_, p = NA_real_, df1 = NA_real_, df2 = NA_real_,
              cells = sum(n >= 3), dropped = sum(n < 3), left_out = names(n)[n < 3],
              zeros_removed = 0L, why = NULL)
  if (out$cells < 2) {
    out$why <- if (out$cells == 0) "no cell has three or more values" else "only one cell has three or more values"
    return(out)
  }
  keep <- g %in% names(n)[n >= 3]
  constant <- all(tapply(y, g, function(v) length(unique(v)) == 1))
  y <- y[keep]; g <- droplevels(g[keep])
  z <- abs(y - stats::ave(y, g, FUN = stats::median))
  if (all(table(g) %% 2 == 1)) {
    sz <- unlist(lapply(split(seq_along(z), g), function(i) i[which(z[i] == 0)[1]]), use.names = FALSE)
    z <- z[-sz]; g <- droplevels(g[-sz]); out$zeros_removed <- length(sz)
  }
  tss <- sum((z - mean(z))^2)
  rss <- sum((z - stats::ave(z, g))^2)
  if (tss == 0 || rss <= 1e-10 * tss) {
    out$why <- if (constant) "every cell's values are identical"
               else if (all(z == 0)) "the values are identical within every cell of three or more"
               else if (out$zeros_removed > 0)
                 "with the median's own zero set aside, the other deviations from the median are equal within every cell"
               else "the deviations from the cell medians do not vary within any cell"
    return(out)
  }
  df1 <- nlevels(g) - 1; df2 <- length(z) - nlevels(g)
  Fv <- ((tss - rss) / df1) / (rss / df2)
  out[c("F", "p", "df1", "df2")] <- list(Fv, stats::pf(Fv, df1, df2, lower.tail = FALSE), df1, df2)
  out
}

## Bartlett's test of equal variances across the cells. A cell needs two
## values for a variance, so cells of one value are left out; a variance of
## zero (every value in a cell the same) has no logarithm, so the test is not
## run and `why` says so.
bartlett_cells <- function(y, g) {
  ok <- !is.na(y) & !is.na(g)
  y <- y[ok]; g <- droplevels(factor(g[ok]))
  n <- table(g)
  out <- list(statistic = NA_real_, p.value = NA_real_, cells = sum(n >= 2),
              dropped = sum(n < 2), why = NULL)
  if (out$cells < 2) {
    out$why <- "fewer than two cells have two or more values"
    return(out)
  }
  keep <- g %in% names(n)[n >= 2]
  y <- y[keep]; g <- droplevels(g[keep])
  s2 <- tapply(y, g, stats::var)
  if (any(s2 == 0)) {
    out$why <- if (all(s2 == 0)) "every cell's values are identical"
               else "the values in some cells are all the same, so those cells have no variance"
    return(out)
  }
  b <- stats::bartlett.test(y, g)
  out$statistic <- unname(b$statistic); out$p.value <- b$p.value
  out
}

## An exact fit: every observation equals its fitted value, so the residuals
## are only the rounding left by the arithmetic (about 1e-16 of the data).
## There is then no error variation to test, transform or plot, and treating
## the rounding as residuals would give verdicts about nothing.
## The rounding grows with the size of the values (10000.001 carries more
## than 0.001), so the tolerance is set against their magnitude; real
## residuals are never within a billionth of the values themselves.
exact_fit <- function(res) {
  y <- res$data[[res$resp]]
  size <- max(abs(y), na.rm = TRUE)
  spread <- max(abs(y - mean(y, na.rm = TRUE)), na.rm = TRUE)
  r <- res$resid
  !length(r) || !is.finite(size) || spread == 0 || all(abs(r) <= 1e-9 * size, na.rm = TRUE)
}

## Box-Cox log-likelihood profile.  For a positive response y and design matrix X,
##   z(lambda) = (y^lambda - 1) / (lambda * gm^(lambda-1)),   z(0) = gm * log(y)
## with gm the geometric mean of y, and  l(lambda) = -n/2 * log(RSS(z)/n).
## Computed directly, so it never depends on re-evaluating a stored model call.
## The confidence interval is at `level`, which the analysis sets to 1 - alpha.
boxcox_profile <- function(y, X, level, lambda = seq(-2, 2, 0.02)) {
  if (any(!is.finite(y)) || any(y <= 0) || is.null(X)) return(NULL)
  n <- length(y); gm <- exp(mean(log(y))); qrx <- qr(X)
  ll <- vapply(lambda, function(l) {
    z <- if (abs(l) < 1e-9) gm * log(y) else (y^l - 1) / (l * gm^(l - 1))
    rss <- sum(qr.resid(qrx, z)^2)
    if (!is.finite(rss) || rss <= 0) return(NA_real_)
    -n / 2 * log(rss / n)
  }, numeric(1))
  if (all(is.na(ll))) return(NULL)
  best <- lambda[which.max(ll)]
  ## confidence interval: lambda values within qchisq(level, 1) / 2 of the
  ## maximum log-likelihood
  inside <- lambda[!is.na(ll) & ll > max(ll, na.rm = TRUE) - 0.5 * stats::qchisq(level, 1)]
  list(x = lambda, y = ll, lambda = best, ci = range(inside), level = level)
}

## The assumption tests are judged at the analysis's own significance level, so
## a user who chose 1% is not told about departures at 5%.
check_assumptions <- function(res) {
  alpha <- res$alpha
  r <- res$resid
  d <- res$data; resp <- res$resp
  cells <- interaction(d[res$facs], drop = TRUE)
  exact <- exact_fit(res)

  sw <- if (!exact && length(r) >= 3 && length(r) <= 5000) stats::shapiro.test(r) else NULL
  norm_why <- if (exact) "the model fits every value exactly, so the residuals are all zero"
              else if (is.null(sw)) "Shapiro-Wilk needs between 3 and 5000 residuals" else NULL
  lev  <- levene_test(d[[resp]], cells)
  bart <- bartlett_cells(d[[resp]], cells)
  if (exact) {
    why <- "the model fits every value exactly"
    lev[c("F", "p")] <- NA_real_; lev$why <- why
    bart[c("statistic", "p.value")] <- NA_real_; bart$why <- why
  }
  ## The equal-variance verdict comes from the test that covers every
  ## treatment: Levene's, which does not assume normality, when every cell has
  ## three or more values; otherwise Bartlett's, which needs only two but
  ## assumes normality; and Levene's on the cells it can use only when
  ## Bartlett's cannot be run. `hov_label` names the test as the text uses it.
  lev_full <- is.finite(lev$p) && lev$dropped == 0
  hov_test <- if (lev_full) "Levene" else if (is.finite(bart$p.value)) "Bartlett"
              else if (is.finite(lev$p)) "Levene" else NA_character_
  p_hov <- if (identical(hov_test, "Levene")) lev$p else if (identical(hov_test, "Bartlett")) bart$p.value else NA_real_
  left <- join_and(head_more(lev$left_out, 6))
  hov_label <- if (identical(hov_test, "Levene") && lev_full) "Levene's test"
    else if (identical(hov_test, "Levene")) sprintf("Levene's test on the cells with three or more values (%s left out)", left)
    else if (identical(hov_test, "Bartlett")) sprintf("Bartlett's test (%s; Bartlett's assumes the values are normal)",
      if (is.finite(lev$p)) sprintf("Levene's test leaves out %s, which %s fewer than three values", left,
                                    if (lev$dropped == 1) "has" else "have")
      else sprintf("Levene's test could not be run: %s", lev$why))
    else NA_character_
  hov_short <- if (identical(hov_test, "Levene") && lev_full) "Levene's"
               else if (identical(hov_test, "Levene")) "Levene's, on some cells" else if (identical(hov_test, "Bartlett")) "Bartlett's"
               else NA_character_
  ## why equal variances could not be tested at all
  hov_why <- if (!is.na(hov_test)) NULL
    else if (identical(lev$why, bart$why)) lev$why
    else sprintf("for Levene's test, %s; for Bartlett's test, %s", lev$why, bart$why)

  ## mean-variance relationship -> Taylor's power law slope
  mv <- data.frame(m = tapply(d[[resp]], cells, mean),
                   v = tapply(d[[resp]], cells, stats::var))
  mv <- mv[stats::complete.cases(mv) & mv$m > 0 & mv$v > 0, ]
  ## with an exact fit the cell variances are block (or row and column)
  ## effects, not error, so they say nothing about the error variance
  if (exact) mv <- mv[0, ]
  slope <- if (nrow(mv) >= 3)
    unname(stats::coef(stats::lm(log(v) ~ log(m), data = mv))[2]) else NA_real_
  ## the slope's own p-value: with two values per cell each variance rests on
  ## one degree of freedom, and a slope from such variances is mostly noise
  slope_p <- if (nrow(mv) >= 4)
    tryCatch(suppressWarnings(summary(stats::lm(log(v) ~ log(m), data = mv))$coefficients[2, 4]),
             error = function(e) NA_real_)
    else NA_real_

  bc <- if (exact) NULL else tryCatch(boxcox_profile(d[[resp]], res$X, level = 1 - alpha),
                                      error = function(e) NULL)

  outliers <- if (exact) integer(0) else which(abs(r / stats::sd(r)) > 3)

  list(alpha = alpha, exact = exact, strata = isTRUE(res$design %in% c("SPLIT", "STRIP")),
       shapiro = sw, norm_why = norm_why,
       levene = lev, bartlett = bart, hov_test = hov_test, hov_label = hov_label, hov_short = hov_short,
       hov_why = hov_why, slope = slope, slope_p = slope_p,
       bc = bc, lambda = if (is.null(bc)) NA_real_ else bc$lambda,
       mv = mv, outliers = outliers,
       p_norm = if (is.null(sw)) NA_real_ else sw$p.value,
       p_hov  = p_hov)
}

## What the checks of normality and equal variances found, for the sentence
## that opens a recommendation: only the tests that could be run are named.
checks_text <- function(asm, alpha) {
  lvl <- paste0(pct(alpha), "%")
  norm <- !is.na(asm$p_norm); hov <- !is.na(asm$p_hov)
  hov_name <- sprintf("the test of equal variances (%s)", asm$hov_short)
  if (norm && hov) sprintf("Neither the normality test nor %s finds a significant departure at the %s level", hov_name, lvl)
  else if (norm) sprintf("The normality test finds no significant departure at the %s level, and equal variances could not be tested (%s)",
                         lvl, asm$hov_why %||% "too few values")
  else if (hov) sprintf("%s finds no significant departure at the %s level, and normality could not be tested (%s)",
                        paste0(toupper(substr(hov_name, 1, 1)), substring(hov_name, 2)), lvl,
                        asm$norm_why %||% "too few residuals")
  else ""
}

suggest_transform <- function(res, asm, dtype = "auto") {
  y <- res$data[[res$resp]]
  y <- y[!is.na(y)]
  pn <- asm$p_norm; ph <- asm$p_hov; b <- asm$slope; lam <- asm$lambda

  nm <- if (!is.null(res$orig_resp)) res$orig_resp else res$resp
  has_frac    <- any(abs(y - round(y)) > 1e-8)
  looks_prop  <- min(y) >= 0 && max(y) <= 1 && has_frac
  looks_count <- min(y) >= 0 && !has_frac
  in_pct_range <- min(y) >= 0 && max(y) <= 100 && !looks_prop
  ## a 0-100 range alone does NOT make a variable a percentage (most yields and
  ## heights live there too), so auto-detection also needs the column name to say so
  pct_name <- grepl("perc|pct|%|incid|sever|infest|germinat|surviv|mortal|infect|damage",
                    tolower(nm))
  looks_pct   <- in_pct_range && pct_name
  count_slope <- !is.na(b) && b >= 0.5 && b < 1.5

  ## an exact fit leaves nothing unexplained for a transformation to correct
  if (isTRUE(asm$exact))
    return(list(method = "none", optional = FALSE,
      why = paste("The model fits every value exactly, so there is no unexplained variation:",
                  "no transformation can help, and none is needed.")))

  ok <- (is.na(pn) || pn > res$alpha) && (is.na(ph) || ph > res$alpha)
  ## Equal variances are tested in full only when the verdict covers every
  ## cell; Levene's on some cells alone leaves the others untested.
  hov_full <- !is.na(ph) && !(identical(asm$hov_test, "Levene") && isTRUE(asm$levene$dropped > 0))
  ## An assumption that could not be tested has not been passed: then a rise
  ## of the variance with the mean decides instead, but only when the slope
  ## is itself significant at the chosen level, since a slope from variances
  ## of two values each is mostly noise.
  slope_evidence <- !is.na(b) && b >= 0.5 && isTRUE(asm$slope_p <= res$alpha)
  if (ok && !hov_full && slope_evidence) ok <- FALSE
  all_tested <- !is.na(pn) && hov_full

  ## When the diagnostics are satisfactory we still name the conventional
  ## transformation for data that are plainly counts or percentages, flagged as
  ## optional - agronomic convention transforms them, the diagnostics do not
  ## demand it, and the analyst should decide knowingly. The opening sentence
  ## names only the checks that could be run.
  if (ok && dtype == "auto") {
    fine <- checks_text(asm, res$alpha)
    so <- if (all_tested) paste0(fine, ", so no transformation is strictly required.")
          else if (nzchar(fine)) paste0(fine, "; the checks that could be run give no reason for a transformation.")
          else "Neither normality nor equal variances could be tested, so the checks give no reason for a transformation."
    if (looks_prop)
      return(list(method = "arcsine01", optional = TRUE,
        why = paste(so, "The response is a proportion, however, and convention is to analyse proportions on the angular (arcsine square-root) scale.")))
    ## only a slope that is itself significant shows the variance rising
    ## with the mean; otherwise the claim would rest on noise
    if (looks_count && count_slope && slope_evidence)
      return(list(method = if (min(y) < 1) "sqrt0.5" else "sqrt", optional = TRUE,
        why = sprintf("%s The response is nevertheless integer-valued with variance proportional to the mean (Taylor slope b = %.2f) - i.e. count data, for which the square root is conventional.", so, b)))
    if (looks_pct)
      return(list(method = "arcsine", optional = TRUE,
        why = sprintf("%s '%s' is bounded by 0 and 100 and named as a percentage, for which the angular (arcsine square-root) transformation is conventional.", so, nm)))
    return(list(method = "none", optional = FALSE,
      why = if (all_tested) paste0(fine, " - no transformation is needed.")
            else if (nzchar(fine)) paste0(fine, "; the checks that could be run give no reason for a transformation.")
            else "Neither normality nor equal variances could be tested, so there is no evidence for or against a transformation."))
  }

  ## user-declared data type wins over any guessing
  if (dtype == "percent")
    return(list(method = if (max(y) <= 1) "arcsine01" else "arcsine",
      why = "You declared the response to be a percentage/proportion, so the angular (arcsine square-root) transformation applies."))
  if (dtype == "count")
    return(list(method = if (min(y) < 1) "sqrt0.5" else "sqrt",
      why = "You declared the response to be a count, so the square-root transformation applies (sqrt(y+0.5) when zeros are present)."))

  if (looks_prop)
    return(list(method = "arcsine01",
      why = "The response lies between 0 and 1 and is not integer - it behaves like a proportion, so the angular (arcsine square-root) transformation applies."))

  if (looks_count && count_slope)
    return(list(method = if (min(y) < 1) "sqrt0.5" else "sqrt",
      why = sprintf("The response is integer-valued and the variance rises in proportion to the mean (Taylor slope b = %.2f) - the classic signature of count data, so the square root is indicated.", b)))

  if (looks_pct && !(looks_count && count_slope))
    return(list(method = "arcsine",
      why = sprintf("'%s' is bounded between 0 and 100 and its name suggests a percentage, so the angular (arcsine square-root) transformation applies.", nm)))

  if (!is.na(b)) {
    if (b >= 0.5 && b < 1.5)
      return(list(method = if (min(y) < 1) "sqrt0.5" else "sqrt",
        why = sprintf("Variance rises roughly in proportion to the mean (Taylor slope b = %.2f) - square root is indicated.", b)))
    if (b >= 1.5 && b < 2.5)
      return(list(method = if (min(y) <= 0) "log1" else "log",
        why = sprintf("Variance rises with the square of the mean (b = %.2f) - the logarithmic transformation is indicated.", b)))
    if (b >= 2.5)
      return(list(method = "reciprocal",
        why = sprintf("Variance rises faster than the square of the mean (b = %.2f) - the reciprocal transformation is indicated.", b)))
  }
  if (!is.na(lam)) {
    m <- if (abs(lam) < 0.15) "log" else if (abs(lam - 0.5) < 0.2) "sqrt" else
         if (abs(lam + 1) < 0.25) "reciprocal" else "boxcox"
    return(list(method = m, why = sprintf("The Box-Cox profile peaks at lambda = %.2f.", lam)))
  }
  hint <- if (in_pct_range && !pct_name)
    " Note: your response lies between 0 and 100. If it really is a percentage, set 'Nature of the response' to 'Percentage / proportion' and the angular transformation will be applied." else ""
  list(method = "none",
       why = paste0("No clear transformation is indicated. If normality is badly violated, consider a non-parametric test (Kruskal-Wallis / Friedman).", hint))
}

#' The transformations DOEpro offers
#'
#' A named list of the variance-stabilising transformations. Each entry holds a
#' label (\code{lab}), the transformation (\code{f}) and its inverse
#' (\code{inv}), which is what lets DOEpro report means on the original scale of
#' measurement alongside the transformed ones.
#'
#' @format A named list of length 9. The names are the keys used in the
#'   \code{trans} argument of \code{\link{run_all}}: \code{"none"},
#'   \code{"log"}, \code{"log1"}, \code{"sqrt"}, \code{"sqrt0.5"},
#'   \code{"arcsine"}, \code{"arcsine01"}, \code{"reciprocal"} and
#'   \code{"boxcox"}.
#'
#' @return A named list of length 9. Each element is itself a list with
#'   \code{lab}, the label shown in the application; \code{f}, a function
#'   applying the transformation; and \code{b}, a function applying its
#'   inverse, which is what allows means to be reported on the original scale
#'   of measurement.
#'
#' @examples
#' names(TRANS)
#' vapply(TRANS, `[[`, character(1), "lab")
#'
#' @export
TRANS <- list(
  none       = list(lab = "None",                       f = function(y, l) y,
                    b = function(z, l) z),
  log        = list(lab = "log(y)",                     f = function(y, l) log(y),
                    b = function(z, l) exp(z)),
  log1       = list(lab = "log(y + 1)",                 f = function(y, l) log(y + 1),
                    b = function(z, l) exp(z) - 1),
  sqrt       = list(lab = "sqrt(y)",                    f = function(y, l) sqrt(y),
                    b = function(z, l) z^2),
  sqrt0.5    = list(lab = "sqrt(y + 0.5)",              f = function(y, l) sqrt(y + 0.5),
                    b = function(z, l) z^2 - 0.5),
  arcsine    = list(lab = "arcsine sqrt(y/100), degrees",
                    f = function(y, l) asin(sqrt(y / 100)) * 180 / pi,
                    b = function(z, l) (sin(z * pi / 180))^2 * 100),
  arcsine01  = list(lab = "arcsine sqrt(y), degrees",
                    f = function(y, l) asin(sqrt(y)) * 180 / pi,
                    b = function(z, l) (sin(z * pi / 180))^2),
  reciprocal = list(lab = "1 / y",                      f = function(y, l) 1 / y,
                    b = function(z, l) 1 / z),
  boxcox     = list(lab = "Box-Cox (optimal lambda)",
                    f = function(y, l) if (abs(l) < 1e-6) log(y) else (y^l - 1) / l,
                    b = function(z, l) if (abs(l) < 1e-6) exp(z) else (z * l + 1)^(1 / l))
)

## ---------------------------------------------------------- tables_detail.R ----
###############################################################################
##  INTEGRATED MEAN TABLES  (integrated agronomy-style output)
###############################################################################
## two-way table with marginal means
two_way <- function(d, resp, f1, f2) {
  tb <- tapply(d[[resp]], list(d[[f1]], d[[f2]]), mean)
  tb <- cbind(tb, `Mean` = rowMeans(tb, na.rm = TRUE))
  tb <- rbind(tb, `Mean` = colMeans(tb, na.rm = TRUE))
  out <- data.frame(rownames(tb), tb, check.names = FALSE)
  names(out)[1] <- f1
  out
}

## SE(m), SE(d) and C.D. under a table of means. With unequal replication they
## differ from mean to mean, and the range is given instead of one figure.
effect_footer <- function(e, cv = NULL) {
  ## a split, strip or pooled interaction's single figures hold only for means
  ## at the same level of its slicing factor; the others follow in e$extra
  within <- if (is.null(e$slice)) "" else sprintf(" (within the same %s)", e$slice)
  rows <- c(
    sprintf("<tr><td>SEm +/-%s</td><td>%s</td></tr>", within, err_text(e, "sem", 3)),
    sprintf("<tr><td>SEd%s</td><td>%s</td></tr>", within, err_text(e, "sed", 3)),
    sprintf("<tr><td>%s%s</td><td>%s</td></tr>", cd_head(e$alpha), within,
            if (effect_sig(e)) err_text(e, "cd", 3) else "NS"))
  if (!is.null(cv)) rows <- c(rows, sprintf("<tr><td>CV (%%)</td><td>%s</td></tr>",
                                            paste(fmt(cv, 2), collapse = " / ")))
  paste0("<table class='doe foot'>", paste(rows, collapse = ""), "</table>")
}

## compact contingency matrix of f1 x f2 cell means (from an effect's table of
## means) with the grouping letters attached as superscripts, plus marginal
## means. Used by the detailed Section C and by the per-environment breakdown.
## The margins and the corner are averages of the cell means, so they agree
## with the adjusted margins when replication is unequal; with a transformation
## they are shown like the cells, back-transformed with the transformed value in
## parentheses (`btf` is the back-transformation).
two_way_lettered <- function(mlet, f1, f2, letter_col, tr_on, digits, caption, btf = NULL) {
  l1 <- levels(factor(mlet[[f1]])); l2 <- levels(factor(mlet[[f2]]))
  disp <- if (tr_on && "Mean_bt" %in% names(mlet)) mlet$Mean_bt else mlet$Mean
  raw  <- mlet$Mean
  ix <- cbind(match(as.character(mlet[[f1]]), l1), match(as.character(mlet[[f2]]), l2))
  cD <- matrix(NA_real_, length(l1), length(l2), dimnames = list(l1, l2))
  cR <- cD; lg <- matrix("", length(l1), length(l2), dimnames = list(l1, l2))
  cD[ix] <- disp; cR[ix] <- raw
  if (!is.null(letter_col) && letter_col %in% names(mlet)) lg[ix] <- mlet[[letter_col]]
  rmean <- rowMeans(cR, na.rm = TRUE); cmean <- colMeans(cR, na.rm = TRUE)
  marg <- function(x) if (tr_on && is.function(btf))
    paste0(fmt(btf(x), digits), " (", fmt(x, digits), ")") else fmt(x, digits)
  body <- lapply(seq_along(l1), function(i)
    c(l1[i],
      vapply(seq_along(l2), function(j)
        paste0(fmt(cD[i, j], digits),
               if (tr_on) paste0(" (", fmt(cR[i, j], digits), ")") else "",
               sup(lg[i, j])), character(1)),
      marg(rmean[i])))
  body[[length(body) + 1L]] <- c("<b>Mean</b>", marg(cmean), marg(mean(cR, na.rm = TRUE)))
  raw_table(c(sprintf("%s \\ %s", f1, f2), l2, "Mean"), body, caption = caption)
}

## the note under a table whose letters restart in each level of a factor
slice_note <- function(e) {
  if (is.null(e$slice)) return("")
  sprintf(paste0("<p class='note'>Letters compare %s means within the same level of %s ",
                 "only; the same letter in two levels of %s means nothing.</p>"),
          paste(setdiff(e$vars, e$slice), collapse = " &times; "), e$slice, e$slice)
}

## per-environment breakdown of a *significant* environment x treatment
## interaction: for each environment, the treatment structure with letters that
## compare cells within that environment (pooled error). A 2-factor treatment
## structure is shown as a matrix; otherwise as a ranked table.
gxe_env_tables <- function(e, digits, grand) {
  E <- e$env; tf <- setdiff(e$vars, E)
  m <- e$means
  out <- vapply(levels(factor(m[[E]])), function(lv) {
    mi <- m[as.character(m[[E]]) == lv, , drop = FALSE]
    cap <- sprintf("<b>%s</b> &mdash; %s means (letters compare cells within %s)",
                   lv, paste(tf, collapse = " &times; "), lv)
    if (length(tf) == 2) {
      two_way_lettered(mi, tf[1], tf[2], "Letter_within_env", FALSE, digits, cap)
    } else {
      mm <- mi[order(-mi$Mean), c(tf, "Mean", "Letter_within_env"), drop = FALSE]
      names(mm)[names(mm) == "Letter_within_env"] <- "Group"
      df_html(mm, caption = cap)
    }
  }, character(1))
  paste0("<div class='ms-env-wrap'>", paste(out, collapse = ""), "</div>")
}

integrated_means_html <- function(res, digits = 2) {
  d <- res$data; resp <- res$resp
  h <- c(sprintf("<p><b>Response:</b> %s &nbsp; | &nbsp; <b>Grand mean:</b> %s &nbsp; | &nbsp; <b>%s</b></p>",
                 resp, fmt(res$grand),
                 paste(sprintf("%s = %s", names(res$cv), fmt(res$cv, 2)), collapse = " | ")))

  tr_on <- !is.null(res$trans) && !identical(res$trans, "none")
  btf <- if (tr_on) function(z) TRANS[[res$trans]]$b(z, res$lambda) else NULL
  ## the unadjusted average, which with a transformation is on that scale too
  raw_lab <- if (tr_on) "Unadjusted mean (transformed scale)" else "Unadjusted mean"
  relabel <- function(x) sub("^Raw_mean$", raw_lab, sub("^Mean_bt$", "Back-transformed",
                             sub("^N$", "n", sub("^Letter$", "Group", x))))

  for (nm in names(res$effects)) {
    e <- res$effects[[nm]]
    sig <- effect_sig(e)
    ttl <- sprintf("Table of means: <b>%s</b> &nbsp;(F = %s, %s, %s)",
                   e$label, fmt(e$F, 2), p_eq(e$p), star(e$p, e$alpha))
    unequal <- !isTRUE(e$equal_rep)
    m <- gate_letters(e)          # letters blanked when the F-test is NS
    foot <- ""; extra <- ""; note <- ""

    if (isTRUE(e$is_gxe)) {
      ## environment x treatment stability table (Rec 3 + footnote gating)
      inner <- if (sig) gxe_env_tables(e, digits, res$grand) else ""
      body <- paste0("<div class='ms-detail-name'>", ttl, "</div>",
                     "<p class='note'>", e$notes, "</p>", inner)

    } else if (length(e$vars) == 1) {
      ## with unequal replication each mean carries its own SE, and an adjusted
      ## mean is shown beside the raw average it was adjusted from
      cols <- intersect(c(e$vars, "Mean", "Raw_mean", "Mean_bt", "N",
                          if (unequal) "SE", "Letter"), names(m))
      if (!has_groups(m)) cols <- setdiff(cols, "Letter")     # drop empty Group when NS
      mm <- m[, cols, drop = FALSE]
      names(mm) <- relabel(names(mm))
      body <- df_html(mm, caption = ttl)
      foot <- effect_footer(e, res$cv)

    } else if (length(e$vars) == 2) {
      ## Rec 4: a single contingency matrix with superscript letters
      lc <- intersect(c("Letter", "Letter_within_MP", "Letter_within_A",
                        "Letter_within_env"), names(m))
      body <- paste0(two_way_lettered(m, e$vars[1], e$vars[2],
                                      if (length(lc)) lc[1] else NULL, tr_on, digits, ttl, btf),
                     if (sig) slice_note(e) else "")
      foot <- effect_footer(e, res$cv)

    } else {
      ## Rec 2: 3+ way pure-treatment table, Group column only when significant
      lc <- intersect(c("Letter", "Letter_within_env"), names(m))
      cols <- c(e$vars, "Mean", intersect(c("Raw_mean", "Mean_bt"), names(m)),
                if (unequal) c("N", "SE"))
      ord <- do.call(order, m[e$vars])
      mm <- m[ord, cols, drop = FALSE]
      if (length(lc) && has_groups(m)) mm$Group <- m[ord, lc[1]]
      names(mm) <- relabel(names(mm))
      body <- df_html(mm, caption = ttl)
      foot <- effect_footer(e, res$cv)
    }

    ## the other comparisons of a split, strip or pooled interaction, each C.D.
    ## shown only where its own F-test is significant
    xt <- extra_text(e)
    if (length(xt))
      extra <- paste0("<table class='doe foot'>",
        paste0(sprintf("<tr><td>%s</td><td>%s</td></tr>", names(xt), xt), collapse = ""),
        "</table>")
    if (!isTRUE(e$is_gxe) && length(e$notes) && nzchar(e$notes[1]))
      note <- paste0("<p class='note'>", e$notes, "</p>")
    h <- c(h, "<div class='block'>", body, foot, extra, note, "</div>")
  }
  HTML(paste(h, collapse = "\n"))
}

## ---------------------------------------------------------- posthoc.R ----
###############################################################################
##  POST-HOC
###############################################################################
## Post-hoc multiple comparisons, computed from the effect's own error term and
## from each pair's own standard error of a difference, taken from the effect's
## SE(d) matrix. With equal replication every pair has the same SE(d) and these
## are the textbook procedures. With unequal replication Tukey's HSD becomes the
## Tukey-Kramer procedure, the LSD, Bonferroni and Scheffe tests stay exact,
## and the two multiple-range tests use Kramer's (1956) pairwise adjustment;
## the output says which. Interaction effects of split plots, strip plots and
## pooled analyses are compared within one level of their slicing factor, the
## only comparisons that share one error term.
PH_METHODS <- c("LSD (Fisher's protected)", "LSD (Bonferroni-adjusted)",
                "Tukey HSD", "Duncan's DMRT", "Student-Newman-Keuls", "Scheffe")

## what each method is called wherever it is shown to the user
PH_LABELS <- c(
  "LSD (Fisher's protected)"  = "Least significant difference (LSD), Fisher's protected",
  "LSD (Bonferroni-adjusted)" = "Least significant difference (LSD), Bonferroni-adjusted",
  "Tukey HSD"                 = "Tukey's honestly significant difference (HSD)",
  "Duncan's DMRT"             = "Duncan's multiple range test (DMRT)",
  "Student-Newman-Keuls"      = "Student-Newman-Keuls (SNK) test",
  "Scheffe"                   = "Scheffe's test")

posthoc <- function(res, effect, method, alpha = res$alpha) {
  e <- res$effects[[effect]]
  if (is.null(e)) stop("Unknown effect.")
  if (!method %in% PH_METHODS) stop("Unknown method")
  m <- e$means
  lab <- apply(m[e$vars], 1, paste, collapse = " : ")
  fams <- if (is.null(e$slice)) list(seq_len(nrow(m)))
          else unname(split(seq_len(nrow(m)), factor(m[[e$slice]], levels = unique(m[[e$slice]]))))
  fams <- fams[lengths(fams) >= 2]
  if (!length(fams)) stop("This effect has fewer than two means.")
  df <- e$df
  ranged <- method %in% c("Student-Newman-Keuls", "Duncan's DMRT")
  if (method %in% c("Tukey HSD", "Student-Newman-Keuls", "Duncan's DMRT") && df < 2)
    stop(sprintf(paste0("%s needs at least 2 error degrees of freedom; this effect has %s. ",
                        "Use the LSD, Bonferroni or Scheffe test, or add replication."),
                 PH_LABELS[[method]], df_text(df)))
  kmax <- max(lengths(fams))
  ## the studentized range for p means spanned (p = 2..kmax), divided by
  ## sqrt(2) so that it multiplies a standard error of a difference; computed
  ## once per span, not once per pair
  qv <- if (ranged) {
    q <- vapply(2:kmax, function(p) {
      pr <- if (method == "Student-Newman-Keuls") 1 - alpha else (1 - alpha)^(p - 1)
      q_tukey(pr, p, df)
    }, numeric(1))
    ## Duncan's ranges must not shrink as more means are spanned; with few error
    ## df the raw quantiles at his protection levels do, so they are held level
    if (method == "Duncan's DMRT") q <- cummax(q)
    c(Inf, q / sqrt(2))
  } else NULL

  run <- function(ix) {
    mu <- m$Mean[ix]; k <- length(mu)
    S <- e$sed_mat[ix, ix, drop = FALSE]            # rows of sed_mat follow e$means
    nC <- k * (k - 1) / 2
    ## the number of means spanned by a pair, counting every mean between the
    ## two values; tied means then share the wider, more cautious range
    ## whatever order their levels happen to be in
    span <- outer(seq_len(k), seq_len(k), Vectorize(function(i, j)
      sum(mu >= min(mu[i], mu[j]) & mu <= max(mu[i], mu[j]))))
    mult <- switch(method,
      "LSD (Fisher's protected)"  = matrix(t_crit(e, alpha), k, k),
      "LSD (Bonferroni-adjusted)" = matrix(stats::qt(1 - alpha / (2 * nC), df), k, k),
      "Tukey HSD"                 = matrix(q_tukey(1 - alpha, k, df) / sqrt(2), k, k),
      "Scheffe"                   = matrix(sqrt((k - 1) * stats::qf(1 - alpha, k - 1, df)), k, k),
      matrix(qv[span], k, k))
    crit <- mult * S
    raw <- abs(outer(mu, mu, "-")) > crit
    diag(raw) <- FALSE
    sig <- if (ranged) step_down(mu, raw) else raw
    lets <- cld_from_sig(mu, sig)

    o <- order(-mu)
    ij <- which(upper.tri(diag(k)), arr.ind = TRUE)
    ij <- ij[order(ij[, 1], ij[, 2]), , drop = FALSE]
    ij <- cbind(o[ij[, 1]], o[ij[, 2]])                 # larger mean first
    pairs <- data.frame(
      Comparison = paste(lab[ix][ij[, 1]], "vs", lab[ix][ij[, 2]]),
      Difference = mu[ij[, 1]] - mu[ij[, 2]],
      SEd = S[ij],
      `Critical value` = mult[ij],
      `Critical difference` = crit[ij],
      Significant = ifelse(sig[ij], "Yes",
                    ifelse(raw[ij], "No (inside a non-significant range)", "No")),
      check.names = FALSE, stringsAsFactors = FALSE)
    list(lets = lets, pairs = pairs, k = k, crit = crit[upper.tri(crit)])
  }
  out <- lapply(fams, run)

  within <- if (is.null(e$slice)) NULL else
    vapply(fams, function(ix) as.character(m[[e$slice]][ix[1]]), character(1))
  groups <- do.call(rbind, lapply(seq_along(fams), function(f) {
    ix <- fams[[f]]
    g <- data.frame(Treatment = lab[ix], Mean = m$Mean[ix], row.names = NULL, check.names = FALSE)
    if (!is.null(m$Raw_mean)) g$`Unadjusted mean` <- m$Raw_mean[ix]
    g <- cbind(g, n = m$N[ix], SE = m$SE[ix], Group = out[[f]]$lets)
    if (!is.null(within)) g <- cbind(Within = within[f], g)
    g[order(-g$Mean), ]
  }))
  rownames(groups) <- NULL
  pairs <- do.call(rbind, lapply(seq_along(fams), function(f) {
    p <- out[[f]]$pairs
    if (!is.null(within)) p <- cbind(Within = within[f], p)
    p
  }))

  ## one critical difference for the whole family only if one really applies
  crit_all <- unlist(lapply(out, `[[`, "crit"))
  equal <- isTRUE(e$equal_rep)
  one_cd <- !ranged && diff(range(crit_all)) <= 1e-9 * max(abs(crit_all))
  ranges <- if (ranged && equal)
    data.frame(`Means apart (p)` = 2:kmax, `Critical range` = qv[2:kmax] * e$sed,
               check.names = FALSE)
  else NULL

  kramer <- !equal && (method == "Tukey HSD" || ranged)
  shown <- if (method == "Tukey HSD" && !equal)
             "Tukey-Kramer procedure (Tukey's HSD for unequal replication)"
           else if (kramer) paste(PH_LABELS[[method]], "with Kramer's adjustment for unequal replication")
           else PH_LABELS[[method]]
  k_txt <- if (is.null(within)) as.character(nrow(m))
           else sprintf("%s within each level of %s", paste(unique(vapply(out, `[[`, numeric(1), "k")),
                                                         collapse = " or "), e$slice)
  st <- data.frame(
    Item  = c("Effect", "Method", "Error mean square", "Error df",
              "SE of a mean (SEm)", "SE of a difference (SEd)",
              "Number of means (k)", "Significance level",
              if (one_cd) "Critical difference (C.D.)" else "Critical difference"),
    Value = c(e$label, shown, fmt(e$mse, 4), df_text(df),
              err_text(e, "sem", 3, html = FALSE), err_text(e, "sed", 3, html = FALSE),
              k_txt, p_lab(alpha),
              if (one_cd) fmt(crit_all[1])
              else if (ranged && equal) "varies with p - see the table of critical ranges"
              else "varies by pair - see the pairwise comparisons"),
    check.names = FALSE)

  f_sig <- !is.na(e$p) && e$p < alpha
  note <- c(
    if (!f_sig)
      sprintf(paste0("The F-test for %s is not significant at the %s%% level, so, as ",
                     "everywhere else in DOEpro, no letters are shown and no pair is ",
                     "declared different."), e$label, pct(alpha)),
    if (!is.null(e$slice))
      sprintf(paste0("Means are compared within each level of %s: these are the only ",
                     "comparisons that share one error term. Letters restart in each level, ",
                     "so the same letter in two levels of %s means nothing."), e$slice, e$slice),
    if (!is.null(e$error_desc)) e$error_desc,
    if (method == "Tukey HSD" && !equal)
      paste0("Replication is unequal, so this is the Tukey-Kramer procedure: Tukey's ",
             "studentized range applied to each pair's own standard error of a difference."),
    if (ranged && !equal)
      paste0("Replication is unequal, so each pair uses its own standard error of a ",
             "difference (Kramer, 1956). agricolae and SAS use the harmonic mean of the ",
             "replications instead, so their critical ranges will differ slightly."),
    if (ranged)
      paste0("As a multiple-range test this is a step-down procedure: two means inside a ",
             "range that is not significant are not declared different, even if their own ",
             "difference exceeds its critical range."),
    if (method %in% c("Tukey HSD", "Student-Newman-Keuls", "Duncan's DMRT"))
      paste0("The critical value in the pairwise table is the studentized range q divided ",
             "by &radic;2, so that critical difference = critical value &times; SEd. Tables of ",
             "q list it before that division."),
    ## notes written for the tables of means describe that table's letters and
    ## level, so they are repeated here only when they apply to this output
    if (is.null(e$slice) && isTRUE(all.equal(alpha, e$alpha))) e$notes,
    if (!isTRUE(all.equal(alpha, e$alpha)))
      sprintf(paste0("These comparisons are at the %s%% level, while the analysis and its ",
                     "tables of means are at the %s%% level."), pct(alpha), pct(e$alpha)))
  note <- note[nzchar(note)]

  list(groups = groups, stats = st, ranges = ranges, pairs = pairs,
       note = if (length(note)) note else NULL, f_sig = f_sig, alpha = alpha,
       method = PH_LABELS[[method]])
}

## What the user sees and exports: the procedure's letters and verdicts only
## when the effect's F-test is significant, as for every other table in
## DOEpro. posthoc() itself keeps them, as an effect keeps its letters.
gate_posthoc <- function(x) {
  if (isTRUE(x$f_sig)) return(x)
  x$groups$Group <- ""
  x$pairs$Significant <- sprintf("Not declared (F-test not significant at %s%%)", pct(x$alpha))
  x
}

## Multiple-range tests are step-down procedures: once a range of means is
## declared homogeneous, no pair inside it may be declared different. Working
## from the widest range inwards, a pair stays significant only if both ranges
## one step wider than it were significant, and therefore every range around it.
## With tied means the enclosing ranges are taken by value, not by position: a
## pair keeps its own test and is gated by every range that strictly encloses
## its two values, so the result does not depend on the order in which tied
## levels happen to sit. Without ties this is the recursion above unchanged.
step_down <- function(mu, sig) {
  k <- length(mu); o <- order(mu, decreasing = TRUE)
  s <- sig[o, o, drop = FALSE]; v <- mu[o]
  out <- matrix(FALSE, k, k)
  for (w in rev(seq_len(k - 1))) for (i in seq_len(k - w)) {
    j <- i + w
    out[i, j] <- s[i, j] && (i == 1 || out[i - 1, j]) && (j == k || out[i, j + 1])
  }
  first <- vapply(v, function(x) min(which(v == x)), integer(1))  # start of each tie block
  last  <- vapply(v, function(x) max(which(v == x)), integer(1))  # end of each tie block
  fin <- matrix(FALSE, k, k)
  for (i in seq_len(k - 1)) for (j in (i + 1):k) {
    ## a range reaching above the larger value, or below the smaller one
    above <- first[i] == 1 || out[first[i] - 1, first[j]]
    below <- last[j] == k || out[last[i], last[j] + 1]
    fin[i, j] <- s[i, j] && above && below
  }
  fin <- fin | t(fin)
  res <- matrix(FALSE, k, k)
  res[o, o] <- fin
  res
}

## qtukey() fails to converge for the long ranges Duncan's test needs once about
## twenty means are compared (it returns NaN); inverting ptukey() does not
q_tukey <- function(pr, p, df) {
  q <- suppressWarnings(stats::qtukey(pr, p, df))
  if (is.finite(q)) return(q)
  f <- function(x) stats::ptukey(x, p, df) - pr
  if (!is.finite(f(1e-3)) || !is.finite(f(100)))
    stop(sprintf(paste0("The studentized range cannot be computed for %d means on %s ",
                        "error degrees of freedom. Use the LSD, Bonferroni or Scheffe test."),
                 p, df_text(df)), call. = FALSE)
  stats::uniroot(f, c(1e-3, 100), tol = 1e-12)$root
}

## degrees of freedom: whole numbers as they are, Satterthwaite's to one decimal
df_text <- function(df) if (abs(df - round(df)) < 1e-8) as.character(round(df)) else fmt(df, 1)

## ---------------------------------------------------------- plots.R ----
###############################################################################
##  PLOTS
###############################################################################
theme_doe <- function() {
  theme_bw(base_size = 13) +
    theme(panel.grid.minor = element_blank(),
          legend.position = "bottom",
          plot.title = element_text(face = "bold", size = 13))
}

## when the response was transformed, say so on the plot
scale_note <- function(res) {
  if (is.null(res$trans) || identical(res$trans, "none")) return(NULL)
  paste("Transformed scale:", TRANS[[res$trans]]$lab)
}

## What the error bars and letters on a plot of means mean, at the chosen level.
## For a split, strip or pooled interaction both differ: the bars are the SE(m)
## for comparing means at the same level of the slicing factor, and the letters
## restart in each of its levels.
plot_caption <- function(e, bars, lets_on) {
  sl <- e$slice
  bars <- if (!bars) NULL
          else if (is.null(sl)) "Error bars: one standard error either side of each mean."
          else sprintf("Error bars: SE(m) for comparing means at the same level of %s (SE(d) / sqrt(2)).", sl)
  lets <- if (!lets_on) NULL
          else if (!effect_sig(e))
            sprintf("No letters: the F-test is not significant at the %s%% level.", pct(e$alpha))
          else if (is.null(sl))
            sprintf("Means sharing a letter are not significantly different at the %s%% level.", pct(e$alpha))
          else sprintf(paste0("Letters compare means within the same level of %s only; there, ",
                              "means sharing a letter are not significantly different at the %s%% level."),
                       sl, pct(e$alpha))
  if (is.null(c(bars, lets))) NULL else paste(c(bars, lets), collapse = " ")
}

## How strongly a factor asks to be the X-axis of an interaction plot. Only
## numbered labels qualify: their natural order is their order in time or
## size, whereas worded labels (Vegetative, Flowering) sort alphabetically and
## a line through them would run in the wrong order. Time comes first,
## recognised by the column name (Days, Week, Stage, Interval...) or by a
## common stem (D0, D60; Week1, Week2; 30 DAS). Next come labels that carry
## real quantities (N0, N60, N120; 2021, 2022; 0, 25, 50) rather than mere
## numbering (T1, T2, V1, V2, V4), which is read as codes. One unnumbered label
## such as Control or Fresh may sit among the numbered ones.
TIME_NAME <- "(^|[^a-z])(day|days|das|dat|dae|doy|time|week|weeks|month|months|year|years|stage|stages|interval|period|storage|hour|hours|date)([^a-z]|$)"
TIME_STEM <- "^(d|day|days|das|dat|dap|dae|doy|h|hr|hrs|hour|hours|wk|wks|week|weeks|month|months|yr|yrs|year|years)$"

x_score <- function(name, lv) {
  num <- "[0-9]+(?:[.][0-9]+)?"
  cnt <- lengths(regmatches(lv, gregexpr(num, lv, perl = TRUE)))
  lab <- lv[cnt == 1]
  if (length(lab) < 2 || any(cnt > 1) || sum(cnt == 0) > 1) return(0)
  stem <- unique(gsub("[^a-z]", "", tolower(gsub(num, "", lab, perl = TRUE))))
  one_stem <- length(stem) == 1
  n <- sort(as.numeric(regmatches(lab, regexpr(num, lab, perl = TRUE))))
  step <- diff(n)
  ## codes: whole numbers starting at 0 or 1 that either run 1, 2, 3 or skip
  ## unevenly (a dropped entry: V1, V2, V4); evenly spaced rates (0, 2, 4;
  ## 0, 40, 80) and other values are quantities
  counting <- anyDuplicated(n) > 0 ||
    (all(n == round(n)) && n[1] %in% c(0, 1) &&
     (all(step == 1) || length(unique(round(step, 9))) > 1))
  ## a one-letter stem (D, H) counts as time only on real quantities, so D0,
  ## D60 and H6, H12 are times while the dose codes D1, D2 and hybrids H1, H2
  ## are not
  stem_time <- one_stem && grepl(TIME_STEM, stem) && (nchar(stem) > 1 || !counting)
  is_time <- grepl(TIME_NAME, tolower(name)) || stem_time
  2 * is_time + (one_stem && !counting)
}

## The factor that goes on the X-axis by default: the best-scoring one above,
## the one with more levels on a tie, and otherwise the effect's first factor.
default_x <- function(e, d) {
  v <- e$vars
  sc <- vapply(v, function(f) x_score(f, levels(d[[f]])), numeric(1))
  if (max(sc) <= 0) return(v[1])
  cand <- v[sc == max(sc)]
  cand[which.max(vapply(cand, function(f) nlevels(d[[f]]), numeric(1)))]
}

## `x_var` names the factor for the X-axis of an interaction plot; by default
## default_x() chooses it. The other factor becomes the lines (or the bar
## colours), and any further factors become panels.
plot_main <- function(res, effect, type = "bar", show_letters = TRUE, x_var = NULL) {
  e <- res$effects[[effect]]; d <- res$data; resp <- res$resp
  m <- gate_letters(e)              # no letters under a non-significant F-test
  v <- e$vars
  m$.se <- m$SE                     # each mean's own SE: replication may differ
  lab_y <- max(m$Mean + m$.se) * 1.06

  if (length(v) == 1) {
    p <- ggplot(m, aes(x = .data[[v]], y = Mean)) +
      (if (type == "bar")
        geom_col(fill = "#3B7DD8", width = .65)
       else if (type == "box")
        geom_boxplot(data = d, aes(x = .data[[v]], y = .data[[resp]]),
                     fill = "#BBD3F2", inherit.aes = FALSE)
       else geom_point(size = 3, colour = "#3B7DD8")) +
      (if (type != "box") geom_errorbar(aes(ymin = Mean - .se, ymax = Mean + .se),
                                        width = .15) else NULL) +
      (if (show_letters && type != "box")
        geom_text(aes(y = Mean + .se, label = Letter), vjust = -0.6, size = 4.5) else NULL) +
      labs(title = paste("Effect of", v, "on", resp), y = resp, x = v,
           subtitle = scale_note(res),
           caption = plot_caption(e, type != "box", show_letters && type != "box")) +
      theme_doe()
    return(p)
  }

  f1 <- if (length(x_var) == 1L && isTRUE(x_var %in% v)) x_var else default_x(e, d)
  rest <- setdiff(v, f1)
  f2 <- rest[1]
  lt <- if ("Letter" %in% names(m)) "Letter" else
        if ("Letter_within_MP" %in% names(m)) "Letter_within_MP"
        else if ("Letter_within_env" %in% names(m)) "Letter_within_env"
        else "Letter_within_A"
  base <- ggplot(m, aes(x = .data[[f1]], y = Mean, fill = .data[[f2]],
                        colour = .data[[f2]], group = .data[[f2]]))
  p <- switch(type,
    "bar" = base + geom_col(position = position_dodge(.8), width = .7, colour = NA) +
      geom_errorbar(aes(ymin = Mean - .se, ymax = Mean + .se),
                    position = position_dodge(.8), width = .2, colour = "grey30") +
      (if (show_letters) geom_text(aes(y = Mean + .se, label = .data[[lt]]),
        position = position_dodge(.8), vjust = -0.5, size = 4, colour = "black") else NULL),
    "line" = base + geom_line(linewidth = 1) + geom_point(size = 3) +
      geom_errorbar(aes(ymin = Mean - .se, ymax = Mean + .se), width = .12),
    "heat" = ggplot(m, aes(x = .data[[f1]], y = .data[[f2]], fill = Mean)) +
      geom_tile(colour = "white") +
      geom_text(aes(label = fmt(Mean, 1)), colour = "black", size = 4) +
      scale_fill_gradient(low = "#EAF1FB", high = "#1B4F9C"),
    "box" = ggplot(d, aes(x = .data[[f1]], y = .data[[resp]], fill = .data[[f2]])) +
      geom_boxplot(position = position_dodge(.8)))
  if (length(rest) > 1) p <- p + facet_wrap(stats::as.formula(
    paste("~", paste(rest[-1], collapse = "+"))))
  p <- p + labs(title = paste("Interaction:", e$label), y = resp, x = f1,
                colour = f2, subtitle = scale_note(res),
                caption = plot_caption(e, type %in% c("bar", "line"),
                                       show_letters && type == "bar")) + theme_doe()
  if (type == "heat") p + labs(fill = paste("Mean", resp), y = f2) else p + labs(fill = f2)
}

plot_diag <- function(res) {
  df <- data.frame(fit = res$fitted, res = res$resid,
                   std = res$resid / stats::sd(res$resid))
  p1 <- ggplot(df, aes(fit, res)) + geom_hline(yintercept = 0, lty = 2) +
    geom_point(colour = "#3B7DD8") + labs(title = "Residuals vs fitted",
    x = "Fitted", y = "Residual") + theme_doe()
  p2 <- ggplot(df, aes(sample = std)) + stat_qq(colour = "#3B7DD8") + stat_qq_line() +
    labs(title = "Normal Q-Q plot", x = "Theoretical", y = "Standardised residual") + theme_doe()
  p3 <- ggplot(df, aes(res)) + geom_histogram(bins = 12, fill = "#BBD3F2", colour = "white") +
    labs(title = "Histogram of residuals", x = "Residual", y = "Count") + theme_doe()
  ## With only a few distinct fitted values (a CRD has one per treatment) a
  ## loess curve swings between them and rises where there are no points, so
  ## the trend joins the mean at each fitted value instead.
  df$sl <- sqrt(abs(df$std))
  df$at <- signif(df$fit, 10)
  trend <- if (length(unique(df$at)) <= 10) {
    m <- stats::aggregate(sl ~ at, data = df, FUN = mean)
    geom_line(data = m, aes(.data$at, .data$sl), colour = "#C0392B", linewidth = 0.9)
  } else geom_smooth(se = FALSE, method = "loess", formula = y ~ x,
                     method.args = list(degree = 1), colour = "#C0392B")
  p4 <- ggplot(df, aes(.data$fit, .data$sl)) + geom_point(colour = "#3B7DD8") + trend +
    labs(title = "Scale-location", x = "Fitted", y = "sqrt|std residual|") + theme_doe()
  list(p1, p2, p3, p4)
}

plot_boxcox <- function(asm) {
  bc <- asm$bc
  if (is.null(bc)) return(NULL)
  df <- data.frame(lambda = bc$x, loglik = bc$y)
  df <- df[stats::complete.cases(df), ]
  ggplot(df, aes(lambda, loglik)) +
    geom_line(colour = "#3B7DD8", linewidth = 1) +
    geom_vline(xintercept = bc$lambda, colour = "#C0392B", lty = 2) +
    geom_vline(xintercept = bc$ci, colour = "grey55", lty = 3) +
    annotate("text", x = bc$lambda, y = min(df$loglik), vjust = -0.4, hjust = -0.1,
             label = sprintf("lambda = %.2f", bc$lambda), colour = "#C0392B", size = 3.6) +
    labs(title = sprintf("Box-Cox profile (optimal lambda = %.2f, %s%% CI %.2f to %.2f)",
                         bc$lambda, pct(bc$level), bc$ci[1], bc$ci[2]),
         x = "lambda", y = "log-likelihood") + theme_doe()
}

plot_meanvar <- function(asm) {
  if (nrow(asm$mv) < 3) return(NULL)
  ggplot(asm$mv, aes(log(m), log(v))) + geom_point(size = 2.5, colour = "#3B7DD8") +
    geom_smooth(method = "lm", formula = y ~ x, se = FALSE, colour = "#C0392B") +
    labs(title = sprintf("Mean-variance relationship (Taylor slope b = %.2f)", asm$slope),
         x = "log(cell mean)", y = "log(cell variance)") + theme_doe()
}

## ---------------------------------------------------------- descriptives.R ----
###############################################################################
##  DESCRIPTIVE STATISTICS
###############################################################################
## A summary of each numeric variable and four plots of its distribution, each
## followed by a plain-language reading of what it shows. Everything here
## describes the observations as they are; whether differences between
## treatments are real is a question for the analysis of variance, and the
## text says so rather than drawing conclusions the numbers cannot support.
## Every sentence states only what the numbers checked for it show: where two
## measures disagree, the text says so instead of picking one.

## How far the ends of a normal Q-Q plot bend in samples that really are
## normal, by sample size: the 99.5th percentile, over 20,000 normal samples
## of each size, of an end reaching out beyond the line (`out`, in units of
## the line's slope) and of an end stopping short of it (`inward`, in
## standard deviations); see qq_ends(). Each kind of bend is measured on the
## scale its cause does not inflate: heavy tails inflate the SD, two clusters
## inflate the quartiles. With both limits, normal values of that size are
## read as bending about once in a hundred. Computed once with
## set.seed(20261008); tests/testthat/test-descriptives.R checks a fresh
## simulation against them. The table is dense where the number of points
## averaged at each end changes (every ten values).
