## fmt() without a minus sign on a figure that rounds to zero
dfmt <- function(x, d) sub("^-(0[.]?0*)$", "\\1", fmt(x, d))

## "row 3" with a capital, to start a sentence; a name written in mixed case
## (pH, kgN) is left as it is
cap1 <- function(s)
  ifelse(grepl("^[a-z]+[A-Z]", s), s, paste0(toupper(substr(s, 1, 1)), substring(s, 2)))

## the order of magnitude of a positive number, rounded first so that an SD
## of 0.0999999999 counts as the 0.1 it is
mag <- function(z) floor(log10(signif(z, 6)))

## a typical spread: the interquartile range on the scale of an SD, which one
## wild value cannot inflate; the SD itself when the quartiles coincide
spread_of <- function(z) {
  z <- z[is.finite(z)]
  if (length(z) < 2) return(NA_real_)
  s <- stats::IQR(z) / 1.349
  if (s > 0) s else if (stats::sd(z) > 0) stats::sd(z) else NA_real_
}

## Decimals for a variable: about three significant figures of its typical
## (median) size and two of its typical spread, so neither a small unit nor a
## small spread rounds to zero, and one wild value (1250 typed for 1.25) does
## not set the precision of everything else. Given the groups `g`, each
## group's SD keeps two significant figures too, so a grouped table never
## shows a group's SD as 0. Whole numbers need no more than two decimals.
var_digits <- function(x, g = NULL) {
  ok <- is.finite(x)
  v <- x[ok]
  nz <- abs(v[v != 0])
  if (!length(nz)) return(2L)
  dg <- 3 - mag(stats::median(nz))
  sp <- spread_of(v)
  if (!is.null(g)) {
    gs <- vapply(split(v, g[ok]), function(z) if (length(z) > 1) stats::sd(z) else NA_real_, numeric(1))
    sp <- c(sp, gs[is.finite(gs) & gs > 0])
  }
  sp <- sp[is.finite(sp)]
  if (length(sp)) dg <- max(dg, 1 - mag(min(sp)))
  dg <- as.integer(min(10, max(0, dg)))
  if (all(v == round(v))) min(dg, 2L) else dg
}

## Excel's SKEW: the adjusted Fisher-Pearson coefficient of skewness, about 0
## for a symmetric spread, positive when the high values trail further out
skew_of <- function(v) {
  n <- length(v)
  if (n < 3) return(NA_real_)
  s <- stats::sd(v)
  if (s == 0) return(NA_real_)
  n / ((n - 1) * (n - 2)) * sum(((v - mean(v)) / s)^3)
}

## its standard error for n values from a normal distribution
skew_se <- function(n) sqrt(6 * n * (n - 1) / ((n - 2) * (n + 1) * (n + 3)))

## the numbers of one variable (one group), and everything said about them
desc_one <- function(x) {
  ## an infinite value is not a measurement, so it counts as missing
  v <- x[is.finite(x)]
  n <- length(v)
  q <- if (n) stats::quantile(v, c(0.25, 0.5, 0.75), type = 7, names = FALSE) else rep(NA_real_, 3)
  mu <- if (n) mean(v) else NA_real_
  s <- if (n > 1) stats::sd(v) else NA_real_
  list(N = n, Missing = sum(!is.finite(x)), Mean = mu, SD = s,
       Min = if (n) min(v) else NA_real_, Q1 = q[1], Median = q[2], Q3 = q[3],
       Max = if (n) max(v) else NA_real_,
       ## a CV compares the spread with the mean, which only makes sense for
       ## values that cannot be negative and are not all zero
       CV = if (n > 1 && min(v) >= 0 && is.finite(mu) && mu > 0) 100 * s / mu else NA_real_,
       Skewness = skew_of(v))
}

## A grouping column as a factor. Numbers are labelled as written (100000,
## not 1e+05) and kept in numeric order, a factor keeps its own order, and
## text takes its natural order; blank labels count as missing, so a row with
## no label is never a group of its own.
group_labels <- function(d, group) {
  x <- d[[group]]
  if (is.numeric(x)) {
    ok <- is.finite(x)
    lab <- rep(NA_character_, length(x))
    lab[ok] <- num_text(x[ok])
    return(factor(lab, levels = num_text(sort(unique(x[ok])))))
  }
  g <- trimws(as.character(x))
  g[!is.na(g) & g == ""] <- NA
  lv <- if (is.factor(x)) unique(trimws(levels(x))) else natural_levels(g)
  factor(g, levels = lv[lv %in% g])
}

#' Descriptive statistics for numeric variables
#'
#' For each variable: the number of values (N), the number missing, the mean,
#' standard deviation (SD), minimum, first quartile (Q1), median, third
#' quartile (Q3), maximum, coefficient of variation (CV, per cent) and
#' skewness, optionally for each level of a grouping column. Quartiles are
#' calculated as Excel's QUARTILE.INC does (\code{quantile(type = 7)}) and
#' skewness as Excel's SKEW does (the adjusted Fisher-Pearson coefficient).
#' Text entries are read as the data check reads them: an entry that is not
#' plainly a number (such as 5,6 or 12a) counts as missing; see
#' \code{\link{check_data}}.
#'
#' @param d A data frame.
#' @param vars The names of the numeric columns to describe.
#' @param group Optionally, the name of a column whose levels split each
#'   variable into groups. Rows without a label in it are left out.
#'
#' @return A data frame with one row per variable (and group): \code{Variable},
#'   \code{Group} (when grouped), \code{N}, \code{Missing}, \code{Mean},
#'   \code{SD}, \code{Min}, \code{Q1}, \code{Median}, \code{Q3}, \code{Max},
#'   \code{CV} and \code{Skewness}. CV is \code{NA} when any value is negative
#'   or the mean is not positive, where it has no useful meaning; skewness
#'   needs three values that are not all equal. Missing counts empty cells,
#'   entries that are not numbers and infinite values.
#'
#' @examples
#' describe_data(demo_data("RCBD"), "Yield")
#' describe_data(demo_data("RCBD"), "Yield", group = "Variety")
#'
#' @export
describe_data <- function(d, vars, group = NULL) {
  if (!length(vars)) stop("Choose at least one variable to describe.")
  if (!is.null(group) && !nzchar(group)) group <- NULL
  gone <- setdiff(c(vars, group), names(d))
  if (length(gone))
    stop(sprintf("%s %s of the data.", join_and(sprintf("'%s'", gone)),
                 pl(length(gone), "is not a column", "are not columns")))
  if (!is.null(group)) {
    g <- group_labels(d, group)
    if (!nlevels(g)) stop(sprintf("'%s' has no labels to group the rows by.", group))
  }
  out <- lapply(vars, function(v) {
    x <- response_values(d[[v]])
    if (is.null(group)) return(data.frame(Variable = v, desc_one(x), check.names = FALSE))
    do.call(rbind, lapply(levels(g), function(lv)
      data.frame(Variable = v, Group = lv, desc_one(x[!is.na(g) & g == lv]), check.names = FALSE)))
  })
  res <- do.call(rbind, out)
  rownames(res) <- NULL
  res
}

## values beyond Tukey's fences (more than 1.5 times the interquartile range
## beyond the quartiles): the points a box plot draws on their own
unusual <- function(x) {
  q <- stats::quantile(x[is.finite(x)], c(0.25, 0.75), type = 7, names = FALSE)
  w <- 1.5 * (q[2] - q[1])
  which(is.finite(x) & (x < q[1] - w | x > q[2] + w))
}

## the same, judged within each group, as a box plot by group draws them
unusual_within <- function(x, g)
  sort(unlist(lapply(split(seq_along(x), g), function(i) i[unusual(x[i])]), use.names = FALSE))

## The shape of a distribution, from the skewness in the table read with
## Bulmer's (1979) bands: under 0.5 either way roughly symmetric, 0.5 to 1
## moderately skewed, over 1 strongly. `clear` is FALSE when a skewness that
## size could easily arise by chance in symmetric data of this size (within
## two standard errors), which the text then says.
shape_of <- function(s) {
  out <- list(kind = "unclear", g1 = s$Skewness, strength = "", clear = FALSE,
              heaped = FALSE)
  if (s$N == 0) return(out)
  if (s$N > 1 && s$SD == 0) { out$kind <- "constant"; return(out) }
  if (s$N < 5) return(out)
  out$heaped <- s$Q3 == s$Q1
  ## judged as printed, so two skewnesses that both print as 0.50 read alike
  g <- as.numeric(dfmt(s$Skewness, 2))
  out$kind <- if (g >= 0.5) "right" else if (g <= -0.5) "left" else "symmetric"
  out$strength <- if (abs(g) > 1) "strongly" else "moderately"
  out$clear <- abs(g) > 2 * skew_se(s$N)
  out
}

## how much the values vary relative to their mean, in words, judged on the
## CV as it is printed so that the word and the number never disagree
cv_words <- function(cv) {
  if (is.na(cv)) return("")
  cv <- as.numeric(fmt(cv, 1))
  if (cv < 10) "little" else if (cv < 20) "moderately" else if (cv < 30) "considerably" else "a great deal"
}

## Entries left out only because they are written in a form the data check
## flags (5,6; 1,250; 45%; 12 kg): numbers the user can bring in by correcting
## them on the Data tab, which the text should say rather than leave a column
## looking empty.
held_text <- function(raw) {
  if (is.numeric(raw)) return(NULL)
  k <- which(read_entries(raw)$kind %in% setdiff(NUMBER_KINDS, "number"))
  if (!length(k)) return(NULL)
  sprintf("%d %s written in a form the data check has flagged (such as '%s'); correct %s on the Data tab to include %s here.",
          length(k), pl(length(k), "entry is a number", "entries are numbers"), trimws(as.character(raw[k[1]])),
          pl(length(k), "it", "them"), pl(length(k), "it", "them"))
}

## "Variety V2", "Variety V2 and Variety V5", at most six named
group_names <- function(group, lv) join_and(head_more(sprintf("%s %s", group, lv), 6))

## the groups whose printed figure is the highest or the lowest: figures are
## compared as they are printed, so a tie in the table is a tie in the text
at_extreme <- function(txt, fun) which(as.numeric(txt) == fun(as.numeric(txt)))

## Which way the values reach further from the median, judged on the
## minimum, median and maximum as the table prints them: "up", "down" or
## "even". The skewness weighs the values furthest out most heavily but not
## only them, so the two usually agree and sometimes do not; when they do
## not, the text says so rather than state a direction the table contradicts.
reach_of <- function(s, digits) {
  p <- function(z) as.numeric(dfmt(z, digits))
  up <- p(s$Max) - p(s$Median); down <- p(s$Median) - p(s$Min)
  if (abs(up - down) < 1e-9 * max(1, abs(up), abs(down))) "even" else if (up > down) "up" else "down"
}

## The sentence on skewness, for the table reading. `s` is desc_one() of the
## values and `digits` the decimals the table prints them to.
skew_text <- function(sh, s, digits) {
  f <- function(z) dfmt(z, digits)
  g <- dfmt(sh$g1, 2)
  if (!sh$kind %in% c("right", "left"))
    return(switch(sh$kind,
      symmetric = sprintf("The skewness of %s is close to zero, so by this measure the values are spread roughly evenly about their mean.", g),
      "There are too few values to say much about the shape of the distribution."))
  side <- if (sh$kind == "right") "up" else "down"
  r <- reach_of(s, digits)
  out <- if (r == side)
    sprintf("The skewness of %s means the values are %s skewed to the %s: they reach further %s the median (%s %s) than %s it (%s %s).",
            g, sh$strength, sh$kind, if (side == "up") "above" else "below",
            if (side == "up") "up to" else "down to", f(if (side == "up") s$Max else s$Min),
            if (side == "up") "below" else "above",
            if (side == "up") "down to" else "up to", f(if (side == "up") s$Min else s$Max))
  else sprintf(paste("The skewness of %s counts as %s %s skew, but the %s value lies %s from the median than the %s,",
                     "so the skew does not come from a long tail of %s values; the histogram shows where the values lie."),
               g, if (sh$strength == "strongly") "a strong" else "a moderate", sh$kind,
               if (side == "up") "lowest" else "highest", if (r == "even") "as far" else "further",
               if (side == "up") "highest" else "lowest", if (side == "up") "high" else "low")
  if (!sh$clear)
    out <- paste(out, sprintf("With %d values, a skewness this size can also arise by chance in values from a symmetric distribution.", s$N))
  out
}

## The reading of the summary table for one variable. `raw` is the column as
## it is in the data (numbers or text); `rows` the row numbers of the data,
## for naming unusual values.
describe_text <- function(v, raw, rows, digits = NULL) {
  x <- response_values(raw)
  if (is.null(digits)) digits <- var_digits(x)
  s <- desc_one(x); sh <- shape_of(s)
  f <- function(z) dfmt(z, digits)
  if (s$N == 0)
    return(paste(c(sprintf("'%s' has no values that can be read as numbers.", v), held_text(raw)), collapse = " "))
  out <- character(0)
  if (s$Missing)
    out <- c(out, sprintf("%d of the %d rows %s no usable value and %s left out of these figures.",
      s$Missing, s$N + s$Missing, pl(s$Missing, "has", "have"), pl(s$Missing, "is", "are")), held_text(raw))
  if (s$N == 1) return(paste(c(out, sprintf("'%s' has a single value, %s.", v, num_text(x[is.finite(x)]))), collapse = " "))
  if (sh$kind == "constant")
    return(paste(c(out, sprintf("Every value of '%s' is %s, so there is no variation to describe.", v,
                                num_text(s$Mean))), collapse = " "))
  out <- c(out, if (s$N >= 5)
    sprintf("The %d values of '%s' average %s (median %s) and run from %s to %s; the middle half lie between %s and %s.",
            s$N, v, f(s$Mean), f(s$Median), f(s$Min), f(s$Max), f(s$Q1), f(s$Q3))
  else sprintf("The %d values of '%s' average %s (median %s) and run from %s to %s.",
               s$N, v, f(s$Mean), f(s$Median), f(s$Min), f(s$Max)))
  out <- c(out, if (!is.na(s$CV))
    sprintf(paste0("The CV of %s%% means the values vary %s relative to their mean. This CV ",
      "covers all the observations, differences between treatments included, so it is not the ",
      "experimental CV of an analysis of variance, which measures only the unexplained variation."),
      fmt(s$CV, 1), cv_words(s$CV))
  else sprintf("No coefficient of variation is given: it needs values that cannot be negative, and the smallest value here is %s.",
               num_text(s$Min)))
  if (sh$heaped) out <- c(out, sprintf("At least half the values are exactly %s.", num_text(s$Median)))
  out <- c(out, skew_text(sh, s, digits))
  u <- unusual(x)
  if (length(u))
    out <- c(out, sprintf(paste0("%d %s outside the usual range for this variable (more than 1.5 times the ",
      "spread of the middle half beyond the quartiles): %s. Check %s for recording errors. %s from a ",
      "treatment that really differs can look unusual too, so do not remove %s only because %s unusual."),
      length(u), pl(length(u), "value lies", "values lie"),
      join_and(head_more(sprintf("%s in row %s", num_text(x[u]), rows[u]), 6)),
      pl(length(u), "it", "them"), pl(length(u), "A value", "Values"),
      pl(length(u), "it", "them"), pl(length(u), "it is", "they are")))
  if (s$N >= 5 && s$N < 8)
    out <- c(out, "With so few values, the quartiles and the shape are only a rough guide.")
  paste(out, collapse = " ")
}

## The reading of the table when it is split by a grouping column: what the
## groups' figures in the table show, judged group by group. Nothing here is
## a test; whether the groups differ is for the analysis of variance.
describe_group_text <- function(v, raw, g, rows, group, digits = NULL) {
  x <- response_values(raw)
  if (is.null(digits)) digits <- var_digits(x, g)
  lab <- !is.na(g)
  st <- lapply(split(x[lab], g[lab]), desc_one)
  n <- vapply(st, function(s) as.numeric(s$N), numeric(1))
  has <- names(st)[n > 0]
  out <- character(0)
  if (any(!lab))
    out <- c(out, sprintf("%s %s no label in '%s' and %s left out of the groups.",
      cap1(rows_text(rows[!lab])), pl(sum(!lab), "has", "have"), group, pl(sum(!lab), "is", "are")))
  if (nlevels(g) == 1)
    return(paste(c(out, sprintf("Every row with a label in '%s' has the same one, %s, so there are no groups to compare.",
                                group, levels(g))), collapse = " "))
  miss <- sum(vapply(st, function(s) as.numeric(s$Missing), numeric(1)))
  if (miss)
    out <- c(out, sprintf("Within the groups, %d %s no usable value and %s left out of the figures.",
      miss, pl(miss, "row has", "rows have"), pl(miss, "is", "are")), held_text(raw[lab]))
  if (!length(has))
    return(paste(c(out, sprintf("No group of %s has a value of '%s' that can be read as a number.", group, v)),
                 collapse = " "))
  if (any(n == 0))
    out <- c(out, sprintf("%s %s no usable values.", cap1(group_names(group, names(st)[n == 0])),
                          pl(sum(n == 0), "has", "have")))
  if (length(has) == 1)
    return(paste(c(out, sprintf("Only %s has values, so there is nothing to compare between groups.",
                                group_names(group, has))), collapse = " "))
  mu <- dfmt(vapply(st[has], function(s) s$Mean, numeric(1)), digits)
  every <- length(has) == nlevels(g)
  out <- c(out, if (length(unique(mu)) == 1)
    (if (every) sprintf("Every group of %s has the same mean of '%s', %s.", group, v, mu[1])
     else sprintf("%s have the same mean of '%s', %s.", cap1(group_names(group, has)), v, mu[1]))
  else sprintf("The group means of '%s' run from %s (%s) to %s (%s).", v,
               mu[at_extreme(mu, min)[1]], group_names(group, has[at_extreme(mu, min)]),
               mu[at_extreme(mu, max)[1]], group_names(group, has[at_extreme(mu, max)])))
  cv <- vapply(st[has], function(s) s$CV, numeric(1))
  ok <- !is.na(cv)
  if (any(ok)) {
    cvo <- fmt(cv[ok], 1); nm <- has[ok]
    out <- c(out, if (length(cvo) == 1)
      sprintf("The CV within %s is %s%%.", group_names(group, nm), cvo)
    else if (length(unique(cvo)) == 1)
      (if (all(ok) && every) sprintf("The CV within every group is %s%%.", cvo[1])
       else sprintf("The CV within %s is %s%%.", group_names(group, nm), cvo[1]))
    else sprintf("The CV within a group runs from %s%% (%s) to %s%% (%s).",
                 cvo[at_extreme(cvo, min)[1]], group_names(group, nm[at_extreme(cvo, min)]),
                 cvo[at_extreme(cvo, max)[1]], group_names(group, nm[at_extreme(cvo, max)])),
      sprintf(paste("%s only the observations within one group, so differences between groups are not part",
                    "of it; it is not the experimental CV of an analysis of variance either."),
              if (length(cvo) == 1) "It covers" else "Each covers"))
  }
  if (any(!ok)) {
    ## why each group without a CV has none, from its own figures
    why <- vapply(st[has[!ok]], function(s) if (s$N < 2) "one" else if (s$Min < 0) "negative" else "zero", "")
    nm <- has[!ok]
    for (w in c("one", "negative", "zero")) if (any(why == w)) {
      k <- sum(why == w); who <- group_names(group, nm[why == w])
      out <- c(out, switch(w,
        one = sprintf("No CV is given for %s, which %s only one value.", who, pl(k, "has", "have")),
        negative = sprintf("No CV is given for %s: a CV needs values that cannot be negative.", who),
        zero = sprintf("No CV is given for %s, where every value is zero.", who)))
    }
  }
  ## Tukey's fences cannot mark any of three values or fewer, so only groups
  ## of four or more can show an unusual value within themselves
  small <- has[n[has] <= 3]
  u <- unusual_within(x, g)
  if (length(u))
    out <- c(out, sprintf(paste0("Judged within %s own group, %d %s outside the usual range (more than 1.5 times the ",
      "spread of the group's middle half beyond its quartiles): %s. Check %s for recording errors; ",
      "do not remove %s only because %s unusual."),
      pl(length(u), "its", "their"), length(u), pl(length(u), "value lies", "values lie"),
      join_and(head_more(sprintf("%s in row %s (%s %s)", num_text(x[u]), rows[u], group,
                                 as.character(g[u])), 6)),
      pl(length(u), "it", "them"), pl(length(u), "it", "them"), pl(length(u), "it is", "they are")))
  else if (length(small) < length(has))
    out <- c(out, if (length(small)) "No value lies outside the usual range of its own group, in the groups with four or more values."
                  else "No value lies outside the usual range of its own group.")
  if (length(small))
    out <- c(out, if (length(small) == length(has))
      "Every group has three or fewer values, too few for any value to stand out within its group."
    else sprintf("%s %s three or fewer values, too few for any value to stand out within %s.",
                 cap1(group_names(group, small)), pl(length(small), "has", "have"), pl(length(small), "it", "them")))
  if (any(n[n > 0] < 5))
    out <- c(out, "Groups with fewer than five values give only a rough guide to their quartiles.")
  out <- c(out, "These figures describe the observations; whether the groups really differ is for the analysis of variance to judge.")
  paste(out, collapse = " ")
}

## ------------------------------------------------------------------ plots ----

## The data of one variable as a frame for plotting, with the row numbers and,
## when a grouping column is given, the group. Rows without a group label are
## dropped only when `drop` is TRUE (the box plot by group, which cannot place
## them); the other plots draw every row.
desc_frame <- function(d, v, group = NULL, drop = TRUE) {
  x <- response_values(d[[v]])
  out <- data.frame(value = x, row = row_ids(d))
  if (!is.null(group) && nzchar(group)) {
    out$group <- group_labels(d, group)
    if (drop) out <- out[!is.na(out$group), , drop = FALSE]
  }
  out[is.finite(out$value), , drop = FALSE]
}

## The fewest values each plot is drawn from. A plot is not drawn below this,
## nor (for the density and Q-Q plots) when every value is the same; the
## reason is what the app shows in its place.
PLOT_MIN <- c(hist = 2, box = 2, density = 3, qq = 3)
plot_refusal <- function(kind, x) {
  if (length(x) < PLOT_MIN[[kind]]) return("There are too few values to draw this plot.")
  if (kind %in% c("density", "qq") && stats::sd(x) == 0)
    return(sprintf("Every value is %s, so there is no spread to draw.", num_text(x[1])))
  NULL
}

## lines for the mean and the median, with a key, for the histogram and density
centre_lines <- function(x) {
  data.frame(what = factor(c("Mean", "Median"), levels = c("Mean", "Median")),
             at = c(mean(x), stats::median(x)))
}

plot_hist <- function(d, v) {
  df <- desc_frame(d, v)
  if (!is.null(plot_refusal("hist", df$value))) return(NULL)
  x <- df$value
  bins <- max(5, min(30, ceiling(log2(length(x)) + 1)))          # Sturges' rule
  ## Values recorded in steps (counts, scores, germination in steps of 5, pH
  ## to 0.1) get bars a whole number of the usual spacing wide, so each bar
  ## holds the same number of the usual recorded values and none is left
  ## empty between values a step apart; the edges sit half the finest step
  ## off the grid, so no value lies on an edge.
  st <- qq_step(x)
  bars <- if (is.finite(st)) {
    ms <- main_step(x)
    bw <- ms * max(1, ceiling(diff(range(x)) / (bins * ms)))
    geom_histogram(binwidth = bw, boundary = min(x) - st / 2, fill = "#BBD3F2", colour = "white")
  } else geom_histogram(bins = bins, fill = "#BBD3F2", colour = "white")
  ggplot(df, aes(x = .data$value)) + bars +
    geom_vline(data = centre_lines(x),
               aes(xintercept = .data$at, linetype = .data$what), colour = "#173F7D", linewidth = 0.8) +
    scale_linetype_manual(values = c(Mean = "dashed", Median = "dotted"), name = NULL) +
    labs(title = paste("Histogram of", v), x = v, y = "Number of observations") +
    theme_doe()
}

plot_density <- function(d, v) {
  df <- desc_frame(d, v)
  if (!is.null(plot_refusal("density", df$value))) return(NULL)
  ggplot(df, aes(x = .data$value)) +
    geom_density(fill = "#BBD3F2", colour = "#3B7DD8", alpha = 0.7) +
    geom_rug(colour = "grey40", alpha = 0.6) +
    geom_vline(data = centre_lines(df$value),
               aes(xintercept = .data$at, linetype = .data$what), colour = "#173F7D", linewidth = 0.8) +
    scale_linetype_manual(values = c(Mean = "dashed", Median = "dotted"), name = NULL) +
    labs(title = paste("Density of", v), x = v, y = "Density") +
    theme_doe()
}

plot_box <- function(d, v, group = NULL) {
  df <- desc_frame(d, v, group)
  if (!is.null(plot_refusal("box", df$value))) return(NULL)
  grouped <- "group" %in% names(df)
  if (!grouped) df$group <- factor(v)
  ggplot(df, aes(x = .data$group, y = .data$value)) +
    geom_boxplot(fill = "#BBD3F2", colour = "#173F7D", outlier.colour = "#C0392B", width = 0.55) +
    stat_summary(fun = mean, geom = "point", shape = 23, size = 3, fill = "white", colour = "#173F7D") +
    labs(title = paste("Box plot of", v, if (grouped) paste("by", group) else ""),
         x = if (grouped) group else NULL, y = v,
         caption = "Diamond: mean. Line in the box: median. Red points: values more than 1.5 box lengths beyond the box.") +
    theme_doe() + (if (!grouped) theme(axis.text.x = element_blank(), axis.ticks.x = element_blank()) else NULL)
}

plot_qq <- function(d, v) {
  df <- desc_frame(d, v)
  if (!is.null(plot_refusal("qq", df$value))) return(NULL)
  ggplot(df, aes(sample = .data$value)) +
    stat_qq(colour = "#3B7DD8") + stat_qq_line(colour = "#C0392B") +
    labs(title = paste("Normal Q-Q plot of", v),
         x = "Where the values would be if they were normal (theoretical quantiles)",
         y = paste(v, "(sample quantiles)")) +
    theme_doe()
}

## How far the two ends of a normal Q-Q plot lie from its line, as drawn:
## the points are the sorted values against qnorm(ppoints(n)) and the line
## passes through the quartiles (stat_qq and stat_qq_line). Each end is the
## mean distance of its outer tenth of the points (at least one) from the
## line, positive above it; `slope` and `sd` are the two scales they are
## judged on.
qq_ends <- function(x) {
  x <- sort(x[is.finite(x)]); n <- length(x)
  t <- stats::qnorm(stats::ppoints(n))
  q <- stats::quantile(x, c(0.25, 0.75), type = 7, names = FALSE)
  b <- (q[2] - q[1]) / diff(stats::qnorm(c(0.25, 0.75)))
  r <- x - (q[1] + b * (t - stats::qnorm(0.25)))
  k <- max(1, floor(0.1 * n))
  c(low = mean(r[seq_len(k)]), high = mean(r[(n - k + 1):n]), slope = b, sd = stats::sd(x))
}

## the bend beyond which a sample of n normal values would rarely go
qq_limit <- function(n, which)
  stats::approx(log(QQ_LIMIT$n), QQ_LIMIT[[which]], log(n), rule = 2)$y

## Values recorded in steps that are large beside their spread (whole days,
## counts) sit in flat runs, and the quartiles the line passes through jump
## from step to step, so the ends of the plot bend for that reason alone.
## By simulation, normal values rounded to steps up to this fraction of
## their SD are still read as bending at most about 2% of the time.
qq_step_limit <- function(n) min(0.33, 0.125 * sqrt(200 / n))
## The recording step: the largest step that every gap between distinct
## values is a whole number of, looked for among the smallest gap divided by
## 1 to 100 (pH to 0.1 with gaps of 0.2 and 0.3 has a step of 0.1), cleared
## of the residue of subtracting decimals (0.0999999999999996 is 0.1). NA
## when the values sit on no such grid, as values kept to full precision do.
qq_step <- function(x) {
  u <- sort(unique(x[is.finite(x)]))
  if (length(u) < 2) return(NA_real_)
  gap <- diff(u)
  for (k in 1:100) {
    r <- gap / (min(gap) / k)
    if (all(abs(r - round(r)) < 1e-6)) return(signif(min(gap) / k, 10))
  }
  NA_real_
}
## The spacing most of the values sit at: the commonest gap between
## neighbouring distinct values. One entry off the grid (5.5 among whole
## numbers, 87.5 among percentages in steps of 5) makes the common step finer
## but leaves this alone.
main_step <- function(x) {
  st <- qq_step(x)
  if (!is.finite(st)) return(NA_real_)
  k <- round(diff(sort(unique(x[is.finite(x)]))) / st)
  signif(st * as.numeric(names(which.max(table(k)))), 10)
}
## "in steps of 5", or "mostly in steps of 5" when a few values sit between
step_words <- function(x)
  paste0(if (isTRUE(all.equal(main_step(x), qq_step(x)))) "" else "mostly ", "in steps of ", num_text(main_step(x)))

## Values recorded in steps: they sit on a grid and repeat. A few values far
## apart are not "recorded in steps" however wide their gaps.
on_grid <- function(x) {
  x <- x[is.finite(x)]
  is.finite(qq_step(x)) && anyDuplicated(x) > 0
}
qq_coarse <- function(x) {
  x <- x[is.finite(x)]
  on_grid(x) && main_step(x) / stats::sd(x) > qq_step_limit(length(x))
}



## Each end as reaching out beyond the line ("out"), stopping short of it
## ("in") or neither ("ok"), against what normal samples of the same size
## show; for example "in out" is the curve of a longer tail of high values.
## The quartiles must differ (the caller deals with heaped values).
qq_pattern <- function(x) {
  n <- sum(is.finite(x))
  e <- qq_ends(x); lo_out <- qq_limit(n, "out"); lo_in <- qq_limit(n, "inward")
  low <- if (-e[["low"]] / e[["slope"]] > lo_out) "out" else if (e[["low"]] / e[["sd"]] > lo_in) "in" else "ok"
  high <- if (e[["high"]] / e[["slope"]] > lo_out) "out" else if (-e[["high"]] / e[["sd"]] > lo_in) "in" else "ok"
  paste(low, high)
}

## When the Q-Q plot shows a tail on one side that the skewness in the table
## does not, the note says so, rather than leave the histogram's "roughly
## even" and the Q-Q plot's "longer tail" side by side unexplained.
qq_vs_skew <- function(pattern, sh) {
  kind <- sh$kind
  ## a clear skewness while neither end passes its limit: the values do lean
  ## to one side, though no end of this plot shows it beyond chance
  if (pattern == "ok ok" && kind %in% c("right", "left") && isTRUE(sh$clear))
    return(paste(" The skewness in the table is larger than chance would usually give, though, even if neither",
                 "end of this plot bends beyond what chance allows for this many values."))
  tail <- if (pattern %in% c("ok out", "in out")) "right" else if (pattern %in% c("out ok", "out in")) "left" else ""
  if (!nzchar(tail) || !kind %in% c("right", "left", "symmetric")) return("")
  if (kind == "symmetric")
    " The skewness in the table is small, so this tail shows only at the very end of the plot, not as a lopsided spread of the values."
  else if (kind != tail)
    " The skewness in the table points the other way: the two measures disagree, so read the histogram as well."
  else ""
}

## The reading of a Q-Q plot from the bend at each end. When neither end
## bends beyond what normal values can show by chance, the text claims no
## more than "no clear sign" of a departure, since a small sample can hide one.
qq_reading <- function(x) {
  switch(qq_pattern(x),
    "ok ok" = "Neither end of the plot bends away from the line more than values drawn from a normal distribution can by chance, so the plot gives no clear sign that the values are not normal.",
    "ok out" = "The points rise above the line at the right-hand end: the highest values reach further than a normal distribution would put them, a longer tail of high values.",
    "in out" = "The points curve upwards along the plot, above the line at both ends: the low values stop short and the high values reach further than a normal distribution would put them, a longer tail of high values (right skew).",
    "in ok" = "The points lie above the line at the left-hand end: the lowest values stop short of where a normal distribution would put them.",
    "out ok" = "The points fall below the line at the left-hand end: the lowest values reach further than a normal distribution would put them, a longer tail of low values.",
    "out in" = "The points curve downwards along the plot, below the line at both ends: the high values stop short and the low values reach further than a normal distribution would put them, a longer tail of low values (left skew).",
    "ok in" = "The points lie below the line at the right-hand end: the highest values stop short of where a normal distribution would put them.",
    "out out" = "Both ends bend away from the line, down at the left and up at the right: there are more very low and very high values than a normal distribution would have (heavy tails).",
    "in in" = "The points flatten out at both ends, above the line at the left and below it at the right (an S-shape): the values stop short of where a normal distribution would reach at both ends, as happens when they form two clusters or are bounded at both ends.")
}

## which end of the plot the unusual values are at
end_words <- function(x, u, low, high, both) {
  m <- stats::median(x)
  if (all(x[u] > m)) high else if (all(x[u] < m)) low else both
}

## With a grouping chosen, the only box plot on screen is the one by group,
## so values flagged over all rows together are described for what they
## are, and each is put in its group's light: ordinary within a group of
## four or more (perhaps a treatment that differs), in a group too small for
## anything to stand out (check it anyway), or without a group label.
pooled_flags <- function(df, u, group) {
  rows <- function(i) rows_text(df$row[i])
  g <- df$group
  size <- table(g)
  lab <- u[!is.na(g[u])]
  unl <- u[is.na(g[u])]
  small <- lab[as.numeric(size[as.character(g[lab])]) <= 3]
  ok_in_group <- setdiff(setdiff(lab, small), unusual_within(df$value, g))
  out <- character(0)
  if (length(ok_in_group))
    out <- c(out, sprintf(paste0("Within %s own group of %s, %s not unusual (see the box plot by group), ",
      "so %s may reflect a difference between groups rather than a recording error."),
      pl(length(ok_in_group), "its", "their"), group,
      paste(rows(ok_in_group), pl(length(ok_in_group), "is", "are")), pl(length(ok_in_group), "it", "they")))
  if (length(small)) {
    ng <- length(unique(as.character(g[small])))
    out <- c(out, sprintf("%s %s in %s of three or fewer values, too few for a value to stand out within %s, so check %s all the same.",
      cap1(rows(small)), pl(length(small), "is", "are"), pl(ng, "a group", "groups"),
      pl(ng, pl(length(small), "its group", "their group"), "their groups"), pl(length(small), "it", "them")))
  }
  if (length(unl))
    out <- c(out, sprintf("%s %s no label in '%s', so the box plot by group does not show %s.",
      cap1(rows(unl)), pl(length(unl), "has", "have"), group, pl(length(unl), "it", "them")))
  out
}

## What each plot shows, and what it shows for these data. The readings use
## only the numbers the plot is drawn from, so they say nothing the plot
## does not; the box plot by group is read group by group.
plot_text <- function(kind, d, v, group = NULL) {
  grouped <- !is.null(group) && nzchar(group)
  refuse <- function(no) list(what = "", reading = paste(c(no, held_text(d[[v]])), collapse = " "))
  if (kind == "box" && grouped) {
    df <- desc_frame(d, v, group)
    no <- plot_refusal("box", df$value)
    if (!is.null(no)) return(refuse(no))
    all <- desc_frame(d, v, group, drop = FALSE)
    ## the same decimals as the grouped table
    dg <- var_digits(response_values(d[[v]]), group_labels(d, group))
    return(list(what = box_what(), reading = box_group_text(df, v, group, all$row[is.na(all$group)], dg)))
  }
  df <- desc_frame(d, v, if (grouped) group, drop = FALSE)
  x <- df$value
  no <- plot_refusal(kind, x)
  if (!is.null(no)) return(refuse(no))
  s <- desc_one(x); sh <- shape_of(s); u <- unusual(x)
  if (sh$kind == "constant")
    return(list(what = switch(kind, hist = hist_what(), box = box_what(), ""),
                reading = sprintf(switch(kind, hist = "Every value is %s, so all the observations fall in one bar.",
                                               box = "Every value is %s, so the box is a single line."),
                                  num_text(s$Mean))))
  rows <- function(i) rows_text(df$row[i])
  own <- if (grouped && length(u)) paste0(" ", pooled_flags(df, u, group), collapse = "") else ""
  flagged <- function(where) if (!length(u)) "" else if (grouped)
    sprintf(" Taken over all rows together, %s would be marked as possibly unusual (more than 1.5 box lengths beyond the box of all the values); %s at the %s.",
            rows(u), pl(length(u), "it is", "they are"), where)
  else sprintf(" The box plot marks %s as possibly unusual; %s at the %s.", rows(u), pl(length(u), "it is", "they are"), where)
  heap <- function(what) if (sh$heaped) sprintf("At least half the values are exactly %s, so %s. ", num_text(s$Median), what) else ""
  g1 <- dfmt(s$Skewness, 2)
  ## which way the drawn values reach further from the median, as the table
  ## prints them, and whether that is the way the skewness points
  r <- reach_of(s, var_digits(response_values(d[[v]])))
  side <- if (sh$kind == "right") "up" else if (sh$kind == "left") "down" else ""
  lean <- function(thing) {
    verb <- if (thing == "bars") "reach" else "reaches"
    hi <- if (side == "up") "above" else "below"; lo <- if (side == "up") "below" else "above"
    if (r == side) sprintf("The %s %s further %s the median than %s it (the skewness is %s).", thing, verb, hi, lo, g1)
    else if (r == "even") sprintf("The skewness is %s, which counts as %s skew, but the %s %s as far %s the median as %s it.",
                                  g1, sh$kind, thing, verb, lo, hi)
    else sprintf("The skewness is %s, which counts as %s skew, but the %s %s further %s the median than %s it.",
                 g1, sh$kind, thing, verb, lo, hi)
  }
  switch(kind,
    hist = list(what = hist_what(), reading = paste0(
      heap("one bar holds at least half the observations"),
      switch(sh$kind,
        right = , left = lean("bars"),
        symmetric = sprintf("The skewness is %s, close to zero, so by this measure the bars are spread roughly evenly about the mean.", g1),
        unclear = "There are too few values to judge the shape."),
      flagged(paste(end_words(x, u, "left-hand end", "right-hand end", "two ends"), "of the histogram")),
      own,
      if (abs(s$Mean - s$Median) <= 0.1 * s$SD) " The mean and median lines nearly coincide."
      else if (s$Mean > s$Median) paste0(" The mean line lies to the right of the median line",
        if (sh$kind == "right") ", as it usually does with right skew." else ".")
      else paste0(" The mean line lies to the left of the median line",
        if (sh$kind == "left") ", as it usually does with left skew." else "."),
      paste(" If the bars form two or more separate humps rather than one, the values fall into groups that lie apart,",
            "often treatments or seasons that differ, and the skewness then reflects how large the groups are rather than a tail"),
      if (grouped) "; the box plot by group shows each group separately."
      else if (length(group_choices(d))) "; choose a column under 'Summarise separately for each level of' to see a box plot for each group."
      else ".")),
    density = list(
      what = "A density curve is a smoothed histogram: the higher the curve, the more observations lie near that value. The ticks along the bottom are the individual observations.",
      reading = paste0(
        heap("the curve has a sharp peak there"),
        switch(sh$kind,
          right = , left = lean("curve"),
          symmetric = sprintf("The skewness is %s, close to zero, so by this measure the curve is spread roughly evenly about the mean.", g1),
          unclear = "There are too few values to judge the shape."),
        " Two or more separate peaks would mean the values gather in more than one place, which often happens when they come from groups that differ.",
        ## The curve is a sum of bell curves as wide as the smoothing
        ## (ggplot2's bandwidth, bw.nrd0), one on each value; two equal bells
        ## stay one hump unless they are more than two widths apart, so only
        ## steps wider than that can give the curve a bump at each value.
        if (on_grid(x) && main_step(x) > 2 * stats::bw.nrd0(x))
          sprintf(paste(" The values are recorded %s, wide beside the smoothing, so the curve may rise and fall",
                        "at each recorded value; bumps like these come from the steps, not from the shape."), step_words(x)),
        " The smoothing can round off sharp features, so read it together with the histogram.")),
    box = list(what = box_what(), reading = paste0(
      if (length(u)) sprintf("%d %s beyond the whiskers (%s); check %s for recording errors.", length(u),
        pl(length(u), "value lies", "values lie"), rows(u), pl(length(u), "it", "them"))
      else "No value lies beyond the whiskers.",
      " ", box_shape(s),
      if (s$N < 5) " With so few values the box is only a rough guide." else "")),
    qq = list(
      what = "Each point is one observation, placed against where it would fall if the values followed a normal distribution. Points close to the straight line mean the values look normal.",
      reading = paste0(
        if (s$N < 5) "There are too few points to judge."
        else if (sh$heaped) sprintf(paste0("At least half the values are exactly %s, so many points sit ",
          "in one flat run; values like these do not follow a normal distribution."), num_text(s$Median))
        else if (qq_coarse(x)) sprintf(paste0("The values are recorded %s, which is large beside their ",
          "spread, so the points sit in flat runs and the line through the quartiles jumps with the steps: ",
          "the ends of this plot cannot be read reliably. The histogram shows the shape better."), step_words(x))
        else paste0(qq_reading(x), qq_vs_skew(qq_pattern(x), sh)),
        if (!length(u)) ""
        else sprintf(" %s %s (%s) %s at the %s.",
          if (grouped) "Taken over all rows together, the" else "The",
          if (grouped) pl(length(u), "value that would be marked as possibly unusual", "values that would be marked as possibly unusual")
          else pl(length(u), "value the box plot marks as possibly unusual", "values the box plot marks as possibly unusual"),
          rows(u), pl(length(u), "is the point", "are the points"),
          end_words(x, u, "bottom end", "top end", "two ends")),
        own,
        if (s$N >= 5 && s$N < 20) sprintf(" With only %d values, a Q-Q plot can show only a large departure from normal.", s$N) else "",
        " For an analysis of variance it is the residuals that should look normal, not the raw values, which mix all the treatments; the Assumptions tab checks the residuals.")))
}

hist_what <- function()
  "A histogram counts how many observations fall in each range of values. The dashed line marks the mean and the dotted line the median."
box_what <- function() paste0(
  "The box covers the middle half of the values (from Q1 to Q3), the line inside it is the median and the diamond the mean. ",
  "The whiskers reach the furthest values within 1.5 box lengths of the box; points beyond them are drawn on their own as possibly unusual values.")

## where the median sits in the box, read straight from the quartiles drawn
box_shape <- function(s) {
  iqr <- s$Q3 - s$Q1
  if (iqr == 0) return(sprintf("The box is a single line: at least half the values are exactly %s.", num_text(s$Median)))
  if (s$Median == s$Q3) return(sprintf("The median is on the top edge of the box: it and Q3 are both %s, as happens when many values are equal.", num_text(s$Median)))
  if (s$Median == s$Q1) return(sprintf("The median is on the bottom edge of the box: it and Q1 are both %s, as happens when many values are equal.", num_text(s$Median)))
  b <- (s$Q3 + s$Q1 - 2 * s$Median) / iqr
  if (b > 0.1) "The median sits towards the bottom of the box, so the middle half is more spread out above the median than below it."
  else if (b < -0.1) "The median sits towards the top of the box, so the middle half is more spread out below the median than above it."
  else "The median sits near the middle of the box, so the middle half is spread about evenly either side of it."
}

## The reading of a box plot by group: which groups have the highest and the
## lowest median and the widest spread, compared as the figures are printed
## (to `digits`, the grouped table's decimals) so that a tie is named as a
## tie, and the values each group's own whiskers leave out. Facts about these
## data only.
box_group_text <- function(df, v, group, unlabelled = integer(0), digits = var_digits(df$value, df$group)) {
  st <- lapply(split(df$value, df$group), function(z) if (length(z)) desc_one(z))
  st <- st[!vapply(st, is.null, logical(1))]
  out <- character(0)
  if (length(unlabelled))
    out <- c(out, sprintf("%s %s no label in '%s' and %s not drawn.", cap1(rows_text(unlabelled)),
                          pl(length(unlabelled), "has", "have"), group, pl(length(unlabelled), "is", "are")))
  if (length(st) < 2)
    return(paste(c(out, sprintf("Only one group of %s has values, so there is nothing to compare.", group)), collapse = " "))
  nm <- names(st)
  ## 'every group' only when every level has values
  every <- if (length(st) == nlevels(df$group)) "every group" else "every group with values"
  med <- dfmt(vapply(st, function(s) s$Median, numeric(1)), digits)
  iqr <- dfmt(vapply(st, function(s) s$Q3 - s$Q1, numeric(1)), digits)
  out <- c(out, if (length(unique(med)) == 1)
    sprintf("The median is the same in %s, %s.", every, med[1])
  else sprintf("The median is highest in %s (%s) and lowest in %s (%s).",
               group_names(group, nm[at_extreme(med, max)]), med[at_extreme(med, max)[1]],
               group_names(group, nm[at_extreme(med, min)]), med[at_extreme(med, min)[1]]))
  raw_iqr <- vapply(st, function(s) s$Q3 - s$Q1, numeric(1))
  out <- c(out, if (all(raw_iqr == 0)) sprintf("Every box is a single line: in %s at least half the values are equal.", every)
  else if (all(as.numeric(iqr) == 0)) sprintf("In %s the middle half is narrower than the last decimal shown, so each box looks like a single line.", every)
  else if (length(unique(iqr)) == 1) sprintf("The middle half is equally spread in %s.", every)
  else sprintf("The spread of the middle half is widest in %s.", group_names(group, nm[at_extreme(iqr, max)])))
  u <- unusual_within(df$value, df$group)
  if (length(u))
    out <- c(out, sprintf("%d %s beyond the whiskers of %s own group (%s).", length(u),
      pl(length(u), "value lies", "values lie"), pl(length(u), "its", "their"), rows_text(df$row[u])))
  n <- vapply(st, function(s) as.numeric(s$N), numeric(1))
  if (any(n <= 3))
    out <- c(out, if (all(n <= 3)) "Every group has three or fewer values, too few for any value to stand out within its group."
                  else sprintf("%s %s three or fewer values, too few for any value to stand out within %s.",
                               cap1(group_names(group, nm[n <= 3])), pl(sum(n <= 3), "has", "have"), pl(sum(n <= 3), "it", "them")))
  if (any(n < 5))
    out <- c(out, "Groups with fewer than five values give only a rough box.")
  paste(c(out, "These are descriptions of the observations; whether the groups really differ is for the analysis of variance to judge."),
        collapse = " ")
}

## the summary table as HTML, numbers right-aligned, with each variable's
## figures to a sensible number of decimals (those of its groups, when the
## table is split by `group`)
describe_html <- function(tab, d, group = NULL) {
  g <- if (!is.null(group) && nzchar(group)) group_labels(d, group)
  digits <- vapply(tab$Variable, function(v) var_digits(response_values(d[[v]]), g), integer(1))
  num <- c("Mean", "SD", "Min", "Q1", "Median", "Q3", "Max")
  body <- lapply(seq_len(nrow(tab)), function(i) c(
    esc(tab$Variable[i]),
    if ("Group" %in% names(tab)) esc(tab$Group[i]),
    as.character(tab$N[i]), as.character(tab$Missing[i]),
    vapply(num, function(k) dfmt(tab[[k]][i], digits[i]), ""),
    fmt(tab$CV[i], 1), dfmt(tab$Skewness[i], 2)))
  head_ <- c("Variable", if ("Group" %in% names(tab)) "Group", "N", "Missing", num, "CV (%)", "Skewness")
  raw_table(head_, body, caption = "Descriptive statistics")
}

## Columns offered for grouping: two or more labels, each used about twice
## on average at least (an identifier or a measurement has a new value in
## nearly every row; a grouping repeats its labels). So a column of numbers
## such as 0, 40, 80, 120 kg N is offered, a measured yield with the odd tie
## is not.
group_choices <- function(d) {
  names(d)[vapply(d, function(z) {
    g <- trimws(as.character(z)); g <- g[!is.na(g) & g != ""]
    k <- length(unique(g))
    k >= 2 && k <= length(g) / 2
  }, logical(1))]
}

## Column names that usually label rows rather than measure anything (Rep,
## Block, Plot No, S. No.), however they are spelt or punctuated, left out of
## the default selection of variables.
ID_KEYS <- c("rep", "reps", "replication", "replicate", "replicationno", "repno", "r",
             "block", "blocks", "blockno", "blk", "b", "row", "rowno", "col", "column",
             "colno", "columnno", "plot", "plotno", "plotnumber", "sno", "slno", "srno",
             "serialno", "id", "no", "number")
is_id_name <- function(nm) gsub("[^a-z]", "", tolower(nm)) %in% ID_KEYS

## ---------------------------------------------------------- correlation.R ----
###############################################################################
##  CORRELATION
###############################################################################
## Pearson's, Spearman's or Kendall's coefficient for every pair of the chosen
## numeric variables, each with N, its p-value, a significance mark at the
## user's level and a short reading; a matrix, a heat map, and a scatter plot
## of one pair. As with the descriptives, every sentence is one the numbers on
## screen bear out: strength and direction are judged on the coefficient as
## printed, a result short of significance is "insufficient evidence", never
## "no correlation", nothing is said about cause, and a p-value that is only
## an approximation is marked as one.

COR_NAMES  <- c(pearson = "Pearson's r", spearman = "Spearman's rho", kendall = "Kendall's tau")
COR_SYMBOL <- c(pearson = "r", spearman = "rho", kendall = "tau")

## Where an association is called weak, moderate or strong. For Pearson's r
## these are Cohen's (1988) 0.1, 0.3 and 0.5. Spearman's rho and Kendall's tau
## run on other scales for the same association: for bivariate normal data
## rho = (6 / pi) asin(r / 2) and tau = (2 / pi) asin(r), which carry Cohen's
## points to 0.10, 0.29, 0.48 for rho and 0.06, 0.19, 0.33 for tau (rounded to
## the two decimals the coefficients are printed to).
COR_CUTS <- list(pearson = c(0.10, 0.30, 0.50), spearman = c(0.10, 0.29, 0.48),
                 kendall = c(0.06, 0.19, 0.33))

## the bands as a reader checks them against printed values, without overlap
cor_bands <- function(method) {
  k <- COR_CUTS[[method]]; f <- function(z) fmt(z, 2)
  sprintf("under %s negligible, %s to %s weak, %s to %s moderate, %s or more strong",
          f(k[1]), f(k[1]), f(k[2] - 0.01), f(k[2]), f(k[3] - 0.01), f(k[3]))
}

## a coefficient as the tables print it (two decimals), NA where there is none
printed2 <- function(x) {
  out <- rep(NA_real_, length(x)); ok <- !is.na(x)
  out[ok] <- as.numeric(dfmt(x[ok], 2))
  out
}

## the strength of a coefficient, judged on its value as printed
cor_strength <- function(coef, method) {
  a <- abs(printed2(coef)); k <- COR_CUTS[[method]]
  ifelse(is.na(a), NA_character_, ifelse(a < k[1], "negligible", ifelse(a < k[2], "weak",
         ifelse(a < k[3], "moderate", "strong"))))
}

## A p-value as printed, with enough figures that one below a threshold the
## marks use (alpha, alpha / 5) never prints at or above it: 0.049973 prints
## as 0.04997, not 0.05, beside its star.
p_show <- function(p, alpha) {
  if (is.na(p)) return("-")
  s <- p_text(p)
  if (p < 1e-4) return(s)
  for (cut in c(alpha / 5, alpha)) {
    d <- 3
    while (p < cut && as.numeric(s) >= cut && d < 12) {
      d <- d + 1
      s <- trimws(formatC(signif(p, d), format = "fg", digits = d))
    }
  }
  s
}

## ------------------------------------------------- rank p-values ----
## Spearman's and Kendall's p-values. If the two variables are unrelated,
## every ordering of one variable's values against the other's is equally
## likely, so the p-value is the share of orderings that give a coefficient at
## least as far from 0 as the one observed. That holds with tied values too,
## where the large-sample approximations cor.test() falls back on can be far
## off: three tied rows rising together came out "significant at 1%" (the
## exact p is 0.33), and ten plots of mostly-zero counts with one shared
## non-zero plot came out "**" (the exact p is 0.10).
##
## So the p-value is exact whenever the distinct orderings of one of the two
## variables can be listed (ties make them few: twelve plots with ten zeros
## have 132), estimated from random orderings when the values have ties but
## too many orderings to list, and taken from cor.test() otherwise: exact
## without ties where it is (Kendall below 50 rows, Spearman at 9), a
## large-sample approximation beyond, which is accurate at those sizes.

## at most this many orderings are listed, and at most this many cells held
COR_EXACT_MAX <- 50000
COR_CELLS_MAX <- 4e6
## random orderings for an estimate; a fixed seed keeps it the same each time.
## An estimate within three standard errors of a significance threshold is
## worked out again from ten times as many, so that a mark near the
## threshold rests on a p-value good to about +/- 0.0005 rather than 0.0015.
COR_PERM_B <- 20000
COR_PERM_B_CLOSE <- 200000
COR_PERM_SEED <- 20261009

## the number of distinct orderings of a variable's values
n_orders <- function(v) {
  cnt <- tabulate(match(v, unique(v)))
  exp(lfactorial(length(v)) - sum(lfactorial(cnt)))
}

## Every distinct ordering of a variable's values, one per row, as indices
## into its sorted distinct values (so the indices order the rows exactly as
## the values do): positions are chosen for the first value, then for the
## next among those left, and so on. Every partial ordering has the same
## number of free positions at each step, so each step is one matrix
## operation over all of them.
distinct_orders <- function(v) {
  u <- sort(unique(v)); cnt <- tabulate(match(v, u), length(u)); n <- length(v)
  A <- matrix(0L, 1, n)
  for (k in seq_len(length(u) - 1)) {
    R <- nrow(A)
    free <- matrix(((which(t(A == 0L)) - 1L) %% n) + 1L, nrow = R, byrow = TRUE)
    cmb <- utils::combn(ncol(free), cnt[k])
    J <- ncol(cmb)
    r_of <- rep(seq_len(R), each = J); j_of <- rep(seq_len(J), times = R)
    cols <- free[cbind(rep(r_of, each = cnt[k]), as.vector(cmb[, j_of]))]
    A <- A[r_of, , drop = FALSE]
    A[cbind(rep(seq_len(R * J), each = cnt[k]), cols)] <- k
  }
  A[A == 0L] <- length(u)
  A
}

## Without ties a variable's terms depend only on the number of rows, so they
## are built once for each size and coefficient and shared by every variable.
untied_cache <- new.env(parent = emptyenv())

## the upper-triangle pairs (i < j), in the order sx[upper.tri(sx)] lists them
upper_pairs <- function(n) which(upper.tri(diag(n)), arr.ind = TRUE)

## For one variable `v` and one coefficient, the statistic's ingredient for
## every ordering (rows of `orders`, indices as distinct_orders() gives them):
## centred ranks for rho, the signs of every pairwise difference for tau.
order_terms <- function(v, orders, method) {
  u <- sort(unique(v))
  if (method == "spearman") {
    rk <- rank(v)[match(u, v)]
    matrix(rk[orders], nrow(orders)) - mean(rank(v))
  } else {
    ij <- upper_pairs(ncol(orders))
    sign(matrix(orders[, ij[, 1]], nrow(orders)) - matrix(orders[, ij[, 2]], nrow(orders)))
  }
}

## the fixed variable's side of the statistic, and the observed value
fixed_terms <- function(x, method) {
  if (method == "spearman") rank(x) - mean(rank(x))
  else { s <- sign(outer(x, x, "-")); s[upper.tri(s)] }
}

## Run `expr` with a fixed seed and put the user's random number stream back
## afterwards, so an estimate is the same every time and nothing else changes.
## The generator is fixed as well as the seed (R's defaults), so a user who
## has chosen another kind of generator gets the same answer; the saved
## stream carries the user's kind back with it. One thing R code cannot put
## back: under Box-Muller normals, the second of a pair drawn but not yet
## used is lost, so the user's next normal draw moves on by one.
with_fixed_seed <- function(seed, expr) {
  had <- exists(".Random.seed", envir = globalenv(), inherits = FALSE)
  old <- if (had) get(".Random.seed", envir = globalenv(), inherits = FALSE)
  kinds <- RNGkind()
  on.exit(if (had) assign(".Random.seed", old, envir = globalenv()) else {
    RNGkind(kinds[1], kinds[2], kinds[3])
    if (exists(".Random.seed", envir = globalenv(), inherits = FALSE)) rm(".Random.seed", envir = globalenv())
  })
  set.seed(seed, kind = "Mersenne-Twister", normal.kind = "Inversion", sample.kind = "Rejection")
  expr
}

## The p-value of rho or tau for one pair and how it was found: "exact" (every
## ordering listed, or cor.test() exact), "estimate" (random orderings) or
## "approximation" (large-sample). `cache` keeps each variable's terms within
## one table, since every pair a variable is in reuses them.
rank_p <- function(x, y, method, cache = NULL, keys = c("x", "y"), alpha = NULL) {
  n <- length(x)
  ties <- anyDuplicated(x) > 0 || anyDuplicated(y) > 0
  width <- if (method == "spearman") n else choose(n, 2)
  m <- c(n_orders(x), n_orders(y))
  ## permute the variable with fewer orderings; list them if few enough
  k <- which.min(m)
  if (m[k] <= COR_EXACT_MAX && m[k] * width <= COR_CELLS_MAX) {
    v <- if (k == 1) x else y; w <- if (k == 1) y else x
    untied <- !anyDuplicated(v)
    store <- if (untied) untied_cache else cache
    key <- if (untied) paste(n, method) else paste(keys[k], method, sep = "\u001f")
    terms <- if (!is.null(store) && !is.null(store[[key]])) store[[key]] else {
      t <- order_terms(if (untied) seq_len(n) else v, distinct_orders(if (untied) seq_len(n) else v), method)
      if (!is.null(store)) assign(key, t, envir = store)
      t
    }
    ## without ties the terms were built from ranks 1..n, so the variable
    ## being ordered enters through its ranks
    if (untied) v <- rank(v)
    a <- fixed_terms(w, method)
    obs <- sum(fixed_terms(v, method) * a)
    s <- drop(terms %*% a)
    return(list(p = mean(abs(s) >= abs(obs) - 1e-9 * max(1, abs(obs))), how = "exact"))
  }
  if (!ties) {
    exact <- (method == "spearman" && n <= 9) || (method == "kendall" && n < 50)
    p <- suppressWarnings(stats::cor.test(x, y, method = method, exact = if (exact) TRUE else NULL))$p.value
    return(list(p = p, how = if (exact) "exact" else "approximation"))
  }
  ## ties, but too many orderings to list: an estimate from random orderings
  ## (Spearman's rho at any size, Kendall's tau up to 20 rows; from 21 rows
  ## Kendall's large-sample approximation held its level in simulation, at
  ## most 5.7% at 5% and 1.2% at 1% for sparse counts and three-level
  ## scores, and the estimate would cost n^2 work per ordering), as
  ## (k + 1) / (B + 1), which keeps the test's level at or below alpha; on any
  ## one data set the estimate falls either side of the exact value, so one
  ## near a threshold is worked out again more closely
  if (method == "spearman" || n <= 20) {
    p <- perm_estimate(x, y, method, COR_PERM_B, cache, keys[1])
    se <- sqrt(p * (1 - p) / COR_PERM_B)
    if (!is.null(alpha) && any(abs(p - c(alpha, alpha / 5)) < 3 * se))
      p <- perm_estimate(x, y, method, COR_PERM_B_CLOSE, cache, keys[1])
    return(list(p = p, how = "estimate"))
  }
  p <- suppressWarnings(stats::cor.test(x, y, method = method, exact = FALSE))$p.value
  list(p = p, how = "approximation")
}

## B random orderings of 1..n under the fixed seed, one per row, drawn by
## sorting uniform numbers within each row: one sort for the whole block.
## Blocks within the usual count are the same for every pair of the same
## size, so they are drawn once and kept: for one size at a time, and only
## while they fit in COR_ORDERS_MAX cells, which bounds the memory held.
## Blocks beyond the usual count (a closer count) are new each time.
COR_ORDERS_MAX <- 1e7
perm_cache <- new.env(parent = emptyenv())
random_orders <- function(n, B, first = 1) {
  keep <- first + B - 1 <= COR_PERM_B && n * COR_PERM_B <= COR_ORDERS_MAX
  key <- paste(B, first)
  if (keep && isTRUE(perm_cache$n == n) && !is.null(perm_cache[[key]])) return(perm_cache[[key]])
  o <- with_fixed_seed(COR_PERM_SEED + first, order(rep(seq_len(B), each = n), stats::runif(n * B)))
  P <- matrix(o - rep((seq_len(B) - 1L) * as.integer(n), each = n), nrow = B, byrow = TRUE)
  if (keep) {
    if (!isTRUE(perm_cache$n == n)) {
      rm(list = ls(perm_cache), envir = perm_cache)
      perm_cache$n <- n
    }
    assign(key, P, envir = perm_cache)
  }
  P
}

## The p-value from B random orderings of x against y, as (k + 1) / (B + 1):
## x's terms for every ordering (as order_terms() builds them for the exact
## count) times y's fixed terms. The orderings come in blocks of at most
## COR_CELLS_MAX cells. In a table x stays the same over consecutive pairs,
## so its terms for the usual first block are kept for the next pair (one
## variable at a time, which bounds the memory held).
perm_estimate <- function(x, y, method, B, cache = NULL, key = NULL) {
  n <- length(x)
  ix <- match(x, sort(unique(x)))
  a <- fixed_terms(y, method)
  obs <- sum(fixed_terms(x, method) * a)
  tol <- 1e-9 * max(1, abs(obs))
  width <- if (method == "spearman") n else choose(n, 2)
  block <- min(B, COR_PERM_B, max(1, floor(COR_CELLS_MAX / width)))
  tk <- paste(key, method, sep = "\u001f")
  hits <- 0; done <- 0
  while (done < B) {
    b <- min(block, B - done)
    keep <- !is.null(cache) && !is.null(key) && done == 0 && b == COR_PERM_B
    terms <- if (keep && identical(cache$perm_key, tk)) cache$perm_terms else {
      t <- order_terms(x, matrix(ix[random_orders(n, b, first = done + 1)], b), method)
      if (keep) { cache$perm_key <- tk; cache$perm_terms <- t }
      t
    }
    s <- drop(terms %*% a)
    hits <- hits + sum(abs(s) >= abs(obs) - tol)
    done <- done + b
  }
  (hits + 1) / (B + 1)
}

## One pair: the coefficient, its p-value, how the p-value was found and (for
## Pearson) the confidence interval at the level that matches alpha, from
## every row with both values.
cor_pair <- function(x, y, method, alpha, xname = "the first variable", yname = "the second variable",
                     cache = NULL) {
  ok <- is.finite(x) & is.finite(y)
  x <- x[ok]; y <- y[ok]; n <- length(x)
  out <- list(N = n, coef = NA_real_, p = NA_real_, low = NA_real_, high = NA_real_,
              how = NA_character_, why = NULL)
  if (n < 3) {
    out$why <- if (n == 0) "no row has both values" else sprintf("only %d %s both values", n, pl(n, "row has", "rows have"))
    return(out)
  }
  flat <- c(xname, yname)[c(stats::sd(x) == 0, stats::sd(y) == 0)]
  if (length(flat)) {
    out$why <- sprintf("%s %s not vary in the rows that have both values",
                       join_and(sprintf("'%s'", flat)), pl(length(flat), "does", "do"))
    return(out)
  }
  if (method == "pearson") {
    ct <- stats::cor.test(x, y, conf.level = 1 - alpha)
    out$coef <- unname(ct$estimate); out$p <- ct$p.value; out$how <- "exact"
    if (!is.null(ct$conf.int)) { out$low <- ct$conf.int[1]; out$high <- ct$conf.int[2] }
    return(out)
  }
  out$coef <- stats::cor(x, y, method = method)
  rows <- paste(which(ok), collapse = ",")
  rp <- rank_p(x, y, method, cache, keys = paste(c(xname, yname), rows, sep = "\u001f"), alpha = alpha)
  out$p <- rp$p; out$how <- rp$how
  out
}

## the reading of one pair, in a line; the direction comes from the sign of
## the coefficient, so a significant 0.00 still says which way it leans
cor_reading <- function(coef, p, strength, alpha, why = NULL) {
  if (length(why) && nzchar(why)) return(paste0("Not available: ", why, "."))
  dir <- if (coef > 0) "positive" else if (coef < 0) "negative" else ""
  lvl <- paste0(pct(alpha), "%")
  if (p < alpha) {
    if (strength == "negligible")
      sprintf(paste("Negligible %s association, though significant at the %s level: with many rows even a very",
                    "small coefficient can be significant."), dir, lvl)
    else sprintf("%s %s association, significant at the %s level.", cap1(strength), dir, lvl)
  } else sprintf("%s; insufficient evidence of an association at the %s level.",
                 if (printed2(coef) != 0) sprintf("%s %s coefficient", cap1(strength), dir) else "A coefficient of 0.00", lvl)
}

## Rows left out of a pair only because an entry is written in a form the
## data check flags (36,2; 45%): they would count once corrected.
held_flags <- function(raw)
  if (is.numeric(raw)) rep(FALSE, length(raw)) else read_entries(raw)$kind %in% setdiff(NUMBER_KINDS, "number")

#' Correlation between pairs of numeric variables
#'
#' For every pair of the variables named: the number of rows with both values
#' (N), the coefficient (Pearson's r, Spearman's rho or Kendall's tau-b), its
#' two-sided p-value, a significance mark at the chosen level (\code{*} at
#' \code{alpha}, \code{**} at \code{alpha / 5}, \code{NS} otherwise), for
#' Pearson's r a confidence interval at level \code{1 - alpha} (Fisher's
#' approximation), the strength of the association, and a one-line reading.
#' Text entries are read as the data check reads them: an entry that is not
#' plainly a number counts as missing; see \code{\link{check_data}}.
#'
#' Pearson's p-value is the usual t test. Spearman's and Kendall's are exact
#' whenever the distinct orderings of one variable's values can be listed (up
#' to 50,000, which covers eight rows and many more when values are tied);
#' with ties and more orderings than that, Spearman's at any size and
#' Kendall's up to 20 rows are estimated from 20,000 random orderings
#' (200,000 near a significance threshold; a fixed seed, and the user's
#' random number stream is left as it was), and Kendall's above 20 rows use
#' the large-sample approximation, which holds its level there; without ties
#' they come from \code{\link[stats]{cor.test}}, exact for Kendall's tau below
#' 50 rows and Spearman's rho at nine, and a large-sample approximation
#' beyond.
#' Strength uses Cohen's 0.1, 0.3 and 0.5 for r, carried to rho and tau
#' through their relation to r for bivariate normal data (0.10, 0.29, 0.48 for
#' rho; 0.06, 0.19, 0.33 for tau).
#'
#' @param d A data frame.
#' @param vars The names of two or more numeric columns.
#' @param method \code{"pearson"}, \code{"spearman"} or \code{"kendall"}.
#' @param alpha The significance level, between 0 and 0.5.
#'
#' @return A data frame with one row per pair: \code{Variable1},
#'   \code{Variable2}, \code{N}, \code{Coefficient}, \code{p}, \code{Mark},
#'   \code{CI_lower} and \code{CI_upper} (Pearson only; \code{NA} otherwise),
#'   \code{Strength}, \code{P_method} (\code{"exact"}, \code{"estimate"} from
#'   random orderings, or \code{"approximation"}), \code{Approximate}
#'   (\code{TRUE} unless exact), \code{Held} (rows left out only because an
#'   entry waits for a data-check correction) and \code{Reading}. A pair that cannot be
#'   computed has \code{NA} coefficient and p-value and says why in
#'   \code{Reading}.
#'
#' @examples
#' d <- demo_data("RCBD")
#' set.seed(1)
#' d$Height <- 60 + 0.8 * d$Yield + rnorm(nrow(d), 0, 2)
#' correlate_data(d, c("Yield", "Height"))
#' correlate_data(d, c("Yield", "Height"), method = "spearman")
#'
#' @export
correlate_data <- function(d, vars, method = c("pearson", "spearman", "kendall"), alpha = 0.05) {
  method <- match.arg(method)
  if (!is.numeric(alpha) || length(alpha) != 1L || is.na(alpha) || alpha <= 0 || alpha >= 0.5)
    stop("The significance level must be a single number between 0 and 0.5, such as 0.05.")
  vars <- unique(vars)
  if (length(vars) < 2) stop("Choose at least two variables to correlate.")
  gone <- setdiff(vars, names(d))
  if (length(gone))
    stop(sprintf("%s %s of the data.", join_and(sprintf("'%s'", gone)),
                 pl(length(gone), "is not a column", "are not columns")))
  vals <- lapply(stats::setNames(vars, vars), function(v) response_values(d[[v]]))
  held <- lapply(stats::setNames(vars, vars), function(v) held_flags(d[[v]]))
  pr <- utils::combn(length(vars), 2)
  cache <- new.env(parent = emptyenv())
  gained <- rep(FALSE, nrow(d))
  out <- do.call(rbind, lapply(seq_len(ncol(pr)), function(k) {
    a <- vars[pr[1, k]]; b <- vars[pr[2, k]]
    cp <- cor_pair(vals[[a]], vals[[b]], method, alpha, a, b, cache)
    ## rows that would have both values once flagged entries are corrected
    has_a <- is.finite(vals[[a]]) | held[[a]]; has_b <- is.finite(vals[[b]]) | held[[b]]
    h <- which((held[[a]] | held[[b]]) & has_a & has_b)
    gained[h] <<- TRUE
    eg <- if (length(h)) trimws(as.character(if (held[[a]][h[1]]) d[[a]][h[1]] else d[[b]][h[1]])) else ""
    why <- cp$why
    if (length(h) && cp$N < 3)
      why <- sprintf("%s as plain numbers, and %d %s an entry the data check has flagged (such as '%s'), which will count once corrected on the Data tab",
                     why, length(h), pl(length(h), "row has", "rows have"), eg)
    st <- cor_strength(cp$coef, method)
    reading <- cor_reading(cp$coef, cp$p, st, alpha, why)
    if (length(h) && cp$N >= 3)
      reading <- paste(reading, sprintf("%d %s an entry the data check has flagged (such as '%s') and %s left out until %s corrected on the Data tab.",
        length(h), pl(length(h), "row has", "rows have"), eg, pl(length(h), "is", "are"), pl(length(h), "it is", "they are")))
    ## Pearson's interval is Fisher's approximation and can disagree with the
    ## t test near the boundary; the reading says so where it does
    if (method == "pearson" && !is.na(cp$low) && (cp$p < alpha) != (cp$low > 0 || cp$high < 0))
      reading <- paste(reading, "Near the boundary the interval, an approximation, and the test disagree; the mark follows the test.")
    data.frame(Variable1 = a, Variable2 = b, N = cp$N, Coefficient = cp$coef, p = cp$p,
               Mark = star(cp$p, alpha), CI_lower = cp$low, CI_upper = cp$high,
               Strength = st, P_method = cp$how, Approximate = !is.na(cp$how) & cp$how != "exact",
               Held = length(h),
               Reading = reading, stringsAsFactors = FALSE)
  }))
  rownames(out) <- NULL
  attr(out, "method") <- method; attr(out, "alpha") <- alpha
  ## variables with fewer than two distinct values have no correlation even
  ## with themselves
  attr(out, "flat") <- vars[vapply(vals, function(v) length(unique(v[is.finite(v)])) < 2, logical(1))]
  ## rows that some pair would gain once a flagged entry is corrected, and one
  ## such entry to show
  attr(out, "held_rows") <- sum(gained)
  attr(out, "held_eg") <- if (any(gained)) {
    i <- which(gained)[1]; v <- vars[vapply(held, function(h) h[i], logical(1))][1]
    trimws(as.character(d[[v]][i]))
  } else ""
  out
}

## ------------------------------------------------------------ display ----

## a coefficient with its mark, as the matrix and the heat map print it
cor_label <- function(coef, mark) ifelse(is.na(coef), "-", paste0(dfmt(coef, 2), ifelse(mark == "NS", "", mark)))

## the key to the marks as the matrix and heat map print them
cor_key <- function(alpha)
  sprintf("** significant at p < %s; * significant at p < %s; no mark: not significant at the %s%% level; -: cannot be worked out (the pairs table says why).",
          p_lab(alpha / 5), p_lab(alpha), pct(alpha))

## the label on the diagonal: 1, or - for a variable that does not vary
cor_diag <- function(tab, v) if (v %in% attr(tab, "flat")) "-" else "1"

## The matrix: each pair once, below the diagonal, so nothing is printed twice.
cor_matrix_html <- function(tab, vars) {
  method <- attr(tab, "method")
  cell <- function(a, b) {
    i <- which((tab$Variable1 == a & tab$Variable2 == b) | (tab$Variable1 == b & tab$Variable2 == a))
    cor_label(tab$Coefficient[i], tab$Mark[i])
  }
  body <- lapply(seq_along(vars), function(i) c(esc(vars[i]), vapply(seq_along(vars), function(j)
    if (j < i) cell(vars[i], vars[j]) else if (j == i) cor_diag(tab, vars[i]) else "", "")))
  raw_table(c("", esc(vars)), body, caption = sprintf("Correlation matrix (%s)", COR_NAMES[[method]]))
}

## Every pair in a table with N, p, the mark, the interval and the reading;
## an approximate p-value carries a note.
cor_pairs_html <- function(tab) {
  method <- attr(tab, "method"); alpha <- attr(tab, "alpha")
  ci <- method == "pearson"
  body <- lapply(seq_len(nrow(tab)), function(i) c(
    esc(tab$Variable1[i]), esc(tab$Variable2[i]), as.character(tab$N[i]),
    dfmt(tab$Coefficient[i], 2),
    paste0(esc(p_show(tab$p[i], alpha)),
           if (identical(tab$P_method[i], "approximation")) "<sup>a</sup>"
           else if (identical(tab$P_method[i], "estimate")) "<sup>b</sup>" else ""),
    if (is.na(tab$p[i])) "" else tab$Mark[i],
    if (ci) (if (is.na(tab$CI_lower[i])) "-" else sprintf("%s to %s", dfmt(tab$CI_lower[i], 2), dfmt(tab$CI_upper[i], 2))),
    esc(tab$Reading[i])))
  head_ <- c("Variable 1", "Variable 2", "N", COR_SYMBOL[[method]], "p", "Mark",
             if (ci) sprintf("%s%% CI", pct(1 - alpha)), "Reading")
  notes <- c(
    if (any(tab$P_method == "approximation", na.rm = TRUE))
      "a: a large-sample approximation, used when the orderings of the values are too many to count; it is accurate at these sizes unless the values are very unevenly spread.",
    if (any(tab$P_method == "estimate", na.rm = TRUE))
      sprintf(paste("b: estimated from %s random orderings of the values, which have ties and too many orderings",
                    "to count (from %s when it falls close to a significance threshold); it can fall either side of",
                    "the exact value, by about 0.003 near p = 0.05, or 0.001 after the closer count."),
              format(COR_PERM_B, big.mark = ","), format(COR_PERM_B_CLOSE, big.mark = ",", scientific = FALSE)),
    if (method != "pearson" && any(tab$P_method == "exact", na.rm = TRUE))
      "Unmarked p-values are exact: every distinct ordering of the values is counted, ties included.",
    if (ci) "The interval is Fisher's approximation; the p-value and the mark come from the exact t test.",
    if (ci && any(!is.na(tab$p) & is.na(tab$CI_lower))) "An interval needs at least four rows.")
  foot <- if (length(notes)) sprintf("<tr><td colspan='%d' class='cdrow'>%s</td></tr>", length(head_), paste(notes, collapse = " "))
  raw_table(head_, body, foot = foot, caption = "Every pair")
}

## what each coefficient measures, in a sentence a student can follow
cor_about <- function(method) switch(method,
  pearson = paste("Pearson's r measures how closely two variables rise and fall together along a straight line,",
                  "from -1 (a perfect falling line) through 0 to +1 (a perfect rising line)."),
  spearman = paste("Spearman's rho is Pearson's r worked out on the ranks of the values: it measures how",
                   "consistently one variable rises (or falls) as the other rises, whether or not along a straight line."),
  kendall = paste("Kendall's tau (tau-b, which allows for tied values) compares every two rows: it is positive when",
                  "more pairs of rows are put in the same order by both variables than in opposite orders (pairs tied",
                  "on either variable count for neither), and negative when the reverse holds. For values scattered",
                  "evenly about a straight line it runs closer to 0 than r or rho."))

## pairs named for the text: "Yield and Height (0.82**)"
cor_pair_names <- function(tab, i)
  sprintf("%s and %s (%s)", tab$Variable1[i], tab$Variable2[i], cor_label(tab$Coefficient[i], tab$Mark[i]))

## The reading of the whole table: what the coefficient measures, which pairs
## are significant, and the cautions that apply to any correlation table.
cor_text <- function(tab) {
  method <- attr(tab, "method"); alpha <- attr(tab, "alpha")
  lvl <- paste0(pct(alpha), "%")
  ok <- !is.na(tab$p)
  sig <- which(ok & tab$p < alpha)
  out <- cor_about(method)
  if (any(!ok))
    out <- c(out, sprintf("%d %s could not be worked out; the table says why.", sum(!ok),
                          pl(sum(!ok), "pair", "pairs")))
  if (any(ok)) {
    sig <- sig[order(-abs(printed2(tab$Coefficient[sig])))]
    n_ok <- sum(ok); n_ns <- n_ok - length(sig)
    out <- c(out,
      if (n_ok == 1 && length(sig))
        sprintf("The pair shows evidence of an association at the %s level: %s.", lvl, cor_pair_names(tab, sig))
      else if (n_ok == 1)
        sprintf("For %s there is insufficient evidence of an association at the %s level.", cor_pair_names(tab, which(ok)), lvl)
      else if (!length(sig))
        sprintf("None of the %d pairs shows evidence of an association at the %s level.", n_ok, lvl)
      else if (length(sig) == n_ok)
        sprintf("All %d pairs show evidence of an association at the %s level: %s.", n_ok, lvl,
                join_and(head_more(cor_pair_names(tab, sig), 6)))
      else sprintf("%d of the %d pairs %s evidence of an association at the %s level: %s.", length(sig), n_ok,
                   pl(length(sig), "shows", "show"), lvl, join_and(head_more(cor_pair_names(tab, sig), 6))))
    if (n_ns > 0 && length(sig))
      out <- c(out, sprintf("For the other %s there is insufficient evidence of an association at the %s level.",
                            if (n_ns == 1) "pair" else paste(n_ns, "pairs"), lvl))
    if (n_ok >= 5 && length(sig)) {
      e <- round(n_ok * alpha, 10)
      out <- c(out, sprintf(paste("Even if no two variables were related, testing %d pairs at the %s level would make,",
                                  "on average, up to %s %s significant by chance (%d x %s), so treat a lone significant",
                                  "pair with care."), n_ok, lvl, num_text(e), if (e == 1) "pair" else "pairs", n_ok, p_lab(alpha)))
    }
  }
  ns <- range(tab$N)
  if (ns[1] != ns[2])
    out <- c(out, sprintf("Each pair uses every row that has both values, so N runs from %d to %d.", ns[1], ns[2]))
  hr <- attr(tab, "held_rows") %||% 0
  if (hr > 0)
    out <- c(out, sprintf(paste("%d %s an entry the data check has flagged (such as '%s') and %s left out of %s pairs",
                                "until corrected on the Data tab; each pair's reading gives the number it loses."),
                          hr, pl(hr, "row has", "rows have"), attr(tab, "held_eg"), pl(hr, "is", "are"),
                          pl(hr, "its", "their")))
  out <- c(out,
    "A correlation shows how two variables vary together; it does not show that one causes the other.",
    paste("In a designed experiment these coefficients use every plot, so they combine differences between",
          "treatments with variation within them: two variables can be correlated simply because both respond",
          "to the same treatments."))
  paste(out, collapse = " ")
}

## the full square of coefficients, each pair shown twice and each variable
## with itself on the diagonal, for the heat map
cor_square <- function(tab, vars) {
  g <- expand.grid(Row = vars, Col = vars, stringsAsFactors = FALSE)
  key <- function(a, b) paste(pmin(a, b), pmax(a, b), sep = "\u001f")
  i <- match(key(g$Row, g$Col), key(tab$Variable1, tab$Variable2))
  g$diag <- g$Row == g$Col
  flat <- g$diag & g$Row %in% attr(tab, "flat")
  g$coef <- ifelse(g$diag, ifelse(flat, NA, 1), tab$Coefficient[i])
  g$label <- ifelse(g$diag, ifelse(flat, "-", "1"), cor_label(tab$Coefficient[i], tab$Mark[i]))
  g$Row <- factor(g$Row, levels = rev(vars)); g$Col <- factor(g$Col, levels = vars)
  g
}

## Up to this many variables each square carries its coefficient; beyond it
## the squares are too small for the labels, which would overlap.
COR_HEAT_LABELS <- 15

plot_cor_heat <- function(tab, vars) {
  method <- attr(tab, "method")
  g <- cor_square(tab, vars)
  g$fill <- ifelse(g$diag, NA_real_, g$coef)
  ## dark tiles take white text, so every label can be read
  g$ink <- ifelse(!g$diag & !is.na(g$coef) & abs(g$coef) >= 0.6, "white", "black")
  n <- length(vars)
  ## the diagonal (each variable with itself) is drawn in white with an
  ## outline, so the grey of pairs that cannot be worked out means only that
  one <- g[g$diag & g$label == "1", , drop = FALSE]
  p <- ggplot(g, aes(x = .data$Col, y = .data$Row)) +
    geom_tile(aes(fill = .data$fill), colour = "white", linewidth = 0.8) +
    geom_tile(data = one, fill = "white", colour = "#B9C6D6", linewidth = 0.5) +
    scale_fill_gradient2(low = "#C0392B", mid = "#F7F7F7", high = "#1B4F9C", midpoint = 0,
                         limits = c(-1, 1), na.value = "#E3E3E3", name = COR_SYMBOL[[method]]) +
    labs(title = sprintf("Correlation heat map (%s)", COR_NAMES[[method]]), x = NULL, y = NULL,
         caption = "Blue: positive. Red: negative. Deeper colour: further from 0. White: each variable with itself. Grey: cannot be worked out.") +
    theme_doe() + theme(axis.text.x = element_text(angle = 30, hjust = 1, size = if (n > 12) 7 else 9),
                        axis.text.y = element_text(size = if (n > 12) 7 else 9), panel.grid = element_blank())
  if (n <= COR_HEAT_LABELS)
    p <- p + geom_text(aes(label = .data$label, colour = .data$ink), size = min(3.6, 40 / n)) + scale_colour_identity()
  p
}

## What the heat map shows, and the largest coefficients either way, named
## as printed (ties named together); the sign decides positive or negative.
cor_heat_text <- function(tab, nvars = NA) {
  alpha <- attr(tab, "alpha")
  what <- paste("Each square holds the coefficient for the variables on its row and column: blue for a positive",
                "coefficient, red for a negative one, and the deeper the colour the further it is from 0. The white",
                "diagonal is each variable with itself.",
                if (!is.na(nvars) && nvars > COR_HEAT_LABELS)
                  sprintf("With more than %d variables the squares are too small to label; read the values from the tables above.", COR_HEAT_LABELS)
                else cor_key(alpha))
  ok <- !is.na(tab$Coefficient)
  if (!any(ok)) return(list(what = what, reading = "No pair could be worked out."))
  pc <- printed2(tab$Coefficient)
  ## a coefficient that prints 0.00 and is not significant leans neither way,
  ## as its reading says
  lean <- ok & !(pc == 0 & tab$Mark == "NS")
  pos <- which(lean & tab$Coefficient > 0); neg <- which(lean & tab$Coefficient < 0)
  top <- function(i, fun) i[pc[i] == fun(pc[i])]
  out <- c(
    if (length(pos)) sprintf("The largest positive coefficient is for %s.", join_and(head_more(cor_pair_names(tab, top(pos, max)), 6)))
    else "No pair has a positive coefficient.",
    if (length(neg)) sprintf("The largest negative coefficient is for %s.", join_and(head_more(cor_pair_names(tab, top(neg, min)), 6)))
    else "No pair has a negative coefficient.")
  list(what = what, reading = paste(out, collapse = " "))
}

## one pair as a scatter plot, every row with both values a point
plot_cor_scatter <- function(d, x, y, method, alpha) {
  if (is.null(x) || is.null(y) || !nzchar(x) || !nzchar(y) || x == y) return(NULL)
  df <- data.frame(x = response_values(d[[x]]), y = response_values(d[[y]]))
  df <- df[is.finite(df$x) & is.finite(df$y), , drop = FALSE]
  if (nrow(df) < 2) return(NULL)
  tab <- correlate_data(d, c(x, y), method, alpha)
  ggplot(df, aes(x = .data$x, y = .data$y)) +
    geom_point(colour = "#3B7DD8", size = 2.4, alpha = 0.8) +
    labs(title = sprintf("%s against %s", y, x), x = x, y = y,
         subtitle = if (is.na(tab$Coefficient)) sprintf("N = %d; %s cannot be worked out", tab$N, COR_NAMES[[method]])
                    else sprintf("%s = %s, N = %d", COR_NAMES[[method]], cor_label(tab$Coefficient, tab$Mark), tab$N)) +
    theme_doe()
}

## What the scatter plot shows, the pair's reading, and the rule for curves
## and stray points left for the reader to apply.
cor_scatter_text <- function(d, x, y, method, alpha) {
  if (is.null(x) || is.null(y) || !nzchar(x) || !nzchar(y) || x == y)
    return(list(what = "", reading = "Choose two different variables to plot."))
  tab <- correlate_data(d, c(x, y), method, alpha)
  xs <- response_values(d[[x]]); ys <- response_values(d[[y]])
  ok <- is.finite(xs) & is.finite(ys)
  if (sum(ok) < 2 || is.na(tab$Coefficient)) return(list(what = if (sum(ok) < 2) "" else "Each point is a row with values of both variables.",
                                                        reading = tab$Reading))
  dup <- sum(duplicated(data.frame(xs[ok], ys[ok])))
  out <- c(sprintf("%s is %s.", COR_NAMES[[method]], cor_label(tab$Coefficient, tab$Mark)),
           tab$Reading,
           if (dup) sprintf("%d %s exactly on another row's point and %s hidden under it.", dup,
                            pl(dup, "row sits", "rows sit"), pl(dup, "is", "are")),
           if (tab$N < 10) sprintf("With only %d rows, a single point can change the coefficient a great deal.", tab$N),
           if (method == "pearson")
             paste("If the points bend along a curve that keeps rising (or keeps falling), or one or two sit far from",
                   "the rest, Pearson's r can mislead: Spearman's rho and Kendall's tau use only the order of the values",
                   "and are less affected. A curve that rises and then falls (or the reverse) can give a coefficient",
                   "near 0 whichever coefficient is used.")
           else paste("Rho and tau depend only on the order of the values, so a curve that keeps rising (or falling)",
                      "can still give a coefficient near +1 (or -1), while one that rises and then falls can give one near 0."))
  list(what = "Each point is a row with values of both variables.", reading = paste(out, collapse = " "))
}

## The variables an Explore tab starts with: the columns read as numbers,
## without the columns mapped as design factors or blocks and without those
## that usually label rows (Rep, Plot No, S. No.).
explore_defaults <- function(num, used = character(0)) {
  def <- setdiff(num, used)
  def <- def[!is_id_name(def)]
  if (length(def)) def else num
}

## ---------------------------------------------------------- regression.R ----
###############################################################################
##  REGRESSION
###############################################################################
## Simple and multiple linear regression of one numeric column on one or more
## others, by least squares, using the rows that have every value. As on the
## other Explore tabs, every sentence is one the tables or the plots on
## screen bear out: estimates are printed to the precision their standard
## errors support, a result short of significance is "insufficient
## evidence", the level named is the level chosen, and nothing is said about
## cause that the data cannot show.

## The rank tolerance for every fit and QR here. Powers of values far from 0
## (Year^4 beside Year^3 for 2001 to 2020) differ from the lower powers by
## about one part in 10^9 even when centred and scaled, which lm's default
## (1e-7) takes for an exact combination; at 1e-10 they fit as poly() fits
## them, while a column that is an exact copy in other units is still caught.
REG_TOL <- 1e-10

## Decimals for a coefficient: enough that its standard error shows about
## three significant figures, so the estimate, its SE and its interval are
## printed to the precision the data support and line up within a row. With
## no standard error (an exact fit) the estimate keeps four figures.
reg_dec <- function(se, est) {
  if (is.finite(se) && se > 0) return(as.integer(min(20, max(0, 2 - floor(log10(se))))))
  a <- signif(abs(est), 6)
  if (!is.finite(a) || a == 0) return(2L)
  as.integer(min(20, max(0, 3 - floor(log10(a)))))
}

## A number to s significant figures, never in scientific notation (MSE,
## sums of squares, the residual checks).
sig_fmt <- function(x, s = 4) vapply(x, function(z) {
  if (!is.finite(z)) return("-")
  if (z == 0) return("0")
  formatC(z, format = "f", digits = max(0, s - 1 - floor(log10(abs(z)))))
}, "")

## "p = 0.0234", or "p < 0.0001", with enough figures that a p below the
## chosen level never prints at or above it
reg_p <- function(p, alpha) if (is.na(p)) "p not available" else if (p < 1e-4) "p < 0.0001" else paste("p =", p_show(p, alpha))

## The column names as they appear in the text and the plots
reg_names <- function(v) sprintf("'%s'", v)

#' Linear regression of one numeric variable on one or more others
#'
#' Fits \code{response} on the \code{predictors} by least squares
#' (\code{\link[stats]{lm}}), using the rows with a value of every variable.
#' One predictor gives a simple linear regression, two or more a multiple
#' regression. Text entries are read as the data check reads them: an entry
#' that is not plainly a number counts as missing; see
#' \code{\link{check_data}}.
#'
#' The coefficient table gives each estimate with its standard error, t
#' statistic, two-sided p-value, a significance mark (\code{*} at
#' \code{alpha}, \code{**} at \code{alpha / 5}, \code{NS} otherwise) and a
#' confidence interval at level \code{1 - alpha}; with two or more
#' predictors, each slope's variance inflation factor. The model summary
#' gives N, R-squared, adjusted R-squared, the residual mean square (MSE, the
#' residual sum of squares divided by its N - k - 1 degrees of freedom), its
#' square root (RMSE, the residual standard error), the mean absolute residual
#' (MAE), and the F test of the whole model. Three checks on the residuals
#' go with them: Shapiro-Wilk's test of normality; the Breusch-Pagan test
#' (Koenker's studentised form) of a spread that changes with the predictors
#' (the squared residuals on the predictors, k degrees of freedom); and a test
#' of a curve, Ramsey's RESET (with one predictor its square added to the
#' model, with several the square of the fitted values). With up to 200 rows
#' the p-values of Shapiro-Wilk and Breusch-Pagan come from 2,000 sets of
#' normal data simulated on the same predictor values (10,000 near a
#' significance threshold), since for residuals from few rows the usual ones
#' can be far off; with one residual degree of freedom both are not
#' available.
#'
#' @param d A data frame.
#' @param response The name of the numeric column to be predicted.
#' @param predictors The names of one or more numeric columns to predict it
#'   from.
#' @param alpha The significance level, between 0 and 0.5.
#'
#' @return A list of class \code{doepro_regression}: \code{equation} (the
#'   fitted equation as printed), \code{coefficients} (a data frame:
#'   \code{Term}, \code{Estimate}, \code{SE}, \code{t}, \code{p}, \code{Mark},
#'   \code{CI_lower}, \code{CI_upper} and, with two or more predictors,
#'   \code{VIF}), \code{model} (a one-row data frame: \code{N}, \code{R2},
#'   \code{Adj_R2}, \code{MSE}, \code{RMSE}, \code{MAE}, \code{F},
#'   \code{df1}, \code{df2}, \code{p}, \code{Mark}), \code{anova} (the
#'   regression, residual and total sums of squares), \code{checks} (the
#'   three residual checks: \code{Check}, \code{Test}, \code{Statistic},
#'   \code{df}, \code{p}, \code{Simulated} (whether the p-value came from
#'   simulation) and \code{Verdict}, which gives the reason when a check is
#'   not available), \code{rows} (the rows used), \code{fit}
#'   (the \code{lm} fit, on columns \code{y}, \code{x1}, \code{x2}, ...: the
#'   predictors centred and scaled by \code{centre} and \code{scale}),
#'   \code{built} (predictors that are powers or products of others), and
#'   the settings. With an exact fit (every residual zero) the standard
#'   errors, tests and intervals are \code{NA}.
#'
#' @examples
#' d <- demo_data("RCBD")
#' set.seed(1)
#' d$Height <- 60 + 0.8 * d$Yield + rnorm(nrow(d), 0, 2)
#' r <- regress_data(d, "Height", "Yield")
#' r$equation
#' r$coefficients
#' r$model
#'
#' @export
regress_data <- function(d, response, predictors, alpha = 0.05) {
  if (!is.numeric(alpha) || length(alpha) != 1L || is.na(alpha) || alpha <= 0 || alpha >= 0.5)
    stop("The significance level must be a single number between 0 and 0.5, such as 0.05.")
  if (!is.character(response) || length(response) != 1L || is.na(response) || !nzchar(response))
    stop("Choose one response variable.")
  predictors <- unique(predictors[!is.na(predictors) & nzchar(predictors)])
  if (!length(predictors)) stop("Choose at least one predictor.")
  if (response %in% predictors)
    stop(sprintf("'%s' is the response, so it cannot also be a predictor.", response))
  vars <- c(response, predictors)
  gone <- setdiff(vars, names(d))
  if (length(gone))
    stop(sprintf("%s %s of the data.", join_and(reg_names(gone)), pl(length(gone), "is not a column", "are not columns")))
  k <- length(predictors)
  vals <- lapply(stats::setNames(vars, vars), function(v) response_values(d[[v]]))
  held <- lapply(stats::setNames(vars, vars), function(v) held_flags(d[[v]]))
  ok <- Reduce(`&`, lapply(vals, is.finite))
  ## rows that would have every value once a flagged entry is corrected
  would <- Reduce(`&`, Map(function(v, h) is.finite(v) | h, vals, held))
  held_rows <- which(would & !ok)
  held_eg <- if (length(held_rows)) {
    i <- held_rows[1]; v <- vars[vapply(held, function(h) h[i], logical(1))][1]
    trimws(as.character(d[[v]][i]))
  } else ""
  held_note <- if (length(held_rows))
    sprintf(" %d more %s an entry the data check has flagged (such as '%s'), which will count once corrected on the Data tab.",
            length(held_rows), pl(length(held_rows), "row has", "rows have"), held_eg) else ""
  n <- sum(ok)
  if (n < k + 2)
    stop(sprintf(paste0("Only %d %s a value of every variable chosen; a regression on %d %s needs at least %d, ",
                        "so that something is left over to measure the scatter about the fitted %s.%s"),
                 n, pl(n, "row has", "rows have"), k, pl(k, "predictor", "predictors"), k + 2,
                 if (k == 1) "line" else "equation", held_note))
  y <- vals[[1]][ok]
  X <- do.call(cbind, lapply(vals[-1], function(v) v[ok]))
  colnames(X) <- predictors
  flat <- predictors[apply(X, 2, function(z) length(unique(z)) < 2)]
  if (length(flat))
    stop(sprintf("%s %s the same value in every row used, so %s cannot be estimated; leave %s out.",
                 join_and(reg_names(flat)), pl(length(flat), "has", "each have"), pl(length(flat), "its effect", "their effects"),
                 pl(length(flat), "it", "them")))
  if (length(unique(y)) < 2)
    stop(sprintf("'%s' has the same value in every row used, so there is no variation for the predictors to account for.", response))

  ## The fit is made on the predictors centred and scaled, and its
  ## coefficients turned back to the scale of the data: raw powers of values
  ## far from 0 (Year, Year^2 and Year^3 for 2001 to 2020), or times written
  ## as large counts, are so alike in their leading digits that a fit on them
  ## drops a column as if it were a combination of the others, which it is not.
  safe <- paste0("x", seq_len(k))
  cen <- colMeans(X); scl <- apply(X, 2, stats::sd)
  Z <- sweep(sweep(X, 2, cen), 2, scl, "/")
  df <- data.frame(y = y, Z); names(df) <- c("y", safe)
  fit <- stats::lm(stats::reformulate(safe, "y"), data = df, tol = REG_TOL)
  g <- stats::coef(fit)
  if (anyNA(g)) {
    al <- predictors[is.na(g[safe])]
    others <- k - length(al)
    stop(sprintf(paste("%s can be worked out exactly from the other %s in the rows used (one may be the sum of others,",
                       "or the same measurement in other units), so %s cannot be told apart from %s; leave %s out."),
                 join_and(reg_names(al)), pl(others, "predictor", "predictors"),
                 pl(length(al), "its effect", "their effects"), pl(others, "the other predictor's", "the others'"),
                 pl(length(al), "it", "them")))
  }
  e <- stats::residuals(fit)
  ## residuals that are only the rounding left by an exact fit: nothing to
  ## test against, so the standard errors, tests and intervals are left out.
  ## They are judged against the spread of the response, with a floor for the
  ## rounding its size leaves (counts near 2e9 that scatter by 1 are not an
  ## exact fit)
  exact <- all(abs(e) <= max(1e-9 * max(abs(y - mean(y))), 1e3 * .Machine$double.eps * max(abs(y))))
  dfr <- fit$df.residual

  ## coefficients and their covariance on the scale of the data
  Tm <- diag(k + 1); Tm[1, -1] <- -cen / scl; Tm[cbind(2:(k + 1), 2:(k + 1))] <- 1 / scl
  est <- unname(drop(Tm %*% g))
  V <- Tm %*% suppressWarnings(stats::vcov(fit)) %*% t(Tm)
  se <- sqrt(pmax(diag(V), 0)); tt <- est / se
  pp <- 2 * stats::pt(-abs(tt), dfr)
  qa <- stats::qt(1 - alpha / 2, dfr)
  lo <- est - qa * se; hi <- est + qa * se
  if (exact) {
    se[] <- tt[] <- pp[] <- lo[] <- hi[] <- NA_real_
    ## an exact fit's zero coefficients come out as rounding residue (3e-15):
    ## any whose part in the fitted values is below that is 0
    part <- abs(est) * c(1, apply(abs(X), 2, max))
    est[part <= 1e-9 * max(abs(y))] <- 0
  }
  coefs <- data.frame(Term = c("Intercept", predictors), Estimate = est, SE = se, t = tt, p = pp,
                      Mark = ifelse(is.na(pp), "", star(pp, alpha)), CI_lower = lo, CI_upper = hi,
                      stringsAsFactors = FALSE)
  if (k >= 2) {
    v <- tryCatch(diag(solve(stats::cor(X))), error = function(err) rep(Inf, k))
    coefs$VIF <- c(NA_real_, unname(v))
  }

  fv <- stats::fitted(fit)
  sse <- sum(e^2); ssr <- sum((fv - mean(y))^2); sst <- sum((y - mean(y))^2)
  mse <- sse / dfr
  Fst <- if (exact) NA_real_ else (ssr / k) / mse
  pF <- if (exact) NA_real_ else stats::pf(Fst, k, dfr, lower.tail = FALSE)
  model <- data.frame(N = n, R2 = if (exact) 1 else ssr / sst,
                      Adj_R2 = if (exact) 1 else 1 - (sse / dfr) / (sst / (n - 1)),
                      MSE = if (exact) 0 else mse, RMSE = if (exact) 0 else sqrt(mse),
                      MAE = if (exact) 0 else mean(abs(e)),
                      F = Fst, df1 = k, df2 = dfr, p = pF, Mark = if (is.na(pF)) "" else star(pF, alpha))
  anova <- data.frame(Source = c("Regression", "Residual", "Total"), df = c(k, dfr, n - 1L),
                      SS = c(ssr, if (exact) 0 else sse, sst),
                      MS = c(ssr / k, if (exact) 0 else mse, NA), F = c(Fst, NA, NA), p = c(pF, NA, NA),
                      stringsAsFactors = FALSE)

  dec <- mapply(reg_dec, se, est)
  ## a significant coefficient's interval excludes 0, so neither end may
  ## print as 0: the row gains decimals until they do not
  for (i in which(!is.na(pp) & pp < alpha)) {
    d0 <- dec[i]
    while (dec[i] < d0 + 6 && (as.numeric(dfmt(lo[i], dec[i])) == 0 || as.numeric(dfmt(hi[i], dec[i])) == 0))
      dec[i] <- dec[i] + 1L
  }
  ## The printed equation must reproduce the fitted values: when predictors
  ## are nearly alike (powers of a calendar year) coefficients rounded one by
  ## one to their standard errors do not, so every row gains decimals until
  ## the printed equation is within 1% of the RMSE of the fit at every row.
  fv0 <- stats::fitted(fit)
  tolv <- if (exact) 1e-6 * stats::sd(y) else 0.01 * sqrt(sse / dfr)
  extra <- 0L
  printed_fit <- function(dd) drop(cbind(1, X) %*% vapply(seq_along(est), function(i) as.numeric(dfmt(est[i], dd[i])), 0))
  while (extra < 12 && max(abs(printed_fit(dec + extra) - fv0)) > tolv) extra <- extra + 1L
  dec <- dec + extra
  ## rows left out for an entry that is not a finite number (Inf from a
  ## division by zero), which the data check does not list
  inf_rows <- sum(!ok & Reduce(`|`, lapply(vals, is.infinite)))
  r <- list(response = response, predictors = predictors, alpha = alpha, k = k, n = n,
            rows = row_ids(d)[ok], y = y, X = X, fit = fit, centre = cen, scale = scl, exact = exact, dec = dec,
            coefficients = coefs, model = model, anova = anova,
            held_rows = length(held_rows), held_eg = held_eg, inf_rows = inf_rows, extra = extra,
            lacking = sum(!would), nrow = nrow(d))
  r$built <- reg_built(X)
  r$equation <- reg_equation(r)
  r$checks <- reg_checks(r)
  class(r) <- "doepro_regression"
  r
}

#' @rdname regress_data
#' @param x A result of \code{regress_data()}.
#' @param ... Not used.
#' @export
print.doepro_regression <- function(x, ...) {
  cat(x$equation, "\n\n")
  print(x$coefficients, row.names = FALSE)
  cat("\n")
  print(x$model, row.names = FALSE)
  invisible(x)
}

## Columns built from other predictors: powers (Dose2 = Dose^2, Dose3 =
## Dose^3, up to the fourth) and products of two (NP = N x P), as when a
## polynomial or a response surface is fitted. A value counts when it is
## the power or product to the decimals it was entered with (156.3 for
## 12.5^2, as a spreadsheet copies it) and to three significant figures.
## One row per built column: `kind` "power" or "product", built from
## predictor `a` (and `b` for a product), `p` the power. A built column
## cannot change without the predictors it is built from, so they are drawn
## and read together.
reg_built <- function(X) {
  k <- ncol(X)
  out <- data.frame(col = integer(0), kind = character(0), a = integer(0), b = integer(0), p = integer(0),
                    stringsAsFactors = FALSE)
  if (k < 2) return(out)
  decs <- lapply(seq_len(k), function(m) {
    s <- num_text(X[, m])
    ifelse(grepl(".", s, fixed = TRUE), nchar(sub("^[^.]*[.]", "", s)), 0)
  })
  ## Each entry must be the target to the decimals it was entered with. When
  ## some entry is only rounded, each entry large enough to carry three
  ## figures at those decimals must also match to three figures, and at
  ## least two distinct non-zero entries must be of that kind, so small whole
  ## numbers (1, 3, 4 beside 1.21, 2.56, 4.41) are not taken for squares.
  same <- function(m, target) {
    big <- max(abs(target))
    if (big == 0) return(FALSE)
    gap <- abs(X[, m] - target)
    if (!all(gap <= pmax(0.5 * 10^(-decs[[m]]), 1e-9 * big) * (1 + 1e-9))) return(FALSE)
    if (all(gap <= 1e-9 * big)) return(TRUE)
    three <- abs(target) >= 10^(2 - decs[[m]])
    all(gap[three] <= 5e-3 * abs(target[three]) + 1e-9 * big) && length(unique(target[three & target != 0])) >= 2
  }
  cand <- list()
  add <- function(m, kind, a, b, p)
    cand[[length(cand) + 1]] <<- data.frame(col = m, kind = kind, a = a, b = b, p = p, stringsAsFactors = FALSE)
  for (m in seq_len(k)) {
    v <- setdiff(seq_len(k), m)
    for (j in v) for (p in 2:4) if (same(m, X[, j]^p)) add(m, "power", j, NA_integer_, p)
    if (length(v) >= 2) for (pr in utils::combn(length(v), 2, simplify = FALSE))
      if (same(m, X[, v[pr[1]]] * X[, v[pr[2]]])) add(m, "product", v[pr[1]], v[pr[2]], NA_integer_)
  }
  if (!length(cand)) return(out)
  cand <- do.call(rbind, cand)
  ## a column built from a built column (Dose4 = Dose2^2) counts only through
  ## predictors that are not themselves built
  built <- unique(cand$col)
  cand <- cand[!cand$a %in% built & (is.na(cand$b) | !cand$b %in% built), , drop = FALSE]
  cand <- cand[!duplicated(cand$col), , drop = FALSE]
  cand <- cand[order(cand$col), , drop = FALSE]
  rownames(cand) <- NULL
  cand
}

reg_power_word <- function(p) c("square", "cube", "fourth power")[p - 1]
## the row of `built` for column m, NULL when m is not built
reg_built_row <- function(r, m) if (is.null(r$built) || !m %in% r$built$col) NULL else r$built[match(m, r$built$col), ]
reg_bases <- function(r) setdiff(seq_len(r$k), r$built$col)
## the power columns of predictor j, by increasing power, and its products
reg_powers_of <- function(r, j) {
  w <- r$built[r$built$kind == "power" & r$built$a == j, , drop = FALSE]
  w$col[order(w$p)]
}
reg_products_of <- function(r, j) r$built$col[r$built$kind == "product" & (r$built$a == j | (!is.na(r$built$b) & r$built$b == j))]
## the square of j when it is j's only power: a quadratic in j
reg_quad_of <- function(r, j) {
  pw <- reg_powers_of(r, j)
  if (length(pw) == 1 && reg_built_row(r, pw)$p == 2) pw else NA_integer_
}
## the predictor a column is shown through: itself, or the first it is
## built from
reg_source <- function(r, m) { w <- reg_built_row(r, m); if (is.null(w)) m else w$a }

## The groups of columns that change together: predictors joined by a
## product, with their powers and products. One vector of column indices
## per group of two or more columns, the predictors first.
reg_groups <- function(r) {
  if (is.null(r$built) || !nrow(r$built)) return(list())
  bases <- reg_bases(r)
  lab <- bases
  prod <- r$built[r$built$kind == "product", , drop = FALSE]
  repeat {
    changed <- FALSE
    for (i in seq_len(nrow(prod))) {
      la <- lab[match(prod$a[i], bases)]; lb <- lab[match(prod$b[i], bases)]
      if (la != lb) { lab[lab == max(la, lb)] <- min(la, lb); changed <- TRUE }
    }
    if (!changed) break
  }
  out <- lapply(unique(lab), function(L) {
    bs <- bases[lab == L]
    c(bs, sort(r$built$col[r$built$a %in% bs]))
  })
  out[vapply(out, length, 1L) > 1]
}
reg_group <- function(r, j) { for (g in reg_groups(r)) if (j %in% g) return(g); j }

## Every column of the design from the values of the predictors that are not
## built: powers and products worked out from them.
reg_design <- function(r, B) {
  for (i in seq_len(NROW(r$built))) {
    w <- r$built[i, ]
    B[, w$col] <- if (w$kind == "power") B[, w$a]^w$p else B[, w$a] * B[, w$b]
  }
  B
}

## predictions from the fit, which is on centred and scaled columns
reg_predict <- function(r, B, interval = FALSE) {
  Z <- sweep(sweep(B, 2, r$centre), 2, r$scale, "/")
  nd <- as.data.frame(Z); names(nd) <- paste0("x", seq_len(r$k))
  suppressWarnings(stats::predict(r$fit, nd, interval = if (interval) "confidence" else "none", level = 1 - r$alpha))
}



## a coefficient as the table prints it
reg_coef_txt <- function(r, i, what = "Estimate") {
  v <- r$coefficients[[what]][i]
  if (is.na(v)) "-" else dfmt(v, r$dec[i])
}

## The fitted equation, each number as the coefficient table prints it:
## Yield = 12.35 + 0.452 x Nitrogen - 1.20 x Rain. The terms are kept apart
## so a wrapped line never splits one.
reg_equation_terms <- function(r) {
  out <- paste(r$response, "=", reg_coef_txt(r, 1))
  for (j in seq_len(r$k)) {
    s <- reg_coef_txt(r, j + 1)
    out <- c(out, paste0(if (startsWith(s, "-")) "- " else "+ ", sub("^-", "", s), " \u00d7 ", r$predictors[j]))
  }
  out
}
reg_equation <- function(r) paste(reg_equation_terms(r), collapse = " ")

## ------------------------------------------------------------- checks ----

## Residuals are not independent values: part of their pattern is set by the
## predictor values, so with few rows the usual p-values of Shapiro-Wilk and
## Breusch-Pagan applied to them can be far off. In simulation (normal data,
## designs with small whole-number predictors or one far-out row) Shapiro-
## Wilk called 10-23% of them non-normal at 5% with 2-5 residual degrees of
## freedom, and Breusch-Pagan 15-28%; Breusch-Pagan settled near 5% only
## from about 10. Neither statistic depends on the coefficients or the SD,
## only on the predictor values, so up to REG_SIM_N rows each p-value is
## found by simulation instead: REG_SIM_B sets of normal data on these same
## predictor values, a fixed seed, and p = (k + 1) / (B + 1) from the sets at
## least as extreme, which holds the level for any design.
## A p-value within three standard errors of alpha or alpha / 5 is worked out
## again from REG_SIM_B_CLOSE sets, so a verdict near the threshold rests on
## a p-value good to about +/- 0.002 rather than 0.005.
REG_SIM_N <- 200
REG_SIM_B <- 2000
REG_SIM_B_CLOSE <- 10000

## residuals of B sets of standard normal data on the model's predictors
reg_sim_resid <- function(fit, B = REG_SIM_B) {
  Q <- qr.Q(fit$qr)
  n <- nrow(Q)
  Z <- with_fixed_seed(COR_PERM_SEED + B, matrix(stats::rnorm(n * B), n))
  Z - Q %*% crossprod(Q, Z)
}

## (k + 1) / (B + 1) from the simulated statistics at least as extreme as the
## observed one, worked out again from more sets when it falls close to a
## threshold; `stat` gives the statistic of each column of residuals and
## `extreme` says which are at least as extreme
reg_sim_p <- function(fit, alpha, E, stat, extreme) {
  p_of <- function(E) (sum(extreme(stat(E))) + 1) / (ncol(E) + 1)
  p <- p_of(E); B <- ncol(E)
  se <- sqrt(p * (1 - p) / B)
  if (any(abs(p - c(alpha, alpha / 5)) < 3 * se)) { p <- p_of(reg_sim_resid(fit, REG_SIM_B_CLOSE)); B <- REG_SIM_B_CLOSE }
  structure(p, sets = B)
}

## Breusch-Pagan's N R^2 of the squared residuals on the predictors, for one
## residual vector or each column of a matrix of them (Koenker's studentised
## form: no assumption of normal residuals in the statistic itself)
reg_bp_stat <- function(E, Q) {
  E <- as.matrix(E)
  S <- E^2
  Sc <- sweep(S, 2, colMeans(S))
  tot <- colSums(Sc^2)
  ## residuals all of one size: no change of spread at all
  flat <- tot <= (1e-8 * colMeans(S))^2 * nrow(S)
  fit <- colSums((Q %*% crossprod(Q, Sc))^2)
  ifelse(flat, 0, nrow(S) * fit / tot)
}

## The test of a curve in predictor j: the square of the (centred) predictor
## added to the full model and tested by F. With one predictor this is
## Ramsey's RESET; it stays defined when the fitted line is flat.
reg_curve <- function(r, j) {
  na <- function(why) list(stat = NA_real_, df = NA_character_, p = NA_real_, why = why)
  m <- reg_quad_of(r, j); pw <- reg_powers_of(r, j)
  if (!is.na(m))
    return(na(sprintf("%s, the square of %s, is already in the model, so a curve in %s is already allowed for",
                      r$predictors[m], r$predictors[j], r$predictors[j])))
  if (length(pw))
    return(na(sprintf("powers of %s (%s) are already in the model, so a curve in %s is already allowed for",
                      r$predictors[j], join_and(r$predictors[pw]), r$predictors[j])))
  if (r$exact) return(na("the model fits every value exactly, so there is no scatter to test"))
  if (r$fit$df.residual < 2)
    return(na(sprintf("it needs at least %d rows, one more than the regression itself", r$k + 3)))
  df <- r$fit$model
  x <- r$X[, j]
  df$q <- ((x - mean(x)) / stats::sd(x))^2
  f2 <- stats::lm(stats::update(stats::formula(r$fit), . ~ . + q), data = df, tol = REG_TOL)
  if (is.na(stats::coef(f2)[["q"]]))
    return(na(if (length(unique(x)) <= 2)
      sprintf("%s takes only two distinct values, so a curve cannot be told from a straight line", r$predictors[j])
      else sprintf(paste("the square of %s can already be worked out from the predictors in the model (a squared",
                         "column may be among them), so a curve in it is already allowed for"), r$predictors[j])))
  a <- stats::anova(r$fit, f2)
  list(stat = a$F[2], df = sprintf("1, %d", f2$df.residual), p = a$`Pr(>F)`[2], why = NULL)
}

## The three checks on the residuals, each with its statistic, degrees of
## freedom, p-value and verdict, or the reason it cannot be worked out:
##   normality: Shapiro-Wilk on the residuals;
##   constant spread: Breusch-Pagan of the squared residuals on the
##     predictors, N R^2 on k df;
##   a curve: with one predictor its square added (Ramsey's RESET); with
##     several, RESET proper, the square of the fitted values added, tested by
##     F on 1 and N - k - 2 df.
reg_checks <- function(r) {
  alpha <- r$alpha
  e <- stats::residuals(r$fit); fv <- stats::fitted(r$fit); n <- r$n
  dfr <- r$fit$df.residual
  Q <- qr.Q(r$fit$qr)
  na <- function(why) list(stat = NA_real_, df = NA_character_, p = NA_real_, why = why, sim = FALSE)
  exact_why <- "the model fits every value exactly, so there is no scatter to test"
  one_df <- "with one residual degree of freedom, the pattern of the residuals is fixed by the predictor values"
  sim <- !r$exact && dfr >= 2 && n <= REG_SIM_N
  ## with many rows a handful of sets is enough to spot a design that fixes
  ## the Breusch-Pagan statistic
  E <- if (!r$exact && dfr >= 2) reg_sim_resid(r$fit, if (sim) REG_SIM_B else 5)
  normal <- if (r$exact) na(exact_why)
    else if (dfr < 2) na(one_df)
    else if (n > 5000) na("Shapiro-Wilk's test takes at most 5,000 values")
    else {
      w <- unname(stats::shapiro.test(e)$statistic)
      p <- if (sim) reg_sim_p(r$fit, alpha, E, function(E) apply(E, 2, function(z) stats::shapiro.test(z)$statistic),
                              function(ws) ws <= w + 1e-12)
           else stats::shapiro.test(e)$p.value
      list(stat = w, df = "", p = as.numeric(p), why = NULL, sim = sim, sets = attr(p, "sets"))
    }
  ## A row that alone decides a coefficient (leverage 1) has a residual of 0
  ## whatever the data, which Breusch-Pagan would read as a change of spread:
  ## it is left out of that test, with the predictors as they are in the rows
  ## that remain.
  keep <- stats::hatvalues(r$fit) < 1 - 1e-8
  ## on the centred and scaled columns the fit used, so no direction is lost
  qk <- qr(cbind(1, as.matrix(r$fit$model[keep, -1, drop = FALSE])), tol = REG_TOL)
  Qk <- qr.Q(qk)[, seq_len(qk$rank), drop = FALSE]
  nk <- sum(keep)
  spread <- if (r$exact) na(exact_why)
    else if (dfr < 2) na(one_df)
    ## when every set's squared residuals are fitted exactly by the
    ## predictors (two rows at each setting, each setting fitted on its own),
    ## the statistic is N whatever the data
    else if (qk$rank < 2)
      na(paste("the rows that have a residual all share one setting of the predictors (each other row alone decides a",
               "coefficient and has no residual), so a change of spread cannot be measured"))
    else if (all(reg_bp_stat(E[keep, seq_len(min(5, ncol(E))), drop = FALSE], Qk) >= nk * (1 - 1e-8)))
      na(paste("the squared residuals are fitted exactly by the predictors whatever the data (as with two rows at each",
               "setting of the predictors), so a change of spread cannot be tested"))
    else {
      st <- reg_bp_stat(e[keep], Qk)
      p <- if (sim) reg_sim_p(r$fit, alpha, E, function(E) reg_bp_stat(E[keep, , drop = FALSE], Qk),
                              function(b) b >= st - 1e-9 * max(1, st))
           else stats::pchisq(st, qk$rank - 1, lower.tail = FALSE)
      list(stat = st, df = as.character(qk$rank - 1), p = as.numeric(p), why = NULL, sim = sim, sets = attr(p, "sets"))
    }
  curve <- if (r$k == 1) c(reg_curve(r, 1), sim = FALSE)
    else if (r$exact) na(exact_why)
    else if (dfr < 2) na(sprintf("it needs at least %d rows, one more than the regression itself", r$k + 3))
    ## a flat fit: its square is rounding residue, not a curve
    else if (stats::sd(fv) <= 1e-9 * stats::sd(r$y))
      na("the fitted values are all the same, so their square cannot show a curve")
    else {
      df <- r$fit$model
      df$q <- ((fv - mean(fv)) / stats::sd(fv))^2
      f2 <- stats::lm(stats::update(stats::formula(r$fit), . ~ . + q), data = df, tol = REG_TOL)
      if (is.na(stats::coef(f2)[["q"]]))
        na(if (length(unique(signif(fv, 10))) <= 2)
             "the fitted values take too few distinct values for a curve to be told from a straight line"
           else paste("the square of the fitted values can already be worked out from the predictors in the model,",
                      "so a curve along them is already allowed for"))
      else {
        a <- stats::anova(r$fit, f2)
        list(stat = a$F[2], df = sprintf("1, %d", f2$df.residual), p = a$`Pr(>F)`[2], why = NULL, sim = FALSE)
      }
    }
  out <- data.frame(Check = c("Normal residuals", "Constant spread", "Straight line"),
                    Test = c("Shapiro-Wilk W", "Breusch-Pagan chi-square",
                             if (r$k == 1) paste0("F, square of ", r$predictors, " added") else "RESET F"),
                    Statistic = c(normal$stat, spread$stat, curve$stat),
                    df = c(normal$df, spread$df, curve$df),
                    p = c(normal$p, spread$p, curve$p),
                    Simulated = c(normal$sim, spread$sim, FALSE),
                    Sets = c(normal$sets %||% NA_real_, spread$sets %||% NA_real_, NA_real_), stringsAsFactors = FALSE)
  out$Verdict <- ifelse(is.na(out$p), paste("not available:", c(normal$why %||% "", spread$why %||% "", curve$why %||% "")),
                        ifelse(out$p < alpha, "significant departure", "no significant departure"))
  out
}

## ------------------------------------------------------------ display ----

reg_mark_key <- function(alpha)
  sprintf("** significant at p < %s; * significant at p < %s; NS not significant at the %s%% level.",
          p_lab(alpha / 5), p_lab(alpha), pct(alpha))

## The coefficients: each estimate, its SE and its interval to the same
## decimals, so the row reads straight across.
reg_coef_html <- function(r) {
  cf <- r$coefficients; alpha <- r$alpha; multi <- r$k >= 2
  body <- lapply(seq_len(nrow(cf)), function(i) c(
    esc(cf$Term[i]), reg_coef_txt(r, i), reg_coef_txt(r, i, "SE"),
    if (is.na(cf$t[i])) "-" else dfmt(cf$t[i], 2),
    esc(p_show(cf$p[i], alpha)), cf$Mark[i],
    if (is.na(cf$CI_lower[i])) "-" else sprintf("%s to %s", reg_coef_txt(r, i, "CI_lower"), reg_coef_txt(r, i, "CI_upper")),
    if (multi) (if (i == 1) "" else if (is.finite(cf$VIF[i])) fmt(cf$VIF[i], 2) else "-")))
  head_ <- c("Term", "Estimate", "SE", "t", "p", "Mark", sprintf("%s%% CI", pct(1 - alpha)), if (multi) "VIF")
  notes <- c(
    sprintf(paste("Estimate: for the intercept, the predicted %s when %s 0; for a predictor, the change in the",
                  "predicted %s for one unit more of it%s. SE: its standard error. t = Estimate / SE, tested on",
                  "N - k - 1 = %d - %d - 1 = %d %s of freedom (N rows used, k predictors). CI: the %s%% confidence interval."),
            esc(r$response), if (multi) "every predictor is" else paste(esc(r$predictors), "is"), esc(r$response),
            if (multi) ", the other predictors held at the same values" else "", r$n, r$k, r$model$df2,
            pl(r$model$df2, "degree", "degrees"), pct(1 - alpha)),
    if (length(reg_groups(r))) paste(vapply(reg_groups(r), function(g) esc(reg_group_note(r, g)), ""), collapse = " "),
    esc(reg_mark_key(alpha)),
    if (multi) paste("VIF (variance inflation factor): how much a slope's variance is inflated because its predictor",
                     "is related to the others; 1 means unrelated, and 5 or more is commonly taken as a warning."),
    if (r$exact) "The model fits every value exactly, so there is no scatter to judge the estimates against: standard errors, tests and intervals are not available.")
  foot <- sprintf("<tr><td colspan='%d' class='cdrow'>%s</td></tr>", length(head_), paste(notes, collapse = " "))
  raw_table(head_, body, foot = foot, caption = "Coefficients")
}

## The model in one row: how well it fits, and its F test.
reg_model_html <- function(r) {
  m <- r$model; alpha <- r$alpha
  body <- list(c(as.character(m$N), fmt(m$R2, 3), dfmt(m$Adj_R2, 3), sig_fmt(m$MSE), sig_fmt(m$RMSE), sig_fmt(m$MAE),
                 if (is.na(m$F)) "-" else fmt(m$F, 2), sprintf("%d, %d", m$df1, m$df2), esc(p_show(m$p, alpha)), m$Mark))
  head_ <- c("N", "R\u00b2", "Adjusted R\u00b2", "MSE", "RMSE", "MAE", "F", "df", "p", "Mark")
  notes <- c(
    "R\u00b2: the share of the variation in the response about its mean that the fitted equation accounts for.",
    paste("Adjusted R\u00b2: the same, with an allowance for the number of predictors; it falls below 0 when the",
          "predictors account for less of the variation than chance alone would give."),
    "MSE: the residual mean square, the sum of squared residuals divided by N - k - 1 (N rows used, k predictors; as in the ANOVA below).",
    "RMSE: its square root, the residual standard error, which estimates the standard deviation of the scatter about the true equation.",
    "MAE: the mean of the absolute residuals.",
    sprintf("F tests the whole model at the %s%% level.", pct(alpha)))
  foot <- sprintf("<tr><td colspan='%d' class='cdrow'>%s</td></tr>", length(head_), paste(notes, collapse = " "))
  raw_table(head_, body, foot = foot, caption = "Model summary")
}

## The regression ANOVA: the total variation split into the part the
## equation accounts for and the residual.
reg_anova_html <- function(r) {
  a <- r$anova; alpha <- r$alpha
  body <- lapply(seq_len(nrow(a)), function(i) c(
    a$Source[i], as.character(a$df[i]), sig_fmt(a$SS[i], 5), if (is.na(a$MS[i])) "" else sig_fmt(a$MS[i], 5),
    if (i == 1 && !is.na(a$F[i])) fmt(a$F[i], 2) else if (i == 1) "-" else "",
    if (i == 1) esc(p_show(a$p[i], alpha)) else "", if (i == 1) r$model$Mark else ""))
  foot <- sprintf(paste("<tr><td colspan='7' class='cdrow'>The total variation in %s about its mean, split into the part",
                        "the fitted equation accounts for and the residual. F = regression mean square / residual mean",
                        "square: the model's test in the summary above. R\u00b2 = regression sum of squares / total.</td></tr>"),
                  esc(r$response))
  raw_table(c("Source", "df", "Sum of squares", "Mean square", "F", "p", "Mark"), body, foot = foot,
            caption = "Analysis of variance of the regression")
}

## The residual checks, with what each would show.
reg_checks_html <- function(r) {
  ck <- r$checks; alpha <- r$alpha
  fams <- NROW(r$built) > 0
  body <- lapply(seq_len(nrow(ck)), function(i) c(
    if (fams && ck$Check[i] == "Straight line") "Shape of the fit" else ck$Check[i], ck$Test[i],
    if (is.na(ck$Statistic[i])) "-" else fmt(ck$Statistic[i], if (i == 1) 3 else 2),
    if (is.na(ck$df[i]) || !nzchar(ck$df[i])) "" else ck$df[i],
    esc(p_show(ck$p[i], alpha)),
    if (grepl("^significant", ck$Verdict[i])) paste0("<b>", ck$Verdict[i], "</b>") else esc(ck$Verdict[i])))
  notes <- c(
    "Shapiro-Wilk: whether the residuals could come from a normal distribution.",
    if (r$k == 1) sprintf("Breusch-Pagan: whether the spread of the residuals changes with %s (a funnel in the residual plot).", esc(r$predictors))
    else "Breusch-Pagan: whether the spread of the residuals changes with the predictors (a band that widens along one of them).",
    if (r$k == 1) sprintf("Straight line: whether adding the square of %s fits significantly better than the straight line (with one predictor, Ramsey's RESET test).", esc(r$predictors))
    else if (fams) paste("RESET: whether adding the square of the fitted values fits significantly better, a pattern along",
                         "the fitted values that the fitted equation does not follow.")
    else paste("RESET: whether adding the square of the fitted values fits significantly better, a curve along the fitted",
               "values; a curve in one predictor is tested in the main plot's note."),
    if (any(ck$Simulated)) {
      sm <- which(ck$Simulated)
      nm <- c("Shapiro-Wilk", "Breusch-Pagan")[sm]
      sets <- vapply(ck$Sets[sm], function(b) formatC(b, format = "d", big.mark = ","), "")
      paste0(sprintf(paste("The %s of %s %s from sets of normal data simulated on these same predictor values (%s):",
                           "with few rows the usual formulas can be far off for residuals."),
                     pl(length(sm), "p-value", "p-values"), join_and(nm), pl(length(sm), "comes", "come"),
                     paste(sprintf("%s for %s", sets, nm), collapse = ", ")),
             if (any(ck$Sets[sm] > REG_SIM_B))
               sprintf(" %s sets are used when the first estimate from %s falls close to a threshold.",
                       formatC(REG_SIM_B_CLOSE, format = "d", big.mark = ","), formatC(REG_SIM_B, format = "d", big.mark = ","))
             else "")
    },
    sprintf("Verdicts at the %s%% level.", pct(alpha)))
  foot <- sprintf("<tr><td colspan='6' class='cdrow'>%s</td></tr>", paste(notes, collapse = " "))
  raw_table(c("Check", "Test", "Statistic", "df", "p", "Verdict"), body, foot = foot, caption = "Checks on the residuals")
}

## the range of a predictor in the rows used, as "40 to 160"
reg_range <- function(r, j) {
  x <- r$X[, j]
  ## whole numbers and short decimals as entered; a long binary fraction cut
  ## to six figures, outward, so the range printed still holds every value
  end <- function(v, up) {
    if (v == round(v) || v == signif(v, 10)) return(num_text(v))
    f <- 10^(5 - floor(log10(abs(v))))
    num_text(signif((if (up) ceiling(v * f) else floor(v * f)) / f, 10))
  }
  paste(end(min(x), FALSE), "to", end(max(x), TRUE))
}

## Where a quadratic in predictor j turns, x = -b1 / (2 b2), from the
## coefficients as fitted (rounded ones can move it by years when j is a
## calendar year), with any product of j taken at the other predictor's held
## value. Printed to a thousandth of the observed range, and judged inside,
## at the end of, or outside it on the printed value.
reg_turn_text <- function(r, j, held = colMeans(r$X)) {
  sq <- reg_quad_of(r, j); cf <- r$coefficients; nm <- r$predictors
  if (as.numeric(reg_coef_txt(r, sq + 1)) == 0)
    return(sprintf("The coefficient of %s prints as 0, so over the data the curve is close to a straight line.", nm[sq]))
  pr <- reg_products_of(r, j)
  b1 <- cf$Estimate[j + 1]
  oth <- integer(0)
  for (m in pr) {
    w <- reg_built_row(r, m); o <- if (w$a == j) w$b else w$a
    b1 <- b1 + cf$Estimate[m + 1] * held[o]; oth <- c(oth, o)
  }
  b2 <- cf$Estimate[sq + 1]
  x <- r$X[, j]; lo <- min(x); hi <- max(x)
  tp <- dfmt(-b1 / (2 * b2), max(0, 3 - floor(log10(hi - lo)))); tv <- as.numeric(tp)
  where <- if (tv > lo && tv < hi) sprintf("inside the observed range (%s)", reg_range(r, j))
           else if (tv == lo || tv == hi) sprintf("at the %s end of the observed range (%s)", if (tv == hi) "upper" else "lower", reg_range(r, j))
           else sprintf("outside the observed range (%s), so over the data the curve keeps %s", reg_range(r, j),
                        if ((b2 < 0) == (tv > hi)) "rising" else "falling")
  paste0(if (length(pr)) "With the other predictors at their means, the curve" else "The curve",
         sprintf(" is %s at %s = %s, where its slope is 0, %s.", if (b2 < 0) "highest" else "lowest", nm[j], tp, where),
         if (length(pr)) sprintf(" Its shape in %s changes with %s (through %s), so at other values it turns elsewhere.",
                                 nm[j], join_and(nm[unique(oth)]), join_and(nm[pr])) else "")
}

## the F test of a group of columns: the model against the model without them
reg_partial <- function(r, cols) {
  keep <- setdiff(seq_len(r$k), cols)
  df <- r$fit$model
  red <- if (length(keep)) stats::lm(stats::reformulate(paste0("x", keep), "y"), data = df, tol = REG_TOL) else stats::lm(y ~ 1, data = df)
  a <- stats::anova(red, r$fit)
  list(F = a$F[2], df1 = a$Df[2], df2 = a$Res.Df[2], p = a$`Pr(>F)`[2])
}

## how a group is named in the reading
reg_group_name <- function(r, g) {
  bs <- intersect(g, reg_bases(r))
  if (length(bs) == 1) sprintf("the curve in %s", r$predictors[bs]) else sprintf("the terms in %s", join_and(r$predictors[bs]))
}

## what each built column of a group is
reg_built_desc <- function(r, m) {
  w <- reg_built_row(r, m); nm <- r$predictors
  if (w$kind == "power") sprintf("%s is the %s of %s", nm[m], reg_power_word(w$p), nm[w$a])
  else sprintf("%s is %s \u00d7 %s", nm[m], nm[w$a], nm[w$b])
}

## the coefficient table's note on a group
reg_group_note <- function(r, g) {
  bs <- intersect(g, reg_bases(r)); built <- setdiff(g, bs); nm <- r$predictors
  if (length(bs) == 1) {
    words <- vapply(built, function(m) reg_power_word(reg_built_row(r, m)$p), "")
    sprintf("%s %s the %s of %s: %s describe one curve and cannot change separately, so %s alone is a change per unit.",
            join_and(nm[built]), pl(length(built), "is", "are"), join_and(words), nm[bs],
            if (length(built) == 1) "the two" else "with it they",
            if (length(built) == 1) "neither coefficient" else "no coefficient among them")
  } else sprintf(paste("%s: these terms describe one surface in %s and cannot change separately, so no coefficient among",
                       "them alone is a change per unit."),
                 cap1(join_and(vapply(built, function(m) reg_built_desc(r, m), ""))), join_and(nm[bs]))
}

## why a group's VIFs are large
reg_group_reason <- function(r, g) {
  bs <- intersect(g, reg_bases(r)); built <- setdiff(g, bs); nm <- r$predictors
  if (length(bs) > 1) return(sprintf("these terms being built from %s", join_and(nm[bs])))
  if (length(built) == 1) return(sprintf("%s being the %s of %s", nm[built], reg_power_word(reg_built_row(r, built)$p), nm[bs]))
  sprintf("these terms being powers of %s", nm[bs])
}

## The reading of a group: what its columns are, and the tests that mean
## something for it (the bend, an interaction, the group as a whole).
reg_group_text <- function(r, g) {
  alpha <- r$alpha; lvl <- paste0(pct(alpha), "%"); cf <- r$coefficients; nm <- r$predictors
  bs <- intersect(g, reg_bases(r)); built <- setdiff(g, bs)
  prods <- built[vapply(built, function(m) reg_built_row(r, m)$kind == "product", logical(1))]
  ## a significant RESET means the data bend in a way this curve misses, so a
  ## lower degree is not offered as an alternative
  missed <- !is.na(r$checks$p[3]) && r$checks$p[3] < alpha
  bend <- function(j) {
    pw <- reg_powers_of(r, j)
    if (!length(pw) || r$exact) return(NULL)
    top <- pw[length(pw)]; quad <- !is.na(reg_quad_of(r, j))
    inj <- if (length(prods)) paste(" in", nm[j]) else ""
    if (cf$p[top + 1] < alpha)
      sprintf("The coefficient of %s, %s, is significant at the %s level (%s): %s.", nm[top],
              if (quad) paste0("which measures the bend", inj) else paste("the highest power of", nm[j]),
              lvl, reg_p(cf$p[top + 1], alpha), if (quad) "the relation curves" else "the curve needs it")
    else sprintf("There is insufficient evidence at the %s level that %s (the coefficient of %s, %s)%s.", lvl,
                 if (quad) paste0("the relation bends", inj) else paste("the highest power of", nm[j], "is needed"),
                 nm[top], reg_p(cf$p[top + 1], alpha),
                 if (missed || length(prods)) "" else if (quad) sprintf(", so a straight line in %s may do as well", nm[j])
                 else ", so a curve of lower degree may do as well")
  }
  if (!length(prods)) {
    j <- bs[1]
    words <- vapply(built, function(m) reg_power_word(reg_built_row(r, m)$p), "")
    deg <- max(vapply(built, function(m) reg_built_row(r, m)$p, 1L))
    out <- c(if (length(built) == 1)
               sprintf(paste("%s is the %s of %s, so the two describe one curve and cannot change separately: neither",
                             "coefficient alone is the change for one unit more of %s."), nm[built], words, nm[j], nm[j])
             else sprintf(paste("%s are the %s of %s, so with it they describe one curve (a polynomial of degree %d) and",
                                "cannot change separately: no coefficient among them alone is the change for one unit more of %s."),
                          join_and(nm[built]), join_and(words), nm[j], deg, nm[j]),
             if (length(setdiff(seq_len(r$k), g))) "The other predictors raise or lower the curve without changing its shape.",
             if (!is.na(reg_quad_of(r, j))) reg_turn_text(r, j) else "The main plot draws the curve.",
             bend(j))
    return(paste(out, collapse = " "))
  }
  out <- sprintf(paste("%s describe one surface in %s: %s. The effect of each of %s therefore depends on the %s, and no",
                       "coefficient among these terms alone is a change per unit."),
                 join_and(nm[g]), join_and(nm[bs]), join_and(vapply(built, function(m) reg_built_desc(r, m), "")), join_and(nm[bs]),
                 if (length(bs) == 2) "other" else "others")
  if (!r$exact && length(g) < r$k) {
    pf <- reg_partial(r, g)
    out <- c(out, if (pf$p < alpha)
      sprintf("Together these terms are significant at the %s level (F = %s on %d and %d degrees of freedom, %s).",
              lvl, fmt(pf$F, 2), pf$df1, pf$df2, reg_p(pf$p, alpha))
      else sprintf("There is insufficient evidence at the %s level that these terms together are related to %s (F = %s on %d and %d degrees of freedom, %s).",
                   lvl, r$response, fmt(pf$F, 2), pf$df1, pf$df2, reg_p(pf$p, alpha)))
  }
  if (!r$exact) for (m in prods) {
    w <- reg_built_row(r, m)
    out <- c(out, if (cf$p[m + 1] < alpha)
      sprintf("The coefficient of %s, which measures how the effect of %s changes with %s, is significant at the %s level (%s).",
              nm[m], nm[w$a], nm[w$b], lvl, reg_p(cf$p[m + 1], alpha))
      else sprintf("There is insufficient evidence at the %s level that the effect of %s changes with %s (the coefficient of %s, %s).",
                   lvl, nm[w$a], nm[w$b], nm[m], reg_p(cf$p[m + 1], alpha)))
  }
  out <- c(out, unlist(lapply(bs, bend)),
           sprintf("The main plot draws the fitted %s for %s, with the other predictors held at their means.",
                   {
                     cv <- vapply(bs, function(j) length(reg_powers_of(r, j)) > 0, logical(1))
                     if (all(cv)) "curve" else if (!any(cv)) "line" else "line or curve"
                   },
                   if (length(bs) == 2) paste(nm[bs], collapse = " or ") else paste("any one of", join_and(nm[bs]))))
  paste(out, collapse = " ")
}

## The parts of the model with a test of their own: each predictor outside
## a group (its t test) and each group as a whole (its F test); the lower
## terms of a group have no meaning alone.
reg_units <- function(r) {
  gs <- reg_groups(r)
  singles <- setdiff(seq_len(r$k), unlist(gs))
  u <- c(lapply(singles, function(j) list(first = j, name = r$predictors[j], p = r$coefficients$p[j + 1])),
         lapply(gs, function(g) list(first = g[1], name = reg_group_name(r, g),
                                     p = if (length(g) == r$k) r$model$p else reg_partial(r, g)$p)))
  u[order(vapply(u, function(x) x$first, 1L))]
}


## "rises by 0.452", "falls by 1.20", or "changes by 0.000", from the
## estimate as printed
reg_move <- function(r, i) {
  s <- reg_coef_txt(r, i)
  if (as.numeric(s) > 0) paste("rises by", s) else if (as.numeric(s) < 0) paste("falls by", sub("^-", "", s))
  else paste("changes by", s)
}

## One slope in a sentence: its size and direction, its interval and its test.
reg_slope_text <- function(r, j) {
  i <- j + 1; cf <- r$coefficients; alpha <- r$alpha; lvl <- paste0(pct(alpha), "%")
  multi <- r$k >= 2
  base <- sprintf("For each unit more of %s, the predicted %s %s%s", r$predictors[j], r$response, reg_move(r, i),
                  if (multi) " when the other predictors are held at the same values" else "")
  if (r$exact) return(paste0(base, "."))
  test <- if (cf$p[i] < alpha)
    sprintf("; the slope is significant at the %s level (%s), with a %s%% confidence interval of %s to %s.", lvl,
            reg_p(cf$p[i], alpha), pct(1 - alpha), reg_coef_txt(r, i, "CI_lower"), reg_coef_txt(r, i, "CI_upper"))
  else sprintf("; there is insufficient evidence at the %s level that the slope differs from 0 (%s)%s.", lvl,
               reg_p(cf$p[i], alpha), if (multi) " once the other predictors are allowed for" else "")
  paste0(base, test)
}

## The reading of the whole model, sentence by sentence, each one checkable
## against the tables above it.
reg_text <- function(r) {
  m <- r$model; alpha <- r$alpha; lvl <- paste0(pct(alpha), "%"); multi <- r$k >= 2
  cf <- r$coefficients; nm <- r$predictors
  groups <- reg_groups(r); gcols <- unlist(groups); bases <- reg_bases(r)
  ## the whole model one curve or one surface
  one <- length(groups) == 1 && length(groups[[1]]) == r$k
  form <- if (one && length(bases) > 1) "surface" else "curve"
  out <- sprintf("The fitted equation is %s, from %d %s.", r$equation, r$n, pl(r$n, "row", "rows"))
  if (r$exact) {
    out <- c(out, paste("The equation passes through every point exactly, so there is no scatter left to judge it",
                        "against: R\u00b2 is 1, and the standard errors, tests and intervals are not available. An exact fit",
                        "usually means the response was worked out from the predictors, or there are hardly more rows than",
                        "coefficients."))
  } else {
    out <- c(out, sprintf("R\u00b2 is %s: %s for %s%% of the variation in %s about its mean%s.", fmt(m$R2, 3),
                          if (one) sprintf("the fitted %s accounts", form) else if (multi) "the predictors together account" else "the line accounts",
                          fmt(100 * m$R2, 1), r$response,
                          if (multi) sprintf(" (adjusted R\u00b2, which allows for the number of predictors, is %s%s)", dfmt(m$Adj_R2, 3),
                                             if (as.numeric(dfmt(m$Adj_R2, 3)) < 0)
                                               ", below 0: the predictors account for less of the variation than chance alone would give"
                                             else "") else ""))
    out <- c(out, if (m$p < alpha)
      sprintf("The regression is significant at the %s level (F = %s on %d and %d degrees of freedom, %s).", lvl,
              fmt(m$F, 2), m$df1, m$df2, reg_p(m$p, alpha))
      else if (one)
        sprintf("There is insufficient evidence at the %s level that %s is related to %s along the fitted %s (F = %s on %d and %d degrees of freedom, %s).",
                lvl, r$response, join_and(nm[bases]), form, fmt(m$F, 2), m$df1, m$df2, reg_p(m$p, alpha))
      else sprintf("There is insufficient evidence at the %s level of a %srelation between %s and %s (F = %s on %d and %d degrees of freedom, %s).",
                   lvl, if (!multi) "straight-line " else if (length(groups)) "" else "linear ", r$response,
                   if (multi) "the predictors taken together" else nm, fmt(m$F, 2), m$df1, m$df2, reg_p(m$p, alpha)))
    ## the F test and the slopes look only for straight lines
    cv <- r$checks[3, ]
    if (!is.na(cv$p) && cv$p < alpha)
      out <- c(out, if (length(groups))
        sprintf(paste("The check of the shape below is significant, though (%s): the data bend in a way the fitted",
                      "equation does not follow (such as a levelling off or an S-shape), so another shape may suit them better."),
                reg_p(cv$p, alpha))
        else sprintf(paste("The check for a curve below is significant, though (%s): the relation bends, which a",
                           "%s cannot show, so read the %s with care."),
                     reg_p(cv$p, alpha), if (multi) "linear equation" else "straight line", if (multi) "slopes" else "slope"))
  }
  ## an equation that needed many more figures than the standard errors to
  ## reproduce the fit: say why, and how to get one that is easier to read
  if (isTRUE(r$extra >= 2)) {
    far0 <- bases[vapply(bases, function(j) abs(mean(r$X[, j])) > 10 * stats::sd(r$X[, j]), logical(1))]
    far0 <- intersect(far0, unlist(groups))
    out <- c(out, paste0("The coefficients carry more figures than their standard errors need: the predictors are so alike",
      " that fewer figures would not reproduce the fitted values.",
      if (length(far0)) sprintf(paste(" Subtracting a starting value from %s (such as %s) before working out %s gives",
                                      "the same fit with coefficients that are easier to read."),
                                join_and(nm[far0]), join_and(vapply(far0, function(j) num_text(floor(min(r$X[, j]) / 10) * 10), "")),
                                pl(length(far0), "its powers", "their powers")) else ""))
  }
  ## each predictor outside a group in a sentence; each group read together
  out <- c(out, unlist(lapply(seq_len(r$k), function(j) {
    g <- reg_group(r, j)
    if (length(g) == 1) reg_slope_text(r, j) else if (j == g[1]) reg_group_text(r, g) else NULL
  })))
  ## A group's own columns are related by construction: their VIFs are no
  ## warning as far as the group explains them (up to twice the VIF among
  ## its own columns); beyond that the other predictors make its position
  ## imprecise.
  hv <- if (multi && !r$exact) which(is.finite(cf$VIF) & round(cf$VIF, 2) >= 5 | is.infinite(cf$VIF)) else integer(0)
  own <- rep(NA_real_, r$k + 1)
  for (g in groups) own[g + 1] <- tryCatch(diag(solve(stats::cor(r$X[, g]))), error = function(err) rep(Inf, length(g)))
  big <- which(is.finite(cf$VIF) & !is.na(own) & cf$VIF > 2 * own)
  raised <- intersect(hv, big)
  ## significant together, none alone; significant alone, not together. The
  ## parts are the predictors outside groups and the groups as a whole.
  units <- reg_units(r)
  if (length(units) >= 2 && !r$exact) {
    up <- vapply(units, function(u) u$p, 0); un <- vapply(units, function(u) u$name, "")
    if (m$p < alpha && all(up >= alpha)) {
      lead <- if (length(units) == 2) sprintf("neither %s nor %s is", un[1], un[2]) else sprintf("none of %s is", join_and(un))
      related <- any(round(cf$VIF[setdiff(seq_len(r$k), gcols) + 1], 2) >= 2, na.rm = TRUE) || length(intersect(big, gcols + 1)) > 0
      out <- c(out, paste0("The predictors are significant together, but ", lead, " significant on its own: ",
        if (related) "this can happen when the predictors are related to each other (see the VIF column), so that each one's share cannot be told apart."
        else "each falls short of significance by itself, while together they account for more of the variation than chance readily gives."))
    }
    if (m$p >= alpha && any(up < alpha)) {
      sg <- un[up < alpha]
      out <- c(out, sprintf(paste("%s %s significant on %s own although the model as a whole is not: with several predictors,",
                                  "one may reach significance by chance, which is what the overall F test guards against,",
                                  "so treat %s with care."),
                            cap1(join_and(sg)), pl(length(sg), "is", "are"), pl(length(sg), "its", "their"), pl(length(sg), "it", "them")))
    }
  }
  if (length(hv)) {
    for (g in groups) {
      ex <- setdiff(intersect(hv, g + 1), raised)
      if (length(ex))
        out <- c(out, sprintf("The large %s of %s %s from %s, and %s no warning about the %s.",
                              pl(length(ex), "VIF", "VIFs"), join_and(cf$Term[ex]), pl(length(ex), "comes", "come"),
                              reg_group_reason(r, g), pl(length(ex), "is", "are"),
                              if (length(intersect(g, bases)) > 1) "surface" else "curve"))
    }
    if (length(raised))
      out <- c(out, sprintf(paste("%s %s (%s) %s also raised by the other predictors, which are related to it, so the",
                                  "position of the curve is imprecise and can change markedly if a predictor is added or removed."),
                            if (length(raised) == 1) paste0(cf$Term[raised], "'s") else paste("The VIFs of", join_and(cf$Term[raised])),
                            if (length(raised) == 1) "VIF" else "", join_and(fmt(cf$VIF[raised], 2)), pl(length(raised), "is", "are")))
    hv <- setdiff(hv, gcols + 1)
    if (length(hv))
      out <- c(out, sprintf(paste("%s %s %s of 5 or more (%s): %s closely related to the other predictors, so %s",
                                  "imprecise and can change markedly if a predictor is added or removed."),
                            join_and(cf$Term[hv]), pl(length(hv), "has", "have"), pl(length(hv), "a VIF", "VIFs"),
                            join_and(ifelse(is.finite(cf$VIF[hv]), fmt(cf$VIF[hv], 2), "-")),
                            pl(length(hv), "it is", "they are"), pl(length(hv), "its slope is", "their slopes are")))
  }
  ## the intercept, and whether 0 lies inside the data, judged on the
  ## predictors themselves (a power or product is 0 when they are)
  outside <- bases[vapply(bases, function(j) min(r$X[, j]) > 0 || max(r$X[, j]) < 0, logical(1))]
  out <- c(out, sprintf("The intercept, %s, is the predicted %s when %s 0%s", reg_coef_txt(r, 1), r$response,
                        if (multi) "every predictor is" else paste(nm, "is"),
                        if (!length(outside)) "."
                        else sprintf(paste0("; but 0 lies outside the observed range of %s, so the intercept is an ",
                                            "extrapolation: it positions the %s rather than describing any row."),
                                     join_and(sprintf("%s (%s)", nm[outside], vapply(outside, function(j) reg_range(r, j), ""))),
                                     if (multi) "fitted equation" else "line")))
  out <- c(out, sprintf("The equation describes the data only over the observed %s (%s); beyond %s, %s is an assumption the data cannot check.",
                        pl(length(bases), "range", "ranges"),
                        join_and(sprintf("%s %s", nm[bases], vapply(bases, function(j) reg_range(r, j), ""))),
                        pl(length(bases), "it", "them"), if (multi) "the fitted relation" else "a straight-line relation"))
  left <- r$nrow - r$n
  if (left > 0) {
    out <- c(out, sprintf("%d of the %d rows %s left out because %s no usable value of %s.", left, r$nrow,
                          pl(left, "is", "are"), pl(left, "it has", "they have"),
                          if (multi) "the response or a predictor" else "one of the two variables"))
    if (r$held_rows > 0)
      out <- c(out, sprintf("Of these, %d %s an entry the data check has flagged (such as '%s') and will count once corrected on the Data tab.",
                            r$held_rows, pl(r$held_rows, "has", "have"), r$held_eg))
    if (r$inf_rows > 0)
      out <- c(out, sprintf("%s %d %s a value that is not a finite number (such as Inf, from a division by zero).",
                            if (r$held_rows > 0) "And" else "Of these,", r$inf_rows, pl(r$inf_rows, "holds", "hold")))
  }
  out <- c(out, sprintf(paste("A regression describes how %s goes with %s in these data; it can show a cause only when %s",
                              "set by the experimenter and assigned to the plots at random."),
                        r$response, join_and(nm[bases]),
                        pl(length(bases), "the predictor was", "the predictors were")))
  paste(out, collapse = " ")
}

## ------------------------------------------------------------- plots ----

## The line (or curve) for one predictor with the others at their means, its
## band at 1 - alpha, and each row's response adjusted to those means (the
## line's value plus the row's residual). Powers and products of the shown
## predictor move with it; those of the others are worked out from their
## means (75 for N gives N2 5625, a setting that can occur). With one
## predictor this is the ordinary fitted line and the observed points.
reg_effect <- function(r, j) {
  k <- r$k; mu <- colMeans(r$X)
  others <- setdiff(reg_bases(r), j)
  g <- seq(min(r$X[, j]), max(r$X[, j]), length.out = 101)
  Bg <- matrix(mu, length(g), k, byrow = TRUE); Bg[, j] <- g; Bg <- reg_design(r, Bg)
  Ba <- matrix(mu, r$n, k, byrow = TRUE); Ba[, j] <- r$X[, j]; Ba <- reg_design(r, Ba)
  pr <- reg_predict(r, Bg, TRUE)
  pts <- data.frame(x = r$X[, j], y = if (!length(others)) r$y else unname(reg_predict(r, Ba)) + unname(stats::residuals(r$fit)))
  list(band = data.frame(x = g, fit = pr[, 1], lwr = pr[, 2], upr = pr[, 3]), pts = pts,
       moving = c(reg_powers_of(r, j), reg_products_of(r, j)), others = others,
       held = reg_design(r, matrix(mu, 1, k))[1, ])
}

## The settings the other predictors are held at, as the note names them:
## "Rain 40.5", or "N 75 and Rain 40.5, so N2 5625". Each mean is printed to
## six figures and the powers and products worked out from the printed
## means, so the reader can check one against the other (Year 2010.5, so
## Year2 4042110).
reg_held_text <- function(r, ef) {
  zap <- reg_zap_means(r)
  shown <- vapply(zap, function(v) num_text(signif(v, 6)), "")
  hb <- setdiff(seq_len(r$k), c(reg_bases(r), ef$moving))
  hv <- reg_design(r, matrix(as.numeric(shown), 1, r$k))[1, hb]
  paste0(join_and(sprintf("%s %s", r$predictors[ef$others], shown[ef$others])),
         if (length(hb)) sprintf(", so %s", join_and(sprintf("%s %s", r$predictors[hb],
                                                              vapply(hv, function(v) num_text(signif(v, 7)), ""))))
         else "")
}

## the predictor shown in the main plot: the one asked for (a power or a
## product is shown through the predictor it is built from), else the first
reg_show <- function(r, show) {
  j <- if (!is.null(show) && show %in% r$predictors) match(show, r$predictors) else reg_bases(r)[1]
  reg_source(r, j)
}

plot_reg_main <- function(r, show = NULL) {
  j <- reg_show(r, show); ef <- reg_effect(r, j); adj <- length(ef$others) > 0
  xl <- r$predictors[j]
  pw <- reg_powers_of(r, j); pr <- reg_products_of(r, j); curve <- length(pw) > 0
  words <- vapply(pw, function(m) reg_power_word(reg_built_row(r, m)$p), "")
  what <- paste0(r$response, " against ", xl,
                 if (length(pw) && !length(pr)) sprintf(" (with %s, its %s)", join_and(r$predictors[pw]), join_and(words))
                 else if (length(c(pw, pr))) sprintf(" (with %s moving with it)", join_and(r$predictors[c(pw, pr)])) else "",
                 if (adj) ", other predictors at their means" else "")
  words <- reg_equation_terms(r)
  if (!r$exact) {
    words[length(words)] <- paste0(words[length(words)], ";")
    words <- c(words, paste("R\u00b2 =", fmt(r$model$R2, 3)))
  }
  sub <- wrap_words(words, 70)
  ggplot() +
    (if (!r$exact) geom_ribbon(data = ef$band, aes(x = .data$x, ymin = .data$lwr, ymax = .data$upr), fill = "#BBD3F2", alpha = 0.7)) +
    geom_point(data = ef$pts, aes(x = .data$x, y = .data$y), colour = "#3B7DD8", size = 2.4, alpha = 0.85) +
    geom_line(data = ef$band, aes(x = .data$x, y = .data$fit), colour = "#173F7D", linewidth = 1) +
    ## titles and caption wrapped, so a long name or equation is not cut off
    ## in a narrow panel
    labs(title = paste(strwrap(what, 50), collapse = "\n"),
         subtitle = sub, x = xl, y = if (adj) paste(r$response, "(adjusted)") else r$response,
         caption = if (!r$exact) paste(strwrap(sprintf("Shaded band: %s%% confidence interval for the average %s along the %s.",
                                         pct(1 - r$alpha), r$response, if (curve) "curve" else "line"), 60), collapse = "\n")) +
    theme_doe()
}

## Words joined into lines of at most `width` characters, each kept whole, so
## "R2 = 0.979" never breaks across lines.
wrap_words <- function(words, width) {
  lines <- character(0); cur <- ""
  for (w in words) {
    if (nzchar(cur) && nchar(cur) + 1 + nchar(w) > width) { lines <- c(lines, cur); cur <- w }
    else cur <- if (nzchar(cur)) paste(cur, w) else w
  }
  paste(c(lines, cur), collapse = "\n")
}

## standardised residuals: each residual over its own standard error; a row
## that fixes the fit on its own (leverage 1) has none
reg_std <- function(r) {
  s <- suppressWarnings(stats::rstandard(r$fit))
  s[!is.finite(s)] <- NA_real_
  s
}

## rows whose standardised residual lies beyond -3 or 3, with room for
## rounding: one at exactly 3 is not beyond it
reg_far <- function(s) which(!is.na(s) & abs(s) > 3 + 1e-8)

plot_reg_resid <- function(r) {
  if (r$exact) return(NULL)
  df <- data.frame(fit = stats::fitted(r$fit), std = reg_std(r), row = r$rows)
  df <- df[!is.na(df$std), , drop = FALSE]
  far <- df[reg_far(df$std), , drop = FALSE]
  ggplot(df, aes(x = .data$fit, y = .data$std)) +
    geom_hline(yintercept = 0, linetype = 2) +
    geom_hline(yintercept = c(-3, 3), linetype = 3, colour = "grey45") +
    geom_point(colour = "#3B7DD8", size = 2.2) +
    (if (nrow(far)) geom_text(data = far, aes(label = paste("row", .data$row), vjust = ifelse(.data$std > 0, -0.8, 1.8)),
                              size = 3.4, colour = "#C0392B")) +
    ## room above and below for the row labels
    scale_y_continuous(expand = expansion(mult = 0.12)) +
    labs(title = "Residuals against fitted values", x = paste("Fitted", r$response),
         y = "Standardised residual") +
    theme_doe()
}

plot_reg_qq <- function(r) {
  if (r$exact) return(NULL)
  df <- data.frame(std = reg_std(r)); df <- df[!is.na(df$std), , drop = FALSE]
  if (nrow(df) < 3) return(NULL)
  ggplot(df, aes(sample = .data$std)) + stat_qq(colour = "#3B7DD8") + stat_qq_line(colour = "#C0392B") +
    labs(title = "Normal Q-Q plot of the residuals", x = "Where the residuals would be if they were normal",
         y = "Standardised residual") +
    theme_doe()
}

plot_reg_obs <- function(r) {
  df <- data.frame(pred = stats::fitted(r$fit), obs = r$y)
  lim <- range(c(df$pred, df$obs))
  ggplot(df, aes(x = .data$pred, y = .data$obs)) +
    geom_abline(intercept = 0, slope = 1, linetype = 2, colour = "grey35") +
    geom_point(colour = "#3B7DD8", size = 2.2) +
    coord_cartesian(xlim = lim, ylim = lim) +
    labs(title = "Observed against predicted", x = paste("Predicted", r$response), y = paste("Observed", r$response),
         subtitle = if (r$exact) "Every point on the line" else sprintf("R\u00b2 = %s;  RMSE = %s", fmt(r$model$R2, 3), sig_fmt(r$model$RMSE)),
         caption = "Dashed line: observed = predicted.") +
    theme_doe()
}

## ------------------------------------------------------- plot notes ----

## rows that sit exactly on another row's point, hidden under it
reg_hidden <- function(x, y) {
  dup <- sum(duplicated(data.frame(x, y)))
  if (dup) sprintf(" %d %s exactly on another row's point and %s hidden under it.", dup,
                   pl(dup, "row sits", "rows sit"), pl(dup, "is", "are")) else ""
}

reg_main_text <- function(r, show = NULL) {
  j <- reg_show(r, show); ef <- reg_effect(r, j); adj <- length(ef$others) > 0
  nm <- r$predictors; cf <- r$coefficients; lvl <- paste0(pct(r$alpha), "%")
  pw <- reg_powers_of(r, j); pr <- reg_products_of(r, j)
  curve <- length(pw) > 0; shape <- if (curve) "curve" else "line"
  quad <- !is.na(reg_quad_of(r, j))
  band <- sprintf("the %s%% confidence interval for the average %s", pct(1 - r$alpha), r$response)
  ## "with Dose2 moving with it as its square", "with N2 moving with it as
  ## its square and NP as N x P"
  mv <- c(pw, pr)
  roles <- c(vapply(pw, function(m) paste("its", reg_power_word(reg_built_row(r, m)$p)), ""),
             vapply(pr, function(m) { w <- reg_built_row(r, m); sprintf("%s \u00d7 %s", nm[w$a], nm[w$b]) }, ""))
  moving <- if (!length(mv)) ""
            else sprintf(", with %s moving with it as %s%s,", nm[mv[1]], roles[1],
                         if (length(mv) > 1) paste0(" and ", join_and(sprintf("%s as %s", nm[mv[-1]], roles[-1]))) else "")
  what <- if (!adj)
    paste0(sprintf("Each point is a row. The %s is the fitted equation%s", shape, sub(",$", "", moving)),
           if (r$exact) "."
           else sprintf(paste(", and the shaded band is %s at each value of %s: it shows where the true %s could lie,",
                              "not where single rows will fall."), band, nm[j], shape))
  else sprintf(paste("The %s shows how the predicted %s changes with %s%s when the other predictors are held at their",
                     "means (%s). Each point is a row's %s adjusted to those means: the %s's value at that row's %s",
                     "plus the row's residual, so the points scatter about the %s exactly as the residuals do about",
                     "the full equation.%s"),
               shape, r$response, nm[j], moving, reg_held_text(r, ef), r$response, shape, nm[j], shape,
               if (r$exact) "" else sprintf(" The shaded band is %s along the %s.", band, shape))
  hidden <- reg_hidden(ef$pts$x, signif(ef$pts$y, 12))
  few <- if (r$n < 10 && !r$exact) sprintf(" With only %d rows, a single point can move the %s a great deal.", r$n, shape) else ""
  ## the tests of the products the shown predictor enters
  inter <- if (r$exact) "" else paste(vapply(pr, function(m) {
    w <- reg_built_row(r, m)
    if (cf$p[m + 1] < r$alpha)
      sprintf(" The coefficient of %s, which measures how the effect of %s changes with %s, is significant at the %s level (%s).",
              nm[m], nm[w$a], nm[w$b], lvl, reg_p(cf$p[m + 1], r$alpha))
    else sprintf(" There is insufficient evidence at the %s level that the effect of %s changes with %s (the coefficient of %s, %s).",
                 lvl, nm[w$a], nm[w$b], nm[m], reg_p(cf$p[m + 1], r$alpha))
  }, ""), collapse = "")
  if (curve) {
    top <- pw[length(pw)]
    reading <- paste0(
      if (quad) reg_turn_text(r, j, ef$held)
      else sprintf("The curve is the fitted polynomial of degree %d in %s%s.", reg_built_row(r, top)$p, nm[j],
                   if (length(pr)) ", drawn with the other predictors at their means" else ""),
      if (r$exact) "" else if (cf$p[top + 1] < r$alpha)
        sprintf(" The coefficient of %s, %s, is significant at the %s level (%s).", nm[top],
                if (quad) "which measures the bend" else "the highest power", lvl, reg_p(cf$p[top + 1], r$alpha))
      else sprintf(" There is insufficient evidence at the %s level that %s (the coefficient of %s, %s).", lvl,
                   if (quad) "the relation bends" else "the highest power is needed", nm[top], reg_p(cf$p[top + 1], r$alpha)),
      inter, hidden, few,
      if (r$exact) "" else " If the points stray from the curve in a pattern, or one point sits far from the rest at either end, the curve can mislead.")
    return(list(what = what, reading = reading))
  }
  i <- j + 1
  reading <- if (length(pr)) {
    ## the slope at the other predictors' means, through the products
    s_eff <- cf$Estimate[i]; oth <- integer(0)
    for (m in pr) {
      w <- reg_built_row(r, m); o <- if (w$a == j) w$b else w$a
      s_eff <- s_eff + cf$Estimate[m + 1] * ef$held[o]; oth <- c(oth, o)
    }
    paste0(sprintf("With the other predictors at their means, the slope is %s (%s per unit of %s); it changes with %s (through %s).",
                   dfmt(s_eff, r$dec[i]), r$response, nm[j], join_and(nm[unique(oth)]), join_and(nm[pr])), inter)
  } else {
    slope <- sprintf("The slope is %s (%s per unit of %s)", reg_coef_txt(r, i), r$response, nm[j])
    if (r$exact) paste0(slope, "; the line passes through every point.")
    else paste0(slope, if (cf$p[i] < r$alpha) sprintf(", significant at the %s level (%s).", lvl, reg_p(cf$p[i], r$alpha))
                else sprintf(", with insufficient evidence at the %s level that it differs from 0 (%s).", lvl, reg_p(cf$p[i], r$alpha)))
  }
  reading <- paste0(reading, hidden, few)
  if (!r$exact) {
    cv <- reg_curve(r, j)
    reading <- paste(reading,
      "If the points bend along a curve about the line, or one point sits far from the rest at either end, the straight line can mislead.",
      if (is.na(cv$p)) sprintf("A curve in %s cannot be tested: %s.", nm[j], cv$why)
      else if (cv$p < r$alpha)
        sprintf("Adding the square of %s to the model fits significantly better at the %s level (%s): the relation bends, so a curve may suit the data better.",
                nm[j], lvl, reg_p(cv$p, r$alpha))
      else sprintf("There is insufficient evidence at the %s level that adding the square of %s fits better than the straight line (%s).",
                   lvl, nm[j], reg_p(cv$p, r$alpha)))
  }
  list(what = what, reading = reading)
}

## the predictors' means for the main plot's note, with a mean that is only
## rounding residue (a centred column) shown as 0
reg_zap_means <- function(r) {
  mu <- colMeans(r$X)
  mu[abs(mu) <= 1e-9 * apply(abs(r$X), 2, max)] <- 0
  mu
}

## the verdict of one check as a sentence: `yes` and `no` hold "{p}" where
## the p-value goes
reg_check_name <- function(r, which)
  switch(which, "Normal residuals" = "Shapiro-Wilk", "Constant spread" = "Breusch-Pagan",
         "Straight line" = if (r$k == 1) "curve" else "RESET")
reg_check_clause <- function(r, which, yes, no) {
  ck <- r$checks[r$checks$Check == which, ]
  if (is.na(ck$p))
    return(sprintf("The %s test is not available: %s.", reg_check_name(r, which), sub("^not available: ", "", ck$Verdict)))
  sub("{p}", reg_p(ck$p, r$alpha), if (ck$p < r$alpha) yes else no, fixed = TRUE)
}

reg_resid_text <- function(r) {
  built <- NROW(r$built) > 0
  what <- paste("Each point is a row: its fitted value across, and its residual (observed minus fitted) divided by",
                sprintf("the residual's standard error up the plot. If %s suits the data, the points form an even",
                        if (built) "the fitted equation" else "a straight line"),
                "band about the dashed line at 0, with no curve and no funnel. The dotted lines mark -3 and 3.")
  if (r$exact) return(list(what = "", reading = "The model fits every value exactly, so every residual is 0 and there is nothing to plot."))
  lvl <- paste0(pct(r$alpha), "%")
  s <- reg_std(r)
  far <- reg_far(s)
  nolev <- sum(is.na(s))
  with_what <- if (r$k == 1) r$predictors else "the predictors"
  dfr <- r$fit$df.residual
  fv <- stats::fitted(r$fit)
  ## a flat fit stands every point in one column of this plot, so a bend or a
  ## widening shows only in the main plot
  flat <- stats::sd(fv) <= 1e-9 * stats::sd(r$y)
  look_bend <- if (flat) "look for the bend in the main plot, since every fitted value here is the same"
               else "look for the points to bend in a U or an arch"
  look_wide <- if (flat) "look for the band of points to widen along the main plot, since every fitted value here is the same"
               else if (r$k == 1) "look for the band of points to widen towards one side"
               else if (built && length(reg_bases(r)) == 1)
                 "look for the band of points to widen along the main plot, where they scatter about the curve by the residuals"
               else if (built)
                 paste("the change need not show against the fitted values here, so choose each of",
                       join_and(r$predictors[reg_bases(r)]), "in turn on the main plot, where the points scatter about",
                       "the fitted line or curve by the residuals, and look for the band to widen along one")
               else paste("the change need not show against the fitted values here, so choose each predictor in turn on the main",
                          "plot, where the points scatter about the line by the residuals, and look for the band to widen along one")
  out <- c(
    if (r$k == 1) reg_check_clause(r, "Straight line",
      paste0("The check for a curve finds that adding the square of ", r$predictors, " fits significantly better than the straight line at the ",
             lvl, " level ({p}): ", look_bend, "; a curve may suit the data better."),
      paste0("The check for a curve finds insufficient evidence at the ", lvl, " level that adding the square of ",
             r$predictors, " fits better than the straight line ({p})."))
    else if (built) reg_check_clause(r, "Straight line",
      paste0("The RESET test finds a pattern along the fitted values that the fitted equation does not follow, significant at the ",
             lvl, " level ({p}): ", look_bend, "; another shape may suit the data better."),
      paste0("The RESET test finds insufficient evidence at the ", lvl,
             " level of a pattern along the fitted values that the fitted equation does not follow ({p})."))
    else reg_check_clause(r, "Straight line",
      paste0("The RESET test finds a curve along the fitted values that fits significantly better than the straight line at the ",
             lvl, " level ({p}): ", look_bend, "; a curve may suit the data better."),
      paste0("The RESET test finds insufficient evidence at the ", lvl, " level of a curve along the fitted values ({p}).")),
    reg_check_clause(r, "Constant spread",
      paste0("The Breusch-Pagan test finds that the spread of the residuals changes with ", with_what, ", significant at the ",
             lvl, " level ({p}): ", look_wide, ". The tests and intervals above are then less trustworthy, and a transformation such as a log often helps."),
      paste0("The Breusch-Pagan test finds insufficient evidence at the ", lvl, " level that the spread of the residuals changes with ",
             with_what, " ({p}).")),
    if (length(far)) paste0(sprintf("%s %s more than three standard errors from 0, which normal residuals seldom are; check %s for a recording error.",
                                    cap1(rows_text(r$rows[far])), pl(length(far), "lies", "lie"), pl(length(far), "it", "them")),
      ## among many rows a few go beyond 3 by chance alone
      if (r$n >= 100) sprintf(" Among %d rows, about %s would lie beyond 3 by chance even if every residual were normal.",
                              r$n, fmt(2 * stats::pnorm(-3) * r$n, 1)) else "")
    ## a standardised residual cannot exceed the square root of the residual
    ## degrees of freedom, so with nine or fewer the lines can flag nothing
    else if (dfr <= 9)
      sprintf(paste("With %d residual %s of freedom, no standardised residual can exceed 3, so the dotted lines cannot",
                    "pick out a stray point here; look instead for one point well apart from the rest."),
              dfr, pl(dfr, "degree", "degrees"))
    else "No point lies beyond -3 or 3.",
    if (nolev) sprintf("%s %s the fit on %s own (%s alone decides a coefficient), so %s no residual to plot.",
                       cap1(rows_text(r$rows[is.na(s)])), pl(nolev, "fixes", "fix"), pl(nolev, "its", "their"),
                       pl(nolev, "it", "each"), pl(nolev, "it has", "they have")))
  list(what = what, reading = paste(out, collapse = " "))
}

reg_qq_text <- function(r) {
  what <- paste("Each point is a residual, placed against where it would fall if the residuals followed a normal",
                "distribution. Points close to the straight line mean the residuals look normal, as the t tests and",
                "intervals assume.")
  if (r$exact) return(list(what = "", reading = "The model fits every value exactly, so there are no residuals to plot."))
  s <- reg_std(r); s <- s[!is.na(s)]
  e <- stats::residuals(r$fit)
  pattern <- if (r$fit$df.residual < 2) "one"
             else if (length(s) < 5) NA
             else if (diff(stats::quantile(s, c(0.25, 0.75), names = FALSE)) == 0) "heaped"
             else if (qq_coarse(e)) "coarse" else qq_pattern(s)
  plot_read <- if (identical(pattern, "one"))
      paste("With one residual degree of freedom every standardised residual is +1 or -1, so the plot cannot show",
            "the shape of the scatter.")
    else if (is.na(pattern)) "There are too few points to judge."
    else if (pattern == "heaped") "At least half the residuals are the same value, so many points sit in one flat run."
    else if (pattern == "coarse") paste("The residuals sit on a coarse grid, as happens when the response is recorded in large steps,",
                                        "so the points form flat runs and the ends of this plot cannot be read reliably.")
    else qq_reading(s)
  plot_read <- gsub("values", "residuals", plot_read, fixed = TRUE)
  ## whether the plot's ends were read at all
  read <- !is.na(pattern) && !pattern %in% c("heaped", "coarse", "one")
  ## A residual the residual plot flags sits far out at one end of this plot;
  ## the reading of the ends averages the outer tenth, which one point moves
  ## little, so the point is named rather than left to contradict it.
  sall <- reg_std(r); far <- reg_far(sall)
  if (read && length(far)) {
    up <- sall[far] > 0
    at_end <- if (all(up)) "far above the line at the top end" else if (!any(up)) "far below the line at the bottom end"
              else "far from the line at the two ends"
    lead <- sprintf("%s %s %s, as the residual plot flags.", cap1(rows_text(r$rows[far])), pl(length(far), "sits", "sit"), at_end)
    plot_read <- if (identical(pattern, "ok ok"))
      paste(lead, sprintf("Apart from %s, %s", pl(length(far), "it", "them"),
                          sub("^Neither", "neither", plot_read)))
    else paste(lead, plot_read)
  }
  lvl <- paste0(pct(r$alpha), "%")
  test <- reg_check_clause(r, "Normal residuals",
    paste0("The Shapiro-Wilk test finds a significant departure from normal at the ", lvl, " level ({p})."),
    paste0("The Shapiro-Wilk test finds insufficient evidence at the ", lvl, " level that the residuals are not normal ({p})."))
  ck <- r$checks[1, ]
  ## the plot's ends and the test can disagree; say why rather than leave both
  calm <- identical(pattern, "ok ok")
  clash <- !is.na(ck$p) && read && ((ck$p < r$alpha && calm) || (ck$p >= r$alpha && !calm))
  out <- c(plot_read, test,
           if (clash) {
             if (length(far)) sprintf(paste("The two need not agree: the test weighs every point, %s among them, while the reading",
                                            "of the plot looks at how far the outer tenth of the points at each end bends on average,",
                                            "which one point moves little."), rows_text(r$rows[far]))
             else paste("The two need not agree: the test weighs every point, while the reading of the plot looks at the outer",
                        "tenth of the points at each end.")
           },
           if (read && length(s) < 20) sprintf("With only %d residuals, a Q-Q plot can show only a large departure from normal.", length(s)),
           if (r$fit$df.residual >= 30 && max(stats::hatvalues(r$fit)) <= 0.2)
             "With this many rows, the tests and intervals for the coefficients are little affected by a moderate departure.")
  list(what = what, reading = paste(out, collapse = " "))
}

reg_obs_text <- function(r) {
  what <- paste("Each point is a row: its predicted value across and its observed value up. Points on the dashed line",
                "are predicted exactly; the closer the points lie to it, the better the fit.")
  if (r$exact) return(list(what = what, reading = "Every point lies on the line: the model fits every value exactly."))
  if (stats::sd(stats::fitted(r$fit)) <= 1e-9 * stats::sd(r$y))
    return(list(what = what, reading = sprintf(paste("Every predicted value is the same (the fitted equation is flat), so the",
      "points stand in one column: the equation accounts for none of the variation in %s (R\u00b2 %s)."), r$response, fmt(r$model$R2, 3))))
  reading <- sprintf(paste("R\u00b2 (%s) is the square of the correlation between the observed and the predicted values.",
                           "The points lie on average %s from the line, vertically (MAE); RMSE (%s) estimates the",
                           "standard deviation of the scatter about the true equation.%s"),
                     fmt(r$model$R2, 3), sig_fmt(r$model$MAE), sig_fmt(r$model$RMSE),
                     reg_hidden(signif(stats::fitted(r$fit), 12), r$y))
  list(what = what, reading = reading)
}

## ---------------------------------------------------------- pca.R ----
###############################################################################
##  PRINCIPAL COMPONENT ANALYSIS
###############################################################################
## Principal components of the chosen numeric columns, from the rows that
## have every value: the eigenvalues with the share of the variation each
## component carries, the loadings (each variable's correlation with each
## component), the scores, and the scree, score, loading and biplot plots.
## As on the other Explore tabs, every sentence is one the tables or plots on
## screen bear out: loadings are judged on their values as printed, the
## number of components worth keeping comes from stated rules (Kaiser's and
## Horn's parallel analysis), and nothing is said about what a component
## "means" beyond which variables rise and fall with it.

## random data sets for Horn's parallel analysis: fewer when each set is
## large (whose eigenvalues vary little from set to set), so the analysis
## stays quick in the browser
PCA_PA_B <- 1000
PCA_PA_MIN <- 100
PCA_PA_CELLS <- 1e8
## a loading of this size or more, as printed, counts as strong
PCA_STRONG <- 0.5

#' Principal component analysis of numeric variables
#'
#' Principal components of the chosen columns, from the rows with a value of
#' every one (\code{\link[stats]{prcomp}}). By default each variable is
#' standardised first, so the analysis works on their correlations and no
#' variable dominates through its units; with \code{scale = FALSE} it works
#' on their covariances, which suits variables measured in the same units.
#' Text entries are read as the data check reads them: an entry that is not
#' plainly a number counts as missing; see \code{\link{check_data}}.
#'
#' Each component's sign is arbitrary (reversing it changes nothing); here it
#' is chosen so that the variable with the largest loading on it loads
#' positively. The loadings are the correlations between each variable and
#' each component. Components are kept by Horn's parallel analysis: those,
#' from the first, whose eigenvalue exceeds the 95th percentile of the
#' eigenvalues of random normal data of the same size (with the same variances
#' for a covariance analysis), simulated with a fixed seed. Kaiser's rule
#' (an eigenvalue above the average, which is 1 for correlations) is shown
#' beside it.
#'
#' @param d A data frame.
#' @param vars The names of two or more numeric columns.
#' @param scale \code{TRUE} (the default) to standardise each variable,
#'   \code{FALSE} to analyse them as measured.
#'
#' @return A list of class \code{doepro_pca}: \code{eigen} (a data frame:
#'   \code{Component}, \code{Eigenvalue}, \code{Proportion},
#'   \code{Cumulative}, \code{PA_threshold}), \code{loadings} (variables by
#'   components, correlations), \code{vectors} (the eigenvectors),
#'   \code{scores} (rows by components), \code{rows} (the rows used),
#'   \code{kaiser} and \code{retained} (the number of components each rule
#'   keeps), and the settings.
#'
#' @examples
#' set.seed(1)
#' d <- data.frame(Height = rnorm(30, 100, 10))
#' d$Tillers <- 0.1 * d$Height + rnorm(30)
#' d$Yield <- 0.3 * d$Height + 0.5 * d$Tillers + rnorm(30, 0, 3)
#' d$Protein <- rnorm(30, 12, 1)
#' p <- pca_data(d, c("Height", "Tillers", "Yield", "Protein"))
#' p$eigen
#' round(p$loadings, 2)
#'
#' @export
pca_data <- function(d, vars, scale = TRUE) {
  vars <- unique(vars[!is.na(vars) & nzchar(vars)])
  if (length(vars) < 2) stop("Choose at least two variables for a principal component analysis.")
  gone <- setdiff(vars, names(d))
  if (length(gone))
    stop(sprintf("%s %s of the data.", join_and(sprintf("'%s'", gone)), pl(length(gone), "is not a column", "are not columns")))
  p <- length(vars)
  vals <- lapply(stats::setNames(vars, vars), function(v) response_values(d[[v]]))
  held <- lapply(stats::setNames(vars, vars), function(v) held_flags(d[[v]]))
  ok <- Reduce(`&`, lapply(vals, is.finite))
  would <- Reduce(`&`, Map(function(v, h) is.finite(v) | h, vals, held))
  held_rows <- which(would & !ok)
  held_eg <- if (length(held_rows)) {
    i <- held_rows[1]; v <- vars[vapply(held, function(h) h[i], logical(1))][1]
    trimws(as.character(d[[v]][i]))
  } else ""
  n <- sum(ok)
  if (n < 3)
    stop(sprintf("Only %d %s a value of every variable chosen; principal components need at least 3.%s",
                 n, pl(n, "row has", "rows have"),
                 if (length(held_rows)) sprintf(" %d more %s an entry the data check has flagged (such as '%s'), which will count once corrected on the Data tab.",
                                                length(held_rows), pl(length(held_rows), "row has", "rows have"), held_eg) else ""))
  X <- do.call(cbind, lapply(vals, function(v) v[ok]))
  colnames(X) <- vars
  flat <- vars[apply(X, 2, function(z) length(unique(z)) < 2)]
  if (length(flat))
    stop(sprintf("%s %s the same value in every row used, so %s nothing to the components; leave %s out.",
                 join_and(sprintf("'%s'", flat)), pl(length(flat), "has", "each have"),
                 pl(length(flat), "it adds", "they add"), pl(length(flat), "it", "them")))

  pc <- stats::prcomp(X, center = TRUE, scale. = scale)
  ev <- pc$sdev^2
  ## components with no variance (more variables than rows, or a variable
  ## that is an exact combination of others) are left out
  m <- sum(ev > 1e-10 * sum(ev))
  ev_all <- ev
  V <- pc$rotation[, seq_len(m), drop = FALSE]
  S <- pc$x[, seq_len(m), drop = FALSE]
  sdv <- apply(X, 2, stats::sd)
  L <- sweep(V, 2, sqrt(ev[seq_len(m)]), "*")
  if (!scale) L <- sweep(L, 1, sdv, "/")
  ## each component's sign chosen so its largest loading is positive
  for (k in seq_len(m)) {
    if (L[which.max(abs(round(L[, k], 10))), k] < 0) { V[, k] <- -V[, k]; S[, k] <- -S[, k]; L[, k] <- -L[, k] }
  }
  comp <- paste0("PC", seq_len(m))
  colnames(V) <- colnames(S) <- colnames(L) <- comp
  rownames(V) <- rownames(L) <- vars

  ## Horn's parallel analysis: eigenvalues of random normal data of the same
  ## size (with the same variances for a covariance analysis), 95th
  ## percentile at each position
  B <- as.integer(max(PCA_PA_MIN, min(PCA_PA_B, floor(PCA_PA_CELLS / (n * p^2)))))
  pa <- with_fixed_seed(COR_PERM_SEED + 11, {
    sims <- vapply(seq_len(B), function(b) {
      Z <- matrix(stats::rnorm(n * p), n)
      if (!scale) Z <- sweep(Z, 2, sdv, "*")
      eigen(if (scale) stats::cor(Z) else stats::cov(Z), symmetric = TRUE, only.values = TRUE)$values
    }, numeric(p))
    apply(matrix(sims, nrow = p), 1, stats::quantile, probs = 0.95, names = FALSE)
  })
  above <- ev[seq_len(m)] > pa[seq_len(m)]
  retained <- if (all(above)) m else which(!above)[1] - 1L
  avg <- sum(ev_all) / p
  kaiser <- sum(ev[seq_len(m)] > avg)

  eig <- data.frame(Component = comp, Eigenvalue = ev[seq_len(m)], Proportion = ev[seq_len(m)] / sum(ev_all),
                    Cumulative = cumsum(ev[seq_len(m)]) / sum(ev_all), PA_threshold = pa[seq_len(m)],
                    stringsAsFactors = FALSE)
  inf_rows <- sum(!ok & Reduce(`|`, lapply(vals, is.infinite)))
  structure(list(vars = vars, scale = scale, n = n, p = p, m = m, X = X, eigen = eig, loadings = L, vectors = V,
                 scores = S, sdev = sqrt(ev[seq_len(m)]), average = avg, kaiser = kaiser, retained = retained,
                 pa_sets = B, rows = row_ids(d)[ok], pos = which(ok), nrow = nrow(d), held_rows = length(held_rows), held_eg = held_eg,
                 inf_rows = inf_rows, zero = p - m),
            class = "doepro_pca")
}

#' @rdname pca_data
#' @param x A result of \code{pca_data()}.
#' @param ... Not used.
#' @export
print.doepro_pca <- function(x, ...) {
  print(x$eigen, row.names = FALSE)
  cat("\nLoadings (correlations with the components):\n")
  print(round(x$loadings, 3))
  invisible(x)
}

## ------------------------------------------------------------ tables ----

## how many components the tables and readings go through: those kept, and
## at least the first two
pca_shown <- function(p) min(p$m, max(2L, p$retained))

pca_eigen_html <- function(p) {
  e <- p$eigen
  body <- lapply(seq_len(nrow(e)), function(i) c(
    e$Component[i], fmt(e$Eigenvalue[i], 3), fmt(100 * e$Proportion[i], 1), fmt(100 * e$Cumulative[i], 1),
    fmt(e$PA_threshold[i], 3),
    if (i <= p$retained) "kept" else ""))
  notes <- c(
    sprintf(paste("Eigenvalue: the variance carried by the component%s; the eigenvalues add up to %s, the total",
                  "variance of %s."), if (p$scale) " (each variable standardised, so each counts 1)" else "",
            fmt(sum(e$Eigenvalue) + 0, 3), if (p$scale) "the standardised variables" else "the variables as measured"),
    sprintf(paste("Parallel analysis: the 95th percentile of the same eigenvalue in %s sets of random normal data of",
                  "this size%s; a component is kept while its eigenvalue is larger."),
            formatC(p$pa_sets, format = "d", big.mark = ","), if (p$scale) "" else " with the same variances"),
    if (p$zero) sprintf("%d more %s an eigenvalue of 0 and %s left out: %s.", p$zero, pl(p$zero, "component has", "components have"),
                        pl(p$zero, "is", "are"),
                        if (p$n <= p$p) "there are no more rows than variables" else "some variable can be worked out exactly from the others"))
  foot <- sprintf("<tr><td colspan='6' class='cdrow'>%s</td></tr>", esc(paste(notes, collapse = " ")))
  raw_table(c("Component", "Eigenvalue", "% of variance", "Cumulative %", "Parallel analysis", ""), body, foot = foot,
            caption = "Eigenvalues")
}

pca_loadings_html <- function(p) {
  k <- pca_shown(p); L <- p$loadings[, seq_len(k), drop = FALSE]
  body <- lapply(seq_len(nrow(L)), function(i) c(esc(rownames(L)[i]), vapply(seq_len(k), function(j) {
    s <- dfmt(L[i, j], 2)
    if (abs(as.numeric(s)) >= PCA_STRONG) paste0("<b>", s, "</b>") else s
  }, ""), fmt(sum(L[i, ]^2), 2)))
  notes <- c(sprintf(paste("Each loading is the correlation between the variable and the component. In bold: %s or more",
                           "either way, taken here as strong."), dfmt(PCA_STRONG, 2)),
             sprintf("Communality: the share of each variable's variance that %s carry together.",
                     if (k == 2) "these two components" else sprintf("these %d components", k)),
             "A component's sign is arbitrary: reversing every loading and score of a component changes nothing.")
  foot <- sprintf("<tr><td colspan='%d' class='cdrow'>%s</td></tr>", k + 2, esc(paste(notes, collapse = " ")))
  raw_table(c("Variable", colnames(L), "Communality"), body, foot = foot, caption = "Loadings")
}

pca_scores_html <- function(p, show = 10) {
  k <- pca_shown(p); S <- p$scores[, seq_len(k), drop = FALSE]
  i <- seq_len(min(show, nrow(S)))
  body <- lapply(i, function(r) c(as.character(p$rows[r]), vapply(seq_len(k), function(j) dfmt(S[r, j], 2), "")))
  foot <- sprintf("<tr><td colspan='%d' class='cdrow'>%s</td></tr>", k + 1,
                  esc(paste0("A row's score is its position along the component: 0 is the average row.",
                             if (nrow(S) > show) sprintf(" The first %d of %d rows; the CSV holds them all.", show, nrow(S)) else "")))
  raw_table(c("Row", colnames(S)), body, foot = foot, caption = "Scores")
}

## ------------------------------------------------------------ readings ----

## the strong loadings of a component, judged on their printed values,
## largest first
pca_strong <- function(p, k) {
  l <- p$loadings[, k]; pr <- as.numeric(dfmt(l, 2))
  i <- which(abs(pr) >= PCA_STRONG)
  i[order(-abs(pr[i]))]
}

## one component in a sentence: what share it carries and which variables
## rise and fall with it
pca_component_text <- function(p, k) {
  nm <- p$vars; l <- p$loadings[, k]
  i <- pca_strong(p, k)
  head_ <- sprintf("PC%d (%s%% of the variation)", k, fmt(100 * p$eigen$Proportion[k], 1))
  if (!length(i))
    return(sprintf("%s: no variable is strongly related to it (every loading lies between %s and %s).", head_,
                   dfmt(-PCA_STRONG, 2), dfmt(PCA_STRONG, 2)))
  pos <- i[l[i] > 0]; neg <- i[l[i] < 0]
  part <- function(j, word) sprintf("%s %s (%s %s)", word, join_and(nm[j]), pl(length(j), "loading", "loadings"),
                                    join_and(dfmt(l[j], 2)))
  paste0(if (length(pos) && length(neg))
           sprintf("%s: rows with high scores have %s and %s; it contrasts %s with %s.", head_, part(pos, "high"), part(neg, "low"),
                   join_and(nm[pos]), join_and(nm[neg]))
         else sprintf("%s: rows with high scores have %s.", head_, part(if (length(pos)) pos else neg, if (length(pos)) "high" else "low")),
         if (k > p$retained) " Parallel analysis does not keep this component, so the pattern may be no more than chance." else "")
}

## The reading of the analysis as a whole.
pca_text <- function(p) {
  e <- p$eigen; k2 <- min(2, p$m)
  out <- sprintf("The analysis uses %d %s and %d variables, %s.", p$n, pl(p$n, "row", "rows"), p$p,
                 if (p$scale) "each standardised, so they count equally whatever their units"
                 else "as measured, so a variable with a larger variance counts for more")
  out <- c(out, sprintf("The first component carries %s%% of the variation%s.", fmt(100 * e$Proportion[1], 1),
                        if (p$m >= 2) sprintf(", and the first two together %s%%", fmt(100 * e$Cumulative[2], 1)) else ""))
  avg <- if (p$scale) "1" else sprintf("%s, the average", fmt(p$average, 3))
  out <- c(out, if (p$retained == 0)
    sprintf(paste("No component has a larger eigenvalue than random data of this size would give (parallel analysis),",
                  "so none stands out from chance; the plots still show the first two."))
    else sprintf("Parallel analysis keeps %s: %s eigenvalue%s larger than random data of this size would give.",
                 if (p$retained == 1) "the first component" else sprintf("the first %d components", p$retained),
                 if (p$retained == 1) "its" else "their", if (p$retained == 1) " is" else "s are"))
  out <- c(out, sprintf("%s keeps %d (%s above %s)%s.", if (p$scale) "Kaiser's rule" else "The rule of an eigenvalue above the average",
                        p$kaiser, pl(p$kaiser, "an eigenvalue", "eigenvalues"), avg,
                        if (p$kaiser != p$retained)
                          "; the two rules disagree, and parallel analysis, which allows for chance, is generally the more reliable"
                        else ""))
  ## with covariances a variable with a large variance makes a component of
  ## its own, which parallel analysis (same variances, no correlation) expects
  if (!p$scale)
    out <- c(out, paste("With covariances, a variable with a much larger variance than the others makes a component almost",
                        "on its own, whether or not it is related to them; parallel analysis allows for that, so a component",
                        "can carry a large share of the variation and still not stand out from chance."))
  out <- c(out, vapply(seq_len(pca_shown(p)), function(k) pca_component_text(p, k), ""))
  weak <- which(as.numeric(fmt(rowSums(p$loadings[, seq_len(pca_shown(p)), drop = FALSE]^2), 2)) < 0.5)
  if (length(weak))
    out <- c(out, sprintf("%s %s less than half of %s variance carried by these components (communality below 0.50), so %s little part in them.",
                          join_and(p$vars[weak]), pl(length(weak), "has", "have"), pl(length(weak), "its", "their"),
                          pl(length(weak), "it plays", "they play")))
  out <- c(out, paste("A component's sign is arbitrary, so high and low can be swapped throughout. The components",
                      "describe how the variables vary together in these rows; they do not show what causes it."))
  left <- p$nrow - p$n
  if (left > 0) {
    out <- c(out, sprintf("%d of the %d rows %s left out because %s no usable value of some variable.", left, p$nrow,
                          pl(left, "is", "are"), pl(left, "it has", "they have")))
    if (p$held_rows > 0)
      out <- c(out, sprintf("Of these, %d %s an entry the data check has flagged (such as '%s') and will count once corrected on the Data tab.",
                            p$held_rows, pl(p$held_rows, "has", "have"), p$held_eg))
  }
  paste(out, collapse = " ")
}

## ------------------------------------------------------------ plots ----

## the components to plot: the two asked for when they exist and differ,
## else the first two
pca_axes <- function(p, a, b) {
  okk <- function(v) length(v) == 1 && is.numeric(v) && !is.na(v) && v >= 1 && v <= p$m
  a <- if (okk(a)) as.integer(a) else 1L
  b <- if (okk(b) && b != a) as.integer(b) else if (a == 1L) min(2L, p$m) else 1L
  c(a, b)
}

plot_pca_scree <- function(p) {
  e <- p$eigen
  df <- data.frame(k = seq_len(nrow(e)), ev = e$Eigenvalue, pa = e$PA_threshold)
  ggplot(df, aes(x = .data$k)) +
    geom_hline(yintercept = p$average, linetype = 3, colour = "grey45") +
    geom_line(aes(y = .data$pa), linetype = 2, colour = "#C0392B") +
    geom_point(aes(y = .data$pa), shape = 4, colour = "#C0392B", size = 2.4) +
    geom_line(aes(y = .data$ev), colour = "#173F7D", linewidth = 0.9) +
    geom_point(aes(y = .data$ev), colour = "#3B7DD8", size = 2.6) +
    scale_x_continuous(breaks = df$k, labels = e$Component) +
    labs(title = "Scree plot", x = "Component", y = "Eigenvalue",
         caption = paste(strwrap(sprintf("Blue: eigenvalues. Red crosses: parallel analysis. Dotted line: %s.",
                                         if (p$scale) "an eigenvalue of 1 (Kaiser)" else "the average eigenvalue"), 70),
                         collapse = "\n")) +
    theme_doe()
}

## rows whose score on either plotted component lies more than three of that
## component's standard deviations from 0
pca_far <- function(p, ax) which(apply(abs(sweep(p$scores[, ax, drop = FALSE], 2, p$sdev[ax], "/")) > 3 + 1e-8, 1, any))

plot_pca_scores <- function(p, ax = c(1, 2), group = NULL) {
  df <- data.frame(x = p$scores[, ax[1]], y = p$scores[, ax[2]], row = p$rows)
  if (!is.null(group)) df$group <- group
  far <- df[pca_far(p, ax), , drop = FALSE]
  g <- ggplot(df, aes(x = .data$x, y = .data$y)) +
    geom_hline(yintercept = 0, colour = "grey70") + geom_vline(xintercept = 0, colour = "grey70") +
    (if (is.null(group)) geom_point(colour = "#3B7DD8", size = 2.4, alpha = 0.85)
     else geom_point(aes(colour = .data$group), size = 2.4, alpha = 0.85)) +
    (if (nrow(far)) geom_text(data = far, aes(label = paste("row", .data$row)), vjust = -0.8, size = 3.3, colour = "#C0392B")) +
    labs(title = "Score plot", colour = NULL,
         x = sprintf("PC%d (%s%%)", ax[1], fmt(100 * p$eigen$Proportion[ax[1]], 1)),
         y = sprintf("PC%d (%s%%)", ax[2], fmt(100 * p$eigen$Proportion[ax[2]], 1))) +
    theme_doe()
  g
}

plot_pca_loadings <- function(p, ax = c(1, 2)) {
  df <- data.frame(x = p$loadings[, ax[1]], y = p$loadings[, ax[2]], v = p$vars)
  circ <- data.frame(t = seq(0, 2 * pi, length.out = 200))
  ggplot(df) +
    geom_path(data = circ, aes(x = cos(.data$t), y = sin(.data$t)), colour = "grey70") +
    geom_hline(yintercept = 0, colour = "grey85") + geom_vline(xintercept = 0, colour = "grey85") +
    geom_segment(aes(x = 0, y = 0, xend = .data$x, yend = .data$y), colour = "#173F7D",
                 arrow = arrow(length = unit(0.18, "cm"))) +
    geom_text(aes(x = .data$x * 1.12, y = .data$y * 1.12, label = .data$v), size = 3.4) +
    coord_equal(xlim = c(-1.2, 1.2), ylim = c(-1.2, 1.2)) +
    labs(title = "Loading plot", caption = "Circle: a correlation of 1 with the two components together.",
         x = sprintf("PC%d", ax[1]), y = sprintf("PC%d", ax[2])) +
    theme_doe()
}

## the factor that stretches the loadings to the scale of the scores
pca_stretch <- function(p, ax) {
  0.8 * max(abs(p$scores[, ax])) / max(sqrt(rowSums(p$loadings[, ax, drop = FALSE]^2)))
}

plot_pca_biplot <- function(p, ax = c(1, 2), group = NULL) {
  f <- pca_stretch(p, ax)
  sc <- data.frame(x = p$scores[, ax[1]], y = p$scores[, ax[2]])
  if (!is.null(group)) sc$group <- group
  ld <- data.frame(x = f * p$loadings[, ax[1]], y = f * p$loadings[, ax[2]], v = p$vars)
  ggplot() +
    geom_hline(yintercept = 0, colour = "grey85") + geom_vline(xintercept = 0, colour = "grey85") +
    (if (is.null(group)) geom_point(data = sc, aes(x = .data$x, y = .data$y), colour = "#8FB3E8", size = 2)
     else geom_point(data = sc, aes(x = .data$x, y = .data$y, colour = .data$group), size = 2, alpha = 0.8)) +
    geom_segment(data = ld, aes(x = 0, y = 0, xend = .data$x, yend = .data$y), colour = "#C0392B",
                 arrow = arrow(length = unit(0.18, "cm"))) +
    geom_text(data = ld, aes(x = .data$x * 1.1, y = .data$y * 1.1, label = .data$v), size = 3.4, colour = "#7B241C") +
    labs(title = "Biplot", colour = NULL,
         x = sprintf("PC%d (%s%%)", ax[1], fmt(100 * p$eigen$Proportion[ax[1]], 1)),
         y = sprintf("PC%d (%s%%)", ax[2], fmt(100 * p$eigen$Proportion[ax[2]], 1)),
         caption = paste(strwrap(sprintf(paste("Points: the scores. Arrows: the loadings, stretched %s times to the scale",
                                               "of the points; read their directions and relative lengths."), sig_fmt(f, 3)), 70),
                         collapse = "\n")) +
    theme_doe()
}

## ------------------------------------------------------------ plot notes ----

pca_scree_text <- function(p) {
  what <- paste("The eigenvalues in order, each the variance its component carries. The red crosses show what",
                "random data of this size would give; a component whose eigenvalue stands above its cross carries more",
                "than chance alone would.", if (p$scale) "The dotted line marks an eigenvalue of 1, Kaiser's rule."
                else "The dotted line marks the average eigenvalue.")
  above <- which(p$eigen$Eigenvalue > p$eigen$PA_threshold)
  later <- setdiff(above, seq_len(p$retained))
  reading <- paste(c(
    if (p$retained == 0 && !length(above)) "No eigenvalue lies above its cross."
    else if (p$retained == 0) "The first eigenvalue lies below its cross, so parallel analysis keeps no component."
    else if (p$retained == 1) paste0("The first eigenvalue lies above its cross", if (p$m > 1) ", the second below." else ".")
    else paste0(sprintf("The first %d eigenvalues lie above their crosses", p$retained),
                if (p$retained < p$m) ", the next below." else "."),
    if (length(later)) sprintf("%s also %s above %s cross, but parallel analysis stops at the first component that falls short.",
                               join_and(p$eigen$Component[later]), pl(length(later), "lies", "lie"),
                               pl(length(later), "its", "their")),
    "If the line drops steeply and then levels off, the components after the bend (the elbow) add little."), collapse = " ")
  list(what = what, reading = reading)
}

pca_scores_text <- function(p, ax = c(1, 2), group = NULL, gname = NULL) {
  what <- sprintf(paste("Each point is a row, placed by its scores on PC%d (across) and PC%d (up). Rows close together",
                        "have similar values of the variables that load strongly on these components; rows near 0 are",
                        "close to the average row.%s"), ax[1], ax[2],
                  if (!is.null(group)) sprintf(" Colours show %s.", gname) else "")
  far <- pca_far(p, ax)
  out <- c(if (length(far))
             paste0(sprintf("%s %s more than three standard deviations from 0 on PC%d or PC%d; check %s for a recording error, or for a treatment that differs.",
                            cap1(rows_text(p$rows[far])), pl(length(far), "lies", "lie"), ax[1], ax[2], pl(length(far), "it", "them")),
                    if (p$n >= 100) sprintf(" Among %d rows, about %s would lie that far by chance on one or other component even if the scores were normal.",
                                            p$n, fmt(p$n * (1 - (1 - 2 * stats::pnorm(-3))^2), 1)) else "")
           else sprintf("No row lies more than three standard deviations from 0 on PC%d or PC%d.", ax[1], ax[2]))
  if (!is.null(group)) {
    mm <- stats::aggregate(p$scores[, ax], list(g = group), mean)
    ## the highest and lowest average score on each axis, ties named as ties
    txt <- function(col) {
      v <- dfmt(mm[[col + 1]], 2); hi <- which(as.numeric(v) == max(as.numeric(v))); lo <- which(as.numeric(v) == min(as.numeric(v)))
      sprintf("on PC%d %s the highest average score (%s) and %s the lowest (%s)", ax[col],
              paste(join_and(as.character(mm$g[hi])), pl(length(hi), "has", "share")), v[hi[1]],
              paste(join_and(as.character(mm$g[lo])), pl(length(lo), "has", "share")), v[lo[1]])
    }
    out <- c(out, sprintf("Among the levels of %s, %s; %s.", gname, txt(1), txt(2)),
             "If the colours form separate clouds, the groups differ in the variables these components carry; if they overlap, the components do not tell them apart.")
  }
  list(what = what, reading = paste(out, collapse = " "))
}

pca_loadings_text <- function(p, ax = c(1, 2)) {
  what <- sprintf(paste("Each arrow is a variable, ending at its loadings on PC%d (across) and PC%d (up). An arrow near the",
                        "circle is well carried by these two components; a short one is not. Arrows pointing the same way",
                        "belong to variables that rise together; opposite arrows, to variables where one rises as the other",
                        "falls; arrows at right angles, to variables these components show as unrelated."), ax[1], ax[2])
  cm <- rowSums(p$loadings[, ax, drop = FALSE]^2)
  shown <- as.numeric(dfmt(cm, 2))
  weak <- which(shown < 0.5)
  top <- which(shown == max(shown))
  reading <- c(sprintf("The longest %s to %s (%s of %s variance on these two components).",
                       pl(length(top), "arrow belongs", "arrows belong"), join_and(p$vars[top]), dfmt(max(cm), 2),
                       pl(length(top), "its", "each one's")),
               if (length(weak)) sprintf("%s %s less than half of %s variance on these two, so %s %s little.",
                                         join_and(p$vars[weak]), pl(length(weak), "has", "have"), pl(length(weak), "its", "their"),
                                         pl(length(weak), "its arrow", "their arrows"), pl(length(weak), "says", "say")))
  list(what = what, reading = paste(reading, collapse = " "))
}

pca_biplot_text <- function(p, ax = c(1, 2)) {
  what <- sprintf(paste("The score plot and the loading plot together: points are rows, arrows are variables. A row lying",
                        "far out in an arrow's direction tends to have a high value of that variable, and one on the opposite",
                        "side a low value; this is only approximate, as the plot shows two components of %d. The arrows are",
                        "stretched %s times so they can be seen beside the points."), p$m, sig_fmt(pca_stretch(p, ax), 3))
  reading <- sprintf(paste("PC%d and PC%d together carry %s%% of the variation, so the plot shows that share of how the",
                           "rows differ; the rest lies on other components."), ax[1], ax[2],
                     fmt(100 * sum(p$eigen$Proportion[ax]), 1))
  list(what = what, reading = reading)
}

## ---------------------------------------------------------- cluster.R ----
###############################################################################
##  CLUSTER ANALYSIS
###############################################################################
## Hierarchical clustering of rows, or of the means of each level of a
## grouping column (varieties by their trait means, as in plant breeding), on
## the chosen numeric columns. As on the other Explore tabs, every sentence is
## one the tables or plots on screen bear out: the number of clusters comes
## from a stated rule (the average silhouette width), clusters are described
## by their means as printed, and nothing is offered as a test, since
## clustering forms clusters even in data with no groups in them.

CL_LINKS <- c(ward = "ward.D2", complete = "complete", average = "average", single = "single")
CL_LINK_NAMES <- c(ward = "Ward's method", complete = "complete linkage", average = "average linkage (UPGMA)",
                   single = "single linkage")
CL_DIST_NAMES <- c(euclidean = "Euclidean", manhattan = "Manhattan")
## the most clusters the silhouette widths are worked out for
CL_KMAX <- 10
## more items than this: the tree is drawn without their labels
CL_LABELS_MAX <- 60
## more items than this would be slow in the browser
CL_ITEMS_MAX <- 1000

#' Hierarchical cluster analysis
#'
#' Clusters the rows, or the means of each level of a grouping column, on the
#' chosen numeric columns (\code{\link[stats]{hclust}}), from the rows with a
#' value of every one. By default each variable is standardised first, so no
#' variable dominates through its units. Text entries are read as the data
#' check reads them; see \code{\link{check_data}}.
#'
#' The number of clusters, unless given, is the one from 2 to 10 (or one
#' fewer than the items) with the largest average silhouette width (Rousseeuw,
#' 1987): for each item, how much closer it lies to the other items of its own
#' cluster than to those of the nearest other cluster, from -1 to 1. The
#' cophenetic correlation measures how faithfully the tree keeps the
#' distances between the items. Clusters are numbered in the order they
#' appear in the tree from left to right.
#'
#' @param d A data frame.
#' @param vars The names of two or more numeric columns.
#' @param group Optional: the name of a column whose levels are clustered by
#'   their means, instead of clustering the rows.
#' @param k The number of clusters, or \code{NULL} for the suggested number.
#' @param distance \code{"euclidean"} or \code{"manhattan"}.
#' @param linkage \code{"ward"} (Ward's method, which needs Euclidean
#'   distances), \code{"complete"}, \code{"average"} or \code{"single"}.
#' @param scale \code{TRUE} (the default) to standardise each variable.
#'
#' @return A list of class \code{doepro_cluster}: \code{items} (the labels of
#'   the items clustered), \code{X} (their values), \code{cluster} (each
#'   item's cluster), \code{sizes}, \code{means} (each cluster's mean of each
#'   variable), \code{silhouette} (each item's width), \code{by_k} (the
#'   average silhouette width for each number of clusters tried),
#'   \code{suggested}, \code{k}, \code{cophenetic}, \code{tree} (the
#'   \code{hclust} result), and the settings.
#'
#' @examples
#' set.seed(1)
#' d <- data.frame(Variety = rep(paste0("V", 1:9), each = 3))
#' d$Yield <- rep(c(30, 31, 29, 40, 42, 41, 35, 36, 34), each = 3) + rnorm(27)
#' d$Height <- rep(c(80, 82, 79, 95, 97, 96, 88, 87, 90), each = 3) + rnorm(27)
#' cl <- cluster_data(d, c("Yield", "Height"), group = "Variety")
#' cl$k
#' cl$cluster
#'
#' @export
cluster_data <- function(d, vars, group = NULL, k = NULL, distance = c("euclidean", "manhattan"),
                         linkage = c("ward", "complete", "average", "single"), scale = TRUE) {
  distance <- match.arg(distance); linkage <- match.arg(linkage)
  if (linkage == "ward" && distance != "euclidean")
    stop("Ward's method needs Euclidean distances; choose Euclidean, or another linkage.")
  vars <- unique(vars[!is.na(vars) & nzchar(vars)])
  if (length(vars) < 2) stop("Choose at least two variables to cluster on.")
  if (!is.null(group) && (is.na(group) || !nzchar(group))) group <- NULL
  gone <- setdiff(c(vars, group), names(d))
  if (length(gone))
    stop(sprintf("%s %s of the data.", join_and(sprintf("'%s'", gone)), pl(length(gone), "is not a column", "are not columns")))
  if (!is.null(group) && group %in% vars) stop(sprintf("'%s' is the grouping column, so it cannot also be a variable.", group))
  vals <- lapply(stats::setNames(vars, vars), function(v) response_values(d[[v]]))
  held <- lapply(stats::setNames(vars, vars), function(v) held_flags(d[[v]]))
  ok <- Reduce(`&`, lapply(vals, is.finite))
  would <- Reduce(`&`, Map(function(v, h) is.finite(v) | h, vals, held))
  held_rows <- which(would & !ok)
  held_eg <- if (length(held_rows)) {
    i <- held_rows[1]; v <- vars[vapply(held, function(h) h[i], logical(1))][1]
    trimws(as.character(d[[v]][i]))
  } else ""
  lab <- if (!is.null(group)) trimws(as.character(d[[group]])) else NULL
  unlabelled <- if (!is.null(group)) sum(ok & (is.na(lab) | lab == "")) else 0L
  if (!is.null(group)) ok <- ok & !is.na(lab) & lab != ""
  R <- do.call(cbind, lapply(vals, function(v) v[ok])); colnames(R) <- vars
  if (is.null(group)) {
    X <- R; items <- as.character(row_ids(d)[ok]); dropped <- character(0); per <- rep(1L, nrow(X))
  } else {
    g <- lab[ok]
    lv_all <- natural_levels(lab[!is.na(lab) & lab != ""])
    items <- intersect(lv_all, unique(g))
    dropped <- setdiff(lv_all, items)
    X <- do.call(rbind, lapply(items, function(l) colMeans(R[g == l, , drop = FALSE])))
    colnames(X) <- vars
    per <- as.integer(table(factor(g, levels = items)))
  }
  n <- nrow(X)
  what <- if (is.null(group)) "rows" else sprintf("levels of %s", group)
  if (n < 3)
    stop(sprintf("Only %d %s %s a value of every variable chosen; clustering needs at least 3.", n,
                 if (is.null(group)) pl(n, "row", "rows") else pl(n, sprintf("level of %s", group), sprintf("levels of %s", group)),
                 pl(n, "has", "have")))
  if (n > CL_ITEMS_MAX)
    stop(sprintf(paste("Clustering %d rows one by one would be slow in the browser; cluster the means of a grouping column",
                       "instead, or choose at most %d rows."), n, CL_ITEMS_MAX))
  flat <- vars[apply(X, 2, function(z) length(unique(z)) < 2)]
  if (length(flat))
    stop(sprintf("%s %s the same value for every %s, so %s nothing to tell the %s apart; leave %s out.",
                 join_and(sprintf("'%s'", flat)), pl(length(flat), "has", "each have"),
                 if (is.null(group)) "row used" else sprintf("level of %s", group),
                 pl(length(flat), "it adds", "they add"), if (is.null(group)) "rows" else sprintf("levels of %s", group),
                 pl(length(flat), "it", "them")))
  Z <- if (scale) base::scale(X) else X
  D <- stats::dist(Z, method = distance)
  if (all(D == 0)) stop(sprintf("Every one of the %s has the same values, so there is nothing to cluster.", what))
  tree <- stats::hclust(D, method = CL_LINKS[[linkage]])
  ## the average silhouette width for each number of clusters tried; the
  ## suggestion is the first of the largest
  K <- min(CL_KMAX, n - 1L)
  M <- as.matrix(D)
  by_k <- vapply(2:K, function(kk) mean(cl_silhouette(stats::cutree(tree, kk), M)), 0)
  suggested <- (2:K)[which.max(by_k)]
  if (is.null(k) || length(k) != 1 || is.na(k)) k <- suggested
  k <- as.integer(k)
  if (k < 2 || k > n - 1)
    stop(sprintf("The number of clusters must be from 2 to %d (one fewer than the %d %s).", n - 1L, n, what))
  ## clusters numbered in the order they appear in the tree, left to right
  c0 <- stats::cutree(tree, k)
  cl <- match(c0, unique(c0[tree$order]))
  sil <- cl_silhouette(cl, M)
  means <- do.call(rbind, lapply(seq_len(k), function(c) colMeans(X[cl == c, , drop = FALSE])))
  rownames(means) <- paste("Cluster", seq_len(k))
  inf_rows <- sum(!Reduce(`&`, lapply(vals, is.finite)) & Reduce(`|`, lapply(vals, is.infinite)))
  structure(list(vars = vars, group = group, items = items, X = X, Z = Z, per = per, n = n, k = k, suggested = suggested,
                 by_k = data.frame(k = 2:K, Silhouette = by_k), cluster = cl, sizes = tabulate(cl, k), means = means,
                 silhouette = sil, cophenetic = stats::cor(as.vector(D), as.vector(stats::cophenetic(tree))),
                 tree = tree, distance = distance, linkage = linkage, scale = scale, dropped = dropped,
                 unlabelled = unlabelled, rows_used = sum(ok), nrow = nrow(d), held_rows = length(held_rows),
                 held_eg = held_eg, inf_rows = inf_rows, digits = vapply(vars, function(v) var_digits(vals[[v]][ok]), 1L)),
            class = "doepro_cluster")
}

#' @rdname cluster_data
#' @param x A result of \code{cluster_data()}.
#' @param ... Not used.
#' @export
print.doepro_cluster <- function(x, ...) {
  cat(sprintf("%d clusters of %d items (suggested: %d); cophenetic correlation %.3f\n\n", x$k, x$n, x$suggested, x$cophenetic))
  print(data.frame(Item = x$items, Cluster = x$cluster, Silhouette = round(x$silhouette, 3)), row.names = FALSE)
  cat("\n")
  print(x$means)
  invisible(x)
}

## Each item's silhouette width (Rousseeuw, 1987): a is its mean distance to
## the other items of its own cluster, b the smallest mean distance to the
## items of another cluster, and the width (b - a) / max(a, b); an item alone
## in its cluster has 0. Worked out for all items at once, from the
## distances as a "dist" object or a full matrix.
cl_silhouette <- function(cl, D) {
  M <- if (inherits(D, "dist")) as.matrix(D) else D
  n <- nrow(M); k <- max(cl)
  ind <- outer(cl, seq_len(k), "==") + 0
  S <- M %*% ind
  sz <- colSums(ind)
  a <- S[cbind(seq_len(n), cl)] / pmax(sz[cl] - 1, 1)
  other <- sweep(S, 2, sz, "/")
  other[cbind(seq_len(n), cl)] <- Inf
  b <- apply(other, 1, min)
  s <- (b - a) / pmax(a, b)
  s[sz[cl] == 1 | pmax(a, b) == 0] <- 0
  unname(s)
}

## Kaufman and Rousseeuw's (1990) reading of an average silhouette width,
## judged on the value as printed
cl_band <- function(w) {
  v <- as.numeric(fmt(w, 2))
  if (v > 0.70) "a strong structure" else if (v > 0.50) "a reasonable structure"
  else if (v > 0.25) "a weak structure that could be artificial" else "no substantial structure"
}

## how the items are named in the text
cl_item_word <- function(cl, n) {
  if (is.null(cl$group)) pl(n, "row", "rows") else pl(n, sprintf("level of %s", cl$group), sprintf("levels of %s", cl$group))
}
cl_item_names <- function(cl, i, most = 12) {
  nm <- if (is.null(cl$group)) paste("row", cl$items[i]) else cl$items[i]
  if (is.null(cl$group) && length(i) > 1) nm <- c(paste("rows", cl$items[i[1]]), cl$items[i[-1]])
  join_and(head_more(nm, most))
}

## ------------------------------------------------------------ tables ----

cl_members_html <- function(cl) {
  body <- lapply(seq_len(cl$k), function(c) {
    i <- which(cl$cluster == c)
    c(as.character(c), as.character(length(i)), esc(cl_item_names(cl, i, 20)),
      fmt(mean(cl$silhouette[i]), 2))
  })
  foot <- sprintf("<tr><td colspan='4' class='cdrow'>%s</td></tr>", esc(paste(
    "Silhouette: the average, over the cluster's items, of how much closer each lies to its own cluster than to the",
    "nearest other (1 well apart, 0 on a boundary, below 0 closer to another cluster). Clusters are numbered as they",
    "appear in the tree from left to right; the numbers are only labels.")))
  raw_table(c("Cluster", "Size", "Members", "Silhouette"), body, foot = foot, caption = "Clusters")
}

cl_means_html <- function(cl) {
  body <- lapply(seq_along(cl$vars), function(j) c(esc(cl$vars[j]),
    vapply(seq_len(cl$k), function(c) dfmt(cl$means[c, j], cl$digits[j]), ""),
    dfmt(mean(cl$X[, j]), cl$digits[j])))
  foot <- sprintf("<tr><td colspan='%d' class='cdrow'>%s</td></tr>", cl$k + 2, esc(paste0(
    "The mean of each variable in each cluster, in the units of the data",
    if (!is.null(cl$group)) sprintf(", worked out from the means of the levels of %s in the cluster", cl$group) else "",
    ". All: the mean over every ", cl_item_word(cl, 1), " clustered.")))
  raw_table(c("Variable", paste("Cluster", seq_len(cl$k)), "All"), body, foot = foot, caption = "Cluster means")
}

cl_items_html <- function(cl) {
  body <- lapply(seq_len(cl$n), function(i) c(esc(cl$items[i]), as.character(cl$cluster[i]), dfmt(cl$silhouette[i], 2),
    if (!is.null(cl$group)) as.character(cl$per[i])))
  raw_table(c(if (is.null(cl$group)) "Row" else esc(cl$group), "Cluster", "Silhouette", if (!is.null(cl$group)) "Rows averaged"),
            body, caption = "Each item's cluster")
}

## ------------------------------------------------------------ readings ----

## a cluster in a sentence: its members, and the variables on which its mean,
## as printed, is the highest or the lowest of the clusters (ties named)
cl_cluster_text <- function(cl, c) {
  i <- which(cl$cluster == c)
  pm <- sapply(seq_along(cl$vars), function(j) as.numeric(dfmt(cl$means[, j], cl$digits[j])))
  pm <- matrix(pm, nrow = cl$k)
  hi <- which(pm[c, ] == apply(pm, 2, max) & apply(pm, 2, function(z) length(unique(z)) > 1))
  lo <- which(pm[c, ] == apply(pm, 2, min) & apply(pm, 2, function(z) length(unique(z)) > 1))
  shared <- function(j) vapply(j, function(v) sum(pm[, v] == pm[c, v]) > 1, logical(1))
  part <- function(j, word) sprintf("the %s %s %s", word, pl(length(j), "mean of", "means of"),
                                    join_and(paste0(cl$vars[j], ifelse(shared(j), " (shared)", ""))))
  head_ <- sprintf("Cluster %d (%s: %s)", c, if (length(i) == 1) paste("1", cl_item_word(cl, 1)) else paste(length(i), cl_item_word(cl, 2)),
                   cl_item_names(cl, i))
  body <- if (length(hi) && length(lo)) sprintf("has %s and %s", part(hi, "highest"), part(lo, "lowest"))
          else if (length(hi)) sprintf("has %s", part(hi, "highest"))
          else if (length(lo)) sprintf("has %s", part(lo, "lowest"))
          else "is neither the highest nor the lowest in any variable"
  sprintf("%s %s.", head_, body)
}

## The reading of the clustering as a whole.
cl_text <- function(cl) {
  w <- mean(cl$silhouette)
  out <- sprintf("The tree joins %d %s by %s, using %s distances between their %s values of %d variables.",
                 cl$n, if (is.null(cl$group)) "rows" else sprintf("levels of %s (each the mean of its rows)", cl$group),
                 CL_LINK_NAMES[[cl$linkage]], CL_DIST_NAMES[[cl$distance]],
                 if (cl$scale) "standardised" else "measured", length(cl$vars))
  sk <- cl$by_k$Silhouette[cl$by_k$k == cl$suggested]
  out <- c(out, sprintf("Of %d to %d clusters, %d %s the largest average silhouette width (%s)%s.",
                        min(cl$by_k$k), max(cl$by_k$k), cl$suggested, "gives", fmt(sk, 2),
                        if (cl$k == cl$suggested) ", and the tree is cut there"
                        else sprintf("; the tree is cut into %d, as chosen, where the average width is %s", cl$k, fmt(w, 2))))
  out <- c(out, sprintf("An average width of %s points to %s (Kaufman and Rousseeuw's bands: above 0.70 strong, 0.51 to 0.70 reasonable, 0.26 to 0.50 weak, 0.25 or less none).",
                        fmt(w, 2), cl_band(w)))
  out <- c(out, sprintf(paste("The cophenetic correlation is %s: how faithfully the heights at which the tree joins the items",
                              "keep the distances between them (1 would be perfect)."), fmt(cl$cophenetic, 2)))
  out <- c(out, vapply(seq_len(cl$k), function(c) cl_cluster_text(cl, c), ""))
  neg <- which(as.numeric(fmt(cl$silhouette, 2)) < 0)
  if (length(neg))
    out <- c(out, sprintf("%s %s a negative silhouette width: on average %s closer to the items of another cluster than to %s own, so %s place is doubtful.",
                          cap1(cl_item_names(cl, neg)), pl(length(neg), "has", "have"), pl(length(neg), "it lies", "they lie"),
                          pl(length(neg), "its", "their"), pl(length(neg), "its", "their")))
  out <- c(out, paste("Clustering always forms clusters, even in data with no groups in them, and gives no test of significance:",
                      "the silhouette widths show how clearly these ones separate. The clusters group items alike in these",
                      "variables; they do not show why they are alike."))
  left <- cl$nrow - cl$rows_used
  if (left > 0) {
    out <- c(out, sprintf("%d of the %d rows %s left out because %s no usable value of some variable%s.", left, cl$nrow,
                          pl(left, "is", "are"), pl(left, "it has", "they have"),
                          if (cl$unlabelled) sprintf(" or no label in %s", cl$group) else ""))
    if (cl$held_rows > 0)
      out <- c(out, sprintf("Of these, %d %s an entry the data check has flagged (such as '%s') and will count once corrected on the Data tab.",
                            cl$held_rows, pl(cl$held_rows, "has", "have"), cl$held_eg))
  }
  if (length(cl$dropped))
    out <- c(out, sprintf("%s %s no row with every value, so %s not clustered.", join_and(head_more(cl$dropped, 8)),
                          pl(length(cl$dropped), "has", "have"), pl(length(cl$dropped), "it is", "they are")))
  paste(out, collapse = " ")
}

## ------------------------------------------------------------ plots ----

## The tree as segments: each join a horizontal at its height and a vertical
## up from each of the two things it joins. A segment takes the colour of the
## cluster below it, or none when it joins two clusters.
cl_dendro <- function(cl) {
  h <- cl$tree; n <- length(h$order)
  xpos <- numeric(n); xpos[h$order] <- seq_len(n)
  nx <- numeric(n - 1); memb <- vector("list", n - 1)
  pos <- function(j) if (j < 0) xpos[-j] else nx[j]
  hgt <- function(j) if (j < 0) 0 else h$height[j]
  mem <- function(j) if (j < 0) -j else memb[[j]]
  colour <- function(m) { u <- unique(cl$cluster[m]); if (length(u) == 1) u else NA_integer_ }
  seg <- vector("list", n - 1)
  for (i in seq_len(n - 1)) {
    a <- h$merge[i, 1]; b <- h$merge[i, 2]
    nx[i] <- (pos(a) + pos(b)) / 2; memb[[i]] <- c(mem(a), mem(b))
    seg[[i]] <- data.frame(x = c(pos(a), pos(b), pos(a)), y = c(hgt(a), hgt(b), h$height[i]),
                           xend = c(pos(a), pos(b), pos(b)), yend = c(h$height[i], h$height[i], h$height[i]),
                           cluster = c(colour(mem(a)), colour(mem(b)), colour(memb[[i]])))
  }
  out <- do.call(rbind, seg)
  out$cluster <- factor(out$cluster, levels = seq_len(cl$k))
  list(seg = out, leaves = data.frame(x = seq_len(n), label = cl$items[h$order], cluster = factor(cl$cluster[h$order], levels = seq_len(cl$k))),
       cut = mean(sort(h$height)[c(n - cl$k, n - cl$k + 1)]))
}

plot_cl_dendro <- function(cl) {
  dd <- cl_dendro(cl)
  g <- ggplot() +
    geom_segment(data = dd$seg, aes(x = .data$x, y = .data$y, xend = .data$xend, yend = .data$yend, colour = .data$cluster),
                 linewidth = 0.7, na.rm = TRUE) +
    geom_hline(yintercept = dd$cut, linetype = 2, colour = "grey45") +
    scale_colour_discrete(breaks = as.character(seq_len(cl$k)), labels = paste("Cluster", seq_len(cl$k)),
                          na.value = "grey55", drop = FALSE) +
    labs(title = "Dendrogram", subtitle = sprintf("%s, %s distances", cap1(CL_LINK_NAMES[[cl$linkage]]), CL_DIST_NAMES[[cl$distance]]),
         x = NULL, y = "Height", colour = NULL,
         caption = sprintf("Dashed line: the cut into %d clusters.", cl$k)) +
    theme_doe() + theme(panel.grid.major.x = element_blank())
  if (cl$n <= CL_LABELS_MAX)
    g <- g + scale_x_continuous(breaks = dd$leaves$x, labels = dd$leaves$label, expand = expansion(add = 0.6)) +
      theme(axis.text.x = element_text(angle = 90, hjust = 1, vjust = 0.5, size = if (cl$n > 30) 7 else 9))
  else g <- g + theme(axis.text.x = element_blank(), axis.ticks.x = element_blank())
  g
}

## the items on their first two principal components, coloured by cluster
cl_pcs <- function(cl) {
  pc <- stats::prcomp(cl$X, center = TRUE, scale. = cl$scale)
  list(scores = pc$x[, 1:2, drop = FALSE], share = pc$sdev[1:2]^2 / sum(pc$sdev^2))
}

plot_cl_pcs <- function(cl) {
  pc <- cl_pcs(cl)
  df <- data.frame(x = pc$scores[, 1], y = pc$scores[, 2], cluster = factor(cl$cluster, levels = seq_len(cl$k)), label = cl$items)
  g <- ggplot(df, aes(x = .data$x, y = .data$y, colour = .data$cluster)) +
    geom_hline(yintercept = 0, colour = "grey85") + geom_vline(xintercept = 0, colour = "grey85") +
    geom_point(size = 2.6) +
    scale_colour_discrete(labels = paste("Cluster", seq_len(cl$k))) +
    labs(title = "Clusters on the first two principal components", colour = NULL,
         x = sprintf("PC1 (%s%%)", fmt(100 * pc$share[1], 1)), y = sprintf("PC2 (%s%%)", fmt(100 * pc$share[2], 1))) +
    theme_doe()
  if (cl$n <= 40) g <- g + geom_text(aes(label = .data$label), vjust = -0.9, size = 3, show.legend = FALSE)
  g
}

plot_cl_silhouette <- function(cl) {
  b <- cl$by_k
  ggplot(b, aes(x = .data$k, y = .data$Silhouette)) +
    geom_hline(yintercept = c(0.25, 0.5, 0.7), linetype = 3, colour = "grey70") +
    geom_line(colour = "#173F7D") + geom_point(colour = "#3B7DD8", size = 2.4) +
    geom_point(data = b[b$k == cl$k, , drop = FALSE], shape = 21, size = 5, colour = "#C0392B", stroke = 1.2) +
    scale_x_continuous(breaks = b$k) +
    labs(title = "Average silhouette width by number of clusters", x = "Number of clusters", y = "Average silhouette width",
         caption = paste(strwrap("Red ring: the number used. Dotted lines: 0.25, 0.50 and 0.70, Kaufman and Rousseeuw's bands.", 55),
                         collapse = "\n")) +
    theme_doe()
}

## ------------------------------------------------------------ plot notes ----

cl_dendro_text <- function(cl) {
  what <- paste("The tree joins the items step by step, the most alike first. The height of each join is how far apart",
                "the two groups it joins are, by the linkage chosen, so a long vertical line below a join means well",
                sprintf("separated groups. The dashed line cuts the tree into %d clusters, coloured.", cl$k))
  hs <- sort(cl$tree$height, decreasing = TRUE)
  reading <- c(sprintf("The cut lies between joins at heights %s and %s.", sig_fmt(hs[cl$k], 3), sig_fmt(hs[cl$k - 1], 3)),
               if (cl$n > CL_LABELS_MAX) sprintf("With %d items the labels are left off; the table of each item's cluster names them.", cl$n))
  list(what = what, reading = paste(reading, collapse = " "))
}

cl_pcs_text <- function(cl) {
  pc <- cl_pcs(cl)
  what <- sprintf(paste("Each point is an item, placed by its scores on the first two principal components of the same",
                        "%s values and coloured by cluster. These two components carry %s%% of the variation, so clusters",
                        "that overlap here may still lie apart on other components."),
                  if (cl$scale) "standardised" else "measured", fmt(100 * sum(pc$share), 1))
  single <- which(cl$sizes == 1)
  reading <- c(if (length(single) == 1) sprintf("Cluster %d holds a single item.", single)
               else if (length(single)) sprintf("Clusters %s each hold a single item.", join_and(single)),
               "If the colours form separate clouds, the clusters are well apart in these variables; if they mix, the split rests on differences these two components do not show.")
  list(what = what, reading = paste(reading, collapse = " "))
}

cl_silhouette_text <- function(cl) {
  what <- paste("For each number of clusters, the average silhouette width: how much closer, on average, each item lies",
                "to its own cluster than to the nearest other (1 well apart, 0 on a boundary, below 0 closer to another",
                "cluster). The highest point is the suggested number of clusters.")
  best <- cl$by_k$Silhouette[cl$by_k$k == cl$suggested]
  reading <- sprintf("The highest is at %d clusters (%s)%s.", cl$suggested, fmt(best, 2),
                     if (cl$k == cl$suggested) ", the number used"
                     else sprintf("; %d are used, as chosen (%s)", cl$k, fmt(mean(cl$silhouette), 2)))
  list(what = what, reading = reading)
}

## ---------------------------------------------------------- interpret.R ----
###############################################################################
##  PLAIN-ENGLISH INTERPRETATION
###############################################################################
cv_verdict <- function(cv) {
  if (is.na(cv)) return("")
  if (cv < 10) "low - the experiment was precisely conducted"
  else if (cv < 20) "moderate - acceptable for most field experiments"
  else if (cv < 30) "high - precision is poor; treatment differences must be large to be detected"
  else "very high - the experiment has low reliability; check for outliers, plot heterogeneity or a wrong error term"
}

## Every statement is made at the significance level the user chose, and a
## non-significant result is reported as insufficient evidence of a difference,
## never as evidence that there is none.
interpret <- function(res, asm, sug, trans_lab = "None") {
  d <- res$data; p <- character(0)
  dn <- names(DESIGNS)[match(res$design, DESIGNS)]
  a <- res$alpha; lvl <- sprintf("%s%%", pct(a))

  ## why the data are unbalanced, in the terms of the design
  why_unbal <- switch(res$design,
    CRD = "the treatments have unequal numbers of replications",
    FCRD = "the treatment combinations have unequal numbers of replications",
    LSD = "a plot is missing from the Latin square",
    "a plot is missing from a block, or the treatments are unequally replicated")
  adjusted <- isTRUE(res$adjusted_ss) &&
    any(vapply(res$effects, function(e) !is.null(e$means$Raw_mean), logical(1)))

  p <- c(p, sprintf("<h4>1. What was analysed</h4><p>A <b>%s</b> was analysed with <b>%s</b> as the response (%d observations). Every test is at the %s significance level.%s%s%s%s</p>",
    dn, res$resp, nrow(d), lvl,
    if (is.null(res$excluded)) "" else paste0(" ", excluded_text(res$excluded, html = TRUE)),
    if (res$balanced) " The data are balanced."
    else sprintf(" The data are <b>unbalanced</b>: %s. Each mean therefore has its own standard error, and two means are compared using the standard error of that particular pair.", why_unbal),
    if (adjusted) " The means are adjusted (least-squares) means, and each term in the ANOVA is tested after allowing for every other term (Type III sums of squares, which need not add up to the total)."
    else if (isTRUE(res$adjusted_ss)) " Each term in the ANOVA is tested after allowing for every other term (Type III sums of squares, which need not add up to the total)."
    else "",
    if (trans_lab != "None") sprintf(" The response was transformed using <b>%s</b>; all means, SEd and C.D. values below are on the transformed scale (back-transformed means are shown alongside).", trans_lab) else ""))

  p <- c(p, sprintf("<h4>2. Precision of the experiment</h4><p>%s. Grand mean = %s. A CV of this magnitude is %s.</p>",
    paste(sprintf("%s = %s", names(res$cv), fmt(res$cv, 2)), collapse = "; "),
    fmt(res$grand), cv_verdict(res$cv[length(res$cv)])))

  ## effect-by-effect
  ee <- character(0)
  inter_sig <- FALSE
  for (nm in names(res$effects)) {
    e <- res$effects[[nm]]
    if (is.na(e$p)) next
    s <- if (e$p < a / 5) "highly significant" else
         if (e$p < a) sprintf("significant at the %s level", lvl)
         else sprintf("not significant at the %s level", lvl)
    best <- e$means[which.max(e$means$Mean), ]
    top <- paste(vapply(e$vars, function(v) as.character(best[[v]]), character(1)),
                 collapse = " x ")
    if (effect_sig(e)) {
      if (length(e$vars) > 1) inter_sig <- TRUE
      cd_txt <- if (!is.null(e$slice))
        sprintf("Two means at the same level of %s must differ by at least <b>%s</b> (C.D. at %s) to be declared different; other comparisons have their own C.D., given with the table of means.",
                e$slice, fmt(e$cd), lvl)
      else if (!is.na(e$cd))
        sprintf("Two means of this effect must differ by at least <b>%s</b> (C.D. at %s) to be declared different.",
                fmt(e$cd), lvl)
      else
        sprintf("Because the data are unbalanced, the difference two means need to be declared different depends on which two are compared: the C.D. at %s ranges from <b>%s</b>.",
                lvl, err_text(e, "cd", 3, html = FALSE))
      ee <- c(ee, sprintf("<li><b>%s</b> is %s (F = %s, %s). The highest mean, %s, was recorded for <b>%s</b>. %s</li>",
        e$label, s, fmt(e$F, 2), p_eq(e$p), fmt(best$Mean), top, cd_txt))
    } else if (length(e$vars) > 1) {
      ## an interaction F-test asks whether one factor's effect depends on the
      ## other, not whether the cell means are all equal
      fx <- e$vars
      ee <- c(ee, sprintf("<li><b>%s</b> is %s (F = %s, %s). There is insufficient evidence at the %s level that the effect of %s depends on the level of %s. This is not evidence that the interaction is absent; a small one may have gone undetected.</li>",
        e$label, s, fmt(e$F, 2), p_eq(e$p), lvl, fx[1], paste(fx[-1], collapse = " and ")))
    } else {
      ee <- c(ee, sprintf("<li><b>%s</b> is %s (F = %s, %s). There is insufficient evidence to conclude that its means differ at the %s level, so no C.D. is quoted and no letters are given. This is not evidence that the means are equal; the experiment may have been too small to detect a real difference.</li>",
        e$label, s, fmt(e$F, 2), p_eq(e$p), lvl))
    }
  }

  ## In a pooled factorial the interaction of the environment with each single
  ## factor is an ANOVA row but not a table of means, so read it from the ANOVA.
  if (res$design %in% c("POOLFRCBD", "POOLFCRD")) {
    env <- setdiff(res$effects[[length(res$effects)]]$vars, res$facs)
    an <- res$anova
    rows <- an[startsWith(an$Source, paste0(env, " x ")) & !is.na(an$p), , drop = FALSE]
    full <- paste0(env, " x ", paste(res$facs, collapse = " x "))
    rows <- rows[rows$Source != full, , drop = FALSE]
    for (i in seq_len(nrow(rows))) {
      fac <- sub(paste0("^", env, " x "), "", rows$Source[i])
      if (rows$p[i] < a) {
        inter_sig <- TRUE
        ee <- c(ee, sprintf("<li><b>%s</b> is significant at the %s level (F = %s, %s): the effect of %s differs between environments, so its pooled means are averages over environments that behave differently and should be read with that in mind.</li>",
          rows$Source[i], lvl, fmt(rows$F[i], 2), p_eq(rows$p[i]), fac))
      } else {
        ee <- c(ee, sprintf("<li><b>%s</b> is not significant at the %s level (F = %s, %s): there is insufficient evidence that the effect of %s differs between environments.</li>",
          rows$Source[i], lvl, fmt(rows$F[i], 2), p_eq(rows$p[i]), fac))
      }
    }
  }
  p <- c(p, "<h4>3. Effect of each source</h4><ul>", ee, "</ul>")

  if (inter_sig) p <- c(p, "<p class='warn'><b>An interaction is significant.</b> The effect of one factor depends on the level of the other, so the main-effect means are averages over conditions that behave differently. Interpret the <i>interaction (cell) means</i> and the simple effects rather than the main effects, and use the interaction plot to describe the pattern.</p>")
  else if (length(res$facs) > 1) p <- c(p, sprintf("<p>No interaction was significant at the %s level, so there is insufficient evidence that the factors interact. The main-effect means can be interpreted directly and the best level of each factor chosen separately, bearing in mind that a small interaction may have gone undetected.</p>", lvl))

  ## assumptions, judged at the same level
  at <- character(0)
  if (isTRUE(asm$exact)) at <- c(at, paste("<li>The model fits every value exactly, so the residuals are all zero:",
    "there is no", if (isTRUE(asm$strata)) "sub-plot" else "residual",
    "error variation, and the checks of normality and equal variances do not apply.</li>"))
  if (!is.na(asm$p_norm)) at <- c(at, sprintf("<li>Shapiro-Wilk on residuals: W = %s, %s - %s.</li>",
    fmt(asm$shapiro$statistic, 3), p_eq(asm$p_norm),
    if (asm$p_norm > a) sprintf("insufficient evidence at the %s level that the residuals depart from normality", lvl)
    else sprintf("the residuals <b>depart from normality</b> at the %s level", lvl)))
  else if (!isTRUE(asm$exact)) at <- c(at, sprintf("<li>Normality could not be tested: %s.</li>",
    asm$norm_why %||% "too few residuals"))
  if (!is.na(asm$p_hov)) at <- c(at, sprintf("<li>%s: %s - %s.</li>",
    paste0(toupper(substr(asm$hov_label, 1, 1)), substring(asm$hov_label, 2)),
    p_eq(asm$p_hov),
    if (asm$p_hov > a) sprintf("insufficient evidence at the %s level that the treatments differ in variance", lvl)
    else sprintf("the variances are <b>heterogeneous</b> at the %s level", lvl)))
  else if (!isTRUE(asm$exact)) at <- c(at, sprintf("<li>Equal variances could not be tested: %s.</li>",
    asm$hov_why %||% "too few values"))
  if (length(asm$outliers)) at <- c(at, sprintf("<li>%d observation(s) have standardised residuals beyond +/-3 (rows %s) - check them for recording errors.</li>",
    length(asm$outliers), paste(asm$outliers, collapse = ", ")))
  at <- c(at, sprintf("<li>Recommendation: <b>%s</b>. %s</li>", TRANS[[sug$method]]$lab, sug$why))
  p <- c(p, "<h4>4. Assumptions of the ANOVA</h4><ul>", at, "</ul>")

  p <- c(p, sprintf("<h4>5. How to report this</h4><p>Present the ANOVA table, then the table of means with SEm&plusmn;, SEd, C.D. (%s) and CV(%%) at the foot%s. Means followed by a common letter are not significantly different at the %s level. For pairwise inference the least significant difference (LSD) is used only after a significant F-test (Fisher's protected LSD); Tukey's honestly significant difference (HSD) or Duncan's multiple range test (DMRT) may be preferred when many treatments are compared.</p>",
    lvl,
    if (res$balanced) "" else "; with unbalanced data give each mean its own SE and quote the range of the SEd and C.D. values",
    lvl))
  paste(p, collapse = "\n")
}

